output:
Функция ЗаполнитьТабличнуюЧастьОстатками(ДокументОбъект)
    // Очищаем табличную часть перед заполнением
    ДокументОбъект.Товары.Очистить();

    // Проверяем обязательные реквизиты
    Если ДокументОбъект.Дата = '00010101' Тогда
        Сообщить("Не заполнена дата документа");
        Возврат;
    КонецЕсли;
    Если Не ЗначениеЗаполнено(ДокументОбъект.Склад) Тогда
        Сообщить("Не заполнен склад");
        Возврат;
    КонецЕсли;

    Запрос = Новый Запрос;
    Запрос.Текст = 
    "ВЫБРАТЬ
    |    ТоварныеЗапасыОстатки.Товар КАК Товар,
    |    ТоварныеЗапасыОстатки.КоличествоОстаток КАК Количество
    |ИЗ
    |    РегистрНакопления.ТоварныеЗапасы.Остатки(
    |        &ДатаДокумента,
    |        Склад = &Склад
    |            И Товар.ВидТовара = &ВидТовара) КАК ТоварныеЗапасыОстатки";

    Запрос.УстановитьПараметр("ДатаДокумента", КонецДня(ДокументОбъект.Дата));
    Запрос.УстановитьПараметр("Склад", ДокументОбъект.Склад);
    Запрос.УстановитьПараметр("ВидТовара", Перечисления.ВидыТоваров.Товар); // Предполагается перечисление ВидыТоваров

    РезультатЗапроса = Запрос.Выполнить();

    Выборка = РезультатЗапроса.Выбрать();
    Пока Выборка.Следующий() Цикл
        НоваяСтрока = ДокументОбъект.Товары.Добавить();
        НоваяСтрока.Товар = Выборка.Товар;
        НоваяСтрока.Количество = Выборка.Количество;
        // Цена и Сумма остаются незаполненными
    КонецЦикла;

КонецФункции

Функция ЗаполнитьТабличныйДокумент(ТабДокумент, Макет, Дата) Экспорт

    // Очищаем табличный документ перед заполнением
    ТабДокумент.Очистить();

    // Выводим шапку
    ОбластьШапка = Макет.ПолучитьОбласть("Шапка");
    ТабДокумент.Вывести(ОбластьШапка);

    // Формируем запрос к регистру накопления "Взаиморасчеты" на указанную дату
    Запрос = Новый Запрос;
    Запрос.Текст = 
    "ВЫБРАТЬ
    |    ВзаиморасчетыОстатки.Контрагент КАК Контрагент,
    |    ВзаиморасчетыОстатки.СуммаОстаток КАК Задолженность
    |ИЗ
    |    РегистрНакопления.Взаиморасчеты.Остатки(&Дата) КАК ВзаиморасчетыОстатки
    |УПОРЯДОЧИТЬ ПО
    |    Контрагент";

    Запрос.УстановитьПараметр("Дата", Дата);

    Результат = Запрос.Выполнить();

    // Обходим результат запроса и выводим строки
    Выборка = Результат.Выбрать();
    Пока Выборка.Следующий() Цикл
        ОбластьСтрока = Макет.ПолучитьОбласть("Строка");
        ОбластьСтрока.Параметры.Контрагент = Выборка.Контрагент;
        ОбластьСтрока.Параметры.Задолженность = Выборка.Задолженность;
        ТабДокумент.Вывести(ОбластьСтрока);
    КонецЦикла;

КонецФункции

Функция УстановитьСклад(ДокументОбъект) Экспорт
    // Проверяем, что переданный объект существует и содержит табличную часть "Товары"
    Если ДокументОбъект = Неопределено Или Не ДокументОбъект.Метаданные().ТабличныеЧасти.Найти("Товары") <> Неопределено Тогда
        Возврат Ложь;
    КонецЕсли;

    // Устанавливаем значение склада для всех строк табличной части
    Для Каждого СтрокаТЧ Из ДокументОбъект.Товары Цикл
        СтрокаТЧ.СкладСтроки = ДокументОбъект.Склад;
    КонецЦикла;

    Возврат Истина;
КонецФункции

&НаСервере
Функция УдалитьПоследнююЗапись(Валюта)
    Запрос = Новый Запрос;
    Запрос.Текст = "ВЫБРАТЬ
    |    МАКСИМУМ(КурсыВалют.Период) КАК Период
    |ИЗ
    |    РегистрСведений.КурсыВалют КАК КурсыВалют
    |ГДЕ
    |    КурсыВалют.Валюта = &Валюта";
    Запрос.УстановитьПараметр("Валюта", Валюта);
    Результат = Запрос.Выполнить();
    Выборка = Результат.Выбрать();
    Если Не Выборка.Следующий() Тогда
        Возврат Ложь;
    КонецЕсли;
    МаксПериод = Выборка.Период;

    Запись = РегистрыСведений.КурсыВалют.СоздатьМенеджерЗаписи();
    Запись.Период = МаксПериод;
    Запись.Валюта = Валюта;
    Попытка
        Запись.Удалить();
        Возврат Истина;
    Исключение
        Возврат Ложь;
    КонецПопытки;
КонецФункции

Функция НеУстановленыЦены(Поставщик)
    СписокТоваров = Новый СписокЗначений;

    Запрос = Новый Запрос;
    Запрос.Текст = 
    "ВЫБРАТЬ
    |    Товары.Ссылка КАК Товар
    |ИЗ
    |    Справочник.Товары КАК Товары
    |    ЛЕВОЕ СОЕДИНЕНИЕ РегистрСведений.ЦеныТоваров КАК ЦеныТоваров
    |    ПО Товары.Ссылка = ЦеныТоваров.Товар
    |ГДЕ
    |    Товары.Поставщик = &Поставщик
    |    И ЦеныТоваров.Товар ЕСТЬ NULL";

    Запрос.УстановитьПараметр("Поставщик", Поставщик);

    Результат = Запрос.Выполнить();

    Выборка = Результат.Выбрать();
    Пока Выборка.Следующий() Цикл
        СписокТоваров.Добавить(Выборка.Товар);
    КонецЦикла;

    Возврат СписокТоваров;
КонецФункции

Функция ВыгрузитьОстаткиСклада(Склад, МинимальныйОстаток, ФайлJson)

    Запрос = Новый Запрос;
    Запрос.Текст = 
    "ВЫБРАТЬ
    |    ТоварныеЗапасыОстатки.Товар.Код КАК Товар_Код,
    |    ТоварныеЗапасыОстатки.Товар.Наименование КАК Товар_Наименование,
    |    ОКРУГЛИТЬ(ТоварныеЗапасыОстатки.КоличествоОстаток, 0) КАК Остаток
    |ИЗ
    |    РегистрНакопления.ТоварныеЗапасы.Остатки КАК ТоварныеЗапасыОстатки
    |ГДЕ
    |    ТоварныеЗапасыОстатки.Склад = &Склад
    |    И ТоварныеЗапасыОстатки.КоличествоОстаток >= &МинимальныйОстаток
    |УПОРЯДОЧИТЬ ПО
    |    Товар_Код ВОЗР";

    Запрос.УстановитьПараметр("Склад", Склад);
    Запрос.УстановитьПараметр("МинимальныйОстаток", МинимальныйОстаток);

    РезультатЗапроса = Запрос.Выполнить();
    Выборка = РезультатЗапроса.Выбрать();

    МассивРезультатов = Новый Массив;

    Пока Выборка.Следующий() Цикл
        ДанныеТовара = Новый Структура;
        ДанныеТовара.Вставить("Товар_Код", Выборка.Товар_Код);
        ДанныеТовара.Вставить("Товар_Наименование", Выборка.Товар_Наименование);
        ДанныеТовара.Вставить("Остаток", Выборка.Остаток);
        МассивРезультатов.Добавить(ДанныеТовара);
    КонецЦикла;

    ЗаписьJSON = Новый ЗаписьJSON;
    ЗаписьJSON.ОткрытьФайл(ФайлJson, "UTF-8");
    ЗаписьJSON.Записать(МассивРезультатов);
    ЗаписьJSON.Закрыть();

КонецФункции

// Функция возвращает отфильтрованную таблицу значений.
// Фильтрация: Склад = параметр Склад,
// Товар.Наименование содержит подстроку Наименование (без учета регистра).
// Параметры:
//   Таблица - ТаблицаЗначений с колонками: Склад (произвольный тип), Товар (СправочникСсылка.Товары), Количество (Число).
//   Склад   - значение для сравнения с колонкой "Склад".
//   Наименование - Строка - подстрока для поиска в наименовании товара.
// Возвращаемое значение:
//   ТаблицаЗначений с той же структурой, содержащая подходящие строки.
Функция ВыбратьСтрокиТаблицы(Таблица, Склад, Наименование) Экспорт

    Если Таблица = Неопределено ИЛИ Таблица.Количество() = 0 Тогда
        // Если таблица пустая, можно сразу вернуть её копию с правильной структурой
        Результат = Новый ТаблицаЗначений;
        Результат.Колонки.Добавить("Склад");
        Результат.Колонки.Добавить("Товар");
        Результат.Колонки.Добавить("Количество");
        Возврат Результат;
    КонецЕсли;

    Запрос = Новый Запрос;
    // Текст запроса использует разделитель строк | для удобочитаемости
    Запрос.Текст = 
    "ВЫБРАТЬ
    |	Таблица.Склад КАК Склад,
    |	Таблица.Товар КАК Товар,
    |	Таблица.Количество КАК Количество
    |ИЗ
    |	&Таблица КАК Таблица
    |ГДЕ
    |	Таблица.Склад = &Склад
    |	И Таблица.Товар.Наименование ПОДОБНО &Наименование";

    Запрос.УстановитьПараметр("Таблица", Таблица);
    Запрос.УстановитьПараметр("Склад", Склад);
    // Для поиска подстроки используем ПОДОБНО с обрамлением процентами,
    // что соответствует логике "содержит" (регистронезависимо для ПОДОБНО)
    Запрос.УстановитьПараметр("Наименование", "%" + Наименование + "%");

    Возврат Запрос.Выполнить().Выгрузить();

КонецФункции

Функция УшедшийТовар(Дата1, Дата2) Экспорт
    Запрос = Новый Запрос;
    Запрос.Текст = 
    "ВЫБРАТЬ
    |    ТоварныеЗапасыОстатки.Товар КАК Товар,
    |    СУММА(ТоварныеЗапасыОстатки.Количество) КАК Количество
    |ПОМЕСТИТЬ ВТ_ОстаткиНаДату1
    |ИЗ
    |    РегистрНакопления.ТоварныеЗапасы.Остатки(&Дата1) КАК ТоварныеЗапасыОстатки
    |СГРУППИРОВАТЬ ПО
    |    ТоварныеЗапасыОстатки.Товар
    |ИМЕЮЩИЕ
    |    СУММА(ТоварныеЗапасыОстатки.Количество) > 0
    |
    |ИНДЕКСИРОВАТЬ ПО
    |    Товар
    |;
    |
    |ВЫБРАТЬ
    |    ТоварныеЗапасыОстатки.Товар КАК Товар,
    |    СУММА(ТоварныеЗапасыОстатки.Количество) КАК Количество
    |ПОМЕСТИТЬ ВТ_ОстаткиНаДату2
    |ИЗ
    |    РегистрНакопления.ТоварныеЗапасы.Остатки(&Дата2, , , , Ложь) КАК ТоварныеЗапасыОстатки
    |СГРУППИРОВАТЬ ПО
    |    ТоварныеЗапасыОстатки.Товар
    |;
    |
    |ВЫБРАТЬ
    |    ВТ_ОстаткиНаДату1.Товар КАК Товар,
    |    ВТ_ОстаткиНаДату1.Количество КАК Количество
    |ИЗ
    |    ВТ_ОстаткиНаДату1 КАК ВТ_ОстаткиНаДату1
    |    ЛЕВОЕ СОЕДИНЕНИЕ ВТ_ОстаткиНаДату2 КАК ВТ_ОстаткиНаДату2
    |    ПО ВТ_ОстаткиНаДату1.Товар = ВТ_ОстаткиНаДату2.Товар
    |ГДЕ
    |    ВТ_ОстаткиНаДату2.Товар ЕСТЬ NULL
    |    ИЛИ ВТ_ОстаткиНаДату2.Количество = 0";

    Запрос.УстановитьПараметр("Дата1", Дата1);
    Запрос.УстановитьПараметр("Дата2", Дата2);

    РезультатЗапроса = Запрос.Выполнить();

    ТаблицаРезультат = Новый ТаблицаЗначений;
    ТаблицаРезультат.Колонки.Добавить("Товар", Новый ОписаниеТипов("СправочникСсылка.Товары"));
    ТаблицаРезультат.Колонки.Добавить("Количество", Новый ОписаниеТипов("Число", Новый КвалификаторыЧисла(10, 2)));

    Выборка = РезультатЗапроса.Выбрать();
    Пока Выборка.Следующий() Цикл
        Строка = ТаблицаРезультат.Добавить();
        Строка.Товар = Выборка.Товар;
        Строка.Количество = Выборка.Количество;
    КонецЦикла;

    Возврат ТаблицаРезультат;
КонецФункции

Функция ПросроченныеДолги(Дата, МинДолг, СрокДолга)

    // Создаём таблицу результатов с нужными колонками
    ТаблицаРезультат = Новый ТаблицаЗначений;
    ТаблицаРезультат.Колонки.Добавить("Контрагент", Новый ОписаниеТипов("СправочникСсылка.Контрагенты"));
    ТаблицаРезультат.Колонки.Добавить("ДолгВсего", Новый ОписаниеТипов("Число", Новый КвалификаторыЧисла(15,2)));
    ТаблицаРезультат.Колонки.Добавить("ДолгПросроченный", Новый ОписаниеТипов("Число", Новый КвалификаторыЧисла(15,2)));
    ТаблицаРезультат.Колонки.Добавить("ДатаОбразованияДолга", Новый ОписаниеТипов("Дата"));

    // 1. Получаем контрагентов с общим долгом больше МинДолг на заданную дату
    Запрос = Новый Запрос;
    Запрос.Текст = 
    "ВЫБРАТЬ
    |    ВзаиморасчетыОстатки.Контрагент КАК Контрагент,
    |    СУММА(ВзаиморасчетыОстатки.СуммаОстаток) КАК ДолгВсего
    |ИЗ
    |    РегистрНакопления.Взаиморасчеты.Остатки(&Дата, ) КАК ВзаиморасчетыОстатки
    |СГРУППИРОВАТЬ ПО
    |    ВзаиморасчетыОстатки.Контрагент
    |ИМЕЮЩИЕ
    |    СУММА(ВзаиморасчетыОстатки.СуммаОстаток) > &МинДолг";

    Запрос.УстановитьПараметр("Дата", Дата);
    Запрос.УстановитьПараметр("МинДолг", МинДолг);

    РезультатОстатков = Запрос.Выполнить();

    МассивКонтрагентов = Новый Массив;
    СоответствиеДолгВсего = Новый Соответствие;

    Выборка = РезультатОстатков.Выбрать();
    Пока Выборка.Следующий() Цикл
        Контрагент = Выборка.Контрагент;
        МассивКонтрагентов.Добавить(Контрагент);
        СоответствиеДолгВсего.Вставить(Контрагент, Выборка.ДолгВсего);
    КонецЦикла;

    Если МассивКонтрагентов.Количество() = 0 Тогда
        Возврат ТаблицаРезультат;
    КонецЕсли;

    // 2. Получаем все обороты с начала учёта до указанной даты для найденных контрагентов
    ЗапросОборотов = Новый Запрос;
    ЗапросОборотов.Текст = 
    "ВЫБРАТЬ
    |    ВзаиморасчетыОбороты.Контрагент КАК Контрагент,
    |    ВзаиморасчетыОбороты.Период КАК ДатаОборотов,
    |    ВзаиморасчетыОбороты.СуммаПриход КАК Приход,
    |    ВзаиморасчетыОбороты.СуммаРасход КАК Расход
    |ИЗ
    |    РегистрНакопления.Взаиморасчеты.Обороты(
    |        &НачалоПериода,
    |        &КонецПериода,
    |        День,
    |        (Контрагент В (&Контрагенты))
    |    ) КАК ВзаиморасчетыОбороты";

    ЗапросОборотов.УстановитьПараметр("НачалоПериода", '00010101');
    ЗапросОборотов.УстановитьПараметр("КонецПериода", КонецДня(Дата));
    ЗапросОборотов.УстановитьПараметр("Контрагенты", МассивКонтрагентов);

    РезультатОборотов = ЗапросОборотов.Выполнить();

    // Группируем обороты по контрагентам в списки значений
    ДанныеОборотов = Новый Соответствие;
    ВыборкаОборотов = РезультатОборотов.Выбрать();
    Пока ВыборкаОборотов.Следующий() Цикл
        Контрагент = ВыборкаОборотов.Контрагент;
        Список = ДанныеОборотов.Получить(Контрагент);
        Если Список = Неопределено Тогда
            Список = Новый СписокЗначений;
            ДанныеОборотов.Вставить(Контрагент, Список);
        КонецЕсли;

        СтрокаОбор = Новый Структура("Дата, Приход, Расход");
        СтрокаОбор.Дата = ВыборкаОборотов.ДатаОборотов;
        СтрокаОбор.Приход = ВыборкаОборотов.Приход;
        СтрокаОбор.Расход = ВыборкаОборотов.Расход;
        Список.Добавить(СтрокаОбор);
    КонецЦикла;

    // Определяем дату отсечки для просрочки
    ДатаОтсечки = НачалоДня(Дата - СрокДолга);

    // 3. Обрабатываем каждого контрагента методом FIFO
    Для Каждого Контрагент Из МассивКонтрагентов Цикл
        Список = ДанныеОборотов.Получить(Контрагент);
        Если Список = Неопределено Или Список.Количество() = 0 Тогда
            Продолжить;
        КонецЕсли;

        // Сортируем обороты по дате
        МассивОборотов = Новый Массив;
        Для Каждого Эл Из Список Цикл
            МассивОборотов.Добавить(Эл);
        КонецЦикла;
        МассивОборотов.Сортировать("Дата");

        // Модель FIFO: очередь непогашенных приходов
        ОчередьПриходов = Новый Массив;
        ТекущийОстаток = 0;

        Для Каждого Оборот Из МассивОборотов Цикл
            Если Оборот.Приход > 0 Тогда
                ОчередьПриходов.Добавить(Новый Структура("Дата, Сумма", Оборот.Дата, Оборот.Приход));
                ТекущийОстаток = ТекущийОстаток + Оборот.Приход;
            КонецЕсли;
            Если Оборот.Расход > 0 Тогда
                ОсталосьПогасить = Оборот.Расход;
                Пока ОсталосьПогасить > 0 И ОчередьПриходов.Количество() > 0 Цикл
                    ПервыйПриход = ОчередьПриходов[0];
                    Если ПервыйПриход.Сумма <= ОсталосьПогасить Тогда
                        ОсталосьПогасить = ОсталосьПогасить - ПервыйПриход.Сумма;
                        ТекущийОстаток = ТекущийОстаток - ПервыйПриход.Сумма;
                        ОчередьПриходов.Удалить(0);
                    Иначе
                        ПервыйПриход.Сумма = ПервыйПриход.Сумма - ОсталосьПогасить;
                        ТекущийОстаток = ТекущийОстаток - ОсталосьПогасить;
                        ОсталосьПогасить = 0;
                    КонецЕсли;
                КонецЦикла;
            КонецЕсли;
        КонецЦикла;

        // Определяем просроченную сумму и дату образования долга
        ПросроченныйДолг = 0;
        ДатаОбразования = Неопределено;
        ОбщийДолг = СоответствиеДолгВсего.Получить(Контрагент);

        Для Каждого ПриходСлой Из ОчередьПриходов Цикл
            Если ПриходСлой.Дата < ДатаОтсечки Тогда
                ПросроченныйДолг = ПросроченныйДолг + ПриходСлой.Сумма;
            КонецЕсли;
            Если ДатаОбразования = Неопределено Или ПриходСлой.Дата < ДатаОбразования Тогда
                ДатаОбразования = ПриходСлой.Дата;
            КонецЕсли;
        КонецЦикла;

        Если ПросроченныйДолг > 0 Тогда
            СтрокаРезультата = ТаблицаРезультат.Добавить();
            СтрокаРезультата.Контрагент = Контрагент;
            СтрокаРезультата.ДолгВсего = ОбщийДолг;
            СтрокаРезультата.ДолгПросроченный = ПросроченныйДолг;
            СтрокаРезультата.ДатаОбразованияДолга = ДатаОбразования;
        КонецЕсли;
    КонецЦикла;

    Возврат ТаблицаРезультат;

КонецФункции

Функция СоздатьИнтернетПочтовоеСообщение(Письмо, Отправитель) Экспорт
    // Создаем объект почтового сообщения
    Сообщение = Новый ИнтернетПочтовоеСообщение;

    // Тема письма — наименование элемента справочника
    Сообщение.Тема = Письмо.Наименование;

    // Добавляем текст письма (простой текст)
    Если ЗначениеЗаполнено(Письмо.Текст) Тогда
        ТекстПочты = Сообщение.Тексты.Добавить(Письмо.Текст);
        ТекстПочты.ТипТекста = ТипТекстаПочтовогоСообщения.ПростойТекст;
    КонецЕсли;

    // Обрабатываем содержимое (если оно есть)
    Если ЗначениеЗаполнено(Письмо.Содержимое) Тогда
        Если ТипЗнч(Письмо.Содержимое) = Тип("Строка") Тогда
            // Содержимое как HTML-текст
            ТекстHTML = Сообщение.Тексты.Добавить(Письмо.Содержимое);
            ТекстHTML.ТипТекста = ТипТекстаПочтовогоСообщения.HTML;
        ИначеЕсли ТипЗнч(Письмо.Содержимое) = Тип("ДвоичныеДанные") Тогда
            // Если потребуется, здесь можно добавить вложение
            // В рамках задачи не требуется
        КонецЕсли;
    КонецЕсли;

    // Устанавливаем отправителя
    Сообщение.Отправитель.Адрес = Отправитель;

    // Основной получатель (реквизит "Получатель")
    Если ЗначениеЗаполнено(Письмо.Получатель) Тогда
        Адрес = Сообщение.Получатели.Добавить(Письмо.Получатель);
        Адрес.Тип = ТипАдресаПочтовогоСообщения.Кому;
    КонецЕсли;

    // Получатели из табличной части
    Запрос = Новый Запрос;
    Запрос.Текст = 
    "ВЫБРАТЬ
    |    ИсходящиеПисьмаПолучатели.ЭлектроннаяПочта КАК ЭлектроннаяПочта
    |ИЗ
    |    Справочник.ИсходящиеПисьма.Получатели КАК ИсходящиеПисьмаПолучатели
    |ГДЕ
    |    ИсходящиеПисьмаПолучатели.Ссылка = &Письмо";

    Запрос.УстановитьПараметр("Письмо", Письмо);

    Результат = Запрос.Выполнить();

    Выборка = Результат.Выбрать();
    Пока Выборка.Следующий() Цикл
        Если ЗначениеЗаполнено(Выборка.ЭлектроннаяПочта) Тогда
            АдресТЧ = Сообщение.Получатели.Добавить(Выборка.ЭлектроннаяПочта);
            АдресТЧ.Тип = ТипАдресаПочтовогоСообщения.Кому;
        КонецЕсли;
    КонецЦикла;

    Возврат Сообщение;
КонецФункции

&НаСервере
Функция СоздатьДвиженияРегистраПродажи(ДокументСсылка)

    Если ДокументСсылка.Пустая() Тогда
        Возврат;
    КонецЕсли;

    ДокументОбъект = ДокументСсылка.ПолучитьОбъект();
    Если ДокументОбъект = Неопределено Тогда
        ВызватьИсключение "Не удалось получить объект документа";
    КонецЕсли;

    Движения = ДокументОбъект.Движения;
    Движения.Продажи.Очистить();

    Для Каждого СтрокаТЧ Из ДокументОбъект.Товары Цикл
        Движение = Движения.Продажи.Добавить();
        Движение.Период = ДокументОбъект.Дата;
        Движение.Контрагент = ДокументОбъект.Контрагент;
        Движение.Номенклатура = СтрокаТЧ.Номенклатура;
        Движение.Количество = СтрокаТЧ.Количество;
        Движение.Сумма = СтрокаТЧ.Сумма;
        Движение.ВидДвижения = ВидДвиженияНакопления.Приход;
    КонецЦикла;

    Движения.Продажи.Записать();

КонецФункции

Функция ЗаменитьНоменклатуру(НоменклатураИсточник, НоменклатураЗамены, ДатаС, ДатаПо) Экспорт
    // Входные проверки
    Если НоменклатураИсточник = Неопределено ИЛИ НоменклатураЗамены = Неопределено Тогда
        Возврат 0;
    КонецЕсли;

    Запрос = Новый Запрос;
    Запрос.Текст = 
    "ВЫБРАТЬ РАЗЛИЧНЫЕ
    |    Заказ.Ссылка КАК Ссылка
    |ИЗ
    |    Документ.Заказ КАК Заказ
    |    ВНУТРЕННЕЕ СОЕДИНЕНИЕ Документ.Заказ.Товары КАК Товары
    |    ПО Товары.Ссылка = Заказ.Ссылка
    |ГДЕ
    |    Заказ.Дата МЕЖДУ &ДатаС И &ДатаПо
    |    И Заказ.ПометкаУдаления = ЛОЖЬ
    |    И Товары.Товар = &НоменклатураИсточник";

    Запрос.УстановитьПараметр("ДатаС", ДатаС);
    Запрос.УстановитьПараметр("ДатаПо", ДатаПо);
    Запрос.УстановитьПараметр("НоменклатураИсточник", НоменклатураИсточник);

    Результат = Запрос.Выполнить();
    Выборка = Результат.Выбрать();

    КоличествоЗамен = 0;

    Пока Выборка.Следующий() Цикл
        ДокСсылка = Выборка.Ссылка;
        Попытка
            ДокОбъект = ДокСсылка.ПолучитьОбъект();
            // Доп. проверка на пометку удаления (параллельные изменения)
            Если ДокОбъект.ПометкаУдаления Тогда
                Продолжить;
            КонецЕсли;

            ЗаменаБыла = Ложь;
            ПроведенИсходно = ДокОбъект.Проведен;

            Для Каждого СтрокаТЧ Из ДокОбъект.Товары Цикл
                Если СтрокаТЧ.Товар = НоменклатураИсточник Тогда
                    СтрокаТЧ.Товар = НоменклатураЗамены;
                    ЗаменаБыла = Истина;
                КонецЕсли;
            КонецЦикла;

            Если ЗаменаБыла Тогда
                Если ПроведенИсходно Тогда
                    ДокОбъект.Записать(РежимЗаписиДокумента.Проведение);
                Иначе
                    ДокОбъект.Записать(РежимЗаписиДокумента.Запись);
                КонецЕсли;
                КоличествоЗамен = КоличествоЗамен + 1;
            КонецЕсли;
        Исключение
            // Логирование ошибки (в реальном коде — запись в журнал регистрации)
            Сообщить("Ошибка обработки документа " + ДокСсылка + ": " + ОписаниеОшибки());
        КонецПопытки;
    КонецЦикла;

    Возврат КоличествоЗамен;
КонецФункции

Функция РасчетКомиссииМенеджера(ТаблицаКомиссий, Процент, ДатаС, ДатаПо)
    // Проверяем и формируем колонки таблицы, если их нет
    Если ТаблицаКомиссий.Колонки.Найти("Менеджер") = Неопределено Тогда
        ТаблицаКомиссий.Колонки.Добавить("Менеджер");
    КонецЕсли;
    Если ТаблицаКомиссий.Колонки.Найти("СуммаЗаказов") = Неопределено Тогда
        ТаблицаКомиссий.Колонки.Добавить("СуммаЗаказов", Новый ОписаниеТипов("Число"));
    КонецЕсли;
    Если ТаблицаКомиссий.Колонки.Найти("Комиссия") = Неопределено Тогда
        ТаблицаКомиссий.Колонки.Добавить("Комиссия", Новый ОписаниеТипов("Число"));
    КонецЕсли;

    // Очищаем таблицу перед заполнением
    ТаблицаКомиссий.Очистить();

    // Формируем запрос для получения агрегированных данных по менеджерам
    Запрос = Новый Запрос;
    Запрос.Текст = 
    "ВЫБРАТЬ
    |   Заказ.Автор КАК Менеджер,
    |   СУММА(Товары.Сумма) КАК СуммаЗаказов
    |ИЗ
    |   Документ.Заказ КАК Заказ
    |      ВНУТРЕННЕЕ СОЕДИНЕНИЕ Документ.Заказ.Товары КАК Товары
    |      ПО Заказ.Ссылка = Товары.Ссылка
    |ГДЕ
    |   Заказ.Проведен
    |   И Заказ.Дата МЕЖДУ &ДатаС И &ДатаПо
    |СГРУППИРОВАТЬ ПО
    |   Заказ.Автор";

    Запрос.УстановитьПараметр("ДатаС", ДатаС);
    Запрос.УстановитьПараметр("ДатаПо", ДатаПо);

    РезультатЗапроса = Запрос.Выполнить();
    Выборка = РезультатЗапроса.Выбрать();

    // Заполняем таблицу результатами
    Пока Выборка.Следующий() Цикл
        НоваяСтрока = ТаблицаКомиссий.Добавить();
        НоваяСтрока.Менеджер = Выборка.Менеджер;
        НоваяСтрока.СуммаЗаказов = Выборка.СуммаЗаказов;
        // Процент передан как целое число (например 5 для 5%)
        НоваяСтрока.Комиссия = Выборка.СуммаЗаказов * Процент / 100;
    КонецЦикла;

    Возврат ТаблицаКомиссий;
КонецФункции

Функция ПолучитьШиринуВысотуКартинкиИзФайлаJPEG(ИмяФайла)

    Результат = Новый Структура;
    Результат.Вставить("Высота", 0);
    Результат.Вставить("Ширина", 0);

    Чтение = Новый ЧтениеДвоичныхДанных(ИмяФайла);
    Попытка
        // Проверяем SOI маркер (0xFF 0xD8)
        ПервыйБайт = Чтение.Прочитать(1);
        Если ПервыйБайт = Неопределено Или ПервыйБайт.Размер() = 0 Тогда
            ВызватьИсключение "Файл пуст или не является JPEG";
        КонецЕсли;
        Если ПервыйБайт.ПолучитьБайты()[0] <> 255 Тогда
            ВызватьИсключение "Неверный формат JPEG: отсутствует маркер SOI";
        КонецЕсли;

        ВторойБайт = Чтение.Прочитать(1);
        Если ВторойБайт = Неопределено Или ВторойБайт.Размер() = 0 Тогда
            ВызватьИсключение "Неверный формат JPEG: отсутствует маркер SOI";
        КонецЕсли;
        Если ВторойБайт.ПолучитьБайты()[0] <> 216 Тогда // 0xD8
            ВызватьИсключение "Неверный формат JPEG: отсутствует маркер SOI";
        КонецЕсли;

        Пока Истина Цикл
            БайтДанные = Чтение.Прочитать(1);
            Если БайтДанные = Неопределено Или БайтДанные.Размер() = 0 Тогда
                Прервать;
            КонецЕсли;
            Байт = БайтДанные.ПолучитьБайты()[0];

            Если Байт <> 255 Тогда
                Продолжить;
            КонецЕсли;

            // Читаем следующий байт после 0xFF
            СледДанные = Чтение.Прочитать(1);
            Если СледДанные = Неопределено Или СледДанные.Размер() = 0 Тогда
                Прервать;
            КонецЕсли;
            Маркер = СледДанные.ПолучитьБайты()[0];

            // Обработка забивочных байтов (0xFF 0x00) – встречается в данных сканирования
            Если Маркер = 0 Тогда
                Продолжить;
            КонецЕсли;

            // Пропускаем множественные 0xFF
            Если Маркер = 255 Тогда
                Продолжить;
            КонецЕсли;

            Если Маркер = 216 Тогда // SOI – игнорируем, если вдруг встретился снова
                Продолжить;
            ИначеЕсли Маркер = 217 Тогда // EOI – конец файла
                Прервать;
            ИначеЕсли Маркер = 218 Тогда // SOS – начало данных изображения, размеры уже должны быть найдены
                Прервать;
            ИначеЕсли Маркер >= 192 И Маркер <= 195 Тогда // SOF0 – SOF3
                // Читаем длину сегмента (2 байта)
                ДлинаДанные = Чтение.Прочитать(2);
                Если ДлинаДанные = Неопределено Или ДлинаДанные.Размер() < 2 Тогда
                    ВызватьИсключение "Ошибка чтения сегмента SOF";
                КонецЕсли;
                БайтыДлины = ДлинаДанные.ПолучитьБайты();
                ДлинаСегмента = БайтыДлины[0] * 256 + БайтыДлины[1];

                // Пропускаем точность данных (1 байт)
                Чтение.Прочитать(1);

                // Читаем высоту (2 байта, big-endian)
                ДанныеВысоты = Чтение.Прочитать(2);
                Если ДанныеВысоты = Неопределено Или ДанныеВысоты.Размер() < 2 Тогда
                    ВызватьИсключение "Ошибка чтения высоты изображения";
                КонецЕсли;
                БайтыВысоты = ДанныеВысоты.ПолучитьБайты();
                Высота = БайтыВысоты[0] * 256 + БайтыВысоты[1];

                // Читаем ширину (2 байта, big-endian)
                ДанныеШирины = Чтение.Прочитать(2);
                Если ДанныеШирины = Неопределено Или ДанныеШирины.Размер() < 2 Тогда
                    ВызватьИсключение "Ошибка чтения ширины изображения";
                КонецЕсли;
                БайтыШирины = ДанныеШирины.ПолучитьБайты();
                Ширина = БайтыШирины[0] * 256 + БайтыШирины[1];

                Результат.Высота = Высота;
                Результат.Ширина = Ширина;
                Возврат Результат;
            Иначе
                // Любой другой маркер с длиной: читаем длину и пропускаем содержимое
                ДлинаДанные = Чтение.Прочитать(2);
                Если ДлинаДанные = Неопределено Или ДлинаДанные.Размер() < 2 Тогда
                    ВызватьИсключение "Ошибка чтения длины маркера";
                КонецЕсли;
                БайтыДлины = ДлинаДанные.ПолучитьБайты();
                ДлинаСегмента = БайтыДлины[0] * 256 + БайтыДлины[1];
                // Пропускаем данные сегмента (длина включает эти 2 байта)
                Чтение.Пропустить(ДлинаСегмента - 2);
            КонецЕсли;
        КонецЦикла;

        ВызватьИсключение "Не удалось найти размеры изображения в JPEG-файле";
    Исключение
        Чтение.Закрыть();
        ВызватьИсключение;
    КонецПопытки;

КонецФункции

Функция ИзвлечьПартииФИФО(ТаблицаПартий, Сумма)
    // Создаём результирующую таблицу с теми же колонками, что и исходная
    Результат = Новый ТаблицаЗначений;
    Для каждого Колонка из ТаблицаПартий.Колонки Цикл
        Результат.Колонки.Добавить(Колонка.Имя, Колонка.ТипЗначения, Колонка.Заголовок);
    КонецЦикла;

    // Если требуемая сумма не положительна – возвращаем пустую таблицу
    Если Сумма <= 0 Тогда
        Возврат Результат;
    КонецЕсли;

    // Сортируем партии по дате (FIFO: сначала более ранние)
    ОтсортированнаяТаблица = ТаблицаПартий.Скопировать();
    ОтсортированнаяТаблица.Сортировать("Дата");

    НакопленнаяСумма = 0;
    Для каждого Строка из ОтсортированнаяТаблица Цикл
        Если НакопленнаяСумма + Строка.Сумма <= Сумма Тогда
            // Партия помещается целиком
            НоваяСтрока = Результат.Добавить();
            ЗаполнитьЗначенияСвойств(НоваяСтрока, Строка);
            НакопленнаяСумма = НакопленнаяСумма + Строка.Сумма;
        ИначеЕсли НакопленнаяСумма < Сумма Тогда
            // Последняя партия – частично, чтобы точно выйти на требуемую сумму
            Остаток = Сумма - НакопленнаяСумма;
            Если Остаток > 0 Тогда
                НоваяСтрока = Результат.Добавить();
                ЗаполнитьЗначенияСвойств(НоваяСтрока, Строка);
                НоваяСтрока.Сумма = Остаток;
                НакопленнаяСумма = Сумма;
            КонецЕсли;
            Прервать;
        Иначе
            // Уже набрали нужную сумму
            Прервать;
        КонецЕсли;
    КонецЦикла;

    Возврат Результат;
КонецФункции

Функция ДополнитьТаблицуЗначениямиИзВторой(Таблица1, Таблица2, КолонкаУникальности)
    // Проверка типов аргументов
    Если ТипЗнч(Таблица1) <> Тип("ТаблицаЗначений") Или ТипЗнч(Таблица2) <> Тип("ТаблицаЗначений") Тогда
        ВызватьИсключение "Параметры должны быть таблицами значений";
    КонецЕсли;

    // Проверка наличия колонки уникальности в обеих таблицах
    Если Таблица1.Колонки.Найти(КолонкаУникальности) = Неопределено Тогда
        ВызватьИсключение "Колонка '" + КолонкаУникальности + "' не найдена в первой таблице";
    КонецЕсли;
    Если Таблица2.Колонки.Найти(КолонкаУникальности) = Неопределено Тогда
        ВызватьИсключение "Колонка '" + КолонкаУникальности + "' не найдена во второй таблице";
    КонецЕсли;

    // Соответствие для быстрого поиска уже существующих уникальных значений
    УникальныеЗначения = Новый Соответствие;
    Для Каждого Строка Из Таблица1 Цикл
        Значение = Строка[КолонкаУникальности];
        Если Значение <> Неопределено Тогда
            УникальныеЗначения.Вставить(Значение, Истина);
        КонецЕсли;
    КонецЦикла;

    // Массив для временного хранения данных строк, которые требуется добавить
    ДанныеДляВставки = Новый Массив;

    // Отбор строк из второй таблицы, отсутствующих в первой, с обеспечением уникальности внутри второй таблицы
    Для Каждого Строка2 Из Таблица2 Цикл
        Значение = Строка2[КолонкаУникальности];
        Если Значение = Неопределено Тогда
            Продолжить; // По условию значения заполнены, но страховка не помешает
        КонецЕсли;

        Если Не УникальныеЗначения.Получить(Значение) Тогда
            // Фиксируем значение как использованное, чтобы избежать дублирования из второй таблицы
            УникальныеЗначения.Вставить(Значение, Истина);

            // Сохраняем все значения строки в структуру
            ДанныеСтроки = Новый Структура;
            Для Каждого Колонка Из Таблица2.Колонки Цикл
                ДанныеСтроки.Вставить(Колонка.Имя, Строка2[Колонка.Имя]);
            КонецЦикла;
            ДанныеДляВставки.Добавить(ДанныеСтроки);
        КонецЕсли;
    КонецЦикла;

    // Вставка собранных строк в начало первой таблицы с сохранением исходного порядка
    Для Индекс = ДанныеДляВставки.Количество() - 1 По 0 Цикл -1 Цикл
        ДанныеСтроки = ДанныеДляВставки[Индекс];
        НоваяСтрока = Таблица1.Вставить(0);
        Для Каждого Элемент Из ДанныеСтроки Цикл
            НоваяСтрока[Элемент.Ключ] = Элемент.Значение;
        КонецЦикла;
    КонецЦикла;

КонецФункции

task:
Создай функцию ОбъектВСтруктуру(ОбъектДанных) принимает на вход объект и возвращает структуру с данными полученными из этого объекта 
1) Если у объекта есть табличные части, реквизиты и значения каждой табличной части должны быть представлены как массив со структурами
2) Стандартные реквизиты (Код, Наименование, Дата, и т.д.) тоже должный быть в структуре ответа
3) Общий вид выходной структуры 
{ "Реквизит1": ЗначениеРеквизита1, 
...    
"РеквизитN": ЗначениеРеквизитаN,
"ТабличныеЧасти": [  
	{ 
		"ИмяТабличнойЧасти1": [ 
			{
				"Реквизит1ТабличнойЧасти1": ЗначениеРеквизита1ВСтроке1,     
				"Реквизит2ТабличнойЧасти1": ЗначениеРеквизита2ВСтроке1,  
				...
			},
			{
				"Реквизит1ТабличнойЧасти1": ЗначениеРеквизита1ВСтроке2,     
				"Реквизит2ТабличнойЧасти1": ЗначениеРеквизита2ВСтроке2,  
				...
			},	
		]
	}
]
}

output:
// Функция преобразует объект 1С (справочник, документ и т.п.) в структуру.
// В результирующую структуру включаются все обычные и стандартные реквизиты,
// а также табличные части в виде массива, каждый элемент которого — структура
// с единственным ключом (имя табличной части) и значением — массивом структур строк.
//
// Параметры:
//   ОбъектДанных - объект 1С (например, ДокументОбъект, СправочникОбъект), 
//                  для которого нужно построить представление.
// Возвращаемое значение:
//   Структура - данные объекта в описанном формате.
Функция ОбъектВСтруктуру(ОбъектДанных) Экспорт
    // Получаем метаданные объекта
    Мета = ОбъектДанных.Метаданные();

    Результат = Новый Структура;
    МассивТабличныхЧастей = Новый Массив; // будет содержать структуры вида {ИмяТЧ: [строки]}

    // Запоминаем имена табличных частей, чтобы не дублировать их как реквизиты
    ИменаТабличныхЧастей = Новый Соответствие;
    Для Каждого ТЧ_Мета Из Мета.ТабличныеЧасти Цикл
        ИменаТабличныхЧастей.Вставить(ТЧ_Мета.Имя, Истина);
    КонецЦикла;

    // Обрабатываем обычные и стандартные реквизиты объекта
    Для Каждого РеквизитМета Из Мета.Реквизиты Цикл
        ИмяРеквизита = РеквизитМета.Имя;
        // Пропускаем реквизиты, которые на самом деле являются табличными частями
        Если ИменаТабличныхЧастей.Получить(ИмяРеквизита) = Неопределено Тогда
            Попытка
                Значение = ОбъектДанных[ИмяРеквизита];
                Результат.Вставить(ИмяРеквизита, Значение);
            Исключение
                // Если доступ к свойству по каким-либо причинам невозможен,
                // просто пропускаем этот реквизит
            КонецПопытки;
        КонецЕсли;
    КонецЦикла;

    // Обрабатываем табличные части
    Для Каждого ТЧ_Мета Из Мета.ТабличныеЧасти Цикл
        ИмяТЧ = ТЧ_Мета.Имя;
        ТабличнаяЧасть = ОбъектДанных[ИмяТЧ];
        МассивСтрок = Новый Массив;

        Для Каждого СтрокаТЧ Из ТабличнаяЧасть Цикл
            СтрокаСтруктура = Новый Структура;
            // Перебираем все реквизиты строки табличной части,
            // включая стандартный НомерСтроки
            Для Каждого РеквизитТЧ_Мета Из ТЧ_Мета.Реквизиты Цикл
                ИмяРеквТЧ = РеквизитТЧ_Мета.Имя;
                Попытка
                    Значение = СтрокаТЧ[ИмяРеквТЧ];
                    СтрокаСтруктура.Вставить(ИмяРеквТЧ, Значение);
                Исключение
                    // Пропускаем реквизиты, к которым нет доступа
                КонецПопытки;
            КонецЦикла;
            МассивСтрок.Добавить(СтрокаСтруктура);
        КонецЦикла;

        // Формируем структуру для текущей табличной части: {ИмяТЧ: [строки]}
        ТЧ_Структура = Новый Структура;
        ТЧ_Структура.Вставить(ИмяТЧ, МассивСтрок);
        МассивТабличныхЧастей.Добавить(ТЧ_Структура);
    КонецЦикла;

    // Добавляем массив табличных частей, если он не пуст
    Если МассивТабличныхЧастей.Количество() > 0 Тогда
        Результат.Вставить("ТабличныеЧасти", МассивТабличныхЧастей);
    КонецЕсли;

    Возврат Результат;
КонецФункции

Функция СкачкиЦен(Процент)

    Запрос = Новый Запрос;
    Запрос.Текст = 
    "ВЫБРАТЬ
    |    ЦеныТоваров.Товар КАК Товар,
    |    ЦеныТоваров.Период КАК Период,
    |    ЦеныТоваров.ВидЦен КАК ВидЦен,
    |    ЦеныТоваров.Цена КАК Цена
    |ПОМЕСТИТЬ ВТ_Исходные
    |ИЗ
    |    РегистрСведений.ЦеныТоваров КАК ЦеныТоваров
    |;
    |
    |////////////////////////////////////////////////////////////////////////////////
    |ВЫБРАТЬ
    |    ВТ_Исходные.Товар КАК Товар,
    |    ВТ_Исходные.Период КАК Период,
    |    ВТ_Исходные.Цена КАК Цена,
    |    (ВЫБРАТЬ
    |        КОЛИЧЕСТВО(ВТ2.Период)
    |    ИЗ
    |        ВТ_Исходные КАК ВТ2
    |    ГДЕ
    |        ВТ2.Товар = ВТ_Исходные.Товар
    |        И (ВТ2.Период < ВТ_Исходные.Период
    |                ИЛИ (ВТ2.Период = ВТ_Исходные.Период
    |                    И ВТ2.ВидЦен <= ВТ_Исходные.ВидЦен))) КАК НомерСтроки
    |ПОМЕСТИТЬ ВТ_Нумерованные
    |ИЗ
    |    ВТ_Исходные КАК ВТ_Исходные
    |;
    |
    |////////////////////////////////////////////////////////////////////////////////
    |ВЫБРАТЬ
    |    Тек.Товар КАК Товар,
    |    Пред.Цена КАК ЦенаБыла,
    |    Тек.Цена КАК ЦенаСтала,
    |    Тек.Период КАК ДатаИзменения
    |ИЗ
    |    ВТ_Нумерованные КАК Тек
    |    ВНУТРЕННЕЕ СОЕДИНЕНИЕ ВТ_Нумерованные КАК Пред
    |    ПО Тек.Товар = Пред.Товар
    |        И Тек.НомерСтроки = Пред.НомерСтроки + 1
    |ГДЕ
    |    Пред.Цена > 0
    |    И (Тек.Цена - Пред.Цена) / Пред.Цена * 100 > &Процент";

    Запрос.УстановитьПараметр("Процент", Процент);
    Результат = Запрос.Выполнить();

    ТаблицаРезультат = Новый ТаблицаЗначений;
    ТаблицаРезультат.Колонки.Добавить("Товар", Новый ОписаниеТипов("СправочникСсылка.Товары"));
    ТаблицаРезультат.Колонки.Добавить("ЦенаБыла", Новый ОписаниеТипов("Число", Новый КвалификаторыЧисла(10,2)));
    ТаблицаРезультат.Колонки.Добавить("ЦенаСтала", Новый ОписаниеТипов("Число", Новый КвалификаторыЧисла(10,2)));
    ТаблицаРезультат.Колонки.Добавить("ДатаИзменения", Новый ОписаниеТипов("Дата"));

    Выборка = Результат.Выбрать();
    Пока Выборка.Следующий() Цикл
        НоваяСтрока = ТаблицаРезультат.Добавить();
        НоваяСтрока.Товар = Выборка.Товар;
        НоваяСтрока.ЦенаБыла = Выборка.ЦенаБыла;
        НоваяСтрока.ЦенаСтала = Выборка.ЦенаСтала;
        НоваяСтрока.ДатаИзменения = Выборка.ДатаИзменения;
    КонецЦикла;

    Возврат ТаблицаРезультат;

КонецФункции

