Функция СформироватьОтчетПолучитьОстаток(Склад, Товар, Строка, Колонка) Экспорт

    // Получаем основную схему компоновки данных отчета
    СхемаКомпоновкиДанных = Отчеты.ОстаткиТоваровНаСкладах.ПолучитьМакет("ОсновнаяСхемаКомпоновкиДанных");

    // Создаем компоновщик настроек и загружаем настройки по умолчанию
    КомпоновщикНастроек = Новый КомпоновщикНастроекКомпоновкиДанных;
    КомпоновщикНастроек.Инициализировать(Новый ИсточникДоступныхНастроекКомпоновкиДанных(СхемаКомпоновкиДанных));
    КомпоновщикНастроек.ЗагрузитьНастройки(СхемаКомпоновкиДанных.НастройкиПоУмолчанию);

    Настройки = КомпоновщикНастроек.Настройки;

    // Добавляем отбор по складу
    ЭлементОтбораСклад = Настройки.Отбор.Элементы.Добавить(Тип("ЭлементОтбораКомпоновкиДанных"));
    ЭлементОтбораСклад.ЛевоеЗначение = Новый ПолеКомпоновкиДанных("Склад");
    ЭлементОтбораСклад.ВидСравнения = ВидСравненияКомпоновкиДанных.Равно;
    ЭлементОтбораСклад.ПравоеЗначение = Склад;

    // Добавляем отбор по товару
    ЭлементОтбораТовар = Настройки.Отбор.Элементы.Добавить(Тип("ЭлементОтбораКомпоновкиДанных"));
    ЭлементОтбораТовар.ЛевоеЗначение = Новый ПолеКомпоновкиДанных("Товар");
    ЭлементОтбораТовар.ВидСравнения = ВидСравненияКомпоновкиДанных.Равно;
    ЭлементОтбораТовар.ПравоеЗначение = Товар;

    // Компонуем макет
    МакетКомпоновки = Новый МакетКомпоновкиДанных;
    МакетКомпоновки.Выполнить(СхемаКомпоновкиДанных, Настройки, , , Тип("ГенераторМакетаКомпоновкиДанныхДляКоллекцииЗначений"));

    // Выполняем компоновку данных
    ПроцессорКомпоновкиДанных = Новый ПроцессорКомпоновкиДанных;
    ПроцессорКомпоновкиДанных.Инициализировать(МакетКомпоновки);

    // Выводим результат в табличный документ
    ТабДок = Новый ТабличныйДокумент;
    ПроцессорВывода = Новый ПроцессорВыводаРезультатаКомпоновкиДанныхВТабличныйДокумент;
    ПроцессорВывода.УстановитьДокумент(ТабДок);
    ПроцессорВывода.Вывести(ПроцессорКомпоновкиДанных);

    // Извлекаем значение из указанной ячейки
    ЗначениеЯчейки = ТабДок.Область(Строка, Колонка).Текст;

    // Преобразуем в целое число (если ячейка пуста — возвращаем 0)
    Возврат ?(ЗначениеЗаполнено(ЗначениеЯчейки), Цел(Число(ЗначениеЯчейки)), 0);

КонецФункции

Функция ЗаполнитьТабличнуюЧастьЗаказаЦенами(Заказ, ВидЦен)

    // Получаем объект документа по ссылке, чтобы иметь возможность изменять табличную часть
    ОбъектЗаказ = Заказ.ПолучитьОбъект();

    Если ОбъектЗаказ = Неопределено Тогда
        Возврат Заказ; // если документ не найден (например, помечен на удаление) — выходим без изменений
    КонецЕсли;

    // Формируем запрос, который за одно обращение к базе данных рассчитывает итоговые цены и суммы
    Запрос = Новый Запрос;
    Запрос.Текст = 
    "ВЫБРАТЬ
    |    Товары.НомерСтроки КАК НомерСтроки,
    |    ВЫБОР
    |        КОГДА Товары.Товар ЕСТЬ NULL ТОГДА 0
    |        ИНАЧЕ ЕСТЬNULL(ВЫБОР
    |                КОГДА ЦеныСрез.Цена ЕСТЬ NULL ТОГДА Товары.Цена
    |                ИНАЧЕ ЦеныСрез.Цена
    |            КОНЕЦ, 0)
    |    КОНЕЦ КАК Цена,
    |    Товары.Количество * ВЫБОР
    |        КОГДА Товары.Товар ЕСТЬ NULL ТОГДА 0
    |        ИНАЧЕ ЕСТЬNULL(ВЫБОР
    |                КОГДА ЦеныСрез.Цена ЕСТЬ NULL ТОГДА Товары.Цена
    |                ИНАЧЕ ЦеныСрез.Цена
    |            КОНЕЦ, 0)
    |    КОНЕЦ КАК Сумма
    |ИЗ
    |    Документ.Заказ.Товары КАК Товары
    |        ЛЕВОЕ СОЕДИНЕНИЕ РегистрСведений.ЦеныТоваров.СрезПоследних(
    |                &ДатаДокумента,
    |                ВидЦен = &ВидЦен,
    |                Товар = Товары.Товар) КАК ЦеныСрез
    |        ПО Товары.Товар = ЦеныСрез.Товар
    |ГДЕ
    |    Товары.Ссылка = &СсылкаЗаказ
    |УПОРЯДОЧИТЬ ПО
    |    Товары.НомерСтроки";

    Запрос.УстановитьПараметр("ДатаДокумента", ОбъектЗаказ.Дата);
    Запрос.УстановитьПараметр("ВидЦен", ВидЦен);
    Запрос.УстановитьПараметр("СсылкаЗаказ", Заказ);

    // Выполняем запрос и обрабатываем результат
    Выборка = Запрос.Выполнить().Выбрать();
    Пока Выборка.Следующий() Цикл
        СтрокаТЧ = ОбъектЗаказ.Товары.Получить(Выборка.НомерСтроки);
        СтрокаТЧ.Цена = Выборка.Цена;
        СтрокаТЧ.Сумма = Выборка.Сумма;
    КонецЦикла;

    // Сохраняем изменения документа
    ОбъектЗаказ.Записать();

    // Возвращаем ссылку на изменённый документ
    Возврат ОбъектЗаказ.Ссылка;

КонецФункции

Функция ПолучитьОстатокНоменклатуры(Номенклатура, Склад, Дата)

    Запрос = Новый Запрос;
    Запрос.Текст = 
    "ВЫБРАТЬ
    |   ЕСТЬNULL(ТоварныеЗапасыОстатки.КоличествоОстаток, 0) КАК Остаток
    |ИЗ
    |   РегистрНакопления.ТоварныеЗапасы.Остатки(
    |       &Дата,
    |       Товар = &Номенклатура
    |       И Склад = &Склад) КАК ТоварныеЗапасыОстатки";

    Запрос.УстановитьПараметр("Дата", Дата);
    Запрос.УстановитьПараметр("Номенклатура", Номенклатура);
    Запрос.УстановитьПараметр("Склад", Склад);

    Результат = Запрос.Выполнить();

    Если Результат.Пустой() Тогда
        Возврат 0;
    Иначе
        Выборка = Результат.Выбрать();
        Выборка.Следующий();
        Возврат Выборка.Остаток;
    КонецЕсли;

КонецФункции

Функция ЗагрузитьПрайсЛистИзCSV(ПутьКФайлу, ВидЦен)

    // Инициализация структуры результата
    ТаблицаОшибок = Новый ТаблицаЗначений;
    ТаблицаОшибок.Колонки.Добавить("НомерСтроки", Новый ОписаниеТипов("Число"));
    ТаблицаОшибок.Колонки.Добавить("Причина", Новый ОписаниеТипов("Строка"));

    Результат = Новый Структура;
    Результат.Вставить("КоличествоОбработанныхСтрок", 0);
    Результат.Вставить("ТаблицаОшибок", ТаблицаОшибок);

    // Проверка корректности переданного ВидаЦен
    Если ТипЗнч(ВидЦен) <> Тип("СправочникСсылка.ВидыЦен") Тогда
        НоваяОшибка = ТаблицаОшибок.Добавить();
        НоваяОшибка.НомерСтроки = 0;
        НоваяОшибка.Причина = "Передан некорректный вид цены";
        Возврат Результат;
    КонецЕсли;

    // Открытие файла
    Чтение = Новый ЧтениеТекста;
    Попытка
        Чтение.Открыть(ПутьКФайлу, "UTF-8"); // Предполагаем кодировку UTF-8
    Исключение
        НоваяОшибка = ТаблицаОшибок.Добавить();
        НоваяОшибка.НомерСтроки = 0;
        НоваяОшибка.Причина = "Ошибка открытия файла: " + ОписаниеОшибки();
        Возврат Результат;
    КонецПопытки;

    КоличествоОбработанныхСтрок = 0;
    НомерСтроки = 0;

    // Построчное чтение и обработка
    Пока Чтение.Строка(Стр) Цикл
        НомерСтроки = НомерСтроки + 1;
        Стр = СокрЛП(Стр);
        Если Стр = "" Тогда
            Продолжить;
        КонецЕсли;

        Попытка
            // Определение разделителя
            Разделитель = ";";
            МассивЧастей = СтрРазделить(Стр, Разделитель, Ложь);
            Если МассивЧастей.Количество() <> 3 Тогда
                Разделитель = ",";
                МассивЧастей = СтрРазделить(Стр, Разделитель, Ложь);
            КонецЕсли;
            Если МассивЧастей.Количество() <> 3 Тогда
                ВызватьИсключение "Неверный формат строки. Ожидается 3 колонки: Артикул, Наименование, Цена";
            КонецЕсли;

            Артикул = СокрЛП(МассивЧастей[0]);
            Наименование = СокрЛП(МассивЧастей[1]);
            ЦенаСтрокой = СокрЛП(МассивЧастей[2]);

            // Преобразование цены
            Цена = Число(ЦенаСтрокой);

            // Проверка на пустоту ключевых полей
            Если ПустаяСтрока(Артикул) И ПустаяСтрока(Наименование) Тогда
                ВызватьИсключение "Артикул и наименование не могут быть одновременно пустыми";
            КонецЕсли;

            // Поиск товара
            НайденныйТовар = Неопределено;

            // 1. Поиск по артикулу и наименованию
            Если Не ПустаяСтрока(Артикул) И Не ПустаяСтрока(Наименование) Тогда
                НайденныйТовар = НайтиТоварПоАртикулуИНаименованию(Артикул, Наименование);
            КонецЕсли;

            // 2. Если не найден – поиск только по артикулу
            Если НайденныйТовар = Неопределено И Не ПустаяСтрока(Артикул) Тогда
                НайденныйТовар = НайтиТоварПоАртикулу(Артикул);
            КонецЕсли;

            // 3. Если не найден – поиск только по наименованию
            Если НайденныйТовар = Неопределено И Не ПустаяСтрока(Наименование) Тогда
                НайденныйТовар = НайтиТоварПоНаименованию(Наименование);
            КонецЕсли;

            Если НайденныйТовар = Неопределено Тогда
                ВызватьИсключение "Товар не найден (артикул: " + Артикул + ", наименование: " + Наименование + ")";
            КонецЕсли;

            // Запись цены в регистр сведений на начало текущего дня
            МенеджерЗаписи = РегистрыСведений.ЦеныТоваров.СоздатьМенеджерЗаписи();
            МенеджерЗаписи.Период = НачалоДня(ТекущаяДатаСеанса());
            МенеджерЗаписи.Товар = НайденныйТовар;
            МенеджерЗаписи.ВидЦен = ВидЦен;
            МенеджерЗаписи.Цена = Цена;
            МенеджерЗаписи.Записать();

            КоличествоОбработанныхСтрок = КоличествоОбработанныхСтрок + 1;

        Исключение
            НоваяОшибка = ТаблицаОшибок.Добавить();
            НоваяОшибка.НомерСтроки = НомерСтроки;
            НоваяОшибка.Причина = ОписаниеОшибки();
        КонецПопытки;

    КонецЦикла;

    Чтение.Закрыть();
    Результат.КоличествоОбработанныхСтрок = КоличествоОбработанныхСтрок;
    Возврат Результат;

КонецФункции

// Вспомогательные функции поиска товара

Функция НайтиТоварПоАртикулуИНаименованию(Артикул, Наименование)
    Запрос = Новый Запрос;
    Запрос.Текст = 
    "ВЫБРАТЬ
    |   Товары.Ссылка КАК Ссылка
    |ИЗ
    |   Справочник.Товары КАК Товары
    |ГДЕ
    |   Товары.Артикул = &Артикул
    |   И Товары.Наименование = &Наименование";

    Запрос.УстановитьПараметр("Артикул", Артикул);
    Запрос.УстановитьПараметр("Наименование", Наименование);

    Результат = Запрос.Выполнить();
    Если Результат.Пустой() Тогда
        Возврат Неопределено;
    Иначе
        Выборка = Результат.Выбрать();
        Выборка.Следующий();
        Возврат Выборка.Ссылка;
    КонецЕсли;
