Функция ПолучитьАктуальнуюЦену(Товар, ВидЦен, Дата)
    Запрос = Новый Запрос;
    Запрос.Текст = 
    "ВЫБРАТЬ
    |    ЦеныТоваровСрезПоследних.Цена КАК Цена
    |ИЗ
    |    РегистрСведений.ЦеныТоваров.СрезПоследних(
    |        &Период,
    |        Товар = &Товар
    |            И ВидЦен = &ВидЦен) КАК ЦеныТоваровСрезПоследних";

    Запрос.УстановитьПараметр("Период", Дата);
    Запрос.УстановитьПараметр("Товар", Товар);
    Запрос.УстановитьПараметр("ВидЦен", ВидЦен);

    Результат = Запрос.Выполнить();
    Если Результат.Пустой() Тогда
        Возврат 0;
    КонецЕсли;

    Выборка = Результат.Выбрать();
    Выборка.Следующий();
    Возврат Выборка.Цена;
КонецФункции

// Функция выгружает таблицу значений в CSV-файл с разделителем ";".
// Первая строка содержит заголовки колонок.
// Файл сохраняется в каталог временных файлов, используется переданное имя файла.
// Возвращает полный путь к созданному файлу.
//
// Параметры:
//   ТаблицаДанных - ТаблицаЗначений - данные для выгрузки.
//   ПутьФайла     - Строка          - имя файла (может содержать относительный путь).
// 
// Возвращаемое значение:
//   Строка - полный путь к созданному CSV-файлу.
Функция ВыгрузитьТаблицуВCSV(ТаблицаДанных, ПутьФайла) Экспорт

    // Проверка типа входного параметра
    Если ТипЗнч(ТаблицаДанных) <> Тип("ТаблицаЗначений") Тогда
        ВызватьИсключение "Параметр ТаблицаДанных должен быть типа ТаблицаЗначений";
    КонецЕсли;

    // Формируем полный путь к файлу в каталоге временных файлов
    ПолныйПуть = КаталогВременныхФайлов() + ПутьФайла;

    // Создаем объект записи текста (UTF-8 без BOM для совместимости)
    Запись = Новый ЗаписьТекста(ПолныйПуть, КодировкаТекста.UTF8NoBOM);

    // Вспомогательная функция для экранирования значения CSV
    Функция ЭкранироватьCSV(Значение)
        СтроковоеЗначение = Строка(Значение);
        Если СтроковоеЗначение = Неопределено Тогда
            СтроковоеЗначение = "";
        КонецЕсли;

        // Если значение содержит разделитель, кавычку или перевод строки, заключаем в кавычки
        Если Найти(СтроковоеЗначение, ";") > 0 
           Или Найти(СтроковоеЗначение, """") > 0 
           Или Найти(СтроковоеЗначение, Символы.ПС) > 0 
           Или Найти(СтроковоеЗначение, Символы.ВК) > 0 Тогда
            // Удваиваем кавычки внутри значения
            СтроковоеЗначение = СтрЗаменить(СтроковоеЗначение, """", """""");
            Возврат """" + СтроковоеЗначение + """";
        Иначе
            Возврат СтроковоеЗначение;
        КонецЕсли;
    КонецФункции

    // Формируем строку заголовков
    Заголовки = Новый Массив;
    Для Каждого Колонка Из ТаблицаДанных.Колонки Цикл
        Заголовки.Добавить(ЭкранироватьCSV(Колонка.Имя));
    КонецЦикла;
    Запись.ЗаписатьСтроку(СтрСоединить(Заголовки, ";"));

    // Выгружаем данные построчно
    Для Каждого СтрокаТЗ Из ТаблицаДанных Цикл
        ЗначенияСтроки = Новый Массив;
        Для Каждого Колонка Из ТаблицаДанных.Колонки Цикл
            Значение = СтрокаТЗ[Колонка.Имя];
            ЗначенияСтроки.Добавить(ЭкранироватьCSV(Значение));
        КонецЦикла;
        Запись.ЗаписатьСтроку(СтрСоединить(ЗначенияСтроки, ";"));
    КонецЦикла;

    Запись.Закрыть();

    Возврат ПолныйПуть;

КонецФункции

Функция СвернутьДубли(ТаблицаДанных)
    // Проверка входного параметра
    Если ТипЗнч(ТаблицаДанных) <> Тип("ТаблицаЗначений") Тогда
        ВызватьИсключение "Параметр должен быть таблицей значений";
    КонецЕсли;

    Запрос = Новый Запрос;
    Запрос.Текст = 
    "ВЫБРАТЬ
    |    ТаблицаДанных.КлючСтроки КАК КлючСтроки,
    |    СУММА(ТаблицаДанных.Значение) КАК Значение
    |ИЗ
    |    &ТаблицаДанных КАК ТаблицаДанных
    |
    |СГРУППИРОВАТЬ ПО
    |    ТаблицаДанных.КлючСтроки
    |
    |УПОРЯДОЧИТЬ ПО
    |    КлючСтроки";

    Запрос.УстановитьПараметр("ТаблицаДанных", ТаблицаДанных);

    // Выполняем запрос и получаем таблицу результатов
    РезультатЗапроса = Запрос.Выполнить().Выгрузить();

    // Формируем выходную таблицу с точными типами колонок
    НоваяТаблица = Новый ТаблицаЗначений;
    НоваяТаблица.Колонки.Добавить("КлючСтроки", 
        Новый ОписаниеТипов("Строка", , Новый КвалификаторыСтроки(100)));
    НоваяТаблица.Колонки.Добавить("Значение", 
        Новый ОписаниеТипов("Число"));

    // Заполняем из результата запроса
    Для Каждого Строка Из РезультатЗапроса Цикл
        НоваяСтрока = НоваяТаблица.Добавить();
        НоваяСтрока.КлючСтроки = Строка.КлючСтроки;
        НоваяСтрока.Значение = Строка.Значение;
    КонецЦикла;

    Возврат НоваяТаблица;
КонецФункции

Функция ПолучитьСреднийКурс(Валюта, ДатаНачала, ДатаОкончания)
    Запрос = Новый Запрос;
    Запрос.Текст = 
    "ВЫБРАТЬ
    |    СУММА(Курсы.Курс) КАК Сумма,
    |    КОЛИЧЕСТВО(Курсы.Курс) КАК Количество
    |ИЗ
    |    РегистрСведений.КурсыВалют.СрезПоследних(&Период, Валюта = &Валюта) КАК Курсы";

    Запрос.УстановитьПараметр("Валюта", Валюта);
    Запрос.УстановитьПараметр("Период", 
        Новый СтандартныйПериод(НачПериода(ДатаНачала), КонПериода(ДатаОкончания)));

    Результат = Запрос.Выполнить();
    Выборка = Результат.Выбрать();

    Если Выборка.Следующий() Тогда
        Если Выборка.Количество > 0 Тогда
            Возврат Окр(Выборка.Сумма / Выборка.Количество, 4);
        Иначе
            Возврат Неопределено;
        КонецЕсли;
    Иначе
        Возврат Неопределено;
    КонецЕсли;
КонецФункции

Функция ДобавитьХарактеристикуТовара(Товар, ВидХарактеристики, Значение, Замещать)
    Запрос = Новый Запрос;
    Запрос.Текст = 
    "ВЫБРАТЬ
    |   КОЛИЧЕСТВО(*) КАК Количество,
    |   МАКСИМУМ(Характеристики.Номер) КАК МаксНомер
    |ИЗ
    |   РегистрСведений.Характеристики КАК Характеристики
    |ГДЕ
    |   Характеристики.Объект = &Товар
    |   И Характеристики.ВидХарактеристики = &ВидХарактеристики";

    Запрос.УстановитьПараметр("Товар", Товар);
    Запрос.УстановитьПараметр("ВидХарактеристики", ВидХарактеристики);

    Результат = Запрос.Выполнить();
    Выборка = Результат.Выбрать();
    Если Выборка.Следующий() Тогда
        Количество = Выборка.Количество;
        МаксНомер = Выборка.МаксНомер;
    Иначе
        Количество = 0;
        МаксНомер = 0;
    КонецЕсли;

    Регистр = РегистрыСведений.Характеристики;

    Если Количество = 0 Тогда
        Запись = Регистр.СоздатьМенеджерЗаписи();
        Запись.Объект = Товар;
        Запись.ВидХарактеристики = ВидХарактеристики;
        Запись.Номер = 1;
        Запись.Значение = Значение;
        Запись.Записать();
        Возврат Истина;
    ИначеЕсли Количество = 1 Тогда
        Если Замещать Тогда
            ЗапросНомер = Новый Запрос;
            ЗапросНомер.Текст = 
            "ВЫБРАТЬ
            |   Характеристики.Номер КАК Номер
            |ИЗ
            |   РегистрСведений.Характеристики КАК Характеристики
            |ГДЕ
            |   Характеристики.Объект = &Товар
            |   И Характеристики.ВидХарактеристики = &ВидХарактеристики";

            ЗапросНомер.УстановитьПараметр("Товар", Товар);
            ЗапросНомер.УстановитьПараметр("ВидХарактеристики", ВидХарактеристики);

            ВыборкаНомер = ЗапросНомер.Выполнить().Выбрать();
            Если ВыборкаНомер.Следующий() Тогда
                Запись = Регистр.СоздатьМенеджерЗаписи();
                Запись.Объект = Товар;
                Запись.ВидХарактеристики = ВидХарактеристики;
                Запись.Номер = ВыборкаНомер.Номер;
                Запись.Значение = Значение;
                Запись.Записать();
                Возврат Истина;
            Иначе
                Возврат Ложь;
            КонецЕсли;
        Иначе
            Возврат Ложь;
        КонецЕсли;
    Иначе // Количество > 1
        Запись = Регистр.СоздатьМенеджерЗаписи();
        Запись.Объект = Товар;
        Запись.ВидХарактеристики = ВидХарактеристики;
        Запись.Номер = МаксНомер + 1;
        Запись.Значение = Значение;
        Запись.Записать();
        Возврат Истина;
    КонецЕсли;
КонецФункции

Функция НайтиГруппировкуПоИмени(Структура, Имя)

    // Проверка на случай, если передана пустая коллекция или Неопределено
    Если Структура = Неопределено Тогда
        Возврат Неопределено;
    КонецЕсли;

    Для Каждого Элемент Из Структура Цикл

        // Проверяем, является ли элемент искомой группировкой или таблицей
        Если ТипЗнч(Элемент) = Тип("ГруппировкаКомпоновкиДанных")
           Или ТипЗнч(Элемент) = Тип("ТаблицаКомпоновкиДанных") Тогда

            Если Элемент.Имя = Имя Тогда
                Возврат Элемент;
            КонецЕсли;

        КонецЕсли;

        // Если элемент — группировка, рекурсивно ищем в её вложенной структуре
        Если ТипЗнч(Элемент) = Тип("ГруппировкаКомпоновкиДанных") Тогда

            Результат = НайтиГруппировкуПоИмени(Элемент.Структура, Имя);
            Если Результат <> Неопределено Тогда
                Возврат Результат;
            КонецЕсли;

        КонецЕсли;

    КонецЦикла;

    Возврат Неопределено;

КонецФункции

Функция ЗначенияРеквизитовОбъекта(Ссылка, Реквизиты)
    // Определяем тип ссылки для доступа к метаданным
    ТипСсылки = ТипЗнч(Ссылка);

    // Обработка параметра Реквизиты в зависимости от типа
    Если ТипЗнч(Реквизиты) = Тип("Строка") Тогда
        Если ПустаяСтрока(Реквизиты) Тогда
            Возврат Новый Структура;
        КонецЕсли;

        МассивСтрок = РазложитьСтрокуВМассивИмен(Реквизиты);
        Если МассивСтрок.Количество() = 1 Тогда
            Имя = МассивСтрок[0];
            Если ЭтоТабличнаяЧасть(ТипСсылки, Имя) Тогда
                Возврат РезультатЗапросаТабличнойЧасти(Ссылка, Имя);
            КонецЕсли;
        КонецЕсли;
        СписокПолей = ПреобразоватьМассивСтрокВСписокПолей(МассивСтрок);
    ИначеЕсли ТипЗнч(Реквизиты) = Тип("Структура") Или ТипЗнч(Реквизиты) = Тип("ФиксированнаяСтруктура") Тогда
        СписокПолей = ПреобразоватьСтруктуруВСписокПолей(Реквизиты);
    ИначеЕсли ТипЗнч(Реквизиты) = Тип("Массив") Или ТипЗнч(Реквизиты) = Тип("ФиксированныйМассив") Тогда
        Если Реквизиты.Количество() = 1 И ТипЗнч(Реквизиты[0]) = Тип("Строка") Тогда
            Имя = Реквизиты[0];
            Если ЭтоТабличнаяЧасть(ТипСсылки, Имя) Тогда
                Возврат РезультатЗапросаТабличнойЧасти(Ссылка, Имя);
            КонецЕсли;
        КонецЕсли;
        СписокПолей = ПреобразоватьМассивВСписокПолей(Реквизиты);
    Иначе
        ВызватьИсключение "Параметр 'Реквизиты' имеет недопустимый тип.";
    КонецЕсли;

    Если СписокПолей.Количество() = 0 Тогда
        Возврат Новый Структура;
    КонецЕсли;

    Возврат ВыполнитьЗапросРеквизитов(Ссылка, СписокПолей);
КонецФункции

// Разбивает строку вида "Реквизит1, Реквизит2" в массив очищенных строк
Функция РазложитьСтрокуВМассивИмен(СтрокаРеквизитов)
    Массив = Новый Массив;
    Части = СтрРазделить(СтрокаРеквизитов, ",");
    Для Каждого Часть Из Части Цикл
        Очищенная = СокрЛП(Часть);
        Если Не ПустаяСтрока(Очищенная) Тогда
            Массив.Добавить(Очищенная);
        КонецЕсли;
    КонецЦикла;
    Возврат Массив;
КонецФункции

Функция ПреобразоватьМассивСтрокВСписокПолей(МассивСтрок)
    Список = Новый Массив;
    Для Каждого Имя Из МассивСтрок Цикл
        Список.Добавить(Новый Структура("Путь, Псевдоним", Имя, Имя));
    КонецЦикла;
    Возврат Список;
КонецФункции

Функция ПреобразоватьСтруктуруВСписокПолей(СтруктураРеквизитов)
    Список = Новый Массив;
    Для Каждого КлючЗначение Из СтруктураРеквизитов Цикл
        Псевдоним = КлючЗначение.Ключ;
        Значение  = КлючЗначение.Значение;
        Если Значение = Неопределено Тогда
            Путь = Псевдоним;
        Иначе
            Путь = Значение;
        КонецЕсли;
        Список.Добавить(Новый Структура("Путь, Псевдоним", Путь, Псевдоним));
    КонецЦикла;
    Возврат Список;
КонецФункции

Функция ПреобразоватьМассивВСписокПолей(МассивРеквизитов)
    Список = Новый Массив;
    Для Каждого Элемент Из МассивРеквизитов Цикл
        Список.Добавить(Новый Структура("Путь, Псевдоним", Элемент, Элемент));
    КонецЦикла;
    Возврат Список;
КонецФункции

// Проверяет, является ли имя табличной частью объекта данного типа
Функция ЭтоТабличнаяЧасть(ТипСсылки, Имя)
    Попытка
        ОбъектМетаданных = Метаданные.НайтиПоТипу(ТипСсылки);
        Если ОбъектМетаданных <> Неопределено Тогда
            Возврат ОбъектМетаданных.ТабличныеЧасти.Найти(Имя) <> Неопределено;
        КонецЕсли;
    Исключение
    КонецПопытки;
    Возврат Ложь;
КонецФункции

// Выполняет запрос для получения табличной части
Функция РезультатЗапросаТабличнойЧасти(Ссылка, ИмяТабличнойЧасти)
    ОбъектМетаданных = Метаданные.НайтиПоТипу(ТипЗнч(Ссылка));
    ПолноеИмя = ОбъектМетаданных.ПолноеИмя();

    Запрос = Новый Запрос;
    Запрос.Текст = 
    "ВЫБРАТЬ *
    |ИЗ " + ПолноеИмя + "." + ИмяТабличнойЧасти + "
    |ГДЕ Ссылка = &Ссылка";

    Запрос.УстановитьПараметр("Ссылка", Ссылка);

    Результат = Запрос.Выполнить();
    Возврат Результат.Выгрузить();
КонецФункции

// Генерирует уникальный алиас на основе базового имени
Функция ПолучитьУникальныйАлиас(БазовыйАлиас, ЗанятыеАлиасы)
    Алиас = БазовыйАлиас;
    Счетчик = 1;
    Пока ЗанятыеАлиасы.Получить(Алиас) <> Неопределено Цикл
        Алиас = БазовыйАлиас + "_" + Счетчик;
        Счетчик = Счетчик + 1;
    КонецЦикла;
    ЗанятыеАлиасы.Вставить(Алиас, Истина);
    Возврат Алиас;
КонецФункции

// Основной запрос для получения реквизитов объекта
Функция ВыполнитьЗапросРеквизитов(Ссылка, СписокПолей)
    ТипСсылки = ТипЗнч(Ссылка);
    ОбъектМетаданных = Метаданные.НайтиПоТипу(ТипСсылки);
    ПолноеИмя = ОбъектМетаданных.ПолноеИмя();

    ПоляЗапроса = Новый Массив;
    СоответствиеАлиасов = Новый Соответствие;
    ЗанятыеАлиасы = Новый Соответствие;

    Для Каждого Поле Из СписокПолей Цикл
        Путь = Поле.Путь;
        Псевдоним = Поле.Псевдоним;
        БазовыйАлиас = СтрЗаменить(Псевдоним, ".", "_");
        АлиасЗапроса = ПолучитьУникальныйАлиас(БазовыйАлиас, ЗанятыеАлиасы);

        ПоляЗапроса.Добавить("Ссылка." + Путь + " КАК " + АлиасЗапроса);
        СоответствиеАлиасов.Вставить(АлиасЗапроса, Псевдоним);
    КонецЦикла;

    ТекстЗапроса = 
    "ВЫБРАТЬ
    |" + СтрСоединить(ПоляЗапроса, ",") + "
    |ИЗ " + ПолноеИмя + "
    |ГДЕ Ссылка = &Ссылка";

    Запрос = Новый Запрос;
    Запрос.Текст = ТекстЗапроса;
    Запрос.УстановитьПараметр("Ссылка", Ссылка);

    Результат = Запрос.Выполнить();
    Выборка = Результат.Выбрать();

    Если Выборка.Следующий() Тогда
        РезультатСтруктура = Новый Структура;
        Для Каждого Алиас Из СоответствиеАлиасов Цикл
            ОригинальныйПсевдоним = СоответствиеАлиасов[Алиас.Ключ];
            Значение = Выборка[Алиас.Ключ];
            РезультатСтруктура.Вставить(ОригинальныйПсевдоним, Значение);
        КонецЦикла;
        Возврат РезультатСтруктура;
    Иначе
        // Объект не найден: пустая или битая ссылка
        РезультатСтруктура = Новый Структура;
        Для Каждого Поле Из СписокПолей Цикл
            РезультатСтруктура.Вставить(Поле.Псевдоним, Неопределено);
        КонецЦикла;
        Возврат РезультатСтруктура;
    КонецЕсли;
КонецФункции

Функция ПодставитьПараметрыВСтроку(ШаблонСтроки, Параметр1, Параметр2, Параметр3, Параметр4, Параметр5)
    Возврат СтрШаблон(ШаблонСтроки, Параметр1, Параметр2, Параметр3, Параметр4, Параметр5);
КонецФункции

Функция СформироватьРеестрРеализаций()
    Запрос = Новый Запрос;
    Запрос.Текст = 
    "ВЫБРАТЬ
    |   РасходТовара.Дата КАК Дата,
    |   РасходТовара.Покупатель КАК Покупатель,
    |   РасходТовара.Склад КАК Склад,
    |   РасходТовара.Валюта КАК Валюта,
    |   РасходТовара.ВидЦен КАК ВидЦен
    |ИЗ
    |   Документ.РасходТовара КАК РасходТовара
    |ГДЕ
    |   РасходТовара.Проведен
    |УПОРЯДОЧИТЬ ПО
    |   РасходТовара.Дата";

    РезультатЗапроса = Запрос.Выполнить();

    ТаблицаРезультат = Новый ТаблицаЗначений;
    ТаблицаРезультат.Колонки.Добавить("Дата",       Новый ОписаниеТипов("Строка"));
    ТаблицаРезультат.Колонки.Добавить("Покупатель", Новый ОписаниеТипов("СправочникСсылка.Контрагенты"));
    ТаблицаРезультат.Колонки.Добавить("Склад",      Новый ОписаниеТипов("СправочникСсылка.Склады"));
    ТаблицаРезультат.Колонки.Добавить("Валюта",     Новый ОписаниеТипов("СправочникСсылка.Валюты"));
    ТаблицаРезультат.Колонки.Добавить("ВидЦен",     Новый ОписаниеТипов("СправочникСсылка.ВидыЦен"));

    Выборка = РезультатЗапроса.Выбрать();
    Пока Выборка.Следующий() Цикл
        НоваяСтрока = ТаблицаРезультат.Добавить();
        НоваяСтрока.Дата       = Формат(Выборка.Дата, "ДФ=dd.MM.yyyy");
        НоваяСтрока.Покупатель = Выборка.Покупатель;
        НоваяСтрока.Склад      = Выборка.Склад;
        НоваяСтрока.Валюта     = Выборка.Валюта;
        НоваяСтрока.ВидЦен     = Выборка.ВидЦен;
    КонецЦикла;

    Возврат ТаблицаРезультат;
КонецФункции

Функция ПолучитьТаблицуЗаказовПоКурсуВалют(ДатаНачала, ДатаОкончания)

    Запрос = Новый Запрос;

    // Формируем базовый текст запроса
    ТекстЗапроса = 
        "ВЫБРАТЬ
        |    Заказ.Дата КАК Дата,
        |    Заказ.Ссылка КАК Заказ,
        |    Заказ.Сумма КАК Сумма,
        |    Заказ.Валюта КАК ВалютаДокумента,
        |    Заказ.Покупатель КАК Покупатель
        |ИЗ
        |    Документ.Заказ КАК Заказ
        |ГДЕ
        |    Заказ.ПометкаУдаления = ЛОЖЬ";

    // Динамическое построение условий по датам в зависимости от параметров
    Если ЗначениеЗаполнено(ДатаНачала) И ЗначениеЗаполнено(ДатаОкончания) Тогда
        ТекстЗапроса = ТекстЗапроса + 
            "
            |    И Заказ.Дата МЕЖДУ &ДатаНачала И &ДатаОкончания";
    ИначеЕсли ЗначениеЗаполнено(ДатаНачала) Тогда
        ТекстЗапроса = ТекстЗапроса + 
            "
            |    И Заказ.Дата > &ДатаНачала";
    ИначеЕсли ЗначениеЗаполнено(ДатаОкончания) Тогда
        ТекстЗапроса = ТекстЗапроса + 
            "
            |    И Заказ.Дата < &ДатаОкончания";
    КонецЕсли;

    // Сортировка по убыванию даты
    ТекстЗапроса = ТекстЗапроса + 
        "
        |УПОРЯДОЧИТЬ ПО
        |    Заказ.Дата УБЫВ";

    Запрос.Текст = ТекстЗапроса;

    // Установка параметров запроса
    Если ЗначениеЗаполнено(ДатаНачала) И ЗначениеЗаполнено(ДатаОкончания) Тогда
        Запрос.УстановитьПараметр("ДатаНачала", НачалоДня(ДатаНачала));
        Запрос.УстановитьПараметр("ДатаОкончания", КонецДня(ДатаОкончания));
    ИначеЕсли ЗначениеЗаполнено(ДатаНачала) Тогда
        Запрос.УстановитьПараметр("ДатаНачала", ДатаНачала);
    ИначеЕсли ЗначениеЗаполнено(ДатаОкончания) Тогда
        Запрос.УстановитьПараметр("ДатаОкончания", ДатаОкончания);
    КонецЕсли;

    РезультатЗапроса = Запрос.Выполнить();

    // Создание результирующей таблицы значений
    ТЗ = Новый ТаблицаЗначений;
    ТЗ.Колонки.Добавить("Дата", Новый ОписаниеТипов("Дата"));
    ТЗ.Колонки.Добавить("Заказ", Новый ОписаниеТипов("ДокументСсылка.Заказ"));
    ТЗ.Колонки.Добавить("Сумма", Новый ОписаниеТипов("Число", Новый КвалификаторыЧисла(15,2)));
    ТЗ.Колонки.Добавить("Покупатель", Новый ОписаниеТипов("СправочникСсылка.Контрагенты"));

    // Кэш курсов валют для ускорения (ключ: "Валюта_Дата")
    КурсыВалютКэш = Новый Соответствие;

    // Обработка выборки
    Выборка = РезультатЗапроса.Выбрать();
    Пока Выборка.Следующий() Цикл
        СуммаДокумента = Выборка.Сумма;
        ВалютаДокумента = Выборка.ВалютаДокумента;
        ДатаДокумента = Выборка.Дата;

        Курс = 1; // Значение по умолчанию, если курс не найден
        Если ЗначениеЗаполнено(ВалютаДокумента) Тогда
            КлючКэша = Строка(ВалютаДокумента) + "_" + Формат(ДатаДокумента, "ДФ=yyyyMMdd");
            ЗначениеКурса = КурсыВалютКэш.Получить(КлючКэша);
            Если ЗначениеКурса = Неопределено Тогда
                // Получаем курс из регистра сведений на дату документа
                ЗапросКурс = Новый Запрос;
                ЗапросКурс.Текст = 
                    "ВЫБРАТЬ
                    |    КурсыВалютСрезПоследних.Курс КАК Курс
                    |ИЗ
                    |    РегистрСведений.КурсыВалют.СрезПоследних(&ДатаДокумента, Валюта = &Валюта) КАК КурсыВалютСрезПоследних";

                ЗапросКурс.УстановитьПараметр("ДатаДокумента", ДатаДокумента);
                ЗапросКурс.УстановитьПараметр("Валюта", ВалютаДокумента);

                РезультатКурс = ЗапросКурс.Выполнить();
                Если Не РезультатКурс.Пустой() Тогда
                    ВыборкаКурс = РезультатКурс.Выбрать();
                    ВыборкаКурс.Следующий();
                    Курс = ВыборкаКурс.Курс;
                КонецЕсли;

                КурсыВалютКэш.Вставить(КлючКэша, Курс);
            Иначе
                Курс = ЗначениеКурса;
            КонецЕсли;
        КонецЕсли;

        ПересчитаннаяСумма = Окр(СуммаДокумента * Курс, 2);

        // Добавление строки в итоговую таблицу
        НоваяСтрока = ТЗ.Добавить();
        НоваяСтрока.Дата = ДатаДокумента;
        НоваяСтрока.Заказ = Выборка.Заказ;
        НоваяСтрока.Сумма = ПересчитаннаяСумма;
        НоваяСтрока.Покупатель = Выборка.Покупатель;
    КонецЦикла;

    // Гарантированная сортировка (основная уже выполнена в запросе)
    ТЗ.Сортировать("Дата Убыв");

    Возврат ТЗ;

КонецФункции

&НаСервере
Функция СформироватьОтчетЗадолженностьКонтрагентов(ДатаНачала, ДатаОкончания, Валюта)
    // Создаем объект отчета
    ОтчетОбъект = Отчеты.ОтчетПоВзаиморасчетам.Создать();

    // Получаем схему компоновки данных
    СхемаКД = ОтчетОбъект.ПолучитьСхемуКомпоновкиДанных();

    // Находим вариант "Основной"
    Вариант = СхемаКД.ВариантыНастроек.Найти("Основной");
    Если Вариант = Неопределено Тогда
        ВызватьИсключение "Вариант отчета ""Основной"" не найден.";
    КонецЕсли;

    // Загружаем настройки варианта в компоновщик для редактирования
    КомпоновщикНастроек = Новый КомпоновщикНастроекКомпоновкиДанных();
    КомпоновщикНастроек.Инициализировать(Новый ИсточникДоступныхНастроекКомпоновкиДанных(СхемаКД));
    КомпоновщикНастроек.ЗагрузитьНастройки(Вариант.Настройки);
    Настройки = КомпоновщикНастроек.Настройки;

    // Очищаем существующие элементы, чтобы задать новые в соответствии с заданием
    Настройки.Структура.Очистить();
    Настройки.Отбор.Очистить();
    Настройки.Выбор.Очистить();
    Настройки.УсловноеОформление.Очистить();

    // Устанавливаем параметр периода
    ЗначениеПериода = Новый Структура("ДатаНачала, ДатаОкончания", ДатаНачала, ДатаОкончания);
    ПараметрНайден = Ложь;
    Для Каждого Элемент Из Настройки.ПараметрыДанных Цикл
        Если Элемент.Параметр.Имя = "Период" Тогда
            Элемент.Значение = ЗначениеПериода;
            ПараметрНайден = Истина;
            Прервать;
        КонецЕсли;
    КонецЦикла;
    Если Не ПараметрНайден Тогда
        ВызватьИсключение "Параметр отчета ""Период"" не найден.";
    КонецЕсли;

    // Параметры вывода
    Настройки.ПараметрыВывода.ВыводитьПараметрыДанных = Ложь;
    Настройки.ПараметрыВывода.ВыводитьОтбор = Ложь;

    // Структура отчета: Таблица (строки: Контрагент, столбцы: Валюта)
    ГруппировкаТаблица = Настройки.Структура.Добавить(Тип("ГруппировкаТаблицыКомпоновкиДанных"));

    ГруппировкаСтрок = ГруппировкаТаблица.Строки.Добавить(Тип("ГруппировкаКомпоновкиДанных"));
    ГруппировкаСтрок.Поле = Новый ПолеКомпоновкиДанных("Контрагент");

    ГруппировкаКолонок = ГруппировкаТаблица.Колонки.Добавить(Тип("ГруппировкаКомпоновкиДанных"));
    ГруппировкаКолонок.Поле = Новый ПолеКомпоновкиДанных("Валюта");

    // Выбранные поля
    ВыбПолеСумма = Настройки.Выбор.Добавить(Тип("ВыбранноеПолеКомпоновкиДанных"));
    ВыбПолеСумма.Поле = Новый ПолеКомпоновкиДанных("СуммаКонечныйОстаток");

    ВыбПолеКонтрагент = Настройки.Выбор.Добавить(Тип("ВыбранноеПолеКомпоновкиДанных"));
    ВыбПолеКонтрагент.Поле = Новый ПолеКомпоновкиДанных("Контрагент");

    // Отборы
    ОтборСумма = Настройки.Отбор.Добавить(Тип("ОтборКомпоновкиДанных"));
    ОтборСумма.ЛевоеЗначение = Новый ПолеКомпоновкиДанных("СуммаКонечныйОстаток");
    ОтборСумма.ВидСравнения = ВидСравненияКомпоновкиДанных.Меньше;
    ОтборСумма.ПравоеЗначение = 0;

    ОтборВалюта = Настройки.Отбор.Добавить(Тип("ОтборКомпоновкиДанных"));
    ОтборВалюта.ЛевоеЗначение = Новый ПолеКомпоновкиДанных("Валюта");
    ОтборВалюта.ВидСравнения = ВидСравненияКомпоновкиДанных.Равно;
    ОтборВалюта.ПравоеЗначение = Валюта;

    // Условное оформление: формат для поля СуммаКонечныйОстаток
    ЭлементУО = Настройки.УсловноеОформление.Добавить();
    ЭлементУО.Оформление.Формат = "ЧЦ=10; ЧДЦ=2; ЧО=1";
    ЭлементУО.Поля.Добавить(Новый ПолеКомпоновкиДанных("СуммаКонечныйОстаток"));

    // Компоновка макета
    КомпоновщикМакета = Новый КомпоновщикМакетаКомпоновкиДанных();
    Макет = КомпоновщикМакета.Выполнить(СхемаКД, Настройки);

    // Процессор компоновки данных
    ПроцессорКомпоновки = Новый ПроцессорКомпоновкиДанных();
    ПроцессорКомпоновки.Инициализировать(Макет);

    // Вывод в табличный документ
    ТабДок = Новый ТабличныйДокумент;
    ПроцессорВывода = Новый ПроцессорВыводаРезультатаКомпоновкиДанныхВТабличныйДокумент;
    ПроцессорВывода.УстановитьДокумент(ТабДок);
    ПроцессорВывода.Вывести(ПроцессорКомпоновки, Истина);

    Возврат ТабДок;
КонецФункции

Функция ПолучитьТаблицуНепрочитанныхПисемКонтрагентов(мКонтрагенты)

    // Определяем начало и конец предыдущего месяца
    ТекущаяДата = ТекущаяДата();
    НачалоПериода = НачалоМесяца(ДобавитьМесяц(ТекущаяДата, -1));
    КонецПериода = КонецМесяца(ДобавитьМесяц(ТекущаяДата, -1));

    Запрос = Новый Запрос;
    Запрос.Текст = 
    "ВЫБРАТЬ
    |    ВходящиеПисьма.Ссылка КАК Письмо,
    |    ВходящиеПисьма.Отправитель КАК Тема,
    |    Контрагенты.Ссылка КАК Контрагент,
    |    ВходящиеПисьма.Дата КАК Дата
    |ИЗ
    |    Справочник.ВходящиеПисьма КАК ВходящиеПисьма
    |    ВНУТРЕННЕЕ СОЕДИНЕНИЕ РегистрСведений.СостояниеВходящихПисем КАК Состояние
    |    ПО ВходящиеПисьма.Ссылка = Состояние.Письмо
    |    ВНУТРЕННЕЕ СОЕДИНЕНИЕ Справочник.Контрагенты КАК Контрагенты
    |    ПО ВходящиеПисьма.ПочтовыйЯщик = Контрагенты.ЭлектроннаяПочта
    |ГДЕ
    |    Состояние.Прочитано = ЛОЖЬ
    |    И ВходящиеПисьма.Дата МЕЖДУ &НачалоПериода И &КонецПериода
    |    И Контрагенты.Ссылка В (&мКонтрагенты)";

    Запрос.УстановитьПараметр("НачалоПериода", НачалоПериода);
    Запрос.УстановитьПараметр("КонецПериода", КонецПериода);
    Запрос.УстановитьПараметр("мКонтрагенты", мКонтрагенты);

    Результат = Запрос.Выполнить();

    Таблица = Новый ТаблицаЗначений;
    Таблица.Колонки.Добавить("Письмо", Новый ОписаниеТипов("СправочникСсылка.ВходящиеПисьма"));
    Таблица.Колонки.Добавить("Тема", Новый ОписаниеТипов("Строка"));
    Таблица.Колонки.Добавить("Контрагент", Новый ОписаниеТипов("СправочникСсылка.Контрагенты"));
    Таблица.Колонки.Добавить("Дата", Новый ОписаниеТипов("Дата"));

    Выборка = Результат.Выбрать();
    Пока Выборка.Следующий() Цикл
        Строка = Таблица.Добавить();
        Строка.Письмо = Выборка.Письмо;
        Строка.Тема = Выборка.Тема;
        Строка.Контрагент = Выборка.Контрагент;
        Строка.Дата = Выборка.Дата;
    КонецЦикла;

    Возврат Таблица;

КонецФункции

Функция ВыгрузитьЗаказыВXMLФайл()
    // Создаем временный файл
    ИмяФайла = ПолучитьИмяВременногоФайла("xml");

    // Создаем объект записи XML
    ЗаписьXML = Новый ЗаписьXML;
    ЗаписьXML.ОткрытьФайл(ИмяФайла, "UTF-8");
    ЗаписьXML.ЗаписатьОбъявлениеXML();

    // Начинаем корневой элемент
    ЗаписьXML.ЗаписатьНачалоЭлемента("Заказ");
    ЗаписьXML.ЗаписатьАтрибут("Имя", "ЗаказТовары");

    // Формируем запрос для получения заказов
    Запрос = Новый Запрос;
    Запрос.Текст = 
    "ВЫБРАТЬ
    |    Заказ.Номер КАК Номер,
    |    Заказ.Дата КАК Дата,
    |    ПРЕДСТАВЛЕНИЕ(Заказ.Покупатель) КАК Покупатель,
    |    ПРЕДСТАВЛЕНИЕ(Заказ.Склад) КАК Склад,
    |    ПРЕДСТАВЛЕНИЕ(Заказ.Валюта) КАК Валюта,
    |    ПРЕДСТАВЛЕНИЕ(Заказ.ВидЦен) КАК ВидЦен,
    |    ПРЕДСТАВЛЕНИЕ(Заказ.Организация) КАК Организация,
    |    ПРЕДСТАВЛЕНИЕ(Заказ.СостояниеЗаказа) КАК СостояниеЗаказа,
    |    Заказ.Сумма КАК Сумма,
    |    Заказ.Ссылка КАК Ссылка
    |ИЗ
    |    Документ.Заказ КАК Заказ
    |ГДЕ
    |    Заказ.Проведен
    |    И Заказ.СостояниеЗаказа = &Состояние";

    Запрос.УстановитьПараметр("Состояние", Перечисления.СостоянияЗаказов.ВРаботе);

    Результат = Запрос.Выполнить();

    // Запрос для товаров
    ЗапросТовары = Новый Запрос;
    ЗапросТовары.Текст = 
    "ВЫБРАТЬ
    |    Товары.Товар КАК Товар,
    |    ПРЕДСТАВЛЕНИЕ(Товары.Товар) КАК ТоварПредставление,
    |    Товары.Цена КАК Цена,
    |    Товары.Количество КАК Количество,
    |    Товары.Сумма КАК Сумма
    |ИЗ
    |    Документ.Заказ.Товары КАК Товары
    |ГДЕ
    |    Товары.Ссылка = &Ссылка";

    // Обходим заказы
    ВыборкаЗаказов = Результат.Выбрать();
    Пока ВыборкаЗаказов.Следующий() Цикл
        // Начинаем элемент Запись
        ЗаписьXML.ЗаписатьНачалоЭлемента("Запись");

        // Записываем реквизиты шапки
        ЗаписьXML.ЗаписатьНачалоЭлемента("Номер");
        ЗаписьXML.ЗаписатьТекст(ВыборкаЗаказов.Номер);
        ЗаписьXML.ЗаписатьКонецЭлемента();

        ЗаписьXML.ЗаписатьНачалоЭлемента("Дата");
        ЗаписьXML.ЗаписатьТекст(Формат(ВыборкаЗаказов.Дата, "ДФ=dd.MM.yyyy"));
        ЗаписьXML.ЗаписатьКонецЭлемента();

        ЗаписьXML.ЗаписатьНачалоЭлемента("Покупатель");
        ЗаписьXML.ЗаписатьТекст(ВыборкаЗаказов.Покупатель);
        ЗаписьXML.ЗаписатьКонецЭлемента();

        ЗаписьXML.ЗаписатьНачалоЭлемента("Склад");
        ЗаписьXML.ЗаписатьТекст(ВыборкаЗаказов.Склад);
        ЗаписьXML.ЗаписатьКонецЭлемента();

        ЗаписьXML.ЗаписатьНачалоЭлемента("Валюта");
        ЗаписьXML.ЗаписатьТекст(ВыборкаЗаказов.Валюта);
        ЗаписьXML.ЗаписатьКонецЭлемента();

        ЗаписьXML.ЗаписатьНачалоЭлемента("ВидЦен");
        ЗаписьXML.ЗаписатьТекст(ВыборкаЗаказов.ВидЦен);
        ЗаписьXML.ЗаписатьКонецЭлемента();

        ЗаписьXML.ЗаписатьНачалоЭлемента("Организация");
        ЗаписьXML.ЗаписатьТекст(ВыборкаЗаказов.Организация);
        ЗаписьXML.ЗаписатьКонецЭлемента();

        ЗаписьXML.ЗаписатьНачалоЭлемента("СостояниеЗаказа");
        ЗаписьXML.ЗаписатьТекст(ВыборкаЗаказов.СостояниеЗаказа);
        ЗаписьXML.ЗаписатьКонецЭлемента();

        ЗаписьXML.ЗаписатьНачалоЭлемента("Сумма");
        ЗаписьXML.ЗаписатьТекст(Формат(ВыборкаЗаказов.Сумма, "ЧДЦ=2"));
        ЗаписьXML.ЗаписатьКонецЭлемента();

        // Получаем товары для этого заказа
        ЗапросТовары.УстановитьПараметр("Ссылка", ВыборкаЗаказов.Ссылка);
        ВыборкаТоваров = ЗапросТовары.Выполнить().Выбрать();

        Если ВыборкаТоваров.Следующий() Тогда
            ЗаписьXML.ЗаписатьНачалоЭлемента("Товары");
            Пока Истина Цикл
                ЗаписьXML.ЗаписатьНачалоЭлемента("Товар");

                ЗаписьXML.ЗаписатьНачалоЭлемента("Наименование");
                ЗаписьXML.ЗаписатьТекст(ВыборкаТоваров.ТоварПредставление);
                ЗаписьXML.ЗаписатьКонецЭлемента();

                ЗаписьXML.ЗаписатьНачалоЭлемента("Цена");
                ЗаписьXML.ЗаписатьТекст(Формат(ВыборкаТоваров.Цена, "ЧДЦ=2"));
                ЗаписьXML.ЗаписатьКонецЭлемента();

                ЗаписьXML.ЗаписатьНачалоЭлемента("Количество");
                ЗаписьXML.ЗаписатьТекст(Формат(ВыборкаТоваров.Количество, "ЧДЦ=0"));
                ЗаписьXML.ЗаписатьКонецЭлемента();

                ЗаписьXML.ЗаписатьНачалоЭлемента("Сумма");
                ЗаписьXML.ЗаписатьТекст(Формат(ВыборкаТоваров.Сумма, "ЧДЦ=2"));
                ЗаписьXML.ЗаписатьКонецЭлемента();

                ЗаписьXML.ЗаписатьКонецЭлемента(); // Товар

                Если Не ВыборкаТоваров.Следующий() Тогда
                    Прервать;
                КонецЕсли;
            КонецЦикла;
            ЗаписьXML.ЗаписатьКонецЭлемента(); // Товары
        КонецЕсли;

        ЗаписьXML.ЗаписатьКонецЭлемента(); // Запись
    КонецЦикла;

    // Закрываем корневой элемент
    ЗаписьXML.ЗаписатьКонецЭлемента(); // Заказ
    ЗаписьXML.Закрыть();

    Возврат ИмяФайла;
КонецФункции

Функция РазложитьСтрокуВМассивПодстрок(Знач Стр, Разделитель = ",")
    // Создаём пустой массив, который будет наполняться подстроками
    Результат = Новый Массив;

    // Если разделитель — пробел, применяем особую логику:
    // ведущие/хвостовые пробелы игнорируются, несколько пробелов подряд считаются одним разделителем
    Если Разделитель = " " Тогда
        // Убираем пробелы в начале и в конце переданной строки
        Строка = СокрЛП(Стр);
        Если Строка = "" Тогда
            // Строка пуста или состояла только из пробелов – возвращаем пустой массив
            Возврат Результат;
        КонецЕсли;

        Длина = СтрДлина(Строка);
        Индекс = 1;
        Пока Индекс <= Длина Цикл
            // Пропускаем все пробельные символы перед началом следующего слова
            Пока Индекс <= Длина И Сред(Строка, Индекс, 1) = " " Цикл
                Индекс = Индекс + 1;
            КонецЦикла;

            Если Индекс > Длина Тогда
                Прервать; // Достигнут конец строки после пропуска пробелов
            КонецЕсли;

            // Запоминаем начало текущего слова
            Начало = Индекс;
            // Двигаемся до конца слова (следующего пробела или окончания строки)
            Пока Индекс <= Длина И Сред(Строка, Индекс, 1) <> " " Цикл
                Индекс = Индекс + 1;
            КонецЦикла;

            // Добавляем выделенное слово в результат
            Результат.Добавить(Сред(Строка, Начало, Индекс - Начало));
        КонецЦикла;

        Возврат Результат;
    Иначе
        // Для всех остальных разделителей (в том числе длинных) используем штатную функцию,
        // явно указывая, что пустые подстроки нужно включать в результат
        Возврат СтрРазделить(Стр, Разделитель, Истина);
    КонецЕсли;
КонецФункции

Функция ЗарегистрированныеКОбменуБитыеСсылки(Узел, ТипМетаданных = Неопределено)
    ТЗ = Новый ТаблицаЗначений;
    ТЗ.Колонки.Добавить("МетаИмя", Новый ОписаниеТипов("Строка"));
    ТЗ.Колонки.Добавить("ТипМетаданных", Новый ОписаниеТипов("ОбъектМетаданных"));
    ТЗ.Колонки.Добавить("УИД", Новый ОписаниеТипов("УникальныйИдентификатор"));

    ПланОбменаМенеджер = Узел.Метаданные();
    ИмяПланаОбмена = ПланОбменаМенеджер.Имя;

    // Подготовка списка метаданных для обработки
    Если ТипМетаданных = Неопределено Тогда
        МассивТипов = Новый Массив;
        Для Каждого Элемент Из ПланОбменаМенеджер.Состав Цикл
            МетаданныеОбъекта = Элемент.Метаданные;
            // Проверяем, что метаданные содержат значения ссылочного типа (справочники, документы и т.п.)
            Если МетаданныеОбъекта.СодержитЗначенияСсылочногоТипа Тогда
                МассивТипов.Добавить(МетаданныеОбъекта);
            КонецЕсли;
        КонецЦикла;
    Иначе
        МассивТипов = Новый Массив;
        МассивТипов.Добавить(ТипМетаданных);
    КонецЕсли;

    Для Каждого Тип Из МассивТипов Цикл
        ПолноеИмя = Тип.ПолноеИмя(); // Например "Справочник.Номенклатура"
        Запрос = Новый Запрос;
        Запрос.Текст = 
        "ВЫБРАТЬ
        |    Изменения.Ссылка КАК Ссылка
        |ИЗ
        |    ПланОбмена." + ИмяПланаОбмена + ".Изменения КАК Изменения
        |ГДЕ
        |    Изменения.Узел = &Узел
        |    И Изменения.Ссылка ССЫЛКА " + ПолноеИмя;
        Запрос.УстановитьПараметр("Узел", Узел);

        Выборка = Запрос.Выполнить().Выбрать();
        Пока Выборка.Следующий() Цикл
            Ссылка = Выборка.Ссылка;
            Попытка
                // Попытка получить объект — для битой ссылки возникнет исключение
                Объект = Ссылка.ПолучитьОбъект();
            Исключение
                Стр = ТЗ.Добавить();
                Стр.МетаИмя = ПолноеИмя;
                Стр.ТипМетаданных = Тип;
                Стр.УИД = Ссылка.УникальныйИдентификатор();
            КонецПопытки;
        КонецЦикла;
    КонецЦикла;

    Возврат ТЗ;
КонецФункции

&НаКлиенте
Функция НайтиАдресПоКоординатам(Широта, Долгота, APIКлюч)

    ЗащищенноеСоединение = Новый ЗащищенноеСоединениеOpenSSL();
    HTTPСоединение = Новый HTTPСоединение("geocode-maps.yandex.ru", , , , , , , ЗащищенноеСоединение);

    // Кодируем API ключ для безопасной передачи в URL
    APIКлючURL = КодироватьСтроку(APIКлюч, СпособКодированияСтроки.URL);

    // Формируем путь запроса с параметрами обратного геокодирования
    Путь = "/1.x/?format=json&apikey=" + APIКлючURL 
         + "&geocode=" + Долгота + "," + Широта 
         + "&sco=latlong&kind=house&results=1";

    HTTPЗапрос = Новый HTTPЗапрос(Путь);
    Ответ = HTTPСоединение.Получить(HTTPЗапрос);

    Если Ответ.КодСостояния = 200 Тогда
        ТелоОтвета = Ответ.ПолучитьТелоКакСтроку();

        ЧтениеJSON = Новый ЧтениеJSON;
        ЧтениеJSON.УстановитьСтроку(ТелоОтвета);
        Данные = ПрочитатьJSON(ЧтениеJSON);
        ЧтениеJSON.Закрыть();

        Если Данные <> Неопределено 
           И Данные.response <> Неопределено 
           И Данные.response.GeoObjectCollection <> Неопределено 
           И Данные.response.GeoObjectCollection.featureMember.Количество() > 0 Тогда

            ГеоОбъект = Данные.response.GeoObjectCollection.featureMember[0].GeoObject;

            Если ГеоОбъект <> Неопределено 
               И ГеоОбъект.metaDataProperty <> Неопределено 
               И ГеоОбъект.metaDataProperty.GeocoderMetaData <> Неопределено Тогда

                Возврат ГеоОбъект.metaDataProperty.GeocoderMetaData.text;

            КонецЕсли;
        КонецЕсли;
    КонецЕсли;

    // Если адрес не найден или произошла ошибка, возвращаем пустую строку
    Возврат "";

КонецФункции

Функция ПроверкаЛимитаЗадолженности(Заказ, ЛимитВРублях)
    // Проверка заполненности параметров
    Если Заказ = Неопределено Тогда
        ВызватьИсключение "Параметр Заказ не определен";
    КонецЕсли;

    Контрагент = Заказ.Контрагент;
    ДатаЗаказа = Заказ.Дата;
    ВалютаЗаказа = Заказ.Валюта;
    СуммаЗаказа = Заказ.Сумма;

    // 1. Получение остатков задолженности по контрагенту на дату заказа
    ЗапросОстатки = Новый Запрос;
    ЗапросОстатки.Текст = 
    "ВЫБРАТЬ
    |    ВзаиморасчетыОстатки.Валюта КАК Валюта,
    |    ВзаиморасчетыОстатки.СуммаОстаток КАК СуммаОстатка
    |ИЗ
    |    РегистрНакопления.Взаиморасчеты.Остатки(&ДатаЗаказа, Контрагент = &Контрагент) КАК ВзаиморасчетыОстатки";

    ЗапросОстатки.УстановитьПараметр("ДатаЗаказа", ДатаЗаказа);
    ЗапросОстатки.УстановитьПараметр("Контрагент", Контрагент);

    РезультатОстатки = ЗапросОстатки.Выполнить();
    ТаблицаОстатков = РезультатОстатки.Выгрузить();

    // 2. Формирование списка валют для запроса курсов (исключая RUB)
    СписокВалют = Новый Массив;
    ВалютаРубль = Справочники.Валюты.НайтиПоКоду("RUB"); // Или другой способ получения рубля
    Для Каждого Строка Из ТаблицаОстатков Цикл
        Если Строка.Валюта <> ВалютаРубль Тогда
            СписокВалют.Добавить(Строка.Валюта);
        КонецЕсли;
    КонецЦикла;

    Если ВалютаЗаказа <> ВалютаРубль И СписокВалют.Найти(ВалютаЗаказа) = Неопределено Тогда
        СписокВалют.Добавить(ВалютаЗаказа);
    КонецЕсли;

    // 3. Получение курсов валют на дату заказа
    КурсыВалют = Новый Соответствие;
    Если СписокВалют.Количество() > 0 Тогда
        ЗапросКурсы = Новый Запрос;
        ЗапросКурсы.Текст = 
        "ВЫБРАТЬ
        |    КурсыВалют.Валюта КАК Валюта,
        |    КурсыВалют.Курс КАК Курс
        |ИЗ
        |    РегистрСведений.КурсыВалют.СрезПоследних(&ДатаЗаказа, Валюта В (&СписокВалют)) КАК КурсыВалют";

        ЗапросКурсы.УстановитьПараметр("ДатаЗаказа", ДатаЗаказа);
        ЗапросКурсы.УстановитьПараметр("СписокВалют", СписокВалют);

        РезультатКурсы = ЗапросКурсы.Выполнить();
        ТаблицаКурсов = РезультатКурсы.Выгрузить();

        Для Каждого СтрокаКурс Из ТаблицаКурсов Цикл
            КурсыВалют.Вставить(СтрокаКурс.Валюта, СтрокаКурс.Курс);
        КонецЦикла;
    КонецЕсли;

    // 4. Расчет суммы дебиторской задолженности в рублях
    СуммаДЗВРублях = 0;
    ЕстьОшибкаКурса = Ложь;
    СообщениеОшибки = "";

    Для Каждого СтрокаОстаток Из ТаблицаОстатков Цикл
        Если СтрокаОстаток.Валюта = ВалютаРубль Тогда
            Курс = 1;
        Иначе
            Курс = КурсыВалют.Получить(СтрокаОстаток.Валюта);
            Если Курс = Неопределено Тогда
                ЕстьОшибкаКурса = Истина;
                СообщениеОшибки = "Не найден курс для валюты " + СтрокаОстаток.Валюта + " на дату " + ДатаЗаказа;
                Прервать;
            КонецЕсли;
        КонецЕсли;
        СуммаДЗВРублях = СуммаДЗВРублях + СтрокаОстаток.СуммаОстатка * Курс;
    КонецЦикла;

    Если ЕстьОшибкаКурса Тогда
        Результат = Новый Структура;
        Результат.Вставить("СуммаДебиторскойЗадолженности", 0);
        Результат.Вставить("СуммаДебиторскойЗадолженностиСЗаказом", 0);
        Результат.Вставить("СуммаЗаказаВРублях", 0);
        Результат.Вставить("ЛимитНеПревышен", Ложь);
        Результат.Вставить("СообщениеПользователю", СообщениеОшибки);
        Возврат Результат;
    КонецЕсли;

    // 5. Расчет суммы заказа в рублях
    Если ВалютаЗаказа = ВалютаРубль Тогда
        КурсЗаказа = 1;
    Иначе
        КурсЗаказа = КурсыВалют.Получить(ВалютаЗаказа);
        Если КурсЗаказа = Неопределено Тогда
            Результат = Новый Структура;
            Результат.Вставить("СуммаДебиторскойЗадолженности", СуммаДЗВРублях);
            Результат.Вставить("СуммаДебиторскойЗадолженностиСЗаказом", 0);
            Результат.Вставить("СуммаЗаказаВРублях", 0);
            Результат.Вставить("ЛимитНеПревышен", Ложь);
            Результат.Вставить("СообщениеПользователю", "Не найден курс для валюты заказа " + ВалютаЗаказа + " на дату " + ДатаЗаказа);
            Возврат Результат;
        КонецЕсли;
    КонецЕсли;

    СуммаЗаказаВРублях = СуммаЗаказа * КурсЗаказа;

    // 6. Сумма задолженности с учетом заказа
    СуммаДЗСЗаказом = СуммаДЗВРублях + СуммаЗаказаВРублях;

    // 7. Проверка лимита
    ЛимитНеПревышен = СуммаДЗСЗаказом <= ЛимитВРублях;

    // 8. Формирование сообщения пользователю
    Сообщение = "Дебиторская задолженность: " + Формат(СуммаДЗВРублях, "ЧДЦ=2") + " руб." + Символы.ПС;
    Сообщение = Сообщение + "Сумма заказа: " + Формат(СуммаЗаказаВРублях, "ЧДЦ=2") + " руб." + Символы.ПС;
    Сообщение = Сообщение + "Задолженность с заказом: " + Формат(СуммаДЗСЗаказом, "ЧДЦ=2") + " руб." + Символы.ПС;
    Сообщение = Сообщение + "Лимит: " + Формат(ЛимитВРублях, "ЧДЦ=2") + " руб." + Символы.ПС;
    Если ЛимитНеПревышен Тогда
        Сообщение = Сообщение + "Лимит не превышен.";
    Иначе
        Сообщение = Сообщение + "Лимит превышен!";
    КонецЕсли;

    // 9. Возврат результирующей структуры
    Результат = Новый Структура;
    Результат.Вставить("СуммаДебиторскойЗадолженности", СуммаДЗВРублях);
    Результат.Вставить("СуммаДебиторскойЗадолженностиСЗаказом", СуммаДЗСЗаказом);
    Результат.Вставить("СуммаЗаказаВРублях", СуммаЗаказаВРублях);
    Результат.Вставить("ЛимитНеПревышен", ЛимитНеПревышен);
    Результат.Вставить("СообщениеПользователю", Сообщение);

    Возврат Результат;
КонецФункции

Функция ПолучитьТаблицуАнализаПродаж(НачалоПериода, ОкончаниеПериода, НормаПродаж)
    // Создаём результирующую таблицу значений
    ТЗРезультат = Новый ТаблицаЗначений;
    ТЗРезультат.Колонки.Добавить("Товар",                   Новый ОписаниеТипов("СправочникСсылка.Товары"));
    ТЗРезультат.Колонки.Добавить("КоличествоДнейМин",      Новый ОписаниеТипов("Число"));
    ТЗРезультат.Колонки.Добавить("КоличествоДнейМакс",     Новый ОписаниеТипов("Число"));
    ТЗРезультат.Колонки.Добавить("КоличествоДнейНорма",    Новый ОписаниеТипов("Число"));
    ТЗРезультат.Колонки.Добавить("СуммаВсего",             Новый ОписаниеТипов("Число"));
    ТЗРезультат.Колонки.Добавить("ОстатокНаКонецПериода",  Новый ОписаниеТипов("Число"));

    // 1. Получаем продажи с детализацией по дням и товарам
    ЗапросПродажи = Новый Запрос;
    ЗапросПродажи.Текст = 
    "ВЫБРАТЬ
    |    ПродажиОбороты.Товар КАК Товар,
    |    ПродажиОбороты.Период КАК Период,
    |    ПродажиОбороты.СуммаОборот КАК СуммаДня
    |ИЗ
    |    РегистрНакопления.Продажи.Обороты(
    |        &НачалоПериода,
    |        &ОкончаниеПериода,
    |        День,
    |        ,
    |        Товар) КАК ПродажиОбороты";

    ЗапросПродажи.УстановитьПараметр("НачалоПериода",   НачалоПериода);
    ЗапросПродажи.УстановитьПараметр("ОкончаниеПериода", ОкончаниеПериода);
    ТЗПродажиПоДням = ЗапросПродажи.Выполнить().Выгрузить();

    // Группируем дневные продажи в соответствие: товар -> таблица дней
    СоответствиеПродажи = Новый Соответствие;
    Для каждого Строка Из ТЗПродажиПоДням Цикл
        ТоварКлюч = Строка.Товар;
        Если Не СоответствиеПродажи.Свойство(ТоварКлюч, ТабПродажТовара) Тогда
            ТабПродажТовара = Новый ТаблицаЗначений;
            ТабПродажТовара.Колонки.Добавить("Период",   Новый ОписаниеТипов("Дата"));
            ТабПродажТовара.Колонки.Добавить("СуммаДня", Новый ОписаниеТипов("Число"));
            СоответствиеПродажи.Вставить(ТоварКлюч, ТабПродажТовара);
        КонецЕсли;
        НоваяСтр = ТабПродажТовара.Добавить();
        НоваяСтр.Период   = Строка.Период;
        НоваяСтр.СуммаДня = Строка.СуммаДня;
    КонецЦикла;

    // 2. Получаем остатки товаров на конец периода (суммарно по всем складам)
    ЗапросОстатки = Новый Запрос;
    ЗапросОстатки.Текст = 
    "ВЫБРАТЬ
    |    ТоварныеЗапасыОстатки.Товар КАК Товар,
    |    ТоварныеЗапасыОстатки.КоличествоОстаток КАК Остаток
    |ИЗ
    |    РегистрНакопления.ТоварныеЗапасы.Остатки(
    |        &ДатаОстатков,
    |        Товар) КАК ТоварныеЗапасыОстатки";

    ЗапросОстатки.УстановитьПараметр("ДатаОстатков", ОкончаниеПериода);
    ТЗОстатки = ЗапросОстатки.Выполнить().Выгрузить();

    СоответствиеОстатков = Новый Соответствие;
    Для каждого Строка Из ТЗОстатки Цикл
        СоответствиеОстатков.Вставить(Строка.Товар, Строка.Остаток);
    КонецЦикла;

    // 3. Формируем полный набор товаров (есть продажи или есть остатки)
    МножествоТоваров = Новый Соответствие;
    Для каждого КлючИзПродаж Из СоответствиеПродажи Цикл
        МножествоТоваров.Вставить(КлючИзПродаж.Ключ, Истина);
    КонецЦикла;
    Для каждого КлючИзОстатков Из СоответствиеОстатков Цикл
        МножествоТоваров.Вставить(КлючИзОстатков.Ключ, Истина);
    КонецЦикла;

    // 4. Рассчитываем показатели для каждого товара
    Для каждого Элемент Из МножествоТоваров Цикл
        Товар = Элемент.Ключ;

        // Достаём дневные продажи товара (если есть)
        ТабПродажТовара = Неопределено;
        СоответствиеПродажи.Свойство(Товар, ТабПродажТовара);
        СоотвДеньСумма = Новый Соответствие;
        Если ТабПродажТовара <> Неопределено Тогда
            Для каждого СтрПродажи Из ТабПродажТовара Цикл
                СоотвДеньСумма.Вставить(СтрПродажи.Период, СтрПродажи.СуммаДня);
            КонецЦикла;
        КонецЕсли;

        // Первый проход – сумма всего и максимальная сумма дня
        СуммаВсего = 0;
        МаксСумма  = 0;
        ДатаТек = НачалоПериода;
        Пока ДатаТек <= ОкончаниеПериода Цикл
            Знач = СоотвДеньСумма.Получить(ДатаТек);
            ТекСумма = ?(Знач <> Неопределено, Знач, 0);
            СуммаВсего = СуммаВсего + ТекСумма;
            Если ТекСумма > МаксСумма Тогда
                МаксСумма = ТекСумма;
            КонецЕсли;
            ДатаТек = ДатаТек + 86400; // следующий день
        КонецЦикла;

        // Второй проход – подсчёт дней по критериям
        ДнейМин   = 0;
        ДнейМакс  = 0;
        ДнейНорма = 0;
        ДатаТек = НачалоПериода;
        Пока ДатаТек <= ОкончаниеПериода Цикл
            Знач = СоотвДеньСумма.Получить(ДатаТек);
            ТекСумма = ?(Знач <> Неопределено, Знач, 0);
            Если ТекСумма = 0 Тогда
                ДнейМин = ДнейМин + 1;
            КонецЕсли;
            Если ТекСумма = МаксСумма Тогда
                ДнейМакс = ДнейМакс + 1;
            КонецЕсли;
            Если ТекСумма > НормаПродаж Тогда
                ДнейНорма = ДнейНорма + 1;
            КонецЕсли;
            ДатаТек = ДатаТек + 86400;
        КонецЦикла;

        ОстатокНаКонец = ?(СоответствиеОстатков.Свойство(Товар, Ост), Ост, 0);

        НовСтрока = ТЗРезультат.Добавить();
        НовСтрока.Товар                   = Товар;
        НовСтрока.КоличествоДнейМин      = ДнейМин;
        НовСтрока.КоличествоДнейМакс     = ДнейМакс;
        НовСтрока.КоличествоДнейНорма    = ДнейНорма;
        НовСтрока.СуммаВсего             = СуммаВсего;
        НовСтрока.ОстатокНаКонецПериода  = ОстатокНаКонец;
    КонецЦикла;

    Возврат ТЗРезультат;
КонецФункции

Функция ЗаполнитьТабличныйДокумент(ТабДокумент, Макет, Дата, ВидЦен) Экспорт

    ТабДокумент.Очистить();

    // Вывод шапки
    ОбластьШапка = Макет.Область("Шапка");
    ОбластьШапка.Параметры.НаДату = Дата;
    ТабДокумент.Вывести(ОбластьШапка);

    // Вывод шапки таблицы
    ОбластьШапкаТаблицы = Макет.Область("ШапкаТаблицы");
    ТабДокумент.Вывести(ОбластьШапкаТаблицы);

    // Построение запроса актуальных цен на дату
    Запрос = Новый Запрос;
    Запрос.Текст = 
    "ВЫБРАТЬ
    |    ЦеныТоваровСрезПоследних.Товар КАК Товар,
    |    Товары.Артикул КАК Артикул,
    |    ЦеныТоваровСрезПоследних.ВидЦен КАК ВидЦен,
    |    ЦеныТоваровСрезПоследних.Цена КАК Цена
    |ИЗ
    |    РегистрСведений.ЦеныТоваров.СрезПоследних(&Дата) КАК ЦеныТоваровСрезПоследних
    |        ЛЕВОЕ СОЕДИНЕНИЕ Справочник.Товары КАК Товары
    |        ПО ЦеныТоваровСрезПоследних.Товар = Товары.Ссылка";

    Если ВидЦен <> Неопределено Тогда
        Запрос.Текст = Запрос.Текст + "
        |ГДЕ
        |    ЦеныТоваровСрезПоследних.ВидЦен = &ВидЦен";
        Запрос.УстановитьПараметр("ВидЦен", ВидЦен);
    КонецЕсли;

    Запрос.УстановитьПараметр("Дата", Дата);

    Результат = Запрос.Выполнить();

    // Вывод строк с ценами
    ОбластьСтрокаШаблон = Макет.Область("Строка");

    Выборка = Результат.Выбрать();
    Пока Выборка.Следующий() Цикл
        ОбластьСтрока = ОбластьСтрокаШаблон.Копировать();
        ОбластьСтрока.Параметры.Товар = Выборка.Товар;
        ОбластьСтрока.Параметры.Артикул = Выборка.Артикул;
        ОбластьСтрока.Параметры.ВидЦен = Выборка.ВидЦен;
        ОбластьСтрока.Параметры.Цена = Выборка.Цена;
        ТабДокумент.Вывести(ОбластьСтрока);
    КонецЦикла;

КонецФункции

Функция НайтиКонтрагентовПоКонтактнойИнформации(СтрокаКонтактнойИнформации)

    Если ПустаяСтрока(СтрокаКонтактнойИнформации) Тогда
        Возврат Новый Структура("КонтактнаяИнформация,Количество,КоличествоПолныхСоответствий,Контрагенты", 
            Неопределено, Неопределено, Неопределено, Неопределено);
    КонецЕсли;

    // Подготовка таблицы результатов
    ТаблицаРезультатов = Новый ТаблицаЗначений;
    ТаблицаРезультатов.Колонки.Добавить("Контрагент", Новый ОписаниеТипов("СправочникСсылка.Контрагенты"));
    ТаблицаРезультатов.Колонки.Добавить("ТипКонтактнойИнформации", Новый ОписаниеТипов("Строка"));
    ТаблицаРезультатов.Колонки.Добавить("Значение", Новый ОписаниеТипов("Строка"));
    ТаблицаРезультатов.Колонки.Добавить("ПолноеСоответствие", Новый ОписаниеТипов("Булево"));

    // Запрос на получение всех контрагентов с нужными реквизитами
    Запрос = Новый Запрос;
    Запрос.Текст = 
    "ВЫБРАТЬ
    | Контрагенты.Ссылка КАК Ссылка,
    | Контрагенты.Телефон КАК Телефон,
    | Контрагенты.Факс КАК Факс,
    | Контрагенты.ЭлектроннаяПочта КАК ЭлектроннаяПочта,
    | Контрагенты.ВебСайт КАК ВебСайт
    |ИЗ
    | Справочник.Контрагенты КАК Контрагенты
    |ГДЕ
    | Контрагенты.ПометкаУдаления = Ложь
    | И (Контрагенты.Телефон <> "" ИЛИ Контрагенты.Факс <> "" ИЛИ Контрагенты.ЭлектроннаяПочта <> "" ИЛИ Контрагенты.ВебСайт <> "")";

