Функция ВыполнитьABCАнализПродаж(ДатаНач, ДатаКон) Экспорт

    // Создаём таблицу для результата
    ТаблицаРезультата = Новый ТаблицаЗначений;
    ТаблицаРезультата.Колонки.Добавить("Товар", Новый ОписаниеТипов("СправочникСсылка.Товары"));
    ТаблицаРезультата.Колонки.Добавить("НаименованиеТовара", Новый ОписаниеТипов("Строка"));
    ТаблицаРезультата.Колонки.Добавить("СуммаПродаж", Новый ОписаниеТипов("Число", Новый КвалификаторыЧисла(15, 2)));
    ТаблицаРезультата.Колонки.Добавить("ДоляПроцентов", Новый ОписаниеТипов("Число", Новый КвалификаторыЧисла(10, 2)));
    ТаблицаРезультата.Колонки.Добавить("НакопительныйПроцент", Новый ОписаниеТипов("Число", Новый КвалификаторыЧисла(10, 2)));
    ТаблицаРезультата.Колонки.Добавить("КатегорияABC", Новый ОписаниеТипов("Строка", , , Новый КвалификаторыСтроки(1)));

    // Формируем запрос для получения оборотов по товарам за период
    Запрос = Новый Запрос;
    Запрос.Текст = 
    "ВЫБРАТЬ
    |    ПродажиОбороты.Товар КАК Товар,
    |    Товар.Наименование КАК НаименованиеТовара,
    |    СУММА(ПродажиОбороты.Сумма) КАК СуммаПродаж
    |ИЗ
    |    РегистрНакопления.Продажи.Обороты(&ДатаНач, &ДатаКон, ) КАК ПродажиОбороты
    |        ЛЕВОЕ СОЕДИНЕНИЕ Справочник.Товары КАК Товар
    |        ПО ПродажиОбороты.Товар = Товар.Ссылка
    |СГРУППИРОВАТЬ ПО
    |    ПродажиОбороты.Товар,
    |    Товар.Наименование
    |УПОРЯДОЧИТЬ ПО
    |    СуммаПродаж УБЫВ";

    Запрос.УстановитьПараметр("ДатаНач", ДатаНач);
    Запрос.УстановитьПараметр("ДатаКон", ДатаКон);

    // Выполняем запрос и собираем данные
    РезультатЗапроса = Запрос.Выполнить();

    Выборка = РезультатЗапроса.Выбрать();

    // Первый проход: заполняем таблицу значений и накапливаем общую сумму
    ОбщаяСумма = 0;
    Пока Выборка.Следующий() Цикл
        НоваяСтрока = ТаблицаРезультата.Добавить();
        НоваяСтрока.Товар = Выборка.Товар;
        НоваяСтрока.НаименованиеТовара = Выборка.НаименованиеТовара;
        НоваяСтрока.СуммаПродаж = Выборка.СуммаПродаж;
        ОбщаяСумма = ОбщаяСумма + Выборка.СуммаПродаж;
        // Временные значения для последующего расчёта
        НоваяСтрока.ДоляПроцентов = 0;
        НоваяСтрока.НакопительныйПроцент = 0;
        НоваяСтрока.КатегорияABC = "";
    КонецЦикла;

    // Второй проход: расчёт процентов и присвоение категорий
    Если ОбщаяСумма > 0 Тогда
        ТекущийНакопленныйПроцент = 0;
        Для Каждого Строка Из ТаблицаРезультата Цикл
            Доля = Строка.СуммаПродаж / ОбщаяСумма * 100;
            Строка.ДоляПроцентов = Окр(Доля, 2);
            ТекущийНакопленныйПроцент = ТекущийНакопленныйПроцент + Доля;
            Строка.НакопительныйПроцент = Окр(ТекущийНакопленныйПроцент, 2);

            // Определение категории
            Если Строка.НакопительныйПроцент <= 80 Тогда
                Строка.КатегорияABC = "A";
            ИначеЕсли Строка.НакопительныйПроцент <= 95 Тогда
                Строка.КатегорияABC = "B";
            Иначе
                Строка.КатегорияABC = "C";
            КонецЕсли;
        КонецЦикла;
    КонецЕсли;

    Возврат ТаблицаРезультата;

КонецФункции

Функция ВыгрузитьЗадолженностьВФайлJSON()

    // Формирование запроса для получения текущих остатков по контрагентам
    Запрос = Новый Запрос;
    Запрос.Текст = 
        "ВЫБРАТЬ
        |    ВзаиморасчетыОстатки.Контрагент КАК Контрагент,
        |    ВзаиморасчетыОстатки.Контрагент.Код КАК КодКонтрагента,
        |    ВзаиморасчетыОстатки.СуммаОстаток КАК СуммаОстаток
        |ИЗ
        |    РегистрНакопления.Взаиморасчеты.Остатки КАК ВзаиморасчетыОстатки
        |ГДЕ
        |    ВзаиморасчетыОстатки.СуммаОстаток <> 0
        |УПОРЯДОЧИТЬ ПО
        |    Контрагент";

    РезультатЗапроса = Запрос.Выполнить();

    // Подготовка временного файла
    ИмяФайла = ПолучитьИмяВременногоФайла("json");
    ЗаписьJSON = Новый ЗаписьJSON;
    ЗаписьJSON.ОткрытьФайл(ИмяФайла, "UTF-8");

    // Начало массива
    ЗаписьJSON.ЗаписатьНачалоМассива();

    Выборка = РезультатЗапроса.Выбрать();
    Пока Выборка.Следующий() Цикл

        // Определение вида задолженности
        Если Выборка.СуммаОстаток > 0 Тогда
            ВидЗадолженности = "Дебиторская";
        Иначе
            ВидЗадолженности = "Кредиторская";
        КонецЕсли;

        // Запись объекта
        ЗаписьJSON.ЗаписатьНачалоОбъекта();
        ЗаписьJSON.ЗаписатьИмяСвойства("Контрагент");
        ЗаписьJSON.ЗаписатьЗначение(Строка(Выборка.Контрагент));
        ЗаписьJSON.ЗаписатьИмяСвойства("КодКонтрагента");
        ЗаписьJSON.ЗаписатьЗначение(Строка(Выборка.КодКонтрагента));
        ЗаписьJSON.ЗаписатьИмяСвойства("СуммаОстаток");
        ЗаписьJSON.ЗаписатьЗначение(Выборка.СуммаОстаток);
        ЗаписьJSON.ЗаписатьИмяСвойства("ВидЗадолженности");
        ЗаписьJSON.ЗаписатьЗначение(ВидЗадолженности);
        ЗаписьJSON.ЗаписатьКонецОбъекта();

    КонецЦикла;

    // Завершение массива
    ЗаписьJSON.ЗаписатьКонецМассива();
    ЗаписьJSON.Закрыть();

    Возврат ИмяФайла;

КонецФункции

Функция СформироватьОтчетОстаткиПоНоменклатуре(ДатаОтчета, МассивТоваров = Неопределено, Склад = Неопределено)

    Запрос = Новый Запрос;
    Запрос.Текст = 
    "ВЫБРАТЬ
    |    Товар КАК Номенклатура,
    |    Количество КАК Остаток
    |ИЗ
    |    РегистрНакопления.ТоварныеЗапасы.Остатки(&ДатаОтчета) КАК Остатки";

    // Динамическое построение условий отбора
    Условия = "";
    Если МассивТоваров <> Неопределено И МассивТоваров.Количество() > 0 Тогда
        Условия = Условия + ?(ПустаяСтрока(Условия), "", " И ") + "Товар В (&МассивТоваров)";
    КонецЕсли;
    Если Склад <> Неопределено Тогда
        Условия = Условия + ?(ПустаяСтрока(Условия), "", " И ") + "Склад = &Склад";
    КонецЕсли;

    Если Не ПустаяСтрока(Условия) Тогда
        Запрос.Текст = Запрос.Текст + "
        |ГДЕ
        |    " + Условия;
    КонецЕсли;

    Запрос.УстановитьПараметр("ДатаОтчета", ДатаОтчета);
    Если МассивТоваров <> Неопределено И МассивТоваров.Количество() > 0 Тогда
        Запрос.УстановитьПараметр("МассивТоваров", МассивТоваров);
    КонецЕсли;
    Если Склад <> Неопределено Тогда
        Запрос.УстановитьПараметр("Склад", Склад);
    КонецЕсли;

    РезультатЗапроса = Запрос.Выполнить();

    // Формирование табличного документа
    ТабДок = Новый ТабличныйДокумент;
    ТабДок.Очистить();

    // Заголовок
    ОбластьЗаголовок = ТабДок.Область(1, 1, 1, 2);
    ОбластьЗаголовок.Объединить();
    ОбластьЗаголовок.Текст = "Остатки номенклатуры";
    ОбластьЗаголовок.Шрифт = Новый Шрифт(, 12, Истина);
    ОбластьЗаголовок.ГоризонтальноеПоложение = ГоризонтальноеПоложение.Центр;
    ТабДок.Вывести(ОбластьЗаголовок);

    // Шапка таблицы
    ОбластьШапки = ТабДок.Область(2, 1, 2, 2);
    ОбластьШапки.Область(1, 1).Текст = "Номенклатура";
    ОбластьШапки.Область(1, 2).Текст = "Остаток";
    ОбластьШапки.Шрифт = Новый Шрифт(, 10, Истина);
    ТабДок.Вывести(ОбластьШапки);

    // Вывод данных и расчет итогов
    ИтогоОстаток = 0;
    НомерСтроки = 3;
    Пока РезультатЗапроса.Следующий() Цикл
        ОбластьСтроки = ТабДок.Область(НомерСтроки, 1, НомерСтроки, 2);
        ОбластьСтроки.Область(1, 1).Текст = РезультатЗапроса.Номенклатура;
        ОстатокТек = РезультатЗапроса.Остаток;
        ОбластьСтроки.Область(1, 2).Текст = ОстатокТек;
        ОбластьСтроки.Область(1, 2).ГоризонтальноеПоложение = ГоризонтальноеПоложение.Право;
        ТабДок.Вывести(ОбластьСтроки);
        ИтогоОстаток = ИтогоОстаток + ОстатокТек;
        НомерСтроки = НомерСтроки + 1;
    КонецЦикла;

    // Итоговая строка (только если были записи)
    Если НомерСтроки > 3 Тогда
        ОбластьИтогов = ТабДок.Область(НомерСтроки, 1, НомерСтроки, 2);
        ОбластьИтогов.Область(1, 1).Текст = "Итого";
        ОбластьИтогов.Область(1, 2).Текст = ИтогоОстаток;
        ОбластьИтогов.Шрифт = Новый Шрифт(, 10, Истина);
        ОбластьИтогов.Область(1, 2).ГоризонтальноеПоложение = ГоризонтальноеПоложение.Право;
        ТабДок.Вывести(ОбластьИтогов);
    КонецЕсли;

    Возврат ТабДок;

КонецФункции

Функция РассчитатьОборачиваемость(Товар, Склад, ДатаНачала, ДатаОкончания)

    // Приводим даты к началу и концу дня для корректного получения остатков и оборотов
    ДатаНачалаОст = НачалоДня(ДатаНачала);
    ДатаОкончанияОст = КонецДня(ДатаОкончания);

    Запрос = Новый Запрос;
    Запрос.Текст = 
    "ВЫБРАТЬ
    |   Товар,
    |   Склад,
    |   Количество КАК ОстатокНачало
    |ПОМЕСТИТЬ НачальныеОстатки
    |ИЗ
    |   РегистрНакопления.ТоварныеЗапасы.Остатки(&ДатаНачалаОст, Товар = &Товар И Склад = &Склад)
    |;
    |
    |ВЫБРАТЬ
    |   Товар,
    |   Склад,
    |   Количество КАК ОстатокКонец
    |ПОМЕСТИТЬ КонечныеОстатки
    |ИЗ
    |   РегистрНакопления.ТоварныеЗапасы.Остатки(&ДатаОкончанияОст, Товар = &Товар И Склад = &Склад)
    |;
    |
    |ВЫБРАТЬ
    |   Товар,
    |   Склад,
    |   КоличествоОборот КАК Оборот
    |ПОМЕСТИТЬ ОборотыЗаПериод
    |ИЗ
    |   РегистрНакопления.ТоварныеЗапасы.Обороты(&ДатаНачалаОст, &ДатаОкончанияОст, , Товар = &Товар И Склад = &Склад)
    |;
    |
    |// Собираем все уникальные пары измерений, которые могли появиться в любом из разрезов
    |ВЫБРАТЬ
    |   Товар,
    |   Склад
    |ПОМЕСТИТЬ Измерения
    |ИЗ
    |   (ВЫБРАТЬ Товар, Склад ИЗ НачальныеОстатки
    |    ОБЪЕДИНИТЬ
    |    ВЫБРАТЬ Товар, Склад ИЗ КонечныеОстатки
    |    ОБЪЕДИНИТЬ
    |    ВЫБРАТЬ Товар, Склад ИЗ ОборотыЗаПериод) КАК ВсеИзмерения
    |;
    |
    |// Объединяем данные
    |ВЫБРАТЬ
    |   ЕСТЬNULL(Нач.ОстатокНачало, 0) КАК ОстатокНачало,
    |   ЕСТЬNULL(Кон.ОстатокКонец, 0) КАК ОстатокКонец,
    |   ЕСТЬNULL(Об.Оборот, 0) КАК Оборот
    |ИЗ
    |   Измерения КАК Измерения
    |   ЛЕВОЕ СОЕДИНЕНИЕ НачальныеОстатки КАК Нач ПО Измерения.Товар = Нач.Товар И Измерения.Склад = Нач.Склад
    |   ЛЕВОЕ СОЕДИНЕНИЕ КонечныеОстатки КАК Кон ПО Измерения.Товар = Кон.Товар И Измерения.Склад = Кон.Склад
    |   ЛЕВОЕ СОЕДИНЕНИЕ ОборотыЗаПериод КАК Об ПО Измерения.Товар = Об.Товар И Измерения.Склад = Об.Склад";

    Запрос.УстановитьПараметр("ДатаНачалаОст", ДатаНачалаОст);
    Запрос.УстановитьПараметр("ДатаОкончанияОст", ДатаОкончанияОст);
    Запрос.УстановитьПараметр("Товар", Товар);
    Запрос.УстановитьПараметр("Склад", Склад);

    Результат = Запрос.Выполнить();

    // Если за весь период не было ни остатков, ни оборотов – возвращаем 0
    Если Результат.Пустой() Тогда
        Возврат 0;
    КонецЕсли;

    Выборка = Результат.Выбрать();
    Выборка.Следующий();

    ОстатокНачало = Выборка.ОстатокНачало;
    ОстатокКонец = Выборка.ОстатокКонец;
    Оборот = Выборка.Оборот;

    СреднийОстаток = (ОстатокНачало + ОстатокКонец) / 2;

    Если СреднийОстаток = 0 Тогда
        Возврат 0;
    Иначе
        Возврат Оборот / СреднийОстаток;
    КонецЕсли;

КонецФункции

task:
Написать функцию СформироватьПрайсТоваровНаСкладе(Дата = Неопределено),
которая формирует прайс товаров, имеющихся в наличии на складе, на указанную дату.
Формирование прайса должно выполняться на основании данных регистра накопления «ТоварныеЗапасы» и регистра сведений «ЦеныТоваров».
Если параметр Дата не передан, в качестве даты формирования прайса используется конец текущего дня (КонецДня(ТекущаяДата())).
Алгоритм формирования данных выполняется следующим образом:
Сначала выполняется запрос к регистру накопления РегистрНакопления.ТоварныеЗапасы.Остатки, где:
отбираются только товары с положительным остатком (КоличествоОстаток > 0);
данные агрегируются по товару;
результат помещается во временную таблицу (ВременнаяТаблица), содержащую:
Товар;
КоличествоОстаток (суммарный остаток по товару).
Далее выполняется основной запрос, в котором:
используются актуальные цены из регистра сведений РегистрСведений.ЦеныТоваров (СрезПоследних);
выполняется внутреннее соединение с временной таблицей остатков по полю Товар;
рассчитываются итоговые показатели:
Цена — актуальная цена товара;
Остаток — количество товара на складе;
СуммаОстатков — произведение остатка на цену (стоимость складского запаса).
Результат запроса выгружается в таблицу значений.
На основании полученных данных формируется итоговая таблица (ТаблицаЗначений) со следующей структурой колонок:
Товар (СправочникСсылка.Товары);
Наименование (строковое представление товара);
Остаток (число);
Цена (число);
СуммаОстатков (число).
Для каждой строки выборки:
создаётся новая строка в таблице значений;
заполняются поля Товар, Остаток, Цена и СуммаОстатков.
После заполнения таблица сортируется по наименованию товара по возрастанию, что обеспечивает удобный вид прайса для анализа и печати.
Функция возвращает таблицу значений, содержащую прайс товаров на складе с актуальными остатками и ценами на указанную дату.
Функция ЗадачаРешена(ТабДок) предназначена для проверки корректности сформированного прайса и выполняет следующие проверки:
результат является типом ТаблицаЗначений;
таблица содержит обязательные колонки: Товар, Цена, Остаток;
таблица не пустая;
у каждой строки заполнен товар;
остаток товара не является отрицательным.
Если все проверки выполняются успешно, функция возвращает Истина, что подтверждает корректное формирование прайса товаров на складе.

output:
Функция СформироватьПрайсТоваровНаСкладе(Дата = Неопределено) Экспорт
    // Определяем дату запроса: если параметр не передан, используем конец текущего дня
    Если Дата = Неопределено Тогда
        ДатаЗапроса = КонецДня(ТекущаяДата());
    Иначе
        ДатаЗапроса = КонецДня(Дата);
    КонецЕсли;

    Запрос = Новый Запрос;
    Запрос.Текст = 
    "ВЫБРАТЬ
    |    ТоварныеЗапасыОстатки.Товар КАК Товар,
    |    СУММА(ТоварныеЗапасыОстатки.Количество) КАК КоличествоОстаток
    |ПОМЕСТИТЬ ВТОстатки
    |ИЗ
    |    РегистрНакопления.ТоварныеЗапасы.Остатки(&Дата) КАК ТоварныеЗапасыОстатки
    |ГДЕ
    |    ТоварныеЗапасыОстатки.Количество > 0
    |СГРУППИРОВАТЬ ПО
    |    ТоварныеЗапасыОстатки.Товар
    |;
    |ВЫБРАТЬ
    |    Цены.Товар КАК Товар,
    |    Цены.Товар.Наименование КАК Наименование,
    |    ВТОстатки.КоличествоОстаток КАК Остаток,
    |    Цены.Цена КАК Цена,
    |    ВТОстатки.КоличествоОстаток * Цены.Цена КАК СуммаОстатков
    |ИЗ
    |    РегистрСведений.ЦеныТоваров.СрезПоследних(&Дата) КАК Цены
    |        ВНУТРЕННЕЕ СОЕДИНЕНИЕ ВТОстатки КАК ВТОстатки
    |        ПО Цены.Товар = ВТОстатки.Товар";

    Запрос.УстановитьПараметр("Дата", ДатаЗапроса);
    РезультатЗапроса = Запрос.Выполнить();
    ТаблицаРезультат = РезультатЗапроса.Выгрузить();

    // Сортировка по наименованию товара для получения прайса в алфавитном порядке
    ТаблицаРезультат.Сортировать("Наименование Возр");

    Возврат ТаблицаРезультат;
КонецФункции

&НаСервере
Функция СформироватьОтчетДинамикаПродажТовара(ДатаНачала, ДатаОкончания, Товар) Экспорт

    // Создаём объект отчета
    ОтчетОбъект = Отчеты.ДинамикаПродаж.Создать();

    // Получаем компоновщик настроек
    КомпоновщикНастроек = ОтчетОбъект.КомпоновщикНастроек;

    // Загружаем настройки нужного варианта отчета
    ВариантНастроек = КомпоновщикНастроек.ВариантыНастроек.Найти(Новый Структура("Имя", "СуммаИКоличество"));
    Если ВариантНастроек <> Неопределено Тогда
        КомпоновщикНастроек.ЗагрузитьНастройки(ВариантНастроек);
    КонецЕсли;

    Настройки = КомпоновщикНастроек.Настройки;

    // 1. Изменяем структуру отчета: очищаем и создаём группировку "Период"
    Настройки.Структура.Элементы.Очистить();
    ГруппировкаПериод = Настройки.Структура.Добавить(Тип("ГруппировкаКомпоновкиДанных"));
    ГруппировкаПериод.Имя = "Период";
    ГруппировкаПериод.Поле = Новый ПолеКомпоновкиДанных("Период");
    ГруппировкаПериод.ТипГруппировки = ТипГруппировкиКомпоновкиДанных.Элементы;
    ГруппировкаПериод.ТипДополнения = ТипДополненияПериодаКомпоновкиДанных.БезДополнения;

    // 2. Устанавливаем параметры данных: период
    ПараметрПериод = Настройки.ПараметрыДанных.Элементы.Найти("Период");
    Если ПараметрПериод = Неопределено Тогда
        // На некоторых компоновках параметр может отсутствовать, игнорируем
    Иначе
        СтандартныйПериод = Новый СтандартныйПериод;
        СтандартныйПериод.ДатаНачала = ДатаНачала;
        СтандартныйПериод.ДатаОкончания = ДатаОкончания;
        ПараметрПериод.Значение = СтандартныйПериод;
        ПараметрПериод.Использование = Истина;
    КонецЕсли;

    // 3. Настройки вывода
    Настройки.ПараметрыВывода.ВыводитьПараметрыДанных = Ложь;
    Настройки.ПараметрыВывода.ВыводитьОтбор = Ложь;

    // 4. Отбор по товару
    Отборы = Настройки.Отбор.Элементы;
    Отборы.Очистить();
    НовыйОтбор = Отборы.Добавить(Тип("ЭлементОтбораКомпоновкиДанных"));
    НовыйОтбор.ЛевоеЗначение = Новый ПолеКомпоновкиДанных("Товар");
    НовыйОтбор.ВидСравнения = ВидСравненияКомпоновкиДанных.Равно;
    НовыйОтбор.ПравоеЗначение = Товар;
    НовыйОтбор.Использование = Истина;

    // Формируем табличный документ
    ТабличныйДокумент = Новый ТабличныйДокумент;
    ОтчетОбъект.СкомпоноватьРезультат(ТабличныйДокумент, Настройки);

    Возврат ТабличныйДокумент;

КонецФункции

task:
Написать функцию СформироватьПереоценкуТоваровНаСкладе(Дата, ПроцентПереоценки),
которая формирует расчет переоценки товаров на складе и выводит прайс с учетом увеличения цены на заданный процент (по умолчанию 10%).
Расчет должен выполняться на основании остатков товаров на складе и актуальных цен номенклатуры.
В обработку должны попадать только те товары, по которым есть положительные остатки на складе.
Если параметр Дата не задан, используется текущая дата (конец дня).
Если процент переоценки не задан, используется значение 10%.
Источник данных:
Регистр накопления ТоварныеЗапасы (остатки товаров на складе);
Регистр сведений ЦеныТоваров (актуальные цены товаров, срез последних на дату).
Логика формирования данных:
Из регистра накопления ТоварныеЗапасы.Остатки выбираются товары с положительным количеством остатка на указанную дату.
Данные агрегируются по измерению Товар с расчетом:
Остаток — суммарное количество товара на складе.
К полученным остаткам выполняется присоединение регистра сведений ЦеныТоваров.СрезПоследних на ту же дату для получения актуальной цены.
Рассчитываются показатели переоценки:
СтараяЦена — текущая цена из регистра цен;
НоваяЦена — цена с учетом переоценки (СтараяЦена * (1 + ПроцентПереоценки / 100));
СуммаПереоценки — общий эффект переоценки по складу (разница цены * остаток товара).
Результат формирования должен представлять таблицу значений (ТаблицаЗначений), содержащую следующие колонки:
Товар (СправочникСсылка.Товары);
Наименование (представление товара);
Остаток (число);
СтараяЦена (число);
НоваяЦена (число);
СуммаПереоценки (число).
В итоговую таблицу включаются только товары, имеющие цену и положительные остатки.
Наименование товара заполняется через представление ссылочного поля номенклатуры для удобства анализа.
После заполнения данных выполняется сортировка таблицы по убыванию суммы переоценки, что позволяет в первую очередь анализировать товары с наибольшим финансовым эффектом от изменения цены.
Функция должна возвращать сформированную таблицу значений, пригодную для:
анализа розничной переоценки;
формирования прайса после изменения цен;
оценки влияния переоценки на стоимость складских остатков;
использования в управленческих отчетах по складу и рознице.

output:
Функция СформироватьПереоценкуТоваровНаСкладе(Знач Дата = Неопределено, Знач ПроцентПереоценки = 10) Экспорт
    // Обработка параметров
    Если Дата = Неопределено Тогда
        ДатаРасчета = КонецДня(ТекущаяДата());
    Иначе
        ДатаРасчета = КонецДня(Дата);
    КонецЕсли;

    // Определение вида цен для получения актуальной цены.
    // В реальной конфигурации требуется уточнение: здесь используется
    // предопределённый элемент справочника ВидыЦен с именем "ОсновнаяЦена".
    ВидЦен = Справочники.ВидыЦен.ОсновнаяЦена;

    // Формирование запроса
    Запрос = Новый Запрос;
    Запрос.Текст = 
    "ВЫБРАТЬ
    |    ТоварныеЗапасыОстатки.Товар КАК Товар,
    |    ТоварныеЗапасыОстатки.КоличествоОстаток КАК Остаток,
    |    ЦеныТоваровСрезПоследних.Цена КАК СтараяЦена
    |ИЗ
    |    РегистрНакопления.ТоварныеЗапасы.Остатки(
    |        &ДатаРасчета,
    |        Товар
    |        И Количество > 0) КАК ТоварныеЗапасыОстатки
    |    ЛЕВОЕ СОЕДИНЕНИЕ РегистрСведений.ЦеныТоваров.СрезПоследних(
    |        &ДатаРасчета,
    |        ВидЦен = &ВидЦен) КАК ЦеныТоваровСрезПоследних
    |    ПО ТоварныеЗапасыОстатки.Товар = ЦеныТоваровСрезПоследних.Товар
    |ГДЕ
    |    ЦеныТоваровСрезПоследних.Цена > 0";

    Запрос.УстановитьПараметр("ДатаРасчета", ДатаРасчета);
    Запрос.УстановитьПараметр("ВидЦен", ВидЦен);

    РезультатЗапроса = Запрос.Выполнить();

    // Создание итоговой таблицы значений
    Таблица = Новый ТаблицаЗначений;
    Таблица.Колонки.Добавить("Товар", Новый ОписаниеТипов("СправочникСсылка.Товары"));
    Таблица.Колонки.Добавить("Наименование", Новый ОписаниеТипов("Строка"));
    Таблица.Колонки.Добавить("Остаток", Новый ОписаниеТипов("Число", Новый КвалификаторыЧисла(15, 2)));
    Таблица.Колонки.Добавить("СтараяЦена", Новый ОписаниеТипов("Число", Новый КвалификаторыЧисла(15, 2)));
    Таблица.Колонки.Добавить("НоваяЦена", Новый ОписаниеТипов("Число", Новый КвалификаторыЧисла(15, 2)));
    Таблица.Колонки.Добавить("СуммаПереоценки", Новый ОписаниеТипов("Число", Новый КвалификаторыЧисла(15, 2)));

    // Заполнение таблицы
    Выборка = РезультатЗапроса.Выбрать();
    Пока Выборка.Следующий() Цикл
        Товар = Выборка.Товар;
        Остаток = Выборка.Остаток;
        СтараяЦена = Выборка.СтараяЦена;

        НоваяЦена = СтараяЦена * (1 + ПроцентПереоценки / 100);
        СуммаПереоценки = (НоваяЦена - СтараяЦена) * Остаток;

        НоваяСтрока = Таблица.Добавить();
        НоваяСтрока.Товар = Товар;
        НоваяСтрока.Наименование = Товар.Наименование;
        НоваяСтрока.Остаток = Остаток;
        НоваяСтрока.СтараяЦена = СтараяЦена;
        НоваяСтрока.НоваяЦена = НоваяЦена;
        НоваяСтрока.СуммаПереоценки = СуммаПереоценки;
    КонецЦикла;

    // Сортировка по убыванию суммы переоценки для приоритетного анализа
    Таблица.Сортировать("СуммаПереоценки Убыв");

    Возврат Таблица;
КонецФункции

&НаСервере
Функция СформироватьОтчетДинамикаПродажКонтрольВТаблице(ДатаНачала, ДатаОкончания, СуммаКонтроль, ТипКонтроля)
    // Проверка поддерживаемых видов сравнения
    Если Не (ТипКонтроля = ВидСравненияКомпоновкиДанных.Равно
          Или ТипКонтроля = ВидСравненияКомпоновкиДанных.БольшеИлиРавно
          Или ТипКонтроля = ВидСравненияКомпоновкиДанных.МеньшеИлиРавно
          Или ТипКонтроля = ВидСравненияКомпоновкиДанных.Больше
          Или ТипКонтроля = ВидСравненияКомпоновкиДанных.Меньше) Тогда
        ВызватьИсключение "Формирование отчета для данного типа контроля не поддерживается.";
    КонецЕсли;

    // Получение схемы компоновки данных отчета
    Схема = Отчеты.ДинамикаПродаж.ПолучитьМакет("ОсновнаяСхемаКомпоновкиДанных");

    // Поиск варианта настроек "ДиаграммаПоПериодам"
    Вариант = Схема.ВариантыНастроек.Найти("ДиаграммаПоПериодам");
    Если Вариант = Неопределено Тогда
        ВызватьИсключение "Вариант отчета 'ДиаграммаПоПериодам' не найден.";
    КонецЕсли;

    // Базовые настройки варианта
    Настройки = Вариант.Настройки;

    // Замена структуры: удаляем диаграмму, добавляем группировку по полю "Период"
    Настройки.Структура.Очистить();
    Группировка = Настройки.Структура.Добавить(Тип("ГруппировкаКомпоновкиДанных"));
    Группировка.Имя = "Период";
    Группировка.Поле = Новый ПолеКомпоновкиДанных("Период");
    Группировка.ТипГруппировки = ТипГруппировкиКомпоновкиДанных.Элементы;
    Группировка.ТипДополнения = ТипДополненияПериодаКомпоновкиДанных.БезДополнения;

    // Явное указание выбранных полей для вывода в группировку
    ВыбранноеПолеПериод = Группировка.Выбор.Элементы.Добавить(Тип("ВыбранноеПолеКомпоновкиДанных"));
    ВыбранноеПолеПериод.Поле = Новый ПолеКомпоновкиДанных("Период");
    ВыбранноеПолеСумма = Группировка.Выбор.Элементы.Добавить(Тип("ВыбранноеПолеКомпоновкиДанных"));
    ВыбранноеПолеСумма.Поле = Новый ПолеКомпоновкиДанных("СуммаОборот");

    // Установка параметров периода
    Период = Новый СтандартныйПериод(ДатаНачала, ДатаОкончания);
    Настройки.ПараметрыДанных.УстановитьЗначениеПараметра("Период", Период);

    // Параметры вывода
    Настройки.ВыводитьПараметрыДанных = Ложь;
    Настройки.ВыводитьОтбор = Ложь;

    // Настройка отбора по сумме
    ЭлементОтбора = Настройки.Отбор.Элементы.Добавить(Тип("ЭлементОтбораКомпоновкиДанных"));
    ЭлементОтбора.ЛевоеЗначение = Новый ПолеКомпоновкиДанных("СуммаОборот");
    ЭлементОтбора.ВидСравнения = ТипКонтроля;
    ЭлементОтбора.ПравоеЗначение = СуммаКонтроль;
    ЭлементОтбора.Использование = Истина;

    // Компоновка и вывод результата в табличный документ
    КомпоновщикМакета = Новый КомпоновщикМакетаКомпоновкиДанных;
    МакетКомпоновки = КомпоновщикМакета.Выполнить(Схема, Настройки);

    ПроцессорКомпоновки = Новый ПроцессорКомпоновкиДанных;
    ПроцессорКомпоновки.Инициализировать(МакетКомпоновки);

    ТабДок = Новый ТабличныйДокумент;
    ПроцессорВывода = Новый ПроцессорВыводаРезультатаКомпоновкиДанныхВТабличныйДокумент;
    ПроцессорВывода.УстановитьДокумент(ТабДок);
    ПроцессорВывода.Вывести(ПроцессорКомпоновки);

    Возврат ТабДок;
КонецФункции

task:
Написать функцию СформироватьРезервированиеТоваровПодЗаказы(Дата = Неопределено),
которая формирует отчет по резервированию товаров на складе под заказы клиентов в виде таблицы значений.
Отчет должен показывать, какое количество товара уже заказано клиентами, какой остаток есть на складе и хватает ли его для обеспечения заказов.
Если дата не передана в параметрах, расчет должен выполняться на конец текущего дня (КонецДня(ТекущаяДата())).
Данные для формирования отчета выбираются из следующих источников метаданных:
Документ.Заказ (табличная часть Товары);
РегистрНакопления.ТоварныеЗапасы.Остатки.
Отбор заказов выполняется по следующим условиям:
документ Заказ проведен (Проведен = Истина);
состояние заказа равно значению перечисления СостоянияЗаказов.ВРаботе.
Алгоритм формирования отчета выполняется следующим образом:
Выполняется запрос к табличной части Документ.Заказ.Товары, где:
данные агрегируются по номенклатуре (Товар);
рассчитывается суммарное количество товара в активных заказах клиентов (КоличествоВЗаказах).
Полученные данные помещаются во временную таблицу.
Далее выполняется запрос к регистру накопления ТоварныеЗапасы.Остатки на указанную дату:
определяется остаток товара на складе (КоличествоОстаток);
выполняется левое соединение с временной таблицей заказов.
Рассчитываются итоговые показатели:
ОстатокНаСкладе — текущий складской остаток товара;
КоличествоВЗаказах — общее количество товара в заказах клиентов;
ДоступныйОстаток — разница между остатком и количеством в заказах;
РезервКОбеспечению — дефицит товара (если заказов больше, чем остатка).
Результат работы функции должен представлять ТаблицаЗначений, где каждая строка соответствует одному товару.
Таблица должна содержать следующие колонки:
Товар — ссылка на элемент справочника Товары;
Наименование — наименование номенклатуры;
ОстатокНаСкладе — текущий остаток товара на складе;
КоличествоВЗаказах — суммарное количество товара в активных заказах клиентов;
ДоступныйОстаток — доступный остаток с учетом резервирования;
РезервКОбеспечению — количество товара, которого не хватает для обеспечения заказов.
В итоговую таблицу включаются только товары, по которым есть остатки или заказы клиентов.
После формирования данных таблица сортируется по полю РезервКОбеспечению в порядке убывания, что позволяет в первую очередь видеть наиболее дефицитные позиции.
Функция ЗадачаРешена(ТабДок) должна выполнять проверку корректности результата:
результат должен быть типа ТаблицаЗначений;
таблица должна содержать обязательные колонки (Товар, ОстатокНаСкладе, КоличествоВЗаказах, РезервКОбеспечению);
у всех строк должен быть заполнен товар;
значение резерва не должно быть отрицательным.
Если структура данных корректна, функция возвращает Истина, в противном случае — Ложь.

output:
Функция СформироватьОтчетДниПродажВышеНормы(ДатаНачала, ДатаОкончания, КоличествоНорма) Экспорт

    // Получаем схему компоновки данных отчета "ДинамикаПродаж"
    СхемаКомпоновкиДанных = Отчеты.ДинамикаПродаж.ПолучитьМакет("ОсновнаяСхемаКомпоновкиДанных");
    Если СхемаКомпоновкиДанных = Неопределено Тогда
        ВызватьИсключение "Не удалось получить основную схему компоновки данных отчета ДинамикаПродаж";
    КонецЕсли;

    // Инициализируем компоновщик настроек
    КомпоновщикНастроек = Новый КомпоновщикНастроекКомпоновкиДанных;
    КомпоновщикНастроек.Инициализировать(Новый ИсточникДоступныхНастроекКомпоновкиДанных(СхемаКомпоновкиДанных));

    // Загружаем настройки варианта "СуммаИКоличество"
    ВариантНайден = Ложь;
    Для Каждого Вариант Из СхемаКомпоновкиДанных.ВариантыНастроек Цикл
        Если Вариант.Имя = "СуммаИКоличество" Тогда
            КомпоновщикНастроек.ЗагрузитьНастройки(Вариант.Настройки);
            ВариантНайден = Истина;
            Прервать;
        КонецЕсли;
    КонецЦикла;

    Если Не ВариантНайден Тогда
        ВызватьИсключение "Вариант отчета 'СуммаИКоличество' не найден";
    КонецЕсли;

    // Получаем текущие настройки
    Настройки = КомпоновщикНастроек.ПолучитьНастройки();

    // Очищаем структуру отчета (убираем диаграмму и прочее)
    Настройки.Структура.Очистить();

    // Добавляем группировку по полю "Период"
    ГруппировкаПериод = Настройки.Структура.Добавить(Тип("ГруппировкаКомпоновкиДанных"));
    ГруппировкаПериод.Поле = Новый ПолеКомпоновкиДанных("Период");
    ГруппировкаПериод.ТипГруппировки = ТипГруппировкиКомпоновкиДанных.Элементы;
    ГруппировкаПериод.ТипДополнения = ТипДополненияПериодаКомпоновкиДанных.БезДополнения;
    ГруппировкаПериод.Использование = Истина;

    // Устанавливаем параметры периода
    ПараметрПериод = Настройки.ПараметрыДанных.Элементы.Найти(Новый ПараметрКомпоновкиДанных("Период"));
    Если ПараметрПериод = Неопределено Тогда
        ПараметрПериод = Настройки.ПараметрыДанных.Элементы.Добавить(Тип("ЗначениеПараметраНастроекКомпоновкиДанных"));
        ПараметрПериод.Параметр = Новый ПараметрКомпоновкиДанных("Период");
    КонецЕсли;
    ПараметрПериод.Значение = Новый СтандартныйПериод(ДатаНачала, ДатаОкончания);
    ПараметрПериод.Использование = Истина;

    // Настройка параметров вывода
    Настройки.ПараметрыВывода.ВыводитьПараметрыДанных = Ложь;
    Настройки.ПараметрыВывода.ВыводитьОтбор = Ложь;

    // Очищаем существующие отборы и добавляем новый
    Настройки.Отбор.Элементы.Очистить();
    ЭлементОтбора = Настройки.Отбор.Элементы.Добавить(Тип("ЭлементОтбораКомпоновкиДанных"));
    ЭлементОтбора.ЛевоеЗначение = Новый ПолеКомпоновкиДанных("КоличествоОборот");
    ЭлементОтбора.ВидСравнения = ВидСравненияКомпоновкиДанных.БольшеИлиРавно;
    ЭлементОтбора.ПравоеЗначение = КоличествоНорма;
    ЭлементОтбора.Использование = Истина;

    // Применяем измененные настройки
    КомпоновщикНастроек.ЗагрузитьНастройки(Настройки);

    // Формируем макет компоновки
    КомпоновщикМакета = Новый КомпоновщикМакетаКомпоновкиДанных;
    МакетКомпоновки = КомпоновщикМакета.Выполнить(СхемаКомпоновкиДанных, КомпоновщикНастроек.ПолучитьНастройки(), , , Тип("ГенераторМакетаКомпоновкиДанныхДляКоллекцииЗначений"));

    // Выполняем компоновку данных
    ПроцессорКомпоновки = Новый ПроцессорКомпоновкиДанных;
    ПроцессорКомпоновки.Инициализировать(МакетКомпоновки);

    // Выводим результат в табличный документ
    ТабличныйДокумент = Новый ТабличныйДокумент;
    ПроцессорВывода = Новый ПроцессорВыводаРезультатаКомпоновкиДанныхВТабличныйДокумент;
    ПроцессорВывода.УстановитьДокумент(ТабличныйДокумент);
    ПроцессорВывода.Вывести(ПроцессорКомпоновки);

    Возврат ТабличныйДокумент;

КонецФункции

task:
Написать функцию СформироватьАнализТоваровВПутиНаличие(Дата),
которая формирует анализ наличия товаров с учетом заказов клиентов в работе в виде таблицы значений.
Анализ должен выполняться на основании данных:
регистра накопления «ТоварныеЗапасы» (остатки товаров на складе);
документа «Заказ» (табличная часть «Товары»), находящегося в состоянии ВРаботе.
Если параметр Дата не задан, в качестве даты анализа используется текущая дата (КонецДня(ТекущаяДата())).
Формирование анализа выполняется в два этапа:
На первом этапе формируется временная таблица, содержащая суммарное количество товаров по заказам клиентов, находящимся в работе.
Данные выбираются из табличной части Документ.Заказ.Товары с отбором по условию:
состояние заказа равно значению перечисления СостоянияЗаказов.ВРаботе.
Данные группируются по полю Товар, рассчитывается суммарное количество заказанного товара (Количество).
На втором этапе выполняется объединение остатков товаров на складе с временной таблицей заказов:
остатки берутся из регистра накопления РегистрНакопления.ТоварныеЗапасы.Остатки на указанную дату;
соединение выполняется по полю Товар;
рассчитываются итоговые показатели:
ОстатокНаСкладе — суммарный остаток товара на складе;
КоличествоВПути — суммарное количество товара в заказах (резерв под заказы клиентов);
НаличиеДляЗаказа — доступное количество товара с учетом заказов, вычисляемое как:
ОстатокНаСкладе − КоличествоВПути.
Результат должен представлять таблицу значений (ТаблицаЗначений), где каждая строка соответствует одному товару, участвующему в заказах клиентов.
Таблица должна содержать следующие поля:
Товар — ссылка на элемент справочника Товары;
ОстатокНаСкладе — текущий остаток товара на складе на дату анализа;
КоличествоВПути — суммарное количество товара в активных заказах клиентов (в работе);
НаличиеДляЗаказа — доступное количество товара после учета заказов;
НедостачаТовара — булево значение, принимающее Истина, если доступное наличие меньше нуля (дефицит товара), и Ложь в противном случае.
В процессе формирования результата:
для каждой строки выборки создается новая строка таблицы значений;
заполняются поля Товар, ОстатокНаСкладе, КоличествоВПути и НаличиеДляЗаказа;
признак НедостачаТовара устанавливается в Истина, если НаличиеДляЗаказа < 0, что позволяет выявить товары с недостатком запасов под текущие заказы клиентов.
После формирования всех строк функция возвращает заполненную таблицу значений, предназначенную для анализа обеспеченности заказов и выявления дефицита товаров на складе

output:
Функция СформироватьОтчетПродажиПоПокупателям(ДатаНачала, ДатаОкончания)

    // Получаем схему компоновки данных из отчета "ДинамикаПродаж"
    Схема = Отчеты.ДинамикаПродаж.ПолучитьМакет("ОсновнаяСхемаКомпоновкиДанных");

    // Создаем компоновщик настроек и инициализируем его
    КомпоновщикНастроек = Новый КомпоновщикНастроекКомпоновкиДанных;
    ИсточникДоступныхНастроек = Новый ИсточникДоступныхНастроекКомпоновкиДанных(Схема);
    КомпоновщикНастроек.Инициализировать(ИсточникДоступныхНастроек);

    // Загружаем вариант настроек "ПродажиТоваровПоПокупателям"
    НайденныйВариант = Неопределено;
    Для Каждого Вариант Из КомпоновщикНастроек.ВариантыНастроек Цикл
        Если Вариант.Имя = "ПродажиТоваровПоПокупателям" Тогда
            НайденныйВариант = Вариант;
            Прервать;
        КонецЕсли;
    КонецЦикла;

    Если НайденныйВариант = Неопределено Тогда
        ВызватьИсключение "Вариант отчета ""ПродажиТоваровПоПокупателям"" не найден.";
    КонецЕсли;

    КомпоновщикНастроек.ЗагрузитьВариантНастроек(НайденныйВариант);
    Настройки = КомпоновщикНастроек.Настройки;

    // Подменяем стандартную группировку (Товар, Покупатель) на новую (Покупатель, Товар)
    Настройки.Структура.Группировки.Очистить();

    // Группировка верхнего уровня "Покупатель"
    ГруппировкаПокупатель = Настройки.Структура.Группировки.Добавить();
    ГруппировкаПокупатель.Имя = "Покупатель";
    ГруппировкаПокупатель.ТипГруппировки = ТипГруппировкиКомпоновкиДанных.Элементы;
    ГруппировкаПокупатель.ДополнениеПериода = ДополнениеПериодаКомпоновкиДанных.БезДополнения;

    НовоеПолеПокупатель = ГруппировкаПокупатель.ПоляГруппировки.Добавить();
    НовоеПолеПокупатель.Имя = "Покупатель";

    // Вложенная группировка "Товар"
    ГруппировкаТовар = ГруппировкаПокупатель.Структура.Группировки.Добавить();
    ГруппировкаТовар.Имя = "Товар";
    ГруппировкаТовар.ТипГруппировки = ТипГруппировкиКомпоновкиДанных.Элементы;
    ГруппировкаТовар.ДополнениеПериода = ДополнениеПериодаКомпоновкиДанных.БезДополнения;

    НовоеПолеТовар = ГруппировкаТовар.ПоляГруппировки.Добавить();
    НовоеПолеТовар.Имя = "Товар";

    // Установка параметров отчета: период
    ПараметрПериод = Настройки.ПараметрыДанных.Найти("Период");
    Если ПараметрПериод <> Неопределено Тогда
        ПараметрПериод.Значение = Новый СтандартныйПериод(ДатаНачала, ДатаОкончания);
        ПараметрПериод.Использование = Истина;
    КонецЕсли;

    // Параметры вывода: не выводить параметры данных и отбор
    Настройки.ВыводитьПараметрыДанных = Ложь;
    Настройки.ВыводитьОтбор = Ложь;

    // Компоновка отчета
    КомпоновщикМакета = Новый КомпоновщикМакетаКомпоновкиДанных;
    МакетКомпоновки = КомпоновщикМакета.Выполнить(
        Схема,
        КомпоновщикНастроек.ПолучитьНастройки(),
        ,
        , // Для управляемых форм можно указать Тип("ГенераторМакетаКомпоновкиДанныхДляКоллекцииЗначений")
        ,
        Тип("ГенераторМакетаКомпоновкиДанных")
    );

    ПроцессорКомпоновки = Новый ПроцессорКомпоновкиДанных;
    ПроцессорКомпоновки.Инициализировать(МакетКомпоновки);

    ПроцессорВывода = Новый ПроцессорВыводаРезультатаКомпоновкиДанныхВТабличныйДокумент;
    ТабДок = Новый ТабличныйДокумент;
    ПроцессорВывода.УстановитьДокумент(ТабДок);
    ПроцессорВывода.Вывести(ПроцессорКомпоновки);

    Возврат ТабДок;

КонецФункции

Функция СформироватьОтчетПоОплатамПоставшика(ПоставщикФильтр, ВидСравненияКД) Экспорт

    // Получаем объект отчета
    ОтчетОбъект = Отчеты.ДокументыОплата.Создать();

    // Получаем схему компоновки данных
    СхемаКомпоновки = ОтчетОбъект.СхемаКомпоновкиДанных;

    // Ищем вариант отчета "Основной"
    ВариантОсновной = Неопределено;
    Для Каждого Вариант Из СхемаКомпоновки.ВариантыНастроек Цикл
        Если Вариант.Имя = "Основной" Тогда
            ВариантОсновной = Вариант;
            Прервать;
        КонецЕсли;
    КонецЦикла;

    // Если вариант не найден, берем настройки по умолчанию
    Если ВариантОсновной = Неопределено Тогда
        НастройкиСКД = СхемаКомпоновки.НастройкиПоУмолчанию;
    Иначе
        НастройкиСКД = ВариантОсновной.Настройки;
    КонецЕсли;

    // Компоновщик настроек
    КомпоновщикНастроек = Новый КомпоновщикНастроекКомпоновкиДанных;
    ИсточникДоступныхНастроек = Новый ИсточникДоступныхНастроекКомпоновкиДанных(СхемаКомпоновки);
    КомпоновщикНастроек.Инициализировать(ИсточникДоступныхНастроек);
    КомпоновщикНастроек.ЗагрузитьНастройки(НастройкиСКД);

    // Получаем текущие настройки
    Настройки = КомпоновщикНастроек.ПолучитьНастройки();

    // Устанавливаем параметры вывода
    Настройки.ПараметрыВывода.ВыводитьПараметрыДанных = ТипВыводаТекстаКомпоновкиДанных.НеВыводить;
    Настройки.ПараметрыВывода.ВыводитьОтбор = ТипВыводаТекстаКомпоновкиДанных.НеВыводить;

    // Добавляем отбор по полю "Поставщик"
    ЭлементОтбора = Настройки.Отбор.Элементы.Добавить(Тип("ЭлементОтбораКомпоновкиДанных"));
    ЭлементОтбора.ЛевоеЗначение = Новый ПолеКомпоновкиДанных("Поставщик");
    ЭлементОтбора.ВидСравнения = ВидСравненияКД;

    // Устанавливаем правое значение только для видов сравнения, которые его используют
    Если Не (ВидСравненияКД = ВидСравненияКомпоновкиДанных.Заполнено
          Или ВидСравненияКД = ВидСравненияКомпоновкиДанных.НеЗаполнено) Тогда
        ЭлементОтбора.ПравоеЗначение = ПоставщикФильтр;
    КонецЕсли;

    // Компоновка макета
    КомпоновщикМакета = Новый КомпоновщикМакетаКомпоновкиДанных;
    МакетКомпоновки = КомпоновщикМакета.Выполнить(СхемаКомпоновки, Настройки);

    // Процессор компоновки
    ПроцессорКомпоновки = Новый ПроцессорКомпоновкиДанных;
    ПроцессорКомпоновки.Инициализировать(МакетКомпоновки);

    // Вывод в табличный документ
    ТабличныйДокумент = Новый ТабличныйДокумент;
    ПроцессорВывода = Новый ПроцессорВыводаРезультатаКомпоновкиДанныхВТабличныйДокумент;
    ПроцессорВывода.УстановитьДокумент(ТабличныйДокумент);
    ПроцессорВывода.Вывести(ПроцессорКомпоновки);

    Возврат ТабличныйДокумент;

КонецФункции

task:
Написать функцию СформироватьАнализНеликвидныхТоваров(ДатаНач, ДатаКон),
которая формирует аналитический отчет по неликвидным товарам на складе за указанный период.
Отчет предназначен для выявления товаров, имеющих остатки на складе, но не имеющих продаж в выбранном периоде, на основании данных регистров накопления «Продажи» и «ТоварныеЗапасы».
Если параметры периода не заданы, функция должна автоматически:
устанавливать ДатаНач = текущая дата минус 30 дней (с начала дня);
устанавливать ДатаКон = текущая дата (конец дня).
Перед выполнением расчета должна выполняться проверка корректности периода:
если ДатаКон меньше ДатаНач — вызывается исключение.
Формирование отчета выполняется следующим образом:
Выполняется запрос к регистру накопления РегистрНакопления.Продажи:
данные отбираются по периоду между ДатаНач и ДатаКон (по дате регистратора);
выполняется группировка по полю Товар;
рассчитывается агрегированный показатель:
КоличествоПродаж — суммарное количество продаж товара за период;
результат помещается во временную таблицу ВТ_Продажи.
Далее выполняется основной запрос к регистру накопления
РегистрНакопления.ТоварныеЗапасы.Остатки на дату ДатаКон:
выбираются товары с положительными остатками на складе;
выполняется левое соединение с временной таблицей продаж;
дополнительно выполняется соединение со справочником Товары для получения наименования;
рассчитываются итоговые показатели:
ОстатокНаСкладе — суммарный остаток товара;
КоличествоПродаж — количество продаж за период (с использованием ЕСТЬNULL = 0 при отсутствии продаж).
На основании полученных данных формируется итоговая таблица значений (ТаблицаЗначений) со следующей структурой:
Товар (СправочникСсылка.Товары);
Наименование (Строка);
ОстатокНаСкладе (Число);
КоличествоПродаж (Число);
Неликвид (Булево).
Заполнение итоговой таблицы выполняется построчно:
в таблицу включаются только товары, у которых:
ОстатокНаСкладе > 0;
КоличествоПродаж = 0;
такие товары помечаются признаком Неликвид = Истина.
После формирования данных выполняется сортировка результата:
по полю ОстатокНаСкладе по убыванию,
что позволяет вывести наиболее критичные неликвидные остатки в верхней части отчета.
Функция должна возвращать объект типа ТаблицаЗначений, содержащий список неликвидных товаров с остатками на складе.
Дополнительно реализуется функция ЗадачаРешена(ТабДок), которая проверяет корректность результата:
тип возвращаемого значения — ТаблицаЗначений;
наличие обязательных колонок (Товар, ОстатокНаСкладе, КоличествоПродаж, Неликвид);
отсутствие отрицательных остатков и продаж;
заполненность ссылки на товар в каждой строке.
В случае отсутствия неликвидных товаров таблица может быть пустой, что считается корректным результатом выполнения задачи анализа.

output:
Функция СформироватьАнализНеликвидныхТоваров(ДатаНач, ДатаКон) Экспорт
    // Обработка параметров по умолчанию
    Если Не ЗначениеЗаполнено(ДатаНач) Тогда
        ДатаНач = НачалоДня(ТекущаяДата() - 30 * 86400); // 30 дней назад, начало дня
    КонецЕсли;
    Если Не ЗначениеЗаполнено(ДатаКон) Тогда
        ДатаКон = КонецДня(ТекущаяДата()); // текущая дата, конец дня
    КонецЕсли;

    // Проверка корректности периода
    Если ДатаКон < ДатаНач Тогда
        ВызватьИсключение "Дата окончания периода не может быть меньше даты начала";
    КонецЕсли;

    Запрос = Новый Запрос;
    Запрос.Текст = 
    "ВЫБРАТЬ
    |    Продажи.Товар КАК Товар,
    |    СУММА(Продажи.Количество) КАК КоличествоПродаж
    |ПОМЕСТИТЬ ВТ_Продажи
    |ИЗ
    |    РегистрНакопления.Продажи КАК Продажи
    |ГДЕ
    |    Продажи.Период МЕЖДУ &ДатаНач И &ДатаКон
    |СГРУППИРОВАТЬ ПО
    |    Продажи.Товар
    |;
    |
    |ВЫБРАТЬ
    |    ТоварныеЗапасыОстатки.Товар КАК Товар,
    |    Товары.Наименование КАК Наименование,
    |    СУММА(ТоварныеЗапасыОстатки.КоличествоОстаток) КАК ОстатокНаСкладе,
    |    МАКСИМУМ(ЕСТЬNULL(ВТ_Продажи.КоличествоПродаж, 0)) КАК КоличествоПродаж
    |ИЗ
    |    РегистрНакопления.ТоварныеЗапасы.Остатки(&ДатаКон) КАК ТоварныеЗапасыОстатки
    |        ЛЕВОЕ СОЕДИНЕНИЕ ВТ_Продажи КАК ВТ_Продажи
    |        ПО ТоварныеЗапасыОстатки.Товар = ВТ_Продажи.Товар
    |        ВНУТРЕННЕЕ СОЕДИНЕНИЕ Справочник.Товары КАК Товары
    |        ПО ТоварныеЗапасыОстатки.Товар = Товары.Ссылка
    |ГДЕ
    |    ТоварныеЗапасыОстатки.КоличествоОстаток > 0
    |    И ЕСТЬNULL(ВТ_Продажи.КоличествоПродаж, 0) = 0
    |СГРУППИРОВАТЬ ПО
    |    ТоварныеЗапасыОстатки.Товар,
    |    Товары.Наименование";

    Запрос.УстановитьПараметр("ДатаНач", ДатаНач);
    Запрос.УстановитьПараметр("ДатаКон", ДатаКон);

    РезультатЗапроса = Запрос.Выполнить();

    // Создание итоговой таблицы значений
    ТаблицаРезультат = Новый ТаблицаЗначений;
    ТаблицаРезультат.Колонки.Добавить("Товар", Новый ОписаниеТипов("СправочникСсылка.Товары"));
    ТаблицаРезультат.Колонки.Добавить("Наименование", Новый ОписаниеТипов("Строка"));
    ТаблицаРезультат.Колонки.Добавить("ОстатокНаСкладе", Новый ОписаниеТипов("Число"));
    ТаблицаРезультат.Колонки.Добавить("КоличествоПродаж", Новый ОписаниеТипов("Число"));
    ТаблицаРезультат.Колонки.Добавить("Неликвид", Новый ОписаниеТипов("Булево"));

    Выборка = РезультатЗапроса.Выбрать();
    Пока Выборка.Следующий() Цикл
        НоваяСтрока = ТаблицаРезультат.Добавить();
        НоваяСтрока.Товар = Выборка.Товар;
        НоваяСтрока.Наименование = Выборка.Наименование;
        НоваяСтрока.ОстатокНаСкладе = Выборка.ОстатокНаСкладе;
        НоваяСтрока.КоличествоПродаж = Выборка.КоличествоПродаж;
        НоваяСтрока.Неликвид = Истина;
    КонецЦикла;

    // Сортировка по остатку на складе по убыванию
    ТаблицаРезультат.Сортировать("ОстатокНаСкладе Убыв");

    Возврат ТаблицаРезультат;
КонецФункции

Функция ЗадачаРешена(ТабДок) Экспорт
    Если ТипЗнч(ТабДок) <> Тип("ТаблицаЗначений") Тогда
        Возврат Ложь;
    КонецЕсли;

    // Проверка наличия обязательных колонок
    ОбязательныеКолонки = Новый Массив;
    ОбязательныеКолонки.Добавить("Товар");
    ОбязательныеКолонки.Добавить("Наименование");
    ОбязательныеКолонки.Добавить("ОстатокНаСкладе");
    ОбязательныеКолонки.Добавить("КоличествоПродаж");
    ОбязательныеКолонки.Добавить("Неликвид");

    Для Каждого ИмяКолонки Из ОбязательныеКолонки Цикл
        Если ТабДок.Колонки.Найти(ИмяКолонки) = Неопределено Тогда
            Возврат Ложь;
        КонецЕсли;
    КонецЦикла;

    // Построчная проверка данных
    Для Каждого Строка Из ТабДок Цикл
        // Ссылка на товар должна быть заполнена
        Если Не ЗначениеЗаполнено(Строка.Товар) Тогда
            Возврат Ложь;
        КонецЕсли;
        // Остатки и продажи не должны быть отрицательными
        Если Строка.ОстатокНаСкладе < 0 Тогда
            Возврат Ложь;
        КонецЕсли;
        Если Строка.КоличествоПродаж < 0 Тогда
            Возврат Ложь;
        КонецЕсли;
    КонецЦикла;

    Возврат Истина;
КонецФункции

&НаСервере
Функция СформироватьОтчетПоОплатамСГруппировкойПоПоставщикам() Экспорт
    // Получаем схему компоновки данных отчета "ДокументыОплата"
    СхемаКомпоновки = Отчеты.ДокументыОплата.ПолучитьМакет("Основная схема компоновки данных");

    // Загружаем стандартные настройки варианта "Основной"
    Настройки = Отчеты.ДокументыОплата.ПолучитьНастройкиВарианта("Основной");

    // Очищаем структуру отчета (стандартную подменяем)
    Настройки.Структура.Очистить();

    // Создаем группировку верхнего уровня по полю "Поставщик"
    ГруппировкаПоставщик = Настройки.Структура.Добавить(Тип("ГруппировкаКомпоновкиДанных"));
    ГруппировкаПоставщик.Использование = Истина;

    // Настраиваем поле группировки
    ПолеГруппировки = ГруппировкаПоставщик.ПоляГруппировки.Элементы.Добавить(Тип("ПолеГруппировкиКомпоновкиДанных"));
    ПолеГруппировки.Поле = Новый ПолеКомпоновкиДанных("Поставщик");
    ПолеГруппировки.ТипГруппировки = ТипГруппировкиКомпоновкиДанных.Элементы;
    ПолеГруппировки.ТипДополнения = ТипДополненияГруппировкиКомпоновкиДанных.БезДополнения;

    // Добавляем детальные записи внутрь группировки
    ДетальныеЗаписи = ГруппировкаПоставщик.Выбор.Элементы.Добавить(Тип("ДетальныеЗаписиКомпоновкиДанных"));
    ДетальныеЗаписи.Использование = Истина;

    // Устанавливаем параметры вывода согласно заданию
    Настройки.ПараметрыВывода.ВыводитьПараметрыДанных = Ложь;
    Настройки.ПараметрыВывода.ВыводитьОтбор = Ложь;

    // Выполняем компоновку данных
    КомпоновщикМакета = Новый КомпоновщикМакетаКомпоновкиДанных;
    МакетКомпоновки = КомпоновщикМакета.Выполнить(СхемаКомпоновки, Настройки);

    ПроцессорКомпоновки = Новый ПроцессорКомпоновкиДанных;
    ПроцессорКомпоновки.Инициализировать(МакетКомпоновки);

    // Формируем табличный документ
    ТабличныйДокумент = Новый ТабличныйДокумент;
    ПроцессорВывода = Новый ПроцессорВыводаРезультатаКомпоновкиДанныхВТабличныйДокумент;
    ПроцессорВывода.УстановитьДокумент(ТабличныйДокумент);
    ПроцессорВывода.Вывести(ПроцессорКомпоновки);

    Возврат ТабличныйДокумент;
КонецФункции

&НаСервере
Функция ПолучитьПродажиСклада(ДатаНачала = Неопределено, ДатаОкончания = Неопределено) Экспорт

    // Установка значений по умолчанию
    Если ДатаНачала = Неопределено Тогда
        ДатаНачала = НачалоМесяца(ТекущаяДата());
    КонецЕсли;
    Если ДатаОкончания = Неопределено Тогда
        ДатаОкончания = КонецДня(ТекущаяДата());
    КонецЕсли;

    // Проверка корректности периода
    Если ДатаОкончания < ДатаНачала Тогда
        ВызватьИсключение "Дата окончания не может быть меньше даты начала";
    КонецЕсли;

    // Формирование запроса к регистру накопления "Продажи"
    Запрос = Новый Запрос;
    Запрос.Текст = 
    "ВЫБРАТЬ
    |    ПродажиОбороты.Регистратор.Склад КАК Склад,
    |    ПродажиОбороты.Товар КАК Товар,
    |    СУММА(ПродажиОбороты.Количество) КАК Количество,
    |    СУММА(ПродажиОбороты.Сумма) КАК Сумма
    |ИЗ
    |    РегистрНакопления.Продажи.Обороты(&ДатаНачала, &ДатаОкончания, ) КАК ПродажиОбороты
    |СГРУППИРОВАТЬ ПО
    |    ПродажиОбороты.Регистратор.Склад,
    |    ПродажиОбороты.Товар";

    Запрос.УстановитьПараметр("ДатаНачала", ДатаНачала);
    Запрос.УстановитьПараметр("ДатаОкончания", ДатаОкончания);

    РезультатЗапроса = Запрос.Выполнить();

    // Подготовка таблицы значений для возврата
    ТаблицаРезультат = Новый ТаблицаЗначений;
    ТаблицаРезультат.Колонки.Добавить("РегистраторСклад", Новый ОписаниеТипов("СправочникСсылка.Склады"));
    ТаблицаРезультат.Колонки.Добавить("Товар", Новый ОписаниеТипов("СправочникСсылка.Товары"));
    ТаблицаРезультат.Колонки.Добавить("Количество", Новый ОписаниеТипов("Число", Новый КвалификаторыЧисла(10, 2)));
    ТаблицаРезультат.Колонки.Добавить("Сумма", Новый ОписаниеТипов("Число", Новый КвалификаторыЧисла(10, 2)));
    ТаблицаРезультат.Колонки.Добавить("СредняяЦена", Новый ОписаниеТипов("Число", Новый КвалификаторыЧисла(10, 2)));

    // Заполнение таблицы значений
    Выборка = РезультатЗапроса.Выбрать();
    Пока Выборка.Следующий() Цикл
        НоваяСтрока = ТаблицаРезультат.Добавить();
        НоваяСтрока.РегистраторСклад = Выборка.Склад;
        НоваяСтрока.Товар = Выборка.Товар;
        НоваяСтрока.Количество = Выборка.Количество;
        НоваяСтрока.Сумма = Выборка.Сумма;
        Если Выборка.Количество <> 0 Тогда
            НоваяСтрока.СредняяЦена = Выборка.Сумма / Выборка.Количество;
        Иначе
            НоваяСтрока.СредняяЦена = 0;
        КонецЕсли;
    КонецЦикла;

    Возврат ТаблицаРезультат;

КонецФункции

Функция СформироватьОтчетПоНеПроведеннымОплатамПоставщиков() Экспорт
    // Поиск варианта отчета "Основной" для отчета "ДокументыОплата"
    Запрос = Новый Запрос;
    Запрос.Текст =
    "ВЫБРАТЬ
    |   ХранилищеВариантовОтчетов.Ссылка КАК Ссылка
    |ИЗ
    |   Справочник.ХранилищеВариантовОтчетов КАК ХранилищеВариантовОтчетов
    |ГДЕ
    |   ХранилищеВариантовОтчетов.КлючОбъекта = &КлючОбъекта
    |   И ХранилищеВариантовОтчетов.ВариантОтчета = &ВариантОтчета";

    Запрос.УстановитьПараметр("КлючОбъекта", "Отчет.ДокументыОплата");
    Запрос.УстановитьПараметр("ВариантОтчета", "Основной");

    Результат = Запрос.Выполнить();
    Если Результат.Пустой() Тогда
        ВызватьИсключение "Не найден вариант отчета ""Основной"" для отчета ""ДокументыОплата"".";
    КонецЕсли;

    Выборка = Результат.Выбрать();
    Выборка.Следующий();
    ОбъектВарианта = Выборка.Ссылка.ПолучитьОбъект();

    // Получение настроек компоновки данных из хранилища
    НастройкиКД = ОбъектВарианта.Настройки.Получить();

    // Создание отчета и инициализация компоновщика
    ОтчетОбъект = Отчеты.ДокументыОплата.Создать();
    Компоновщик = ОтчетОбъект.КомпоновщикНастроек;
    Компоновщик.ЗагрузитьНастройки(НастройкиКД);

    // Настройка параметров вывода
    Компоновщик.Настройки.ПараметрыВывода.ВыводитьПараметрыДанных = РежимВыводаПараметровДанных.НеВыводить;
    Компоновщик.Настройки.ПараметрыВывода.ВыводитьОтбор = РежимВыводаОтбора.НеВыводить;

    // Добавление отбора по непроведенным документам
    ЭлементОтбора = Компоновщик.Настройки.Отбор.Элементы.Добавить(Тип("ЭлементОтбораКомпоновкиДанных"));
    ЭлементОтбора.ЛевоеЗначение = Новый ПолеКомпоновкиДанных("Проведен");
    ЭлементОтбора.ВидСравнения = ВидСравненияКомпоновкиДанных.Равно;
    ЭлементОтбора.ПравоеЗначение = Ложь;
    ЭлементОтбора.Использование = Истина;

    // Компоновка отчета
    КомпоновщикМакета = Новый КомпоновщикМакетаКомпоновкиДанных;
    Макет = КомпоновщикМакета.Выполнить(Компоновщик.ПолучитьСхему(), Компоновщик.ПолучитьНастройки(), , );

    ПроцессорКомпоновки = Новый ПроцессорКомпоновкиДанных;
    ПроцессорКомпоновки.Инициализировать(Макет);

    ТабличныйДокумент = Новый ТабличныйДокумент;
    ПроцессорВывода = Новый ПроцессорВыводаРезультатаКомпоновкиДанныхВТабличныйДокумент;
    ПроцессорВывода.УстановитьДокумент(ТабличныйДокумент);
    ПроцессорВывода.Вывести(ПроцессорКомпоновки);

    Возврат ТабличныйДокумент;
КонецФункции

Функция СформироватьОтчетТоварыБезЦены(ВидЦен)
    // Получаем схему компоновки данных для отчета "ПрайсЛист"
    СхемаКомпоновки = Отчеты.ПрайсЛист.ПолучитьМакет("ОсновнаяСхемаКомпоновкиДанных");

    // Создаем компоновщик настроек и загружаем настройки по умолчанию (вариант "Основной")
    КомпоновщикНастроек = Новый КомпоновщикНастроекКомпоновкиДанных;
    КомпоновщикНастроек.ЗагрузитьНастройки(СхемаКомпоновки.НастройкиПоУмолчанию);

    // Устанавливаем параметр "ВидЦен"
    ПараметрВидЦен = КомпоновщикНастроек.Настройки.ПараметрыДанных.Найти("ВидЦен");
    Если ПараметрВидЦен = Неопределено Тогда
        ПараметрВидЦен = КомпоновщикНастроек.Настройки.ПараметрыДанных.Добавить();
        ПараметрВидЦен.Имя = "ВидЦен";
    КонецЕсли;
    ПараметрВидЦен.Значение = ВидЦен;
    ПараметрВидЦен.Использование = Истина;

    // Настраиваем параметры вывода
    КомпоновщикНастроек.Настройки.ПараметрыВывода.ВыводитьПараметрыДанных = Ложь;
    КомпоновщикНастроек.Настройки.ПараметрыВывода.ВыводитьОтбор = Ложь;

    // Добавляем условное оформление для строк с незаполненной ценой
    ЭлементОформления = КомпоновщикНастроек.Настройки.УсловноеОформление.Добавить();

    // Оформление: цвет фона
    ЭлементОформления.Оформление.УстановитьЗначениеПараметра("ЦветФона", Цвет(255, 236, 239));

    // Отбор: Цена не заполнена
    Отбор = ЭлементОформления.Отбор;
    ГруппаОтбора = Отбор.Элементы.Добавить(Тип("ГруппаЭлементовОтбораКомпоновкиДанных"));
    ГруппаОтбора.ТипГруппы = ТипГруппыЭлементовОтбораКомпоновкиДанных.ГруппаИ;

    ЭлементОтбора = ГруппаОтбора.Элементы.Добавить(Тип("ЭлементОтбораКомпоновкиДанных"));
    ЭлементОтбора.ЛевоеЗначение = Новый ПолеКомпоновкиДанных("Цена");
    ЭлементОтбора.ВидСравнения = ВидСравненияКомпоновкиДанных.НеЗаполнено;
    ЭлементОтбора.Использование = Истина;

    // Компонуем макет
    КомпоновщикМакета = Новый КомпоновщикМакетаКомпоновкиДанных;
    МакетКомпоновки = КомпоновщикМакета.Выполнить(СхемаКомпоновки, КомпоновщикНастроек.Настройки, , , Тип("ГенераторМакетаКомпоновкиДанных"));

    // Выполняем компоновку и выгружаем результат в табличный документ
    ПроцессорКомпоновки = Новый ПроцессорКомпоновкиДанных;
    ПроцессорКомпоновки.Инициализировать(МакетКомпоновки);

    ТабличныйДокумент = Новый ТабличныйДокумент;
    ПроцессорВывода = Новый ПроцессорВыводаРезультатаКомпоновкиДанныхВТабличныйДокумент;
    ПроцессорВывода.УстановитьДокумент(ТабличныйДокумент);
    ПроцессорВывода.Вывести(ПроцессорКомпоновки);

    Возврат ТабличныйДокумент;
КонецФункции

Функция СформироватьАнализКурсовойРазницыПоОплатам(ДатаНач = '00010101', ДатаКон = '00010101') Экспорт
    // Установка периода по умолчанию, если не задан
    Если ДатаНач = '00010101' Тогда
        ДатаНач = НачалоДня(ТекущаяДата() - 30 * 86400);
    КонецЕсли;
    Если ДатаКон = '00010101' Тогда
        ДатаКон = КонецДня(ТекущаяДата());
    КонецЕсли;

    // Проверка корректности периода
    Если ДатаКон < ДатаНач Тогда
        ВызватьИсключение "Дата окончания периода не может быть меньше даты начала";
    КонецЕсли;

    // Запрос к проведенным документам оплаты за период
    ЗапросПлатежи = Новый Запрос;
    ЗапросПлатежи.Текст = 
    "ВЫБРАТЬ
    |    Оплата.Ссылка КАК Документ,
    |    Оплата.Дата КАК Дата,
    |    Оплата.Поставщик КАК Поставщик,
    |    Оплата.Валюта КАК Валюта,
    |    Оплата.Сумма КАК СуммаВВалюте
    |ИЗ
    |    Документ.Оплата КАК Оплата
    |ГДЕ
    |    Оплата.Проведен
    |    И Оплата.Дата МЕЖДУ &ДатаНач И &ДатаКон";

    ЗапросПлатежи.УстановитьПараметр("ДатаНач", ДатаНач);
    ЗапросПлатежи.УстановитьПараметр("ДатаКон", ДатаКон);

    РезультатПлатежей = ЗапросПлатежи.Выполнить();

    // Создание таблицы значений для результата
    ТЗ = Новый ТаблицаЗначений;
    ТЗ.Колонки.Добавить("Документ", Новый ОписаниеТипов("ДокументСсылка.Оплата"));
    ТЗ.Колонки.Добавить("Дата", Новый ОписаниеТипов("Дата"));
    ТЗ.Колонки.Добавить("Поставщик", Новый ОписаниеТипов("СправочникСсылка.Контрагенты"));
    ТЗ.Колонки.Добавить("Валюта", Новый ОписаниеТипов("СправочникСсылка.Валюты"));
    ТЗ.Колонки.Добавить("СуммаВВалюте", Новый ОписаниеТипов("Число", Новый КвалификаторыЧисла(10, 2)));
    ТЗ.Колонки.Добавить("Курс", Новый ОписаниеТипов("Число", Новый КвалификаторыЧисла(10, 2)));
    ТЗ.Колонки.Добавить("СуммаВБазовойВалюте", Новый ОписаниеТипов("Число", Новый КвалификаторыЧисла(10, 2)));
    ТЗ.Колонки.Добавить("КурсоваяРазница", Новый ОписаниеТипов("Число", Новый КвалификаторыЧисла(10, 2)));
    // Временная колонка для сортировки по абсолютному значению курсовой разницы
    ТЗ.Колонки.Добавить("АбсКурсоваяРазница", Новый ОписаниеТипов("Число", Новый КвалификаторыЧисла(10, 2)));

    // Запрос для получения курса валюты на дату документа
    ЗапросКурс = Новый Запрос;
    ЗапросКурс.Текст = 
    "ВЫБРАТЬ ПЕРВЫЕ 1
    |    КурсыВалют.Курс КАК Курс
    |ИЗ
    |    РегистрСведений.КурсыВалют.СрезПоследних(&ДатаДокумента, Валюта = &Валюта) КАК КурсыВалют";

    // Цикл по документам оплаты
    ВыборкаПлатежей = РезультатПлатежей.Выбрать();
    Пока ВыборкаПлатежей.Следующий() Цикл
        // Получение курса на дату документа
        ЗапросКурс.УстановитьПараметр("ДатаДокумента", ВыборкаПлатежей.Дата);
        ЗапросКурс.УстановитьПараметр("Валюта", ВыборкаПлатежей.Валюта);
        РезультатКурса = ЗапросКурс.Выполнить();
        ВыборкаКурса = РезультатКурса.Выбрать();

        Если ВыборкаКурса.Следующий() Тогда
            Курс = ВыборкаКурса.Курс;
            СуммаВБазовойВалюте = ВыборкаПлатежей.СуммаВВалюте * Курс;
            КурсоваяРазница = СуммаВБазовойВалюте - ВыборкаПлатежей.СуммаВВалюте;

            НоваяСтрока = ТЗ.Добавить();
            НоваяСтрока.Документ = ВыборкаПлатежей.Документ;
            НоваяСтрока.Дата = ВыборкаПлатежей.Дата;
            НоваяСтрока.Поставщик = ВыборкаПлатежей.Поставщик;
            НоваяСтрока.Валюта = ВыборкаПлатежей.Валюта;
            НоваяСтрока.СуммаВВалюте = ВыборкаПлатежей.СуммаВВалюте;
            НоваяСтрока.Курс = Курс;
            НоваяСтрока.СуммаВБазовойВалюте = СуммаВБазовойВалюте;
            НоваяСтрока.КурсоваяРазница = КурсоваяРазница;
            НоваяСтрока.АбсКурсоваяРазница = ?(КурсоваяРазница < 0, -КурсоваяРазница, КурсоваяРазница);
        Иначе
            // Если курс не найден, пропускаем этот документ
            Продолжить;
        КонецЕсли;
    КонецЦикла;

    // Сортировка по убыванию абсолютного значения курсовой разницы
    ТЗ.Сортировать("АбсКурсоваяРазница Убыв");

    // Удаление временной колонки
    ТЗ.Колонки.Удалить("АбсКурсоваяРазница");

    Возврат ТЗ;
КонецФункции

Функция СформироватьСреднийЧекПродаж(Знач ДатаНач = Неопределено, Знач ДатаКон = Неопределено)

    // Установка значений по умолчанию, если они не заданы
    Если ДатаНач = Неопределено Тогда
        ДатаНач = НачалоДня(ТекущаяДата() - 30 * 86400); // 30 дней назад
    КонецЕсли;
    Если ДатаКон = Неопределено Тогда
        ДатаКон = КонецДня(ТекущаяДата());
    КонецЕсли;

    // Проверка корректности периода
    Если ДатаКон < ДатаНач Тогда
        ВызватьИсключение "Дата окончания периода не может быть меньше даты начала.";
    КонецЕсли;

    // Формирование запроса
    Запрос = Новый Запрос;
    Запрос.Текст = 
    "ВЫБРАТЬ
    |   РасходТовара.Ссылка КАК Документ,
    |   СУММА(РасходТовараТовары.Сумма) КАК СуммаЧека
    |ИЗ
    |   Документ.РасходТовара КАК РасходТовара
    |   ВНУТРЕННЕЕ СОЕДИНЕНИЕ Документ.РасходТовара.Товары КАК РасходТовараТовары
    |   ПО РасходТовара.Ссылка = РасходТовараТовары.Ссылка
    |ГДЕ
    |   РасходТовара.Проведен
    |   И РасходТовара.Дата МЕЖДУ &ДатаНач И &ДатаКон
    |СГРУППИРОВАТЬ ПО
    |   РасходТовара.Ссылка";

    Запрос.УстановитьПараметр("ДатаНач", ДатаНач);
    Запрос.УстановитьПараметр("ДатаКон", ДатаКон);

    // Выполнение запроса и агрегация данных
    РезультатЗапроса = Запрос.Выполнить();
    Выборка = РезультатЗапроса.Выбрать();

    КоличествоЧеков = 0;
    ОбщаяСуммаПродаж = 0;

    Пока Выборка.Следующий() Цикл
        КоличествоЧеков = КоличествоЧеков + 1;
        ОбщаяСуммаПродаж = ОбщаяСуммаПродаж + Выборка.СуммаЧека;
    КонецЦикла;

    // Расчет среднего чека
    Если КоличествоЧеков = 0 Тогда
        СреднийЧек = 0;
    Иначе
        СреднийЧек = ОбщаяСуммаПродаж / КоличествоЧеков;
    КонецЕсли;

    // Формирование итоговой таблицы значений
    ТаблицаРезультата = Новый ТаблицаЗначений;
    ТаблицаРезультата.Колонки.Добавить("КоличествоЧеков", Новый ОписаниеТипов("Число"));
    ТаблицаРезультата.Колонки.Добавить("ОбщаяСуммаПродаж", Новый ОписаниеТипов("Число"));
    ТаблицаРезультата.Колонки.Добавить("СреднийЧек", Новый ОписаниеТипов("Число"));

    НоваяСтрока = ТаблицаРезультата.Добавить();
    НоваяСтрока.КоличествоЧеков = КоличествоЧеков;
    НоваяСтрока.ОбщаяСуммаПродаж = ОбщаяСуммаПродаж;
    НоваяСтрока.СреднийЧек = СреднийЧек;

    Возврат ТаблицаРезультата;

КонецФункции

Функция СформироватьПродажиПоДням(ДатаНач = Неопределено, ДатаКон = Неопределено)

    // Если параметры не заданы, используем значения по умолчанию
    Если Не ЗначениеЗаполнено(ДатаНач) Тогда
        ДатаНач = НачалоДня(ТекущаяДата() - 30 * 86400);
    КонецЕсли;

    Если Не ЗначениеЗаполнено(ДатаКон) Тогда
        ДатаКон = КонецДня(ТекущаяДата());
    КонецЕсли;

    // Проверка корректности периода
    Если ДатаКон < ДатаНач Тогда
        ВызватьИсключение "Дата окончания периода не может быть меньше даты начала";
    КонецЕсли;

    // Формирование запроса
    Запрос = Новый Запрос;
    Запрос.Текст = 
    "ВЫБРАТЬ
    |    Товары.Ссылка.Дата КАК Дата,
    |    СУММА(Товары.Количество) КАК КоличествоПродаж,
    |    СУММА(Товары.Сумма) КАК СуммаПродаж
    |ИЗ
    |    Документ.РасходТовара.Товары КАК Товары
    |ГДЕ
    |    Товары.Ссылка.Проведен И
    |    Товары.Ссылка.Дата МЕЖДУ &ДатаНач И &ДатаКон
    |СГРУППИРОВАТЬ ПО
    |    Товары.Ссылка.Дата
    |УПОРЯДОЧИТЬ ПО
    |    Дата";

    Запрос.УстановитьПараметр("ДатаНач", ДатаНач);
    Запрос.УстановитьПараметр("ДатаКон", ДатаКон);

    // Выполнение запроса и выгрузка в таблицу значений
    РезультатЗапроса = Запрос.Выполнить();
    ТЗРезультат = РезультатЗапроса.Выгрузить();

    // Исключение строк с неопределённой датой (на всякий случай)
    Для Сч = ТЗРезультат.Количество() - 1 По 0 Цикл
        Строка = ТЗРезультат[Сч];
        Если Строка.Дата = Дата(1,1,1) Тогда
            ТЗРезультат.Удалить(Сч);
        КонецЕсли;
    КонецЦикла;

    // Возврат итоговой таблицы (данные уже отсортированы по дате)
    Возврат ТЗРезультат;

КонецФункции

Функция СформироватьТоварыСОтрицательнымиОстатками(ДатаОстатков)

    // Проверка и установка значения даты по умолчанию
    Если НЕ ЗначениеЗаполнено(ДатаОстатков) Тогда
        ДатаОстатков = КонецДня(ТекущаяДата());
    КонецЕсли;

    // Создание и настройка запроса
    Запрос = Новый Запрос;
    Запрос.Текст = 
    "ВЫБРАТЬ
    |    ТоварныеЗапасыОстатки.Товар КАК Товар,
    |    СУММА(ТоварныеЗапасыОстатки.КоличествоОстаток) КАК КоличествоОстаток
    |ИЗ
    |    РегистрНакопления.ТоварныеЗапасы.Остатки(&ДатаОстатков) КАК ТоварныеЗапасыОстатки
    |ГДЕ
    |    ТоварныеЗапасыОстатки.Товар <> ЗНАЧЕНИЕ(Справочник.Товары.ПустаяСсылка)
    |
    |СГРУППИРОВАТЬ ПО
    |    ТоварныеЗапасыОстатки.Товар
    |
    |ИМЕЮЩИЕ
    |    СУММА(ТоварныеЗапасыОстатки.КоличествоОстаток) < 0
    |
    |УПОРЯДОЧИТЬ ПО
    |    Товар";

    Запрос.УстановитьПараметр("ДатаОстатков", ДатаОстатков);

    // Выполнение запроса и выгрузка в таблицу значений
    РезультатЗапроса = Запрос.Выполнить();

    ТаблицаРезультата = Новый ТаблицаЗначений;
    ТаблицаРезультата.Колонки.Добавить("Товар", Новый ОписаниеТипов("СправочникСсылка.Товары"));
    ТаблицаРезультата.Колонки.Добавить("КоличествоОстаток", Новый ОписаниеТипов("Число", Новый КвалификаторыЧисла(10, 2)));

    Выборка = РезультатЗапроса.Выбрать();
    Пока Выборка.Следующий() Цикл
        // Исключаем неопределённые товары (дублирующая проверка, если в запросе не обработано)
        Если Выборка.Товар = Справочники.Товары.ПустаяСсылка() Тогда
            Продолжить;
        КонецЕсли;

        НоваяСтрока = ТаблицаРезультата.Добавить();
        НоваяСтрока.Товар = Выборка.Товар;
        НоваяСтрока.КоличествоОстаток = Выборка.КоличествоОстаток;
    КонецЦикла;

    // Таблица уже отсортирована запросом, но можно явно отсортировать для надёжности
    ТаблицаРезультата.Сортировать("Товар Возр");

    Возврат ТаблицаРезультата;
КонецФункции

Функция СформироватьТоварыБезЦены(ДатаЦен = Неопределено) Экспорт
    // Проверка и установка значения даты по умолчанию
    Если ДатаЦен = Неопределено Тогда
        ДатаЦен = КонецДня(ТекущаяДата());
    КонецЕсли;

    // Инициализация таблицы результата
    Результат = Новый ТаблицаЗначений;
    Результат.Колонки.Добавить("Товар");

    // Формирование текста запроса
    Запрос = Новый Запрос;
    Запрос.Текст = 
        "ВЫБРАТЬ
        |    Товары.Ссылка КАК Товар
        |ИЗ
        |    Справочник.Товары КАК Товары
        |    ЛЕВОЕ СОЕДИНЕНИЕ РегистрСведений.ЦеныТоваров.СрезПоследних(&ДатаЦен) КАК Цены
        |    ПО Товары.Ссылка = Цены.Товар
        |ГДЕ
        |    Цены.Цена ЕСТЬ NULL
        |УПОРЯДОЧИТЬ ПО
        |    Товар";

    Запрос.УстановитьПараметр("ДатаЦен", ДатаЦен);

    // Выполнение запроса и загрузка данных в таблицу значений
    Выборка = Запрос.Выполнить().Выбрать();
    Пока Выборка.Следующий() Цикл
        // Исключение потенциально неопределённых товаров (страховочная проверка)
        Если Выборка.Товар <> Неопределено Тогда
            НовСтр = Результат.Добавить();
            НовСтр.Товар = Выборка.Товар;
        КонецЕсли;
    КонецЦикла;

    // Сортировка уже выполнена в запросе, дополнительная не требуется
    Возврат Результат;
КонецФункции

Функция СформироватьСебестоимостьТоваровСредневзвеш()

    Запрос = Новый Запрос;
    Запрос.Текст = 
    "ВЫБРАТЬ
    |    Остатки.Товар КАК Товар,
    |    СУММА(Остатки.Количество) КАК КоличествоОстаток,
    |    МАКСИМУМ(ЕСТЬNULL(Приходы.СебестоимостьЕд, 0)) КАК СебестоимостьЕд
    |ИЗ
    |    РегистрНакопления.ТоварныеЗапасы.Остатки(&Дата, ) КАК Остатки
    |        ЛЕВОЕ СОЕДИНЕНИЕ (ВЫБРАТЬ
    |            ПриходТовараТовары.Товар КАК Товар,
    |            ВЫБОР
    |                КОГДА СУММА(ПриходТовараТовары.Количество) <> 0
    |                    ТОГДА СУММА(ПриходТовараТовары.Сумма) / СУММА(ПриходТовараТовары.Количество)
    |                ИНАЧЕ 0
    |            КОНЕЦ КАК СебестоимостьЕд
    |        ИЗ
    |            Документ.ПриходТовара.Товары КАК ПриходТовараТовары
    |        ГДЕ
    |            ПриходТовараТовары.Ссылка.Проведен
    |        СГРУППИРОВАТЬ ПО
    |            ПриходТовараТовары.Товар) КАК Приходы
    |        ПО Остатки.Товар = Приходы.Товар
    |СГРУППИРОВАТЬ ПО
    |    Остатки.Товар
    |ИМЕЮЩИЕ
    |    СУММА(Остатки.Количество) > 0";

    Запрос.УстановитьПараметр("Дата", ТекущаяДата());

    РезультатЗапроса = Запрос.Выполнить();

    // Формирование таблицы значений
    КвалификаторыЧисла = Новый КвалификаторыЧисла(10, 2);
    ТЗ = Новый ТаблицаЗначений;
    ТЗ.Колонки.Добавить("Товар", Новый ОписаниеТипов("СправочникСсылка.Товары"));
    ТЗ.Колонки.Добавить("КоличествоОстаток", Новый ОписаниеТипов("Число", , , , КвалификаторыЧисла));
    ТЗ.Колонки.Добавить("СебестоимостьЕд", Новый ОписаниеТипов("Число", , , , КвалификаторыЧисла));
    ТЗ.Колонки.Добавить("СебестоимостьОстатка", Новый ОписаниеТипов("Число", , , , КвалификаторыЧисла));

    Выборка = РезультатЗапроса.Выбрать();
    Пока Выборка.Следующий() Цикл
        СтрокаТЗ = ТЗ.Добавить();
        СтрокаТЗ.Товар = Выборка.Товар;
        СтрокаТЗ.КоличествоОстаток = Выборка.КоличествоОстаток;
        СтрокаТЗ.СебестоимостьЕд = Выборка.СебестоимостьЕд;
        СтрокаТЗ.СебестоимостьОстатка = СтрокаТЗ.КоличествоОстаток * СтрокаТЗ.СебестоимостьЕд;
    КонецЦикла;

    Возврат ТЗ;

КонецФункции

Функция ВыгрузитьПродажиВXMLФайл(ДатаНач, ДатаКон)
    // 1. Определяем имя временного файла
    ИмяФайла = ПолучитьИмяВременногоФайла("xml");

    // 2. Готовим запрос к регистру накопления
    Запрос = Новый Запрос;
    Запрос.Текст = 
    "ВЫБРАТЬ
    |    Продажи.Покупатель КАК Покупатель,
    |    Продажи.Покупатель.Наименование КАК ПокупательНаименование,
    |    Продажи.Товар КАК Товар,
    |    Продажи.Товар.Наименование КАК ТоварНаименование,
    |    СУММА(Продажи.Количество) КАК Количество,
    |    СУММА(Продажи.Сумма) КАК Сумма
    |ИЗ
    |    РегистрНакопления.Продажи.Обороты КАК Продажи
    |ГДЕ
    |    Продажи.Регистратор.Дата МЕЖДУ &ДатаНач И &ДатаКон
    |СГРУППИРОВАТЬ ПО
    |    Продажи.Покупатель,
    |    Продажи.Товар,
    |    Продажи.Покупатель.Наименование,
    |    Продажи.Товар.Наименование";

    Запрос.УстановитьПараметр("ДатаНач", ДатаНач);
    Запрос.УстановитьПараметр("ДатаКон", ДатаКон);

    РезультатЗапроса = Запрос.Выполнить();
    Выборка = РезультатЗапроса.Выбрать();

    // 3. Формируем XML
    ЗаписьXML = Новый ЗаписьXML;
    Попытка
        ЗаписьXML.ОткрытьФайл(ИмяФайла, "UTF-8");
        ЗаписьXML.ЗаписатьОбъявлениеXML();

        ЗаписьXML.ЗаписатьНачалоЭлемента("Продажи");
        ЗаписьXML.ЗаписатьАтрибут("Имя", "ПродажиПоПокупателямИТоварам");
        ЗаписьXML.ЗаписатьАтрибут("ДатаНач", Формат(ДатаНач, "ДФ=yyyy-MM-dd"));
        ЗаписьXML.ЗаписатьАтрибут("ДатаКон", Формат(ДатаКон, "ДФ=yyyy-MM-dd"));

        Пока Выборка.Следующий() Цикл
            ЗаписьXML.ЗаписатьНачалоЭлемента("Запись");

            ЗаписьXML.ЗаписатьНачалоЭлемента("Покупатель");
            ЗаписьXML.ЗаписатьТекст(Выборка.ПокупательНаименование);
            ЗаписьXML.ЗаписатьКонецЭлемента();

            ЗаписьXML.ЗаписатьНачалоЭлемента("Товар");
            ЗаписьXML.ЗаписатьТекст(Выборка.ТоварНаименование);
            ЗаписьXML.ЗаписатьКонецЭлемента();

            ЗаписьXML.ЗаписатьНачалоЭлемента("Количество");
            ЗаписьXML.ЗаписатьТекст(Формат(Выборка.Количество, "ЧГ=0; ЧДЦ=2; ЧРГ='.'"));
            ЗаписьXML.ЗаписатьКонецЭлемента();

            ЗаписьXML.ЗаписатьНачалоЭлемента("Сумма");
            ЗаписьXML.ЗаписатьТекст(Формат(Выборка.Сумма, "ЧГ=0; ЧДЦ=2; ЧРГ='.'"));
            ЗаписьXML.ЗаписатьКонецЭлемента();

            ЗаписьXML.ЗаписатьКонецЭлемента(); // Запись
        КонецЦикла;

        ЗаписьXML.ЗаписатьКонецЭлемента(); // Продажи
    Исключение
        // В случае ошибки пробрасываем исключение наверх
        Если ЗаписьXML.Открыт() Тогда
            ЗаписьXML.Закрыть();
        КонецЕсли;
        УдалитьФайлы(ИмяФайла);
        ВызватьИсключение;
    КонецПопытки;
    ЗаписьXML.Закрыть();

    Возврат ИмяФайла;
КонецФункции

task:
Написать функцию ПолучитьДанныеФайла(ФайлСсылка), которая получает структуру с сведениями о переданном файле.
Параметры функции:
ФайлСсылка (тип: СправочникСсылка.ХранимыеФайлы) - ссылка на файл.

Возвращаемое значение:
Структура - данные о файле:
    * Ссылка (тип СправочникСсылка.ХранимыеФайлы) - ссылка на файл;
    * СсылкаНаДвоичныеДанныеФайла (тип Строка) - адрес во временном хранилище, по которому помещены данные файла.
    * Владелец (тип СправочникСсылка.Товары, СправочникСсылка.Контрагенты) - ссылка на объект-владелец файла;
    * ИмяФайла (тип Строка) - имя файла;
    * Наименование (тип Строка) наименование файла (в справочнике ХранимыеФайлы);   
    * Расширение (тип Строка) - расширение файла без точки;  
    * Подписан (тип Булево) - признак того, что файл подписан;
    * Зашифрован (тип Булево) - признак того, что файл зашифрован; 
    * Ширина (тип Число) - ширина файла, только для .png;
    * Высота (тип Число) - высота файла, только для .png;
    * Размер (тип Число) - размер файла в кб.

output:
Функция ПолучитьДанныеФайла(ФайлСсылка)
    Если ФайлСсылка = Неопределено Или ФайлСсылка.Пустая() Тогда
        Возврат Неопределено;
    КонецЕсли;

    Результат = Новый Структура;
    Результат.Вставить("Ссылка", ФайлСсылка);

    // Получаем объект файла
    ОбъектФайла = ФайлСсылка.ПолучитьОбъект();
    Если ОбъектФайла = Неопределено Тогда
        Возврат Неопределено;
    КонецЕсли;

    Результат.Вставить("Наименование", ОбъектФайла.Наименование);
    Результат.Вставить("ИмяФайла", ОбъектФайла.ИмяФайла);
    Результат.Вставить("Подписан", ОбъектФайла.Подписан);
    Результат.Вставить("Зашифрован", ОбъектФайла.Зашифрован);

    // Данные файла
    ДанныеФайла = ОбъектФайла.ДанныеФайла;
    Если ДанныеФайла = Неопределено Тогда
        Результат.Вставить("СсылкаНаДвоичныеДанныеФайла", "");
        РазмерФайла = 0;
        ДвоичныеДанные = Неопределено;
    Иначе
        // Извлекаем двоичные данные из хранилища значения
        ДвоичныеДанные = ДанныеФайла.Получить();
        Если ДвоичныеДанные = Неопределено Тогда
            Результат.Вставить("СсылкаНаДвоичныеДанныеФайла", "");
            РазмерФайла = 0;
        Иначе
            Адрес = ПоместитьВоВременноеХранилище(ДвоичныеДанные);
            Результат.Вставить("СсылкаНаДвоичныеДанныеФайла", Адрес);
            РазмерФайла = ДвоичныеДанные.Размер() / 1024;
        КонецЕсли;
    КонецЕсли;

    Результат.Вставить("Размер", РазмерФайла);

    // Расширение
    ИмяФайла = ОбъектФайла.ИмяФайла;
    Если ИмяФайла = "" Тогда
        Расширение = "";
    Иначе
        ПозТочки = СтрНайти(ИмяФайла, ".", НаправлениеПоиска.СКонца);
        Если ПозТочки > 0 Тогда
            Расширение = Сред(ИмяФайла, ПозТочки + 1);
        Иначе
            Расширение = "";
        КонецЕсли;
    КонецЕсли;
    Результат.Вставить("Расширение", Расширение);

    // Ширина и высота для PNG
    Ширина = 0;
    Высота = 0;
    Если НРег(Расширение) = "png" И ДвоичныеДанные <> Неопределено Тогда
        Попытка
            Картинка = Новый Картинка(ДвоичныеДанные);
            Ширина = Картинка.Ширина;
            Высота = Картинка.Высота;
        Исключение
            // Не удалось определить размеры
        КонецПопытки;
    КонецЕсли;
    Результат.Вставить("Ширина", Ширина);
    Результат.Вставить("Высота", Высота);

    // Поиск владельца
    Владелец = Неопределено;

    // Проверяем в справочнике Товары
    Запрос = Новый Запрос;
    Запрос.Текст = 
    "ВЫБРАТЬ
    |    Товары.Ссылка КАК Ссылка
    |ИЗ
    |    Справочник.Товары КАК Товары
    |ГДЕ
    |    Товары.ФайлКартинки = &ФайлСсылка";
    Запрос.УстановитьПараметр("ФайлСсылка", ФайлСсылка);
    РезультатЗапроса = Запрос.Выполнить();
    Если Не РезультатЗапроса.Пустой() Тогда
        Выборка = РезультатЗапроса.Выбрать();
        Выборка.Следующий();
        Владелец = Выборка.Ссылка;
    КонецЕсли;

    // Если не нашли в Товарах, проверяем в Контрагентах (динамически ищем реквизит с типом ХранимыеФайлы)
    Если Владелец = Неопределено Тогда
        МетаданныеКонтрагенты = Метаданные.Справочники.Контрагенты;
        ИмяРеквизитаФайл = "";
        Для Каждого Реквизит Из МетаданныеКонтрагенты.Реквизиты Цикл
            Если Реквизит.Тип.СодержитТип(Тип("СправочникСсылка.ХранимыеФайлы")) Тогда
                ИмяРеквизитаФайл = Реквизит.Имя;
                Прервать;
            КонецЕсли;
        КонецЦикла;
        Если ИмяРеквизитаФайл <> "" Тогда
            ЗапросКонтр = Новый Запрос;
            ЗапросКонтр.Текст = 
            "ВЫБРАТЬ
            |    Контрагенты.Ссылка КАК Ссылка
            |ИЗ
            |    Справочник.Контрагенты КАК Контрагенты
            |ГДЕ
            |    Контрагенты." + ИмяРеквизитаФайл + " = &ФайлСсылка";
            ЗапросКонтр.УстановитьПараметр("ФайлСсылка", ФайлСсылка);
            РезультатЗапросаКонтр = ЗапросКонтр.Выполнить();
            Если Не РезультатЗапросаКонтр.Пустой() Тогда
                ВыборкаКонтр = РезультатЗапросаКонтр.Выбрать();
                ВыборкаКонтр.Следующий();
                Владелец = ВыборкаКонтр.Ссылка;
            КонецЕсли;
        КонецЕсли;
    КонецЕсли;

    Результат.Вставить("Владелец", Владелец);

    Возврат Результат;
КонецФункции

Функция ЗагрузитьДанныеТоваровИзJSON(СтрокаJSON)
    // Чтение JSON и преобразование в структуры данных
    ЧтениеJSON = Новый ЧтениеJSON;
    ЧтениеJSON.УстановитьСтроку(СтрокаJSON);
    ДанныеJSON = ПрочитатьJSON(ЧтениеJSON, Ложь);

    // Приведение к массиву для единообразной обработки
    Если ТипЗнч(ДанныеJSON) = Тип("Соответствие") Тогда
        МассивТоваров = Новый Массив;
        МассивТоваров.Добавить(ДанныеJSON);
    ИначеЕсли ТипЗнч(ДанныеJSON) = Тип("Массив") Тогда
        МассивТоваров = ДанныеJSON;
    Иначе
        ВызватьИсключение "Некорректный формат JSON. Ожидался массив или объект.";
    КонецЕсли;

    КоличествоОбработано = 0;
    КоличествоПропущено = 0;

    Для Каждого ТоварJSON Из МассивТоваров Цикл
        // Проверка наличия обязательных полей
        Если Не ТоварJSON.Свойство("article") 
           Или Не ТоварJSON.Свойство("description") Тогда
            КоличествоПропущено = КоличествоПропущено + 1;
            Продолжить;
        КонецЕсли;

        article = СокрЛП(Строка(ТоварJSON.article));
        description = СокрЛП(Строка(ТоварJSON.description));

        // Пропуск пустых обязательных значений
        Если Не ЗначениеЗаполнено(article) 
           Или Не ЗначениеЗаполнено(description) Тогда
            КоличествоПропущено = КоличествоПропущено + 1;
            Продолжить;
        КонецЕсли;

        // Поиск существующего товара по артикулу и наименованию
        Запрос = Новый Запрос;
        Запрос.Текст = 
            "ВЫБРАТЬ
            |   Товары.Ссылка КАК Ссылка
            |ИЗ
            |   Справочник.Товары КАК Товары
            |ГДЕ
            |   Товары.Артикул = &Артикул
            |   И Товары.Наименование = &Наименование";

        Запрос.УстановитьПараметр("Артикул", article);
        Запрос.УстановитьПараметр("Наименование", description);

        Результат = Запрос.Выполнить();
        Выборка = Результат.Выбрать();

        Если Выборка.Следующий() Тогда
            ТоварОбъект = Выборка.Ссылка.ПолучитьОбъект();
        Иначе
            // Создание нового элемента
            ТоварОбъект = Справочники.Товары.СоздатьЭлемент();
            ТоварОбъект.Наименование = description;
            ТоварОбъект.Артикул = article;
        КонецЕсли;

        // Заполнение необязательных реквизитов

        // Поставщик (контрагент по коду)
        Если ТоварJSON.Свойство("counterparty_code") 
           И ЗначениеЗаполнено(ТоварJSON.counterparty_code) Тогда
            КодКонтрагента = Строка(ТоварJSON.counterparty_code);

            ЗапросКонтрагент = Новый Запрос;
            ЗапросКонтрагент.Текст = 
                "ВЫБРАТЬ ПЕРВЫЕ 1
                |   Контрагенты.Ссылка КАК Ссылка
                |ИЗ
                |   Справочник.Контрагенты КАК Контрагенты
                |ГДЕ
                |   Контрагенты.Код = &Код";

            ЗапросКонтрагент.УстановитьПараметр("Код", КодКонтрагента);
            РезультатКонтр = ЗапросКонтрагент.Выполнить();
            Если НЕ РезультатКонтр.Пустой() Тогда
                ВыборкаКонтр = РезультатКонтр.Выбрать();
                ВыборкаКонтр.Следующий();
                ТоварОбъект.Поставщик = ВыборкаКонтр.Ссылка;
            КонецЕсли;
        КонецЕсли;

        // Штрихкод
        Если ТоварJSON.Свойство("barcode") 
           И ЗначениеЗаполнено(ТоварJSON.barcode) Тогда
            ТоварОбъект.Штрихкод = СокрЛП(Строка(ТоварJSON.barcode));
        КонецЕсли;

        // Вид товара (перечисление)
        Если ТоварJSON.Свойство("type") 
           И ЗначениеЗаполнено(ТоварJSON.type) Тогда
            СтрокаВида = СокрЛП(Строка(ТоварJSON.type));
            Попытка
                ТоварОбъект.Вид = Перечисления.ВидыТоваров[СтрокаВида];
            Исключение
                // Игнорируем некорректное значение перечисления
            КонецПопытки;
        КонецЕсли;

        // Сохранение элемента
        ТоварОбъект.Записать();
        КоличествоОбработано = КоличествоОбработано + 1;
    КонецЦикла;

    Возврат КоличествоОбработано; // Количество успешно загруженных товаров
КонецФункции

&НаСервере
Функция СформироватьРасчетЗаказа(Знач ДатаНач = Неопределено, Знач ДатаКон = Неопределено) Экспорт

    // Инициализация дат с учётом значений по умолчанию и приведение границ
    Если ДатаНач = Неопределено Тогда
        ДатаНач = НачалоДня(ТекущаяДата()) - 30 * 86400; // 30 дней назад от начала текущего дня
    Иначе
        ДатаНач = НачалоДня(ДатаНач);
    КонецЕсли;

    Если ДатаКон = Неопределено Тогда
        ДатаКон = КонецДня(ТекущаяДата());
    Иначе
        ДатаКон = КонецДня(ДатаКон);
    КонецЕсли;

    Если ДатаКон < ДатаНач Тогда
        ВызватьИсключение "Дата окончания периода не может быть меньше даты начала.";
    КонецЕсли;

    Запрос = Новый Запрос;
    Запрос.Текст = 
    "ВЫБРАТЬ
    |    ПродажиОбороты.Товар КАК Товар,
    |    СУММА(ПродажиОбороты.Количество) КАК КоличествоПродаж
    |ПОМЕСТИТЬ ВТПродажи
    |ИЗ
    |    РегистрНакопления.Продажи.Обороты(&ДатаНач, &ДатаКон) КАК ПродажиОбороты
    |СГРУППИРОВАТЬ ПО
    |    ПродажиОбороты.Товар
    |;
    |////////////////////////////////////////////////////////////////////////////////
    |ВЫБРАТЬ
    |    ТоварныеЗапасыОстатки.Товар КАК Товар,
    |    СУММА(ТоварныеЗапасыОстатки.Количество) КАК Остаток
    |ПОМЕСТИТЬ ВТОстатки
    |ИЗ
    |    РегистрНакопления.ТоварныеЗапасы.Остатки(&ДатаКон) КАК ТоварныеЗапасыОстатки
    |СГРУППИРОВАТЬ ПО
    |    ТоварныеЗапасыОстатки.Товар
    |;
    |////////////////////////////////////////////////////////////////////////////////
    |ВЫБРАТЬ
    |    Товары.Товар КАК Товар,
    |    ЕСТЬNULL(Продажи.КоличествоПродаж, 0) КАК КоличествоПродаж,
    |    ЕСТЬNULL(Остатки.Остаток, 0) КАК ОстаткиТовара,
    |    ВЫБОР
    |        КОГДА ЕСТЬNULL(Продажи.КоличествоПродаж, 0) - ЕСТЬNULL(Остатки.Остаток, 0) > 0
    |        ТОГДА ЕСТЬNULL(Продажи.КоличествоПродаж, 0) - ЕСТЬNULL(Остатки.Остаток, 0)
    |        ИНАЧЕ 0
    |    КОНЕЦ КАК РекомендуемыйЗаказ
    |ПОМЕСТИТЬ ВТРасчет
    |ИЗ
    |    (ВЫБРАТЬ
    |        ВТПродажи.Товар КАК Товар
    |    ИЗ
    |        ВТПродажи КАК ВТПродажи
    |    ОБЪЕДИНИТЬ
    |    ВЫБРАТЬ
    |        ВТОстатки.Товар
    |    ИЗ
    |        ВТОстатки КАК ВТОстатки) КАК Товары
    |ЛЕВОЕ СОЕДИНЕНИЕ ВТПродажи КАК Продажи
    |ПО Товары.Товар = Продажи.Товар
    |ЛЕВОЕ СОЕДИНЕНИЕ ВТОстатки КАК Остатки
    |ПО Товары.Товар = Остатки.Товар
    |;
    |////////////////////////////////////////////////////////////////////////////////
    |ВЫБРАТЬ
    |    ВТРасчет.Товар КАК Товар,
    |    ВТРасчет.КоличествоПродаж КАК КоличествоПродаж,
    |    ВТРасчет.ОстаткиТовара КАК ОстаткиТовара,
    |    ВТРасчет.РекомендуемыйЗаказ КАК РекомендуемыйЗаказ
    |ИЗ
    |    ВТРасчет КАК ВТРасчет
    |ГДЕ
    |    ВТРасчет.РекомендуемыйЗаказ > 0";

    Запрос.УстановитьПараметр("ДатаНач", ДатаНач);
    Запрос.УстановитьПараметр("ДатаКон", ДатаКон);

    РезультатЗапроса = Запрос.Выполнить();

    // Формирование итоговой таблицы значений
    ТаблицаРезультата = Новый ТаблицаЗначений;
    ТаблицаРезультата.Колонки.Добавить("Товар", Новый ОписаниеТипов("СправочникСсылка.Товары"));
    ТаблицаРезультата.Колонки.Добавить("КоличествоПродаж", Новый ОписаниеТипов("Число", Новый КвалификаторыЧисла(10, 2)));
    ТаблицаРезультата.Колонки.Добавить("ОстаткиТовара", Новый ОписаниеТипов("Число", Новый КвалификаторыЧисла(10, 2)));
    ТаблицаРезультата.Колонки.Добавить("РекомендуемыйЗаказ", Новый ОписаниеТипов("Число", Новый КвалификаторыЧисла(10, 2)));

    Выборка = РезультатЗапроса.Выбрать();
    Пока Выборка.Следующий() Цикл
        Строка = ТаблицаРезультата.Добавить();
        Строка.Товар = Выборка.Товар;
        Строка.КоличествоПродаж = Выборка.КоличествоПродаж;
        Строка.ОстаткиТовара = Выборка.ОстаткиТовара;
        Строка.РекомендуемыйЗаказ = Выборка.РекомендуемыйЗаказ;
    КонецЦикла;

    Возврат ТаблицаРезультата;
КонецФункции

Функция УчетТоваровПоИнвентаризации(ДатаНачала, ДатаОкончания)

    ТаблицаРезультата = Новый ТаблицаЗначений;
    ТаблицаРезультата.Колонки.Добавить("Товар", , "СправочникСсылка.Товары");
    ТаблицаРезультата.Колонки.Добавить("Склад", , "СправочникСсылка.Склады");
    ТаблицаРезультата.Колонки.Добавить("Корректировка", , "ДокументСсылка.ОперацияПоУчетуТоваров");
    ТаблицаРезультата.Колонки.Добавить("ЗначениеКорректировки", , "Число");
    ТаблицаРезультата.Колонки.Добавить("ОстатокНаКонецПериода", , "Число");

    Запрос = Новый Запрос;
    Запрос.Текст = 
    "ВЫБРАТЬ
    |    Остатки.Товар КАК Товар,
    |    Остатки.Склад КАК Склад,
    |    Корректировки.Регистратор КАК Корректировка,
    |    Корректировки.ЗначениеКорректировки КАК ЗначениеКорректировки,
    |    Остатки.КоличествоОстаток КАК ОстатокНаКонецПериода
    |ИЗ
    |    РегистрНакопления.ТоварныеЗапасы.Остатки(&ДатаОкончания) КАК Остатки
    |    ЛЕВОЕ СОЕДИНЕНИЕ (ВЫБРАТЬ
    |                    ТоварныеЗапасыОбороты.Товар,
    |                    ТоварныеЗапасыОбороты.Склад,
    |                    ТоварныеЗапасыОбороты.Регистратор,
    |                    СУММА(ТоварныеЗапасыОбороты.КоличествоПриход) - СУММА(ТоварныеЗапасыОбороты.КоличествоРасход) КАК ЗначениеКорректировки
    |                ИЗ
    |                    РегистрНакопления.ТоварныеЗапасы.Обороты(&ДатаНачала, &ДатаОкончания, Документ) КАК ТоварныеЗапасыОбороты
    |                        ВНУТРЕННЕЕ СОЕДИНЕНИЕ Документ.ОперацияПоУчетуТоваров КАК Док
    |                        ПО ТоварныеЗапасыОбороты.Регистратор = Док.Ссылка
    |                ГДЕ
    |                    (НРЕГ(Док.СодержаниеОперации) ПОДОБНО НРЕГ('%инвентаризация%')
    |                    ИЛИ НРЕГ(Док.СодержаниеОперации) ПОДОБНО НРЕГ('%в результате инвентаризации%')
    |                    ИЛИ НРЕГ(Док.СодержаниеОперации) ПОДОБНО НРЕГ('%по инвентаризации%')
    |                    ИЛИ НРЕГ(Док.СодержаниеОперации) ПОДОБНО НРЕГ('%инвентар.%') )
    |                СГРУППИРОВАТЬ ПО
    |                    ТоварныеЗапасыОбороты.Товар,
    |                    ТоварныеЗапасыОбороты.Склад,
    |                    ТоварныеЗапасыОбороты.Регистратор) КАК Корректировки
    |    ПО Остатки.Товар = Корректировки.Товар
    |        И Остатки.Склад = Корректировки.Склад";

    Запрос.УстановитьПараметр("ДатаНачала", ДатаНачала);
    Запрос.УстановитьПараметр("ДатаОкончания", ДатаОкончания);

    РезультатЗапроса = Запрос.Выполнить();
    Выборка = РезультатЗапроса.Выбрать();

    Пока Выборка.Следующий() Цикл
        СтрокаТаблицы = ТаблицаРезультата.Добавить();
        СтрокаТаблицы.Товар = Выборка.Товар;
        СтрокаТаблицы.Склад = Выборка.Склад;
        СтрокаТаблицы.Корректировка = Выборка.Корректировка;
        СтрокаТаблицы.ЗначениеКорректировки = Выборка.ЗначениеКорректировки;
        СтрокаТаблицы.ОстатокНаКонецПериода = Выборка.ОстатокНаКонецПериода;
    КонецЦикла;

    Возврат ТаблицаРезультата;

КонецФункции

Функция ЗагрузитьЦеныТоваровJSON(СтрокаJSON) Экспорт

    // Преобразовать строку JSON в массив структур
    ЧтениеJSON = Новый ЧтениеJSON;
    ЧтениеJSON.УстановитьСтроку(СтрокаJSON);
    РезультатЧтения = ПрочитатьJSON(ЧтениеJSON, Ложь);
    ЧтениеJSON.Закрыть();

    Если РезультатЧтения = Неопределено Тогда
        Возврат "Ошибка разбора JSON";
    КонецЕсли;

    МассивДанных = Новый Массив;
    Если ТипЗнч(РезультатЧтения) = Тип("Массив") Тогда
        МассивДанных = РезультатЧтения;
    ИначеЕсли ТипЗнч(РезультатЧтения) = Тип("Структура") Тогда
        МассивДанных.Добавить(РезультатЧтения);
    Иначе
        Возврат "Неверный формат JSON. Ожидался массив или объект.";
    КонецЕсли;

    Если МассивДанных.Количество() = 0 Тогда
        Возврат "Нет данных для загрузки";
    КонецЕсли;

    // Сбор уникальных артикулов/наименований и видов цен для пакетного поиска
    Артикулы = Новый Соответствие;
    Наименования = Новый Соответствие;
    ВидыЦенНаименования = Новый Соответствие;

    Для Каждого ЭлементJSON Из МассивДанных Цикл
        Если ТипЗнч(ЭлементJSON) <> Тип("Структура") Тогда
            Продолжить;
        КонецЕсли;

        Артикул = ?(ЭлементJSON.Свойство("article"), СокрЛП(ЭлементJSON.article), "");
        Наименование = ?(ЭлементJSON.Свойство("description"), СокрЛП(ЭлементJSON.description), "");
        ВидЦены = ?(ЭлементJSON.Свойство("type_of_price"), СокрЛП(ЭлементJSON.type_of_price), "");

        Если ЗначениеЗаполнено(Артикул) И ЗначениеЗаполнено(Наименование) Тогда
            Артикулы.Вставить(Артикул, Истина);
            Наименования.Вставить(Наименование, Истина);
        КонецЕсли;
        Если ЗначениеЗаполнено(ВидЦены) Тогда
            ВидыЦенНаименования.Вставить(ВидЦены, Истина);
        КонецЕсли;
    КонецЦикла;

    // Поиск товаров по артикулу и наименованию
    СоответствиеТоваров = Новый Соответствие; // Ключ: "артикул|наименование", Значение: ссылка на товар
    Если Артикулы.Количество() > 0 Тогда
        ЗапросТовары = Новый Запрос;
        ЗапросТовары.Текст = 
        "ВЫБРАТЬ
        |    Товары.Ссылка КАК Ссылка,
        |    Товары.Артикул КАК Артикул,
        |    Товары.Наименование КАК Наименование
        |ИЗ
        |    Справочник.Товары КАК Товары
        |ГДЕ
        |    Товары.Артикул В (&Артикулы)
        |    И Товары.Наименование В (&Наименования)";

        ЗапросТовары.УстановитьПараметр("Артикулы", Новый Массив(Артикулы));
        ЗапросТовары.УстановитьПараметр("Наименования", Новый Массив(Наименования));

        РезультатТовары = ЗапросТовары.Выполнить();
        ВыборкаТовары = РезультатТовары.Выбрать();
        Пока ВыборкаТовары.Следующий() Цикл
            Ключ = ВыборкаТовары.Артикул + "|" + ВыборкаТовары.Наименование;
            СоответствиеТоваров.Вставить(Ключ, ВыборкаТовары.Ссылка);
        КонецЦикла;
    КонецЕсли;

    // Поиск видов цен по наименованию
    СоответствиеВидовЦен = Новый Соответствие; // Ключ: наименование, Значение: ссылка
    Если ВидыЦенНаименования.Количество() > 0 Тогда
        ЗапросВидыЦен = Новый Запрос;
        ЗапросВидыЦен.Текст = 
        "ВЫБРАТЬ
        |    ВидыЦен.Ссылка КАК Ссылка,
        |    ВидыЦен.Наименование КАК Наименование
        |ИЗ
        |    Справочник.ВидыЦен КАК ВидыЦен
        |ГДЕ
        |    ВидыЦен.Наименование В (&Наименования)";

        ЗапросВидыЦен.УстановитьПараметр("Наименования", Новый Массив(ВидыЦенНаименования));

        РезультатВидыЦен = ЗапросВидыЦен.Выполнить();
        ВыборкаВидыЦен = РезультатВидыЦен.Выбрать();
        Пока ВыборкаВидыЦен.Следующий() Цикл
            СоответствиеВидовЦен.Вставить(ВыборкаВидыЦен.Наименование, ВыборкаВидыЦен.Ссылка);
        КонецЦикла;
    КонецЕсли;

    // Обработка каждой записи и запись в регистр
    Для Каждого ЭлементJSON Из МассивДанных Цикл
        Если ТипЗнч(ЭлементJSON) <> Тип("Структура") Тогда
            Продолжить;
        КонецЕсли;

        // Извлечение свойств
        Артикул = ?(ЭлементJSON.Свойство("article"), СокрЛП(ЭлементJSON.article), "");
        Наименование = ?(ЭлементJSON.Свойство("description"), СокрЛП(ЭлементJSON.description), "");
        СтрДата = ?(ЭлементJSON.Свойство("date"), ЭлементJSON.date, Неопределено);
        ВидЦеныНаим = ?(ЭлементJSON.Свойство("type_of_price"), СокрЛП(ЭлементJSON.type_of_price), "");
        Цена = ?(ЭлементJSON.Свойство("price"), ЭлементJSON.price, Неопределено);

        // Проверка обязательных реквизитов
        Если Не ЗначениеЗаполнено(Артикул) Или Не ЗначениеЗаполнено(Наименование) Тогда
            Продолжить;
        КонецЕсли;

        Если Не ЗначениеЗаполнено(ВидЦеныНаим) Тогда
            Продолжить;
        КонецЕсли;

        Если СтрДата = Неопределено Или Не ТипЗнч(СтрДата) = Тип("Дата") Тогда
            Продолжить;
        КонецЕсли;

        Если Цена = Неопределено Или Не ТипЗнч(Цена) = Тип("Число") Тогда
            Продолжить;
        КонецЕсли;

        // Проверка на отрицательную цену
        Если Цена < 0 Тогда
            Продолжить;
        КонецЕсли;

        // Поиск товара
        КлючТовара = Артикул + "|" + Наименование;
        ТоварСсылка = СоответствиеТоваров.Получить(КлючТовара);
        Если ТоварСсылка = Неопределено Тогда
            Продолжить;
        КонецЕсли;

        // Поиск вида цены
        ВидЦеныСсылка = СоответствиеВидовЦен.Получить(ВидЦеныНаим);
        Если ВидЦеныСсылка = Неопределено Тогда
            Продолжить;
        КонецЕсли;

        // Запись в регистр сведений (независимый, периодический, замещение)
        НаборЗаписей = РегистрыСведений.ЦеныТоваров.СоздатьНаборЗаписей();
        НаборЗаписей.Отбор.Период.Установить(СтрДата);
        НаборЗаписей.Отбор.Товар.Установить(ТоварСсылка);
        НаборЗаписей.Отбор.ВидЦен.Установить(ВидЦеныСсылка);

        МенеджерЗаписи = НаборЗаписей.Добавить();
        МенеджерЗаписи.Период = СтрДата;
        МенеджерЗаписи.Товар = ТоварСсылка;
        МенеджерЗаписи.ВидЦен = ВидЦеныСсылка;
        МенеджерЗаписи.Цена = Цена;

        НаборЗаписей.Записать(Истина);
    КонецЦикла;

    Возврат "Загрузка завершена";
КонецФункции

task:
Написать функцию СформироватьИнвентаризациюТоваров(Склад = Неопределено, ДатаИнв = Неопределено),
которая формирует инвентаризацию товаров на складе в виде таблицы значений на указанную дату.
Инвентаризация должна формироваться на основании данных регистра накопления «ТоварныеЗапасы».
Данные выбираются из регистра РегистрНакопления.ТоварныеЗапасы.Остатки с учетом следующих условий:
остатки рассчитываются на дату, переданную в параметре ДатаИнв (на конец дня);
если склад не указан, формируется инвентаризация по всем складам;
если склад указан, выполняется отбор по конкретному складу.
Перед выполнением запроса выполняется проверка входных параметров:
если дата инвентаризации не задана, используется текущая дата;
если тип даты некорректен, формируется исключение.
Формирование инвентаризации выполняется следующим образом:
выполняется запрос к регистру накопления «ТоварныеЗапасы.Остатки» на дату инвентаризации;
данные группируются по складу и товару;
рассчитывается фактическое количество остатка товара на складе;
из результирующей выборки отбираются только позиции с ненулевыми остатками.
Результат должен представлять таблицу значений (ТаблицаЗначений), где каждая строка соответствует сочетанию:
Склад + Товар.
Таблица должна содержать следующие поля:
Склад — ссылка на склад хранения товаров (измерение регистра ТоварныеЗапасы);
Товар — номенклатура (измерение регистра ТоварныеЗапасы);
КоличествоФактическое — фактический остаток товара на складе на дату инвентаризации (ресурс регистра).
После формирования таблицы выполняется сортировка данных по складу и товару для удобства анализа инвентаризационных остатков.

output:
Функция СформироватьИнвентаризациюТоваров(Склад = Неопределено, ДатаИнв = Неопределено) Экспорт
    // Проверка и обработка даты инвентаризации
    Если ДатаИнв = Неопределено Тогда
        ДатаИнв = ТекущаяДата();
    ИначеЕсли ТипЗнч(ДатаИнв) <> Тип("Дата") Тогда
        ВызватьИсключение "Некорректный тип параметра ""ДатаИнв"". Ожидалось значение типа Дата или Неопределено.";
    КонецЕсли;

    // Приведение даты к концу дня для корректных остатков
    ДатаИнвНаКонецДня = КонецДня(ДатаИнв);

    // Построение текста запроса с динамическим отбором по складу
    Запрос = Новый Запрос;
    ТекстЗапроса = 
    "ВЫБРАТЬ
    |    ТоварныеЗапасыОстатки.Склад КАК Склад,
    |    ТоварныеЗапасыОстатки.Товар КАК Товар,
    |    ТоварныеЗапасыОстатки.КоличествоОстаток КАК КоличествоФактическое
    |ИЗ
    |    РегистрНакопления.ТоварныеЗапасы.Остатки(
    |        &ДатаИнв,
    |        ";

    ТекстЗапроса = ТекстЗапроса + ?(Склад = Неопределено, "", "Склад = &Склад");
    ТекстЗапроса = ТекстЗапроса + 
    "    ) КАК ТоварныеЗапасыОстатки
    |ГДЕ
    |    ТоварныеЗапасыОстатки.КоличествоОстаток <> 0";

    Запрос.Текст = ТекстЗапроса;
    Запрос.УстановитьПараметр("ДатаИнв", ДатаИнвНаКонецДня);

    Если Склад <> Неопределено Тогда
        Запрос.УстановитьПараметр("Склад", Склад);
    КонецЕсли;

    // Выполнение запроса
    РезультатЗапроса = Запрос.Выполнить();

    // Создание результирующей таблицы значений
    ТаблицаИнв = Новый ТаблицаЗначений;
    ТаблицаИнв.Колонки.Добавить("Склад", Новый ОписаниеТипов("СправочникСсылка.Склады"));
    ТаблицаИнв.Колонки.Добавить("Товар", Новый ОписаниеТипов("СправочникСсылка.Товары"));
    ТаблицаИнв.Колонки.Добавить("КоличествоФактическое", Новый ОписаниеТипов("Число", Новый КвалификаторыЧисла(10, 2)));

    // Заполнение таблицы
    Выборка = РезультатЗапроса.Выбрать();
    Пока Выборка.Следующий() Цикл
        Строка = ТаблицаИнв.Добавить();
        Строка.Склад = Выборка.Склад;
        Строка.Товар = Выборка.Товар;
        Строка.КоличествоФактическое = Выборка.КоличествоФактическое;
    КонецЦикла;

    // Сортировка для удобства анализа
    ТаблицаИнв.Сортировать("Склад, Товар");

    Возврат ТаблицаИнв;
КонецФункции

Функция ПроверитьСтрокуНаСоответствие(Знач ИсходнаяСтрока, Знач Фильтр)

    // Проверка на использование только кириллицы
    Если Фильтр.Свойство("ИспользоватьТолькоКириллицу") И Фильтр.ИспользоватьТолькоКириллицу Тогда
        Если СодержитЛатиницу(ИсходнаяСтрока) Тогда
            Возврат Ложь;
        КонецЕсли;
    КонецЕсли;

    // Проверка на использование только цифр
    Если Фильтр.Свойство("ИспользоватьТолькоЦифры") И Фильтр.ИспользоватьТолькоЦифры Тогда
        Если НЕ ЭтоТолькоЦифры(ИсходнаяСтрока) Тогда
            Возврат Ложь;
        КонецЕсли;
    КонецЕсли;

    // Проверка на начало с заданной строки
    Если Фильтр.Свойство("НачинаетсяС") И ЗначениеЗаполнено(Фильтр.НачинаетсяС) Тогда
        Если Лев(ИсходнаяСтрока, СтрДлина(Фильтр.НачинаетсяС)) <> Фильтр.НачинаетсяС Тогда
            Возврат Ложь;
        КонецЕсли;
    КонецЕсли;

    // Проверка на содержание подстроки
    Если Фильтр.Свойство("Подстрока") И ЗначениеЗаполнено(Фильтр.Подстрока) Тогда
        Если СтрНайти(ИсходнаяСтрока, Фильтр.Подстрока) = 0 Тогда
            Возврат Ложь;
        КонецЕсли;
    КонецЕсли;

    // Проверка формата даты
    Если Фильтр.Свойство("ЭтоФорматДата") И Фильтр.ЭтоФорматДата Тогда
        Если НЕ ЭтоКорректнаяДата(ИсходнаяСтрока) Тогда
            Возврат Ложь;
        КонецЕсли;
    КонецЕсли;

    // Проверка формата телефона
    Если Фильтр.Свойство("ЭтоФорматТелефон") И Фильтр.ЭтоФорматТелефон Тогда
        Если НЕ ТелефонСоответствуетФормату(ИсходнаяСтрока) Тогда
            Возврат Ложь;
        КонецЕсли;
    КонецЕсли;

    // Проверка формата email
    Если Фильтр.Свойство("ЭтоФорматEmail") И Фильтр.ЭтоФорматEmail Тогда
        Если НЕ ЭтоКорректныйEmail(ИсходнаяСтрока) Тогда
            Возврат Ложь;
        КонецЕсли;
    КонецЕсли;

    Возврат Истина;
КонецФункции

// Проверяет, содержит ли строка латинские буквы
Функция СодержитЛатиницу(Стр)
    Для Индекс = 1 По СтрДлина(Стр) Цикл
        Код = КодСимвола(Сред(Стр, Индекс, 1));
        Если (Код >= 65 И Код <= 90) Или (Код >= 97 И Код <= 122) Тогда
            Возврат Истина;
        КонецЕсли;
    КонецЦикла;
    Возврат Ложь;
КонецФункции

// Проверяет, состоит ли строка только из цифр
Функция ЭтоТолькоЦифры(Стр)
    Для Индекс = 1 По СтрДлина(Стр) Цикл
        Код = КодСимвола(Сред(Стр, Индекс, 1));
        Если Код < 48 Или Код > 57 Тогда
            Возврат Ложь;
        КонецЕсли;
    КонецЦикла;
    Возврат Истина;
КонецФункции

// Проверяет, является ли строка корректной датой в формате дд.мм.гггг
Функция ЭтоКорректнаяДата(Стр)
    Если СтрДлина(Стр) <> 10 Тогда
        Возврат Ложь;
    КонецЕсли;
    Если Сред(Стр, 3, 1) <> "." Или Сред(Стр, 6, 1) <> "." Тогда
        Возврат Ложь;
    КонецЕсли;
    День = Лев(Стр, 2);
    Месяц = Сред(Стр, 4, 2);
    Год = Сред(Стр, 7, 4);
    Если НЕ ЭтоТолькоЦифры(День) Или НЕ ЭтоТолькоЦифры(Месяц) Или НЕ ЭтоТолькоЦифры(Год) Тогда
        Возврат Ложь;
    КонецЕсли;
    ЧислоДень = Число(День);
    ЧислоМесяц = Число(Месяц);
    ЧислоГод = Число(Год);
    Если ЧислоДень < 1 Или ЧислоДень > 31 Тогда Возврат Ложь; КонецЕсли;
    Если ЧислоМесяц < 1 Или ЧислоМесяц > 12 Тогда Возврат Ложь; КонецЕсли;
    Если ЧислоГод < 1 Или ЧислоГод > 9999 Тогда Возврат Ложь; КонецЕсли;
    Попытка
        ПроверяемаяДата = Дата(ЧислоГод, ЧислоМесяц, ЧислоДень);
    Исключение
        Возврат Ложь;
    КонецПопытки;
    Если День(ПроверяемаяДата) <> ЧислоДень Или Месяц(ПроверяемаяДата) <> ЧислоМесяц Или Год(ПроверяемаяДата) <> ЧислоГод Тогда
        Возврат Ложь;
    КонецЕсли;
    Возврат Истина;
КонецФункции

// Проверяет строку на соответствие маске, где X обозначает любую цифру
Функция СоответствуетМаске(Стр, Маска)
    Если СтрДлина(Стр) <> СтрДлина(Маска) Тогда
        Возврат Ложь;
    КонецЕсли;
    Для Индекс = 1 По СтрДлина(Маска) Цикл
        СимволМаски = Сред(Маска, Индекс, 1);
        СимволСтроки = Сред(Стр, Индекс, 1);
        Если СимволМаски = "X" Тогда
            Код = КодСимвола(СимволСтроки);
            Если Код < 48 Или Код > 57 Тогда
                Возврат Ложь;
            КонецЕсли;
        ИначеЕсли СимволМаски <> СимволСтроки Тогда
            Возврат Ложь;
        КонецЕсли;
    КонецЦикла;
    Возврат Истина;
КонецФункции

// Проверяет строку на соответствие одному из допустимых форматов телефона
Функция ТелефонСоответствуетФормату(Стр)
    Если СоответствуетМаске(Стр, "+7(8) XXX-XXX-XX-XX") Тогда
        Возврат Истина;
    ИначеЕсли СоответствуетМаске(Стр, "+7(8)(XXX)XXXXXXX") Тогда
        Возврат Истина;
    ИначеЕсли СоответствуетМаске(Стр, "+7(8)XXXXXXXXXX") Тогда
        Возврат Истина;
    КонецЕсли;
    Возврат Ложь;
КонецФункции

// Проверяет строку на соответствие базовому формату email
Функция ЭтоКорректныйEmail(Стр)
    Позиция = СтрНайти(Стр, "@");
    Если Позиция = 0 Или Позиция = 1 Или Позиция = СтрДлина(Стр) Тогда
        Возврат Ложь;
    КонецЕсли;
    ЛокальнаяЧасть = Лев(Стр, Позиция - 1);
    Домен = Сред(Стр, Позиция + 1);
    Если СтрДлина(ЛокальнаяЧасть) = 0 Или СтрДлина(Домен) = 0 Тогда
        Возврат Ложь;
    КонецЕсли;
    ПозТочки = СтрНайти(Домен, ".");
    Если ПозТочки = 0 Или ПозТочки = 1 Или ПозТочки = СтрДлина(Домен) Тогда
        Возврат Ложь;
    КонецЕсли;
    Если СтрНайти(Стр, " ") > 0 Тогда
        Возврат Ложь;
    КонецЕсли;
    Если СтрНайти(ЛокальнаяЧасть, "@") > 0 Или СтрНайти(Домен, "@") > 0 Тогда
        Возврат Ложь;
    КонецЕсли;
    Возврат Истина;
КонецФункции

Функция ЗагрузитьРасчетныеСчетаКонтрагентовJSON(СтрокаJSON)

    // Проверка входного параметра
    Если Не ЗначениеЗаполнено(СтрокаJSON) Тогда
        Возврат 0;
    КонецЕсли;

    // Преобразование JSON в массив структур (или структуру)
    Попытка
        ДанныеJSON = ПрочитатьJSON(СтрокаJSON);
    Исключение
        // Если не удалось прочитать JSON, возвращаем 0
        Возврат 0;
    КонецПопытки;

    // Приводим к единому виду: массив элементов
    Если ТипЗнч(ДанныеJSON) = Тип("Структура") Тогда
        МассивЭлементов = Новый Массив;
        МассивЭлементов.Добавить(ДанныеJSON);
    ИначеЕсли ТипЗнч(ДанныеJSON) = Тип("Массив") Тогда
        МассивЭлементов = ДанныеJSON;
    Иначе
        // Неподдерживаемый формат
        Возврат 0;
    КонецЕсли;

    КоличествоЗагруженных = 0;

    Для Каждого ЭлементJSON Из МассивЭлементов Цикл

        // Проверка обязательных свойств
        Если Не ЭлементJSON.Свойство("bank_description") 
            Или Не ЭлементJSON.Свойство("counterparty_code") 
            Или Не ЭлементJSON.Свойство("number") Тогда
            Продолжить;
        КонецЕсли;

        // Извлечение значений
        НаименованиеБанка = СокрЛП(ЭлементJSON.bank_description);
        КодКонтрагента = СокрЛП(ЭлементJSON.counterparty_code);
        НомерСчета = СокрЛП(ЭлементJSON.number);

        // Поиск банка по наименованию
        Запрос = Новый Запрос;
        Запрос.Текст = 
        "ВЫБРАТЬ
        |	Банки.Ссылка КАК Ссылка,
        |	Банки.ПометкаУдаления КАК ПометкаУдаления
        |ИЗ
        |	Справочник.Банки КАК Банки
        |ГДЕ
        |	Банки.Наименование = &Наименование";
        Запрос.УстановитьПараметр("Наименование", НаименованиеБанка);
        Результат = Запрос.Выполнить();

        Если Результат.Пустой() Тогда
            Продолжить; // Банк не найден
        КонецЕсли;

        ВыборкаБанк = Результат.Выбрать();
        ВыборкаБанк.Следующий();
        Если ВыборкаБанк.ПометкаУдаления Тогда
            Продолжить; // Банк помечен на удаление
        КонецЕсли;
        БанкСсылка = ВыборкаБанк.Ссылка;

        // Поиск контрагента по коду
        Запрос = Новый Запрос;
        Запрос.Текст = 
        "ВЫБРАТЬ
        |	Контрагенты.Ссылка КАК Ссылка,
        |	Контрагенты.ПометкаУдаления КАК ПометкаУдаления
        |ИЗ
        |	Справочник.Контрагенты КАК Контрагенты
        |ГДЕ
        |	Контрагенты.Код = &Код";
        Запрос.УстановитьПараметр("Код", КодКонтрагента);
        Результат = Запрос.Выполнить();

        Если Результат.Пустой() Тогда
            Продолжить; // Контрагент не найден
        КонецЕсли;

        ВыборкаКонтрагент = Результат.Выбрать();
        ВыборкаКонтрагент.Следующий();
        Если ВыборкаКонтрагент.ПометкаУдаления Тогда
            Продолжить; // Контрагент помечен на удаление
        КонецЕсли;
        КонтрагентСсылка = ВыборкаКонтрагент.Ссылка;

        // Проверка уникальности расчетного счета
        Запрос = Новый Запрос;
        Запрос.Текст = 
        "ВЫБРАТЬ
        |	РасчетныеСчетаКонтрагентов.Ссылка КАК Ссылка
        |ИЗ
        |	Справочник.РасчетныеСчетаКонтрагентов КАК РасчетныеСчетаКонтрагентов
        |ГДЕ
        |	РасчетныеСчетаКонтрагентов.Владелец = &Владелец
        |	И РасчетныеСчетаКонтрагентов.Банк = &Банк
        |	И РасчетныеСчетаКонтрагентов.Номер = &Номер";
        Запрос.УстановитьПараметр("Владелец", КонтрагентСсылка);
        Запрос.УстановитьПараметр("Банк", БанкСсылка);
        Запрос.УстановитьПараметр("Номер", НомерСчета);
        Результат = Запрос.Выполнить();

        Если Не Результат.Пустой() Тогда
            Продолжить; // Элемент уже существует
        КонецЕсли;

        // Создание нового элемента справочника
        НовыйСчет = Справочники.РасчетныеСчетаКонтрагентов.СоздатьЭлемент();
        НовыйСчет.Владелец = КонтрагентСсылка;
        НовыйСчет.Банк = БанкСсылка;
        НовыйСчет.Номер = НомерСчета;

        Попытка
            НовыйСчет.Записать();
            КоличествоЗагруженных = КоличествоЗагруженных + 1;
        Исключение
            // Ошибка записи — пропускаем
            Продолжить;
        КонецПопытки;

    КонецЦикла;

    Возврат КоличествоЗагруженных;

КонецФункции

// Функция проверки корректности заполнения карточек номенклатуры.
// Возвращает таблицу значений с перечнем некорректно заполненных позиций.
//
Функция ПроверкаКорректностиЗаполненияНоменклатуры() Экспорт

    // Шаг 1. Формирование запроса к справочнику Товары
    Запрос = Новый Запрос;
    Запрос.Текст = 
    "ВЫБРАТЬ
    |    Товары.Ссылка       КАК Ссылка,
    |    Товары.Наименование КАК Наименование,
    |    Товары.Штрихкод     КАК Штрихкод,
    |    Товары.Описание     КАК Описание
    |ИЗ
    |    Справочник.Товары КАК Товары";

    // Выполнение запроса и выгрузка результата в таблицу значений
    // для последующей программной обработки
    РезультатЗапроса = Запрос.Выполнить();
    ПромежуточнаяТаблица = РезультатЗапроса.Выгрузить();

    // Шаг 2. Создание результирующей таблицы значений с требуемой структурой колонок
    РезультирующаяТаблица = Новый ТаблицаЗначений;
    РезультирующаяТаблица.Колонки.Добавить("Товар",               Новый ОписаниеТипов("СправочникСсылка.Товары"));
    РезультирующаяТаблица.Колонки.Добавить("Наименование",       Новый ОписаниеТипов("Строка"));
    РезультирующаяТаблица.Колонки.Добавить("Штрихкод",           Новый ОписаниеТипов("Строка"));
    РезультирующаяТаблица.Колонки.Добавить("Описание",           Новый ОписаниеТипов("Строка"));
    РезультирующаяТаблица.Колонки.Добавить("КорректноЗаполнено", Новый ОписаниеТипов("Булево"));

    // Шаг 3. Цикл по всем выбранным элементам справочника
    Для Каждого Строка Из ПромежуточнаяТаблица Цикл

        // Проверка заполненности обязательных реквизитов
        // Элемент считается заполненным некорректно, если хотя бы один из реквизитов
        // не заполнен (используется функция ЗначениеЗаполнено, которая учитывает
        // пустые строки, Null и Неопределено)
        Если Не ЗначениеЗаполнено(Строка.Наименование)
           Или Не ЗначениеЗаполнено(Строка.Штрихкод)
           Или Не ЗначениеЗаполнено(Строка.Описание) Тогда

            // Добавление записи о проблемной позиции в результирующую таблицу
            НовСтрока = РезультирующаяТаблица.Добавить();
            НовСтрока.Товар               = Строка.Ссылка;
            НовСтрока.Наименование       = Строка.Наименование;
            НовСтрока.Штрихкод           = Строка.Штрихкод;
            НовСтрока.Описание           = Строка.Описание;
            НовСтрока.КорректноЗаполнено = Ложь;
        КонецЕсли;

    КонецЦикла;

    // Шаг 4. Сортировка результирующей таблицы по наименованию в возрастающем порядке
    РезультирующаяТаблица.Сортировать("Наименование Возр");

    // Шаг 5. Возврат сформированной таблицы (может быть пустой, это корректно)
    Возврат РезультирующаяТаблица;

КонецФункции

Функция СформироватьОтчетВзаимосвязьПродажТоваровВариантТаблица(ДатаНачала, ДатаОкончания, СравниваемыйТовар)
    // Получаем объект отчета
    Отчет = Отчеты.ВзаимосвязьПродажТоваров.Создать();

    // Загружаем настройки варианта "Основной"
    Вариант = Отчет.ВариантыНастроек.Найти("Основной");
    Если Вариант = Неопределено Тогда
        ВызватьИсключение "Вариант отчета ""Основной"" не найден.";
    КонецЕсли;
    КомпоновщикНастроек = Отчет.КомпоновщикНастроек;
    КомпоновщикНастроек.ЗагрузитьНастройки(Вариант);
    Настройки = КомпоновщикНастроек.Настройки;

    // Устанавливаем параметры данных
    Настройки.ПараметрыДанных.УстановитьЗначениеПараметра("НачалоПериода", ДатаНачала);
    Настройки.ПараметрыДанных.УстановитьЗначениеПараметра("КонецПериода", ДатаОкончания);
    Настройки.ПараметрыДанных.УстановитьЗначениеПараметра("СравниваемыйТовар", СравниваемыйТовар);

    // Изменяем структуру отчета на таблицу
    Настройки.Структура.Группировки.Очистить();

    // Группировка по товару (строки)
    ГруппировкаТовар = Настройки.Структура.Группировки.Добавить(Тип("ГруппировкаКомпоновкиДанных"));
    ГруппировкаТовар.Имя = "Товар";
    ГруппировкаТовар.Поле = Новый ПолеКомпоновкиДанных("Товар");
    ГруппировкаТовар.ВидГруппировки = ВидГруппировкиКомпоновкиДанных.Элементы;
    ГруппировкаТовар.Дополнение = ДополнениеПериодаКомпоновкиДанных.БезДополнения;
    ГруппировкаТовар.Роль = РольГруппировкиКомпоновкиДанных.Строка;

    // Группировка по периоду (столбцы)
    ГруппировкаПериод = Настройки.Структура.Группировки.Добавить(Тип("ГруппировкаКомпоновкиДанных"));
    ГруппировкаПериод.Имя = "Период";
    ГруппировкаПериод.Поле = Новый ПолеКомпоновкиДанных("Период");
    ГруппировкаПериод.ВидГруппировки = ВидГруппировкиКомпоновкиДанных.Элементы;
    ГруппировкаПериод.Дополнение = ДополнениеПериодаКомпоновкиДанных.БезДополнения;
    ГруппировкаПериод.Роль = РольГруппировкиКомпоновкиДанных.Колонка;

    // Настройки вывода
    Настройки.ПараметрыВывода.ВыводитьПараметрыДанных = Ложь;
    Настройки.ПараметрыВывода.ВыводитьОтбор = Ложь;
    Настройки.ПараметрыВывода.ВертикальноеРасположениеОбщихИтогов = Ложь;

    // Компоновка и вывод в табличный документ
    КомпоновщикМакета = Новый КомпоновщикМакетаКомпоновкиДанных;
    МакетКомпоновки = КомпоновщикМакета.Выполнить(Отчет.СхемаКомпоновкиДанных, Настройки, , , Тип("ГенераторМакетаКомпоновкиДанныхДляКоллекцииЗначений"));

    ПроцессорКомпоновки = Новый ПроцессорКомпоновкиДанных;
    ПроцессорКомпоновки.Инициализировать(МакетКомпоновки);

    ТабличныйДокумент = Новый ТабличныйДокумент;
    ПроцессорВывода = Новый ПроцессорВыводаРезультатаКомпоновкиДанныхВТабличныйДокумент;
    ПроцессорВывода.УстановитьДокумент(ТабличныйДокумент);
    ПроцессорВывода.Вывести(ПроцессорКомпоновки);

    Возврат ТабличныйДокумент;
КонецФункции

Функция ВыгрузитьЗадолженностьКонтрагентовВJSON()

    ТекущаяДата = ТекущаяДата();

    // Формирование запроса к виртуальной таблице остатков регистра "Взаиморасчеты"
    Запрос = Новый Запрос;
    Запрос.Текст = 
    "ВЫБРАТЬ
    |    ВзаиморасчетыОстатки.Валюта КАК Валюта,
    |    ВзаиморасчетыОстатки.Валюта.Наименование КАК ВалютаНаименование,
    |    ВзаиморасчетыОстатки.Контрагент КАК Контрагент,
    |    ВзаиморасчетыОстатки.Контрагент.Наименование КАК КонтрагентНаименование,
    |    ВзаиморасчетыОстатки.СуммаОстаток КАК Сумма
    |ИЗ
    |    РегистрНакопления.Взаиморасчеты.Остатки(&ТекущаяДата, ) КАК ВзаиморасчетыОстатки
    |ГДЕ
    |    ВзаиморасчетыОстатки.СуммаОстаток < 0
    |УПОРЯДОЧИТЬ ПО
    |    ВалютаНаименование,
    |    КонтрагентНаименование";

    Запрос.УстановитьПараметр("ТекущаяДата", ТекущаяДата);
    Результат = Запрос.Выполнить();

    Выборка = Результат.Выбрать();

    // Группировка результатов: для каждой валюты собираем массив контрагентов
    МассивВалют = Новый Массив;
    ТекущаяВалюта = Неопределено;
    МассивКонтрагентов = Неопределено;
    ТекущееНаименованиеВалюты = "";

    Пока Выборка.Следующий() Цикл
        ВалютаСсылка = Выборка.Валюта;

        Если ТекущаяВалюта = Неопределено ИЛИ ВалютаСсылка <> ТекущаяВалюта Тогда
            // Завершаем предыдущую группу
            Если ТекущаяВалюта <> Неопределено Тогда
                ЗаписьВалюты = Новый Структура;
                ЗаписьВалюты.Вставить("Валюта", ТекущееНаименованиеВалюты);
                ЗаписьВалюты.Вставить("Контрагенты", МассивКонтрагентов);
                МассивВалют.Добавить(ЗаписьВалюты);
            КонецЕсли;

            // Начинаем новую группу
            ТекущаяВалюта = ВалютаСсылка;
            ТекущееНаименованиеВалюты = Выборка.ВалютаНаименование;
            МассивКонтрагентов = Новый Массив;
        КонецЕсли;

        // Добавляем контрагента в текущий массив
        ЗаписьКонтрагента = Новый Структура;
        ЗаписьКонтрагента.Вставить("Контрагент", Выборка.КонтрагентНаименование);
        ЗаписьКонтрагента.Вставить("Сумма", Выборка.Сумма);
        МассивКонтрагентов.Добавить(ЗаписьКонтрагента);
    КонецЦикла;

    // Не забываем добавить последнюю группу
    Если ТекущаяВалюта <> Неопределено Тогда
        ЗаписьВалюты = Новый Структура;
        ЗаписьВалюты.Вставить("Валюта", ТекущееНаименованиеВалюты);
        ЗаписьВалюты.Вставить("Контрагенты", МассивКонтрагентов);
        МассивВалют.Добавить(ЗаписьВалюты);
    КонецЕсли;

    // Сохранение в файл JSON
    ИмяФайла = ПолучитьИмяВременногоФайла("json");

    ЗаписьJSON = Новый ЗаписьJSON;
    ЗаписьJSON.ОткрытьФайл(ИмяФайла);
    ЗаписьJSON.УстановитьСтрокуФорматирования(ПереводСтрокиJSON.Да);

    ЗаписьJSON.ЗаписатьНачалоМассива();

    Для Каждого ЗаписьВалюты Из МассивВалют Цикл
        ЗаписьJSON.ЗаписатьНачалоОбъекта();

        ЗаписьJSON.ЗаписатьИмяСвойства("Валюта");
        ЗаписьJSON.ЗаписатьЗначение(ЗаписьВалюты.Валюта);

        ЗаписьJSON.ЗаписатьИмяСвойства("Контрагенты");
        ЗаписьJSON.ЗаписатьНачалоМассива();

        Для Каждого ЗаписьКонтрагента Из ЗаписьВалюты.Контрагенты Цикл
            ЗаписьJSON.ЗаписатьНачалоОбъекта();

            ЗаписьJSON.ЗаписатьИмяСвойства("Контрагент");
            ЗаписьJSON.ЗаписатьЗначение(ЗаписьКонтрагента.Контрагент);

            ЗаписьJSON.ЗаписатьИмяСвойства("Сумма");
            ЗаписьJSON.ЗаписатьЗначение(ЗаписьКонтрагента.Сумма);

            ЗаписьJSON.ЗаписатьКонецОбъекта();
        КонецЦикла;

        ЗаписьJSON.ЗаписатьКонецМассива();
        ЗаписьJSON.ЗаписатьКонецОбъекта();
    КонецЦикла;

    ЗаписьJSON.ЗаписатьКонецМассива();
    ЗаписьJSON.Закрыть();

    Возврат ИмяФайла;

КонецФункции

Функция СформироватьОтчетОборачиваемости(ДатаНач = Неопределено, ДатаКон = Неопределено) Экспорт

    // Проверка и инициализация периода по умолчанию (последние 30 календарных дней)
    Если Не ЗначениеЗаполнено(ДатаНач) Или Не ЗначениеЗаполнено(ДатаКон) Тогда
        ДатаКон = ТекущаяДата();
        ДатаНач = ДатаКон - 29; // 30 дней включительно (с ДатаНач по ДатаКон)
    КонецЕсли;

    // Проверка корректности периода
    Если ДатаКон < ДатаНач Тогда
        ВызватьИсключение "Дата окончания периода не может быть меньше даты начала";
    КонецЕсли;

    // Расчет количества календарных дней в периоде (для среднедневных продаж)
    НачДата = НачалоДня(ДатаНач);
    КонДата = НачалоДня(ДатаКон);
    КоличествоДней = (КонДата - НачДата) / 86400 + 1;

    // Условно высокая величина оборачиваемости при отсутствии продаж
    УсловноВысокаяВеличина = 999999999;

    // Формирование запроса
    Запрос = Новый Запрос;
    Запрос.Текст = 
    "ВЫБРАТЬ
    |    Продажи.Товар КАК Товар,
    |    СУММА(Продажи.Количество) КАК КоличествоПродаж
    |ПОМЕСТИТЬ ВТПродажи
    |ИЗ
    |    РегистрНакопления.Продажи КАК Продажи
    |ГДЕ
    |    Продажи.Регистратор.Дата МЕЖДУ &ДатаНач И &ДатаКон
    |СГРУППИРОВАТЬ ПО
    |    Продажи.Товар
    |;
    |
    |ВЫБРАТЬ
    |    ТоварныеЗапасыОстатки.Товар КАК Товар,
    |    СУММА(ТоварныеЗапасыОстатки.КоличествоОстаток) КАК Остаток,
    |    ЕСТЬNULL(ВТПродажи.КоличествоПродаж, 0) КАК КоличествоПродаж
    |ПОМЕСТИТЬ ВТДанные
    |ИЗ
    |    РегистрНакопления.ТоварныеЗапасы.Остатки(&ДатаКон) КАК ТоварныеЗапасыОстатки
    |    ЛЕВОЕ СОЕДИНЕНИЕ ВТПродажи КАК ВТПродажи
    |    ПО ТоварныеЗапасыОстатки.Товар = ВТПродажи.Товар
    |СГРУППИРОВАТЬ ПО
    |    ТоварныеЗапасыОстатки.Товар,
    |    ВТПродажи.КоличествоПродаж
    |;
    |
    |ВЫБРАТЬ
    |    ВТДанные.Товар КАК Товар,
    |    ВТДанные.Остаток КАК Остаток,
    |    ВТДанные.КоличествоПродаж КАК КоличествоПродаж,
    |    ВТДанные.КоличествоПродаж / &КоличествоДней КАК СреднедневныеПродажи,
    |    ВЫБОР
    |        КОГДА ВТДанные.КоличествоПродаж = 0 ТОГДА &УсловноВысокаяВеличина
    |        ИНАЧЕ ВТДанные.Остаток / (ВТДанные.КоличествоПродаж / &КоличествоДней)
    |    КОНЕЦ КАК ОборачиваемостьВДнях
    |ИЗ
    |    ВТДанные КАК ВТДанные";

    Запрос.УстановитьПараметр("ДатаНач", ДатаНач);
    Запрос.УстановитьПараметр("ДатаКон", ДатаКон);
    Запрос.УстановитьПараметр("КоличествоДней", КоличествоДней);
    Запрос.УстановитьПараметр("УсловноВысокаяВеличина", УсловноВысокаяВеличина);

    // Выполнение запроса и получение таблицы значений
    Результат = Запрос.Выполнить().Выгрузить();

    // Сортировка по оборачиваемости в днях по убыванию
    Результат.Сортировать("ОборачиваемостьВДнях УБЫВ");

    Возврат Результат;

КонецФункции

Функция СформироватьОтчетДинамикаПродажТовара(ДатаНачала, ДатаОкончания, Товар)

    // Проверка входных параметров
    Если ДатаНачала = Неопределено Или ДатаОкончания = Неопределено Или Товар = Неопределено Тогда
        ВызватьИсключение "Не заданы обязательные параметры: ДатаНачала, ДатаОкончания, Товар";
    КонецЕсли;

    // Создаем объект отчета
    ОтчетОбъект = Отчеты.ДинамикаПродаж.Создать();

    // Получаем схему компоновки данных
    СхемаКомпоновкиДанных = ОтчетОбъект.СхемаКомпоновкиДанных;

    // Создаем компоновщик настроек
    КомпоновщикНастроек = Новый КомпоновщикНастроекКомпоновкиДанных;
    КомпоновщикНастроек.Инициализировать(Новый ИсточникДоступныхНастроекКомпоновкиДанных(СхемаКомпоновкиДанных));

    // Загружаем настройки варианта отчета
    ВариантНастроек = СхемаКомпоновкиДанных.ВариантыНастроек["ПродажиТоваровПоПокупателям"];
    Если ВариантНастроек = Неопределено Тогда
        ВызватьИсключение "Вариант отчета 'ПродажиТоваровПоПокупателям' не найден";
    КонецЕсли;
    КомпоновщикНастроек.ЗагрузитьНастройки(ВариантНастроек);

    // Получаем текущие настройки
    Настройки = КомпоновщикНастроек.Настройки;

    // Устанавливаем параметр периода
    Период = Новый Структура("ДатаНачала, ДатаОкончания", ДатаНачала, ДатаОкончания);
    Настройки.ПараметрыДанных.УстановитьЗначениеПараметра("Период", Период);

    // Настраиваем отбор по товару
    // Удаляем существующие отборы по полю "Товар", если есть
    МассивУдаляемых = Новый Массив;
    Для Каждого ЭлементОтбора Из Настройки.Отбор.Элементы Цикл
        Если ЭлементОтбора.ЛевоеЗначение = Новый ПолеКомпоновкиДанных("Товар") Тогда
            МассивУдаляемых.Добавить(ЭлементОтбора);
        КонецЕсли;
    КонецЦикла;
    Для Каждого Элемент Из МассивУдаляемых Цикл
        Настройки.Отбор.Элементы.Удалить(Элемент);
    КонецЦикла;

    // Добавляем новый отбор
    ЭлементОтбора = Настройки.Отбор.Элементы.Добавить(Тип("ЭлементОтбораКомпоновкиДанных"));
    ЭлементОтбора.ЛевоеЗначение = Новый ПолеКомпоновкиДанных("Товар");
    ЭлементОтбора.ВидСравнения = ВидСравненияКомпоновкиДанных.Равно;
    ЭлементОтбора.ПравоеЗначение = Товар;

    // Настройки вывода: не выводить параметры данных и отбор
    Настройки.Вывод.ПараметрыДанных.Значение = Ложь;
    Настройки.Вывод.Отбор.Значение = Ложь;

    // Компоновка макета
    КомпоновщикМакета = Новый КомпоновщикМакетаКомпоновкиДанных;
    МакетКомпоновки = КомпоновщикМакета.Выполнить(СхемаКомпоновкиДанных, Настройки, , , Тип("ГенераторМакетаКомпоновкиДанныхДляКоллекцииЗначений"));

    // Выполнение отчета
    ПроцессорКомпоновкиДанных = Новый ПроцессорКомпоновкиДанных;
    ПроцессорКомпоновкиДанных.Инициализировать(МакетКомпоновки);

    ТабличныйДокумент = Новый ТабличныйДокумент;
    ПроцессорВывода = Новый ПроцессорВыводаРезультатаКомпоновкиДанныхВТабличныйДокумент;
    ПроцессорВывода.УстановитьДокумент(ТабличныйДокумент);
    ПроцессорВывода.Вывести(ПроцессорКомпоновкиДанных);

    Возврат ТабличныйДокумент;

КонецФункции

Функция ПолучитьОстаткиПоНоменклатуреПоВсемСкладам(ТаблицаТовары)

    // Создаем менеджер временных таблиц и регистрируем в нем исходные данные
    МенеджерВременныхТаблиц = Новый МенеджерВременныхТаблиц;
    МенеджерВременныхТаблиц.Таблицы.Добавить("ВТ_ИсходныеДанные", ТаблицаТовары);

    Запрос = Новый Запрос;
    Запрос.МенеджерВременныхТаблиц = МенеджерВременныхТаблиц;
    Запрос.Текст = 
    "ВЫБРАТЬ
    |    ВТ_ИсходныеДанные.Номенклатура КАК Номенклатура,
    |    СУММА(ВТ_ИсходныеДанные.Количество) КАК Количество,
    |    СУММА(ВТ_ИсходныеДанные.Сумма) КАК Сумма
    |ИЗ
    |    ВТ_ИсходныеДанные КАК ВТ_ИсходныеДанные
    |СГРУППИРОВАТЬ ПО
    |    ВТ_ИсходныеДанные.Номенклатура
    |УПОРЯДОЧИТЬ ПО
    |    Номенклатура ВОЗР";

    Возврат Запрос.Выполнить().Выгрузить();

КонецФункции

Функция НайтиМаксимальноеЗначениеВКолонке(Таблица, Колонка)
    // Проверка на пустую таблицу – для пустой коллекции максимального значения нет
    Если Таблица.Количество() = 0 Тогда
        Возврат Неопределено;
    КонецЕсли;

    // Проверка существования колонки в коллекции
    Если Таблица.Колонки.Найти(Колонка) = Неопределено Тогда
        ВызватьИсключение "Колонка """ + Колонка + """ не найдена в таблице";
    КонецЕсли;

    // Безопасное экранирование имени колонки для запроса
    ИмяКолонкиЗапроса = """" + СтрЗаменить(Колонка, """", """""") + """";

    Запрос = Новый Запрос;
    // Менеджер временных таблиц позволит передать внешнюю коллекцию
    Запрос.МенеджерВременныхТаблиц = Новый МенеджерВременныхТаблиц;
    Запрос.УстановитьВнешнююТаблицу("ВнешняяТаблица", Таблица);

    Запрос.Текст = 
    "ВЫБРАТЬ
    |   МАКСИМУМ(Т." + ИмяКолонкиЗапроса + ") КАК МаксимальноеЗначение
    |ПОМЕСТИТЬ ВременнаяТаблица
    |ИЗ
    |   ВнешняяТаблица КАК Т";

    Запрос.Выполнить();

    Запрос2 = Новый Запрос;
    Запрос2.МенеджерВременныхТаблиц = Запрос.МенеджерВременныхТаблиц;
    Запрос2.Текст = 
    "ВЫБРАТЬ
    |   МаксимальноеЗначение
    |ИЗ
    |   ВременнаяТаблица";

    Результат = Запрос2.Выполнить().Выбрать();
    Если Результат.Следующий() Тогда
        Возврат Результат.МаксимальноеЗначение;
    Иначе
        Возврат Неопределено;
    КонецЕсли;
КонецФункции

Функция НайтиДублиТоваров(Товар) Экспорт
    // Принимает ссылку или объект справочника Товары
    Если Товар = Неопределено Тогда
        Возврат Неопределено;
    КонецЕсли;

    // Приведение к ссылке, если передан объект
    Если ТипЗнч(Товар) = Тип("СправочникОбъект.Товары") Тогда
        СсылкаТовара = Товар.Ссылка;
    ИначеЕсли ТипЗнч(Товар) = Тип("СправочникСсылка.Товары") Тогда
        СсылкаТовара = Товар;
    Иначе
        ВызватьИсключение "Параметр ""Товар"" должен быть ссылкой или объектом справочника Товары";
    КонецЕсли;

    Запрос = Новый Запрос;
    Запрос.Текст = 
    "ВЫБРАТЬ
    |   Товары.Ссылка КАК Товар,
    |   Товары.Артикул КАК Артикул
    |ИЗ
    |   Справочник.Товары КАК Товары
    |ГДЕ
    |   Товары.Артикул = &Артикул
    |   И Товары.Ссылка <> &ТекущийТовар
    |   И Товары.Артикул <> """""; // Исключаем пустой артикул

    Запрос.УстановитьПараметр("Артикул", СсылкаТовара.Артикул);
    Запрос.УстановитьПараметр("ТекущийТовар", СсылкаТовара);

    Результат = Запрос.Выполнить().Выгрузить();

    Возврат Результат;
КонецФункции

// Функция вычисляет сумму значений в указанной колонке таблицы значений.
// Параметры:
//   ТаблицаДанных - ТаблицаЗначений - исходная таблица, не изменяется.
//   ИмяКолонки   - Строка          - имя колонки, значения которой суммируются.
// Возвращаемое значение:
//   Число - итоговая сумма значений колонки.
Функция РассчитатьИтогПоКолонке(ТаблицаДанных, ИмяКолонки)

    Итог = 0;

    Для Каждого Строка Из ТаблицаДанных Цикл
        Значение = Строка[ИмяКолонки];
        Если Значение <> Null И Значение <> Неопределено Тогда
            Если ТипЗнч(Значение) = Тип("Число") Тогда
                Итог = Итог + Значение;
            Иначе
                // Пытаемся преобразовать к числу (например, если строка содержит число)
                Попытка
                    Итог = Итог + Число(Значение);
                Исключение
                    // Нечисловые значения игнорируем (можно было бы выдавать ошибку, 
                    // но по условию задачи требуется вернуть число; игнорирование — компромисс)
                КонецПопытки;
            КонецЕсли;
        КонецЕсли;
    КонецЦикла;

    Возврат Итог;

КонецФункции

Функция ПолучитьКонтрагентовПоЧастиНаименования(СтрокаПоиска)

    Запрос = Новый Запрос;
    Запрос.Текст = 
    "ВЫБРАТЬ
    |    Контрагенты.Ссылка КАК Ссылка,
    |    Контрагенты.Наименование КАК Наименование
    |ИЗ
    |    Справочник.Контрагенты КАК Контрагенты
    |ГДЕ
    |    Контрагенты.Наименование ПОДОБНО &Шаблон";

    // Формируем шаблон для оператора ПОДОБНО - ищем любое вхождение подстроки
    ШаблонПоиска = "%" + СтрокаПоиска + "%";
    Запрос.УстановитьПараметр("Шаблон", ШаблонПоиска);

    // Выполняем запрос и получаем выборку
    РезультатЗапроса = Запрос.Выполнить();
    Выборка = РезультатЗапроса.Выбрать();

    // Создаем результирующую таблицу значений
    ТаблицаРезультат = Новый ТаблицаЗначений;
    ТаблицаРезультат.Колонки.Добавить("Ссылка");
    ТаблицаРезультат.Колонки.Добавить("Наименование");

    // Заполняем таблицу данными из выборки
    Пока Выборка.Следующий() Цикл
        НоваяСтрока = ТаблицаРезультат.Добавить();
        НоваяСтрока.Ссылка = Выборка.Ссылка;
        НоваяСтрока.Наименование = Выборка.Наименование;
    КонецЦикла;

    Возврат ТаблицаРезультат;

КонецФункции

Функция ПолучитьОборотыПоПокупателю(Покупатель, ДатаНачала, ДатаОкончания)
    Запрос = Новый Запрос;
    Запрос.Текст = 
    "ВЫБРАТЬ
    |   СУММА(ПродажиОбороты.Количество) КАК КоличествоОборот,
    |   СУММА(ПродажиОбороты.Сумма) КАК СуммаОборот
    |ИЗ
    |   РегистрНакопления.Продажи.Обороты(
    |       &ДатаНачала,
    |       &ДатаОкончания,
    |       Отбор = (Покупатель = &Покупатель)) КАК ПродажиОбороты";

    Запрос.УстановитьПараметр("ДатаНачала", ДатаНачала);
    Запрос.УстановитьПараметр("ДатаОкончания", ДатаОкончания);
    Запрос.УстановитьПараметр("Покупатель", Покупатель);

    Результат = Запрос.Выполнить();
    Выборка = Результат.Выбрать();

    СтруктураОборотов = Новый Структура;
    Если Выборка.Следующий() Тогда
        СтруктураОборотов.Вставить("КоличествоОборот", Выборка.КоличествоОборот);
        СтруктураОборотов.Вставить("СуммаОборот", Выборка.СуммаОборот);
    Иначе
        СтруктураОборотов.Вставить("КоличествоОборот", 0);
        СтруктураОборотов.Вставить("СуммаОборот", 0);
    КонецЕсли;

    Возврат СтруктураОборотов;
КонецФункции

Функция НайтиМинимальноеЗначениеВКолонке(Таблица, Колонка)
    // 1. Проверка наличия колонки в таблице
    Если Таблица.Колонки.Найти(Колонка) = Неопределено Тогда
        ВызватьИсключение "Колонка """ + Колонка + """ не найдена в таблице значений";
    КонецЕсли;

    // 2. Если таблица пустая — возвращаем 0
    Если Таблица.Количество() = 0 Тогда
        Возврат 0;
    КонецЕсли;

    // 3. Перебор строк и поиск минимального значения
    МинимальноеЗначение = Неопределено;
    Для Каждого Строка Из Таблица Цикл
        Значение = Строка[Колонка];
        // Пропускаем значения Null, так как они не являются числом и не могут участвовать в сравнении
        Если Значение <> NULL Тогда
            Если МинимальноеЗначение = Неопределено Или Значение < МинимальноеЗначение Тогда
                МинимальноеЗначение = Значение;
            КонецЕсли;
        КонецЕсли;
    КонецЦикла;

    // 4. Обработка случая, когда все значения колонки оказались Null
    Если МинимальноеЗначение = Неопределено Тогда
        Возврат 0;
    Иначе
        Возврат МинимальноеЗначение;
    КонецЕсли;
КонецФункции

Функция ПолучитьСписокНоменклатурыПоГруппе(Группа)
    ТаблицаРезультат = Новый ТаблицаЗначений;
    ТаблицаРезультат.Колонки.Добавить("Ссылка");
    ТаблицаРезультат.Колонки.Добавить("Код");
    ТаблицаРезультат.Колонки.Добавить("Наименование");

    Если Группа = Неопределено Тогда
        Возврат ТаблицаРезультат;
    КонецЕсли;

    Запрос = Новый Запрос;
    Запрос.Текст = 
    "ВЫБРАТЬ
    |    Номенклатура.Ссылка КАК Ссылка,
    |    Номенклатура.Код,
    |    Номенклатура.Наименование
    |ИЗ
    |    Справочник.Номенклатура КАК Номенклатура
    |ГДЕ
    |    Номенклатура.Родитель = &Группа
    |    И Номенклатура.ЭтоГруппа = ЛОЖЬ
    |УПОРЯДОЧИТЬ ПО
    |    Наименование";

    Запрос.УстановитьПараметр("Группа", Группа);

    РезультатЗапроса = Запрос.Выполнить();

    Если РезультатЗапроса.Пустой() Тогда
        Возврат ТаблицаРезультат;
    КонецЕсли;

    ТаблицаРезультат = РезультатЗапроса.Выгрузить();

    Возврат ТаблицаРезультат;
КонецФункции

Функция НайтиЭлементПоРеквизиту(ИмяСправочника, ИмяРеквизита, ЗначениеРеквизита)
    Попытка
        Запрос = Новый Запрос;
        ТекстЗапроса = 
        "ВЫБРАТЬ
        |    Справочник.""" + ИмяСправочника + """.Ссылка КАК Ссылка
        |ИЗ
        |    Справочник.""" + ИмяСправочника + """ КАК Справочник
        |ГДЕ
        |    Справочник.""" + ИмяРеквизита + """ = &Значение";

        Запрос.Текст = ТекстЗапроса;
        Запрос.УстановитьПараметр("Значение", ЗначениеРеквизита);

        РезультатЗапроса = Запрос.Выполнить();
        Выборка = РезультатЗапроса.Выгрузить();

        Если Выборка.Количество() = 0 Тогда
            Возврат Неопределено;
        ИначеЕсли Выборка.Количество() = 1 Тогда
            Возврат Выборка[0].Ссылка;
        Иначе
            МассивСсылок = Новый Массив;
            Для Каждого Строка Из Выборка Цикл
                МассивСсылок.Добавить(Строка.Ссылка);
            КонецЦикла;
            Возврат МассивСсылок;
        КонецЕсли;
    Исключение
        Возврат Неопределено;
    КонецПопытки;
КонецФункции

Функция ПодготовитьМассивСтруктурДляИнтеграции(Таблица)
    МассивСтруктур = Новый Массив;

    Если Таблица = Неопределено Или Не ТипЗнч(Таблица) = Тип("ТаблицаЗначений") Тогда
        Возврат МассивСтруктур;
    КонецЕсли;

    Для Каждого Строка Из Таблица Цикл
        СтруктураСтроки = Новый Структура("Товар, Количество, Цена, Сумма", 
            Строка.Товар, Строка.Количество, Строка.Цена, Строка.Сумма);
        МассивСтруктур.Добавить(СтруктураСтроки);
    КонецЦикла;

    Возврат МассивСтруктур;
КонецФункции

Функция ДобавитьСтрокуВТабличнуюЧастьДокумента(ДокументОбъект, СтруктураСтроки)
    // Добавляем новую строку в табличную часть "Товары"
    НоваяСтрока = ДокументОбъект.Товары.Добавить();

    // Заполняем колонки строки из структуры
    Для каждого КлючЗначение Из СтруктураСтроки Цикл
        Ключ = КлючЗначение.Ключ;
        // Проверяем, есть ли такая колонка в табличной части
        Если НоваяСтрока.Свойство(Ключ) Тогда
            НоваяСтрока[Ключ] = КлючЗначение.Значение;
        КонецЕсли;
    КонецЦикла;

    // Возвращаем номер добавленной строки (нумерация с 1)
    Возврат НоваяСтрока.НомерСтроки + 1;
КонецФункции

Функция ПолучитьВсеЦеныТоваровНаДату(Номенклатура, Дата) Экспорт
    Запрос = Новый Запрос;
    Запрос.Текст = 
    "ВЫБРАТЬ
    |   ЦеныТоваровСрезПоследних.ВидЦен КАК ВидЦен,
    |   ЦеныТоваровСрезПоследних.Цена КАК Цена
    |ИЗ
    |   РегистрСведений.ЦеныТоваров.СрезПоследних(
    |       &Дата,
    |       Товар = &Номенклатура) КАК ЦеныТоваровСрезПоследних";

    Запрос.УстановитьПараметр("Дата", Дата);
    Запрос.УстановитьПараметр("Номенклатура", Номенклатура);

    РезультатЗапроса = Запрос.Выполнить();

    ТаблицаЦен = Новый ТаблицаЗначений;
    ТаблицаЦен.Колонки.Добавить("ВидЦен");
    ТаблицаЦен.Колонки.Добавить("Цена");

    Выборка = РезультатЗапроса.Выбрать();
    Пока Выборка.Следующий() Цикл
        Строка = ТаблицаЦен.Добавить();
        Строка.ВидЦен = Выборка.ВидЦен;
        Строка.Цена = Выборка.Цена;
    КонецЦикла;

    Возврат ТаблицаЦен;
КонецФункции

Функция СкопироватьПараметрСхемыКомпоновкиДанных(СхемаКомпоновкиДанных, Приемник, Источник, ЗначениеПриемника = Неопределено) Экспорт
    // Проверка обязательных параметров
    Если СхемаКомпоновкиДанных = Неопределено Тогда
        ВызватьИсключение "Параметр ""СхемаКомпоновкиДанных"" не определен";
    КонецЕсли;
    Если Не ЗначениеЗаполнено(Приемник) Тогда
        ВызватьИсключение "Имя параметра-приемника не может быть пустым";
    КонецЕсли;
    Если Не ЗначениеЗаполнено(Источник) Тогда
        ВызватьИсключение "Имя параметра-источника не может быть пустым";
    КонецЕсли;

    // Поиск параметра-источника
    ПараметрИсточник = СхемаКомпоновкиДанных.Параметры.Найти(Источник);
    Если ПараметрИсточник = Неопределено Тогда
        ВызватьИсключение СтрШаблон("Параметр-источник с именем ""%1"" не найден в схеме компоновки данных", Источник);
    КонецЕсли;

    // Поиск или создание параметра-приемника
    ПараметрПриемник = СхемаКомпоновкиДанных.Параметры.Найти(Приемник);
    Если ПараметрПриемник = Неопределено Тогда
        ПараметрПриемник = СхемаКомпоновкиДанных.Параметры.Добавить();
        ПараметрПриемник.Имя = Приемник;
    КонецЕсли;

    // Копирование основных свойств
    ПараметрПриемник.Заголовок                = ПараметрИсточник.Заголовок;
    ПараметрПриемник.ТипЗначения              = ПараметрИсточник.ТипЗначения;
    ПараметрПриемник.Доступен                 = ПараметрИсточник.Доступен;
    ПараметрПриемник.Использование            = ПараметрИсточник.Использование;
    ПараметрПриемник.ОграничениеИспользования = ПараметрИсточник.ОграничениеИспользования;
    ПараметрПриемник.РежимИзменения           = ПараметрИсточник.РежимИзменения;
    ПараметрПриемник.РежимРедактирования      = ПараметрИсточник.РежимРедактирования;
    ПараметрПриемник.Подсказка                = ПараметрИсточник.Подсказка;

    // Копирование формата значения
    Если ПараметрИсточник.Формат = Неопределено Тогда
        ПараметрПриемник.Формат = Неопределено;
    Иначе
        ПараметрПриемник.Формат = Новый ФорматЗначения;
        ЗаполнитьЗначенияСвойств(ПараметрПриемник.Формат, ПараметрИсточник.Формат);
    КонецЕсли;

    // Копирование параметров выбора
    ПараметрПриемник.ПараметрыВыбора.Очистить();
    Для каждого ЭлементВыбора Из ПараметрИсточник.ПараметрыВыбора Цикл
        НовыйЭлемент = ПараметрПриемник.ПараметрыВыбора.Добавить();
        НовыйЭлемент.Значение      = ЭлементВыбора.Значение;
        НовыйЭлемент.Представление = ЭлементВыбора.Представление;
        НовыйЭлемент.Пометка       = ЭлементВыбора.Пометка;
        НовыйЭлемент.Идентификатор = ЭлементВыбора.Идентификатор;
    КонецЦикла;

    // Копирование связей параметров выбора
    ПараметрПриемник.СвязиПараметровВыбора.Очистить();
    Для каждого Связь Из ПараметрИсточник.СвязиПараметровВыбора Цикл
        НоваяСвязь = ПараметрПриемник.СвязиПараметровВыбора.Добавить();
        НоваяСвязь.ПараметрВыбора    = Связь.ПараметрВыбора;
        НоваяСвязь.ЗависимыйПараметр = Связь.ЗависимыйПараметр;
        НоваяСвязь.ВыражениеСвязи    = Связь.ВыражениеСвязи;
    КонецЦикла;

    // Установка значения приемника (только если оно передано)
    Если ЗначениеПриемника <> Неопределено Тогда
        ПараметрПриемник.Значение = ЗначениеПриемника;
    КонецЕсли;

    Возврат ПараметрПриемник;
КонецФункции

// Функция разбирает строку параметров в структуру.
// Параметры:
//   СтрокаПараметров - строка вида "Имя1=Значение1;Имя2=Значение2", где значения могут быть заключены в кавычки,
//                      внутри которых удвоенные кавычки экранируются.
//   Разделитель      - строка-разделитель между параметрами.
// Возвращаемое значение:
//   Структура - ключи: имена параметров, значения: строковые значения.
Функция ПараметрыИзСтроки(СтрокаПараметров, Разделитель)
    Результат = Новый Структура;

    Если ПустаяСтрока(СтрокаПараметров) Тогда
        Возврат Результат;
    КонецЕсли;

    ДлинаСтроки = СтрДлина(СтрокаПараметров);
    ДлинаРазделителя = СтрДлина(Разделитель);
    Позиция = 1;

    Пока Позиция <= ДлинаСтроки Цикл
        ТекущийФрагмент = "";
        ВКавычках = Ложь;

        // Собираем очередной фрагмент до разделителя (вне кавычек) или до конца строки
        Пока Позиция <= ДлинаСтроки Цикл
            Символ = Сред(СтрокаПараметров, Позиция, 1);

            Если ВКавычках Тогда
                Если Символ = """" Тогда
                    // Проверяем, не удвоенная ли кавычка
                    Если Позиция < ДлинаСтроки И Сред(СтрокаПараметров, Позиция + 1, 1) = """" Тогда
                        // Экранированная кавычка внутри значения
                        ТекущийФрагмент = ТекущийФрагмент + """";
                        Позиция = Позиция + 2;
                        Продолжить;
                    Иначе
                        // Закрывающая кавычка значения
                        ВКавычках = Ложь;
                        Позиция = Позиция + 1;
                        Прервать; // Завершаем сбор фрагмента
                    КонецЕсли;
                Иначе
                    ТекущийФрагмент = ТекущийФрагмент + Символ;
                    Позиция = Позиция + 1;
                КонецЕсли;
            Иначе
                Если Символ = """" Тогда
                    // Открывающая кавычка значения
                    ВКавычках = Истина;
                    Позиция = Позиция + 1;
                ИначеЕсли Сред(СтрокаПараметров, Позиция, ДлинаРазделителя) = Разделитель Тогда
                    // Встретили разделитель вне кавычек
                    Прервать;
                Иначе
                    ТекущийФрагмент = ТекущийФрагмент + Символ;
                    Позиция = Позиция + 1;
                КонецЕсли;
            КонецЕсли;
        КонецЦикла;

        // Обрабатываем собранный фрагмент
        Если Не ПустаяСтрока(ТекущийФрагмент) Тогда
            ПозицияРавно = Найти(ТекущийФрагмент, "=");
            Если ПозицияРавно > 0 Тогда
                ИмяПараметра = СокрЛП(Лев(ТекущийФрагмент, ПозицияРавно - 1));
                ЗначениеПараметра = СокрЛП(Сред(ТекущийФрагмент, ПозицияРавно + 1));
                Результат.Вставить(ИмяПараметра, ЗначениеПараметра);
            КонецЕсли;
        КонецЕсли;

        // Пропускаем разделитель, если мы остановились на нём
        Если Позиция <= ДлинаСтроки И Сред(СтрокаПараметров, Позиция, ДлинаРазделителя) = Разделитель Тогда
            Позиция = Позиция + ДлинаРазделителя;
        КонецЕсли;
    КонецЦикла;

    Возврат Результат;
КонецФункции

Функция ПроверитьПроведенностьДокументов(мДокументы)
    // Массив для хранения непроведенных документов
    МассивНепроведенных = Новый Массив;

    // Если передан пустой массив, сразу возвращаем пустой результат
    Если мДокументы.Количество() = 0 Тогда
        Возврат МассивНепроведенных;
    КонецЕсли;

    // Построение запроса к общей таблице Документ
    Запрос = Новый Запрос;
    Запрос.Текст = 
    "ВЫБРАТЬ
    |    Документ.Ссылка КАК Ссылка
    |ИЗ
    |    Документ КАК Документ
    |ГДЕ
    |    Документ.Ссылка В (&СписокСсылок)
    |    И Документ.Проведен = ЛОЖЬ";

    // Передача входного массива в параметр запроса
    Запрос.УстановитьПараметр("СписокСсылок", мДокументы);

    // Выполнение запроса и выгрузка результата в массив
    РезультатЗапроса = Запрос.Выполнить();
    Выборка = РезультатЗапроса.Выбрать();

    Пока Выборка.Следующий() Цикл
        МассивНепроведенных.Добавить(Выборка.Ссылка);
    КонецЦикла;

    Возврат МассивНепроведенных;
КонецФункции

Функция ПровестиДокументы(мДокументы)
    МассивОшибок = Новый Массив;

    Для Каждого Ссылка Из мДокументы Цикл
        Попытка
            ДокОбъект = Ссылка.ПолучитьОбъект();
            ДокОбъект.Записать(РежимЗаписиДокумента.Проведение);
        Исключение
            Ошибка = Новый Структура;
            Ошибка.Вставить("Ссылка", Ссылка);
            Ошибка.Вставить("ОписаниеОшибки", ОписаниеОшибки());
            МассивОшибок.Добавить(Ошибка);
        КонецПопытки;
    КонецЦикла;

    Возврат МассивОшибок;
КонецФункции

Функция НайтиПараметрыВНайстройкахКД(ПользовательскиеНастройкиКД, НастройкиКД, ИменаПараметров)
    // Возвращает структуру, где ключ — имя параметра, значение — значение параметра.
    // Если параметр не найден ни в одной из коллекций, значение будет Неопределено.

    Результат = Новый Структура;

    Если ПустаяСтрока(ИменаПараметров) Тогда
        Возврат Результат;
    КонецЕсли;

    МассивИмен = СтрРазделить(ИменаПараметров, ",");

    Для Каждого ИмяПараметра Из МассивИмен Цикл
        Имя = СокрЛП(ИмяПараметра);
        Если ПустаяСтрока(Имя) Тогда
            Продолжить;
        КонецЕсли;

        ЗначениеПараметра = Неопределено;
        ПараметрНайден = Ложь;

        // Первая итерация: поиск в пользовательских настройках
        Если ПользовательскиеНастройкиКД <> Неопределено Тогда
            Для Каждого Элемент Из ПользовательскиеНастройкиКД.Элементы Цикл
                Если Элемент.ТипЭлемента = ТипЭлементаПользовательскихНастроекКомпоновкиДанных.ПараметрДанных 
                   И Элемент.ИдентификаторПользовательскойНастройки = Имя Тогда
                    ЗначениеПараметра = Элемент.Значение;
                    ПараметрНайден = Истина;
                    Прервать;
                КонецЕсли;
            КонецЦикла;
        КонецЕсли;

        // Вторая итерация: поиск в настройках варианта отчета
        Если Не ПараметрНайден И НастройкиКД <> Неопределено Тогда
            Для Каждого Параметр Из НастройкиКД.ПараметрыДанных Цикл
                Если Параметр.Имя = Имя Тогда
                    ЗначениеПараметра = Параметр.Значение;
                    ПараметрНайден = Истина;
                    Прервать;
                КонецЕсли;
            КонецЦикла;
        КонецЕсли;

        // Добавляем результат в структуру (даже если Неопределено)
        Результат.Вставить(Имя, ЗначениеПараметра);
    КонецЦикла;

    Если Результат.Количество() = 0 Тогда
        Возврат Неопределено;
    КонецЕсли;

    Возврат Результат;
КонецФункции

Функция ДобавитьГруппировкуВКореньСтруктуры(КомпоновщикНастроек, Знач Поле = Неопределено, ПараметрыГруппировки = Неопределено) Экспорт
    // Определяем настройки компоновки данных
    Если ТипЗнч(КомпоновщикНастроек) = Тип("КомпоновщикНастроекКомпоновкиДанных") Тогда
        Настройки = КомпоновщикНастроек.Настройки;
    ИначеЕсли ТипЗнч(КомпоновщикНастроек) = Тип("НастройкиКомпоновкиДанных") Тогда
        Настройки = КомпоновщикНастроек;
    Иначе
        ВызватьИсключение "Неверный тип параметра КомпоновщикНастроек. Ожидается КомпоновщикНастроекКомпоновкиДанных или НастройкиКомпоновкиДанных";
    КонецЕсли;

    // Добавляем новую группировку в корень структуры
    НоваяГруппировка = Настройки.Структура.Добавить(Тип("ГруппировкаКомпоновкиДанных"));

    // Устанавливаем поле группировки, если оно передано
    Если Поле <> Неопределено Тогда
        Если ТипЗнч(Поле) = Тип("Строка") Тогда
            ПолеКомпоновки = Новый ПолеКомпоновкиДанных(Поле);
        ИначеЕсли ТипЗнч(Поле) = Тип("ПолеКомпоновкиДанных") Тогда
            ПолеКомпоновки = Поле;
        Иначе
            ВызватьИсключение "Неверный тип параметра Поле. Ожидается Строка или ПолеКомпоновкиДанных";
        КонецЕсли;
        НоваяГруппировка.Поле = ПолеКомпоновки;
    КонецЕсли;

    // Применяем дополнительные параметры группировки
    Если ПараметрыГруппировки <> Неопределено Тогда
        Если ПараметрыГруппировки.Свойство("НачалоПериода") И ПараметрыГруппировки.НачалоПериода <> Неопределено Тогда
            НоваяГруппировка.НачалоПериода = ПараметрыГруппировки.НачалоПериода;
        КонецЕсли;
        Если ПараметрыГруппировки.Свойство("КонецПериода") И ПараметрыГруппировки.КонецПериода <> Неопределено Тогда
            НоваяГруппировка.КонецПериода = ПараметрыГруппировки.КонецПериода;
        КонецЕсли;
        Если ПараметрыГруппировки.Свойство("ТипГруппировки") И ПараметрыГруппировки.ТипГруппировки <> Неопределено Тогда
            НоваяГруппировка.ТипГруппировки = ПараметрыГруппировки.ТипГруппировки;
        КонецЕсли;
        Если ПараметрыГруппировки.Свойство("ТипДополнения") И ПараметрыГруппировки.ТипДополнения <> Неопределено Тогда
            НоваяГруппировка.ТипДополнения = ПараметрыГруппировки.ТипДополнения;
        КонецЕсли;
    КонецЕсли;

    Возврат НоваяГруппировка;
КонецФункции

// Функция устанавливает ограничения использования поля в схеме компоновки данных.
// Параметры:
//   СхемаКД       - СхемаКомпоновкиДанных - схема, в которой выполняется поиск поля.
//   Поле          - Строка или ПолеКомпоновкиДанных - идентификатор поля (путь к данным).
//   Ограничения   - Структура - ключи: "Поле", "Условие", "Группа", "Упорядочивание".
//                     Каждый ключ должен содержать Булево - разрешение/запрет.
//
Функция УстановитьОграниченияИспользованияПоля(СхемаКД, Поле, Ограничения) Экспорт

    // Определяем строку идентификации поля (путь к данным)
    Если ТипЗнч(Поле) = Тип("Строка") Тогда
        ИмяПоля = Поле;
    ИначеЕсли ТипЗнч(Поле) = Тип("ПолеКомпоновкиДанных") Тогда
        ИмяПоля = Поле.Поле;
    Иначе
        ВызватьИсключение "Параметр 'Поле' должен быть строкой или объектом ПолеКомпоновкиДанных";
    КонецЕсли;

    // Проходим по всем наборам данных схемы
    Для Каждого НаборДанных Из СхемаКД.НаборыДанных Цикл
        // Внутри каждого набора ищем поле с заданным путём
        Для Каждого ПолеКД Из НаборДанных.Поля Цикл
            Если ПолеКД.Поле = ИмяПоля Тогда
                // Устанавливаем ограничения согласно переданной структуре
                Если Ограничения.Свойство("Поле") Тогда
                    ПолеКД.ДоступноДляВыбора = Ограничения.Поле;
                КонецЕсли;

                Если Ограничения.Свойство("Условие") Тогда
                    ПолеКД.ДоступноДляУсловия = Ограничения.Условие;
                КонецЕсли;

                Если Ограничения.Свойство("Группа") Тогда
                    ПолеКД.ДоступноДляГруппировки = Ограничения.Группа;
                КонецЕсли;

                Если Ограничения.Свойство("Упорядочивание") Тогда
                    ПолеКД.ДоступноДляУпорядочивания = Ограничения.Упорядочивание;
                КонецЕсли;
            КонецЕсли;
        КонецЦикла;
    КонецЦикла;

КонецФункции

// Устанавливает роль поля набора данных в схеме компоновки данных.
//
// Параметры:
//   СхемаКД      - СхемаКомпоновкиДанных - схема отчета, в которой выполняется поиск поля.
//   Поле         - Строка, ПолеКомпоновкиДанных - имя поля (или объект поля), для которого настраивается роль.
//   СвойстваРоль - Структура - описание роли в виде набора свойств (см. входящий тип).
//
// Возвращаемое значение:
//   Неопределено - функция изменяет переданную схему, не возвращая результата.
//
Функция УстановитьРольПоляНабораДанныхСКД(СхемаКД, Поле, СвойстваРоль) Экспорт

    // Получаем строковое имя поля
    Если ТипЗнч(Поле) = Тип("ПолеКомпоновкиДанных") Тогда
        ИмяПоля = Поле.Поле;
    ИначеЕсли ТипЗнч(Поле) = Тип("Строка") Тогда
        ИмяПоля = СокрЛП(Поле);
    Иначе
        ВызватьИсключение "Параметр Поле должен быть типа Строка или ПолеКомпоновкиДанных";
    КонецЕсли;

    // Перебор всех наборов данных схемы
    Для Каждого НаборДанных Из СхемаКД.НаборыДанных Цикл
        // Поиск поля в коллекции полей текущего набора данных
        Для Каждого ПолеНабора Из НаборДанных.Поля Цикл
            Если ПолеНабора.Поле = ИмяПоля Тогда
                // Создаём новый экземпляр роли
                НоваяРоль = Новый РольПоляНабораДанныхСхемыКомпоновкиДанных();

                // Если указан флаг "БезРоли" со значением Истина, оставляем все свойства по умолчанию (очищены)
                Если НЕ (СвойстваРоль.Свойство("БезРоли") И СвойстваРоль.БезРоли) Тогда
                    ЗаполнитьСвойстваРолиИзСтруктуры(НоваяРоль, СвойстваРоль);
                КонецЕсли;

                // Применяем роль к полю набора данных
                ПолеНабора.Роль = НоваяРоль;
            КонецЕсли;
        КонецЦикла;
    КонецЦикла;

    Возврат Неопределено;

КонецФункции

// Заполняет свойства объекта роли значениями из структуры.
// Устанавливаются только те свойства, ключи которых присутствуют в структуре.
//
// Параметры:
//   Роль     - РольПоляНабораДанныхСхемыКомпоновкиДанных - целевой объект.
//   Свойства - Структура - источник значений.
//
Процедура ЗаполнитьСвойстваРолиИзСтруктуры(Роль, Свойства) Экспорт

    Если Свойства.Свойство("ВыражениеВидаСчета") Тогда
        Роль.ВыражениеВидаСчета = Свойства.ВыражениеВидаСчета;
    КонецЕсли;
    Если Свойства.Свойство("ГруппаОстатка") Тогда
        Роль.ГруппаОстатка = Свойства.ГруппаОстатка;
    КонецЕсли;
    Если Свойства.Свойство("НомерПериода") Тогда
        Роль.НомерПериода = Свойства.НомерПериода;
    КонецЕсли;
    Если Свойства.Свойство("ИгнорироватьЗначенияNULL") Тогда
        Роль.ИгнорироватьЗначенияNULL = Свойства.ИгнорироватьЗначенияNULL;
    КонецЕсли;
    Если Свойства.Свойство("Измерение") Тогда
        Роль.Измерение = Свойства.Измерение;
    КонецЕсли;
    Если Свойства.Свойство("Обязательное") Тогда
        Роль.Обязательное = Свойства.Обязательное;
    КонецЕсли;
    Если Свойства.Свойство("Остаток") Тогда
        Роль.Остаток = Свойства.Остаток;
    КонецЕсли;
    Если Свойства.Свойство("ПолеСчета") Тогда
        Роль.ПолеСчета = Свойства.ПолеСчета;
    КонецЕсли;
    Если Свойства.Свойство("РеквизитИзмерения") Тогда
        Роль.РеквизитИзмерения = Свойства.РеквизитИзмерения;
    КонецЕсли;
    Если Свойства.Свойство("РодительскоеИзмерение") Тогда
        Роль.РодительскоеИзмерение = Свойства.РодительскоеИзмерение;
    КонецЕсли;
    Если Свойства.Свойство("Счет") Тогда
        Роль.Счет = Свойства.Счет;
    КонецЕсли;
    Если Свойства.Свойство("ТипБухгалтерскогоОстатка") Тогда
        Роль.ТипБухгалтерскогоОстатка = Свойства.ТипБухгалтерскогоОстатка;
    КонецЕсли;
    Если Свойства.Свойство("ТипОстатка") Тогда
        Роль.ТипОстатка = Свойства.ТипОстатка;
    КонецЕсли;
    Если Свойства.Свойство("ТипПериода") Тогда
        Роль.ТипПериода = Свойства.ТипПериода;
    КонецЕсли;

КонецПроцедуры

Функция СформироватьОтчетПрайсЛистТолькоЦены(ВидЦен)

    // Создаем результирующий табличный документ
    ТабличныйДокумент = Новый ТабличныйДокумент;

    // Получаем схему компоновки данных отчета "ПрайсЛист"
    СхемаКомпоновки = Отчеты.ПрайсЛист.ПолучитьСхемуКомпоновкиДанных();
    Если СхемаКомпоновки = Неопределено Тогда
        Возврат ТабличныйДокумент;
    КонецЕсли;

    // Ищем настройки варианта "Основной"
    НастройкиОтчета = Неопределено;
    Для Каждого Вариант Из СхемаКомпоновки.ВариантыНастроек Цикл
        Если Вариант.Имя = "Основной" Тогда
            НастройкиОтчета = Вариант.Настройки;
            Прервать;
        КонецЕсли;
    КонецЦикла;

    Если НастройкиОтчета = Неопределено Тогда
        НастройкиОтчета = СхемаКомпоновки.НастройкиПоУмолчанию;
    КонецЕсли;

    // Создаем компоновщик настроек и загружаем в него исходные настройки
    КомпоновщикНастроек = Новый КомпоновщикНастроекКомпоновкиДанных;
    КомпоновщикНастроек.Инициализировать(Новый ИсточникДоступныхНастроекКомпоновкиДанных(СхемаКомпоновки));
    КомпоновщикНастроек.ЗагрузитьНастройки(НастройкиОтчета);

    // Полностью переопределяем структуру отчета
    Структура = КомпоновщикНастроек.Настройки.Структура;
    Структура.Элементы.Очистить();

    // Добавляем единственную группировку – детальные записи
    ГруппировкаДетальные = Структура.Элементы.Добавить(Тип("ГруппировкаКомпоновкиДанных"));
    ГруппировкаДетальные.Использование = Истина;
    ГруппировкаДетальные.ТипГруппировки = ТипГруппировкиКомпоновкиДанных.ДетальныеЗаписи;

    // Настраиваем выбранные поля: Товар, Артикул, Цена
    ВыбранныеПоля = ГруппировкаДетальные.ВыбранныеПоля.Элементы;
    ВыбранныеПоля.Очистить();

    ПолеТовар = ВыбранныеПоля.Добавить(Тип("ВыбранноеПолеКомпоновкиДанных"));
    ПолеТовар.Заголовок = "Товар";
    ПолеТовар.Поле = Новый ПолеКомпоновкиДанных("Товар");

    ПолеАртикул = ВыбранныеПоля.Добавить(Тип("ВыбранноеПолеКомпоновкиДанных"));
    ПолеАртикул.Заголовок = "Артикул";
    ПолеАртикул.Поле = Новый ПолеКомпоновкиДанных("Товар.Артикул");

    ПолеЦена = ВыбранныеПоля.Добавить(Тип("ВыбранноеПолеКомпоновкиДанных"));
    ПолеЦена.Заголовок = "Цена";
    ПолеЦена.Поле = Новый ПолеКомпоновкиДанных("Цена");

    // Устанавливаем параметр "ВидЦен"
    ПараметрыДанных = КомпоновщикНастроек.Настройки.ПараметрыДанных;
    ПараметрВидЦен = ПараметрыДанных.Элементы.Найти("ВидЦен");
    Если ПараметрВидЦен = Неопределено Тогда
        ПараметрВидЦен = ПараметрыДанных.Элементы.Добавить(Тип("ПараметрДанныхКомпоновкиДанных"));
        ПараметрВидЦен.Параметр = Новый ПараметрКомпоновкиДанных("ВидЦен");
    КонецЕсли;
    ПараметрВидЦен.Использование = Истина;
    ПараметрВидЦен.Значение = ВидЦен;

    // Настраиваем параметры вывода: не показывать параметры данных и отборы
    КомпоновщикНастроек.Настройки.ПараметрыВывода.ВыводитьПараметрыДанных = РежимВыводаПараметровДанныхКомпоновкиДанных.НеВыводить;
    КомпоновщикНастроек.Настройки.ПараметрыВывода.ВыводитьОтбор = РежимВыводаПараметровДанныхКомпоновкиДанных.НеВыводить;

    // Компонуем макет по измененным настройкам
    КомпоновщикМакета = Новый КомпоновщикМакетаКомпоновкиДанных;
    Макеты = КомпоновщикМакета.Выполнить(СхемаКомпоновки, КомпоновщикНастроек.Настройки);
    Если Макеты.Количество() = 0 Тогда
        Возврат ТабличныйДокумент;
    КонецЕсли;

    // Выводим результат в табличный документ
    ПроцессорВывода = Новый ПроцессорВыводаРезультатаКомпоновкиДанныхВТабличныйДокумент;
    ПроцессорВывода.УстановитьДокумент(ТабличныйДокумент);
    ПроцессорВывода.Вывести(Макеты[0]);

    Возврат ТабличныйДокумент;

КонецФункции

Функция УстановитьОформлениеОстатка(СхемаКД, ТипОстатка, ДопПараметры)

    // 1. Определяем имя поля по типу остатка
    Если ТипОстатка = "Количество" Тогда
        ИмяПоля = "КоличествоОстаток";
    ИначеЕсли ТипОстатка = "Сумма" Тогда
        ИмяПоля = "СуммаОстаток";
    Иначе
        ВызватьИсключение "Некорректный тип остатка: """ + ТипОстатка + """";
    КонецЕсли;

    // 2. Получаем настройки по умолчанию, при необходимости создаем
    Если СхемаКД.НастройкиПоУмолчанию = Неопределено Тогда
        СхемаКД.НастройкиПоУмолчанию = Новый НастройкиКомпоновкиДанных;
    КонецЕсли;

    Настройки = СхемаКД.НастройкиПоУмолчанию;

    // 3. Ищем существующее оформление для поля или создаем новое
    ЭлементОформления = Неопределено;
    Для Каждого Оформление Из Настройки.ОформлениеПолей Цикл
        Если Оформление.Поле = ИмяПоля Тогда
            ЭлементОформления = Оформление;
            Прервать;
        КонецЕсли;
    КонецЦикла;

    Если ЭлементОформления = Неопределено Тогда
        // Создаем новый элемент оформления
        ЭлементОформления = Настройки.ОформлениеПолей.Добавить(
            Тип("ОформлениеПоляНастроекКомпоновкиДанных"));
        ЭлементОформления.Поле = ИмяПоля;
    КонецЕсли;

    // 4. Устанавливаем обязательные параметры оформления
    ЭлементОформления.ВыделятьОтрицательные = Истина;
    ЭлементОформления.Формат = "ЧЦ=10; ЧДЦ=2; ЧН=0; ЧО=1";
    ЭлементОформления.ГоризонтальноеПоложение = ГоризонтальноеПоложение.Право;

    // 5. Устанавливаем дополнительные параметры, если они переданы
    Если ДопПараметры <> Неопределено Тогда
        Для Каждого ДопПараметр Из ДопПараметры Цикл
            Если ТипЗнч(ДопПараметр) = Тип("Структура") Тогда
                ПараметрИмя = ДопПараметр.Ключ;
                ПараметрЗначение = ДопПараметр.Значение;

                // Устанавливаем свойство элемента оформления по имени
                Попытка
                    // Используем прямое присваивание для типовых свойств
                    Если ПараметрИмя = "ВыделятьОтрицательные" Тогда
                        ЭлементОформления.ВыделятьОтрицательные = ПараметрЗначение;
                    ИначеЕсли ПараметрИмя = "Формат" Тогда
                        ЭлементОформления.Формат = ПараметрЗначение;
                    ИначеЕсли ПараметрИмя = "ГоризонтальноеПоложение" Тогда
                        ЭлементОформления.ГоризонтальноеПоложение = ПараметрЗначение;
                    Иначе
                        // Остальные свойства устанавливаем через универсальный механизм
                        ЭлементОформления[ПараметрИмя] = ПараметрЗначение;
                    КонецЕсли;
                Исключение
                    // Если свойство отсутствует, игнорируем или логируем
                КонецПопытки;
            КонецЕсли;
        КонецЦикла;
    КонецЕсли;

    Возврат Истина; // или можно вернуть ЭлементОформления

КонецФункции

Функция ДобавитьНаборДанныхИзТаблицыЗначений(СхемаКД, ИмяИсточникДанных, Таблица, ИмяНабора = "")

    // Если имя набора не задано, используем значение по умолчанию
    Если ПустаяСтрока(ИмяНабора) Тогда
        ИмяНабора = "НаборДанныхИзТаблицы";
    КонецЕсли;

    // Поиск источника данных, при отсутствии - создание
    Источник = СхемаКД.ИсточникиДанных.Найти(ИмяИсточникДанных);
    Если Источник = Неопределено Тогда
        Источник = СхемаКД.ИсточникиДанных.Добавить(Тип("ИсточникДанныхСхемыКомпоновкиДанных"));
        Источник.Имя = ИмяИсточникДанных;
        Источник.СтрокаСоединения = "";
        Источник.ТипИсточникаДанных = "Local";
    КонецЕсли;

    // Добавление нового набора данных в источник
    НовыйНабор = Источник.НаборыДанных.Добавить(Тип("НаборДанныхОбъектСхемыКомпоновкиДанных"));
    НовыйНабор.Имя = ИмяНабора;

    // Заполнение полей набора данных на основе колонок таблицы значений
    Для Каждого Колонка Из Таблица.Колонки Цикл
        Поле = НовыйНабор.Поля.Добавить(Тип("ПолеКомпоновкиДанных"));
        Поле.Поле = Колонка.Имя;
        Поле.Заголовок = Колонка.Имя;
        Поле.ТипЗначения = Новый ОписаниеТипов(Колонка.ТипЗначения);
        Поле.ПутьКДанным = Колонка.Имя;
    КонецЦикла;

    Возврат НовыйНабор;

КонецФункции

Функция СформироватьОтчетПоПроведеннымОплатамСВалютой()

    // Создаем схему компоновки данных
    СхемаКомпоновкиДанных = Новый СхемаКомпоновкиДанных;

    // Добавляем источник данных – запрос к документам Оплата
    ИсточникДанных = СхемаКомпоновкиДанных.ИсточникиДанных.Добавить();
    ИсточникДанных.Имя = "ИсточникДанных1";
    ИсточникДанных.ТипИсточникаДанных = "Local";

    Запрос = Новый Запрос;
    Запрос.Текст = 
    "ВЫБРАТЬ
    |    Оплата.Дата КАК Дата,
    |    Оплата.Номер КАК Номер,
    |    Оплата.Поставщик КАК Поставщик,
    |    Оплата.РасчетныйСчетПоставщика КАК РасчетныйСчетПоставщика,
    |    Оплата.Валюта КАК Валюта,
    |    Оплата.Сумма КАК Сумма,
    |    Оплата.Проведен КАК Проведен,
    |    Оплата.ПометкаУдаления КАК ПометкаУдаления
    |ИЗ
    |    Документ.Оплата КАК Оплата";

    ИсточникДанных.Запрос = Запрос;

    // Получаем настройки компоновки по умолчанию
    Настройки = СхемаКомпоновкиДанных.НастройкиПоУмолчанию;

    // Создаем структуру отчета – детальные записи
    ГруппировкаДетальные = Настройки.Структура.Добавить(Тип("ГруппировкаКомпоновкиДанных"));
    ГруппировкаДетальные.Использование = Истина;

    // Задаем выбранные поля в нужном порядке (Валюта перед Суммой)
    ВыбранныеПоля = ГруппировкаДетальные.Выбор.Элементы;
    ВыбранныеПоля.Добавить(Тип("ПолеКомпоновкиДанных")).Поле = Новый ПолеКомпоновкиДанных("Дата");
    ВыбранныеПоля.Добавить(Тип("ПолеКомпоновкиДанных")).Поле = Новый ПолеКомпоновкиДанных("Номер");
    ВыбранныеПоля.Добавить(Тип("ПолеКомпоновкиДанных")).Поле = Новый ПолеКомпоновкиДанных("Поставщик");
    ВыбранныеПоля.Добавить(Тип("ПолеКомпоновкиДанных")).Поле = Новый ПолеКомпоновкиДанных("РасчетныйСчетПоставщика");
    ВыбранныеПоля.Добавить(Тип("ПолеКомпоновкиДанных")).Поле = Новый ПолеКомпоновкиДанных("Валюта");
    ВыбранныеПоля.Добавить(Тип("ПолеКомпоновкиДанных")).Поле = Новый ПолеКомпоновкиДанных("Сумма");

    // Настраиваем отборы: только проведенные и не помеченные на удаление
    Отбор = ГруппировкаДетальные.Отбор;

    ЭлементОтбора = Отбор.Элементы.Добавить(Тип("ЭлементОтбораКомпоновкиДанных"));
    ЭлементОтбора.ЛевоеЗначение = Новый ПолеКомпоновкиДанных("Проведен");
    ЭлементОтбора.ВидСравнения = ВидСравненияКомпоновкиДанных.Равно;
    ЭлементОтбора.ПравоеЗначение = Истина;
    ЭлементОтбора.Использование = Истина;

    ЭлементОтбора2 = Отбор.Элементы.Добавить(Тип("ЭлементОтбораКомпоновкиДанных"));
    ЭлементОтбора2.ЛевоеЗначение = Новый ПолеКомпоновкиДанных("ПометкаУдаления");
    ЭлементОтбора2.ВидСравнения = ВидСравненияКомпоновкиДанных.Равно;
    ЭлементОтбора2.ПравоеЗначение = Ложь;
    ЭлементОтбора2.Использование = Истина;

    // Параметры вывода: не показывать параметры данных и отборы
    Настройки.ПараметрыВывода.ВыводитьПараметрыДанных = Ложь;
    Настройки.ПараметрыВывода.ВыводитьОтбор = Ложь;

    // Компоновка макета
    КомпоновщикМакета = Новый КомпоновщикМакетаКомпоновкиДанных;
    МакетКомпоновки = КомпоновщикМакета.Выполнить(СхемаКомпоновкиДанных, Настройки);

    // Процессор компоновки данных
    ПроцессорКомпоновкиДанных = Новый ПроцессорКомпоновкиДанных;
    ПроцессорКомпоновкиДанных.Инициализировать(МакетКомпоновки);

    // Вывод результата в табличный документ
    ТабличныйДокумент = Новый ТабличныйДокумент;
    ПроцессорВывода = Новый ПроцессорВыводаРезультатаКомпоновкиДанныхВТабличныйДокумент;
    ПроцессорВывода.УстановитьДокумент(ТабличныйДокумент);
    ПроцессорВывода.Вывести(ПроцессорКомпоновкиДанных);

    Возврат ТабличныйДокумент;

КонецФункции

Функция СохранитьНастройкиСКДВФайлXML(КомпоновщикНастроек, Путь) Экспорт
    // Проверяем, задан ли путь (не передан или пустая строка)
    Если Путь = Неопределено Или Путь = "" Тогда
        // Создаем временный файл с расширением xml
        Путь = ПолучитьИмяВременногоФайла("xml");
    Иначе
        // Формируем полное имя файла, добавляя "config.xml" к указанному пути
        Путь = ОбъединитьПути(Путь, "config.xml");
    КонецЕсли;

    // Создаем объект записи XML и открываем файл
    ЗаписьXML = Новый ЗаписьXML;
    ЗаписьXML.ОткрытьФайл(Путь);

    // Сохраняем настройки компоновщика в XML
    КомпоновщикНастроек.Настройки.ЗаписатьXML(ЗаписьXML);

    // Закрываем файл
    ЗаписьXML.Закрыть();

    // Возвращаем итоговый путь (может быть полезно вызывающему коду)
    Возврат Путь;
КонецФункции

Функция ВыгрузитьПросроченныеЗаказыВФайлJSON(Знач ДатаКонтроля = Неопределено) Экспорт

    // Если параметр не задан, устанавливаем текущую дату
    Если ДатаКонтроля = Неопределено Тогда
        ДатаКонтроля = ТекущаяДата();
    КонецЕсли;

    Запрос = Новый Запрос;
    Запрос.Текст = 
    "ВЫБРАТЬ
    |    Заказ.Номер КАК НомерЗаказа,
    |    Заказ.Дата КАК ДатаЗаказа,
    |    ПРЕДСТАВЛЕНИЕ(Заказ.Покупатель) КАК Покупатель,
    |    Заказ.Сумма КАК Сумма,
    |    ВЫБОР
    |        КОГДА Контрагенты.ЭлектроннаяПочта ЕСТЬ NULL
    |        ТОГДА """"
    |        ИНАЧЕ Контрагенты.ЭлектроннаяПочта
    |    КОНЕЦ КАК ЭлектроннаяПочта,
    |    ПРЕДСТАВЛЕНИЕ(Заказ.СостояниеЗаказа) КАК СостояниеЗаказа,
    |    РАЗНОСТЬДАТ(НАЧАЛОПЕРИОДА(Заказ.Дата, ДЕНЬ), НАЧАЛОПЕРИОДА(&ДатаКонтроля, ДЕНЬ), ДЕНЬ) КАК ПросроченоДней
    |ИЗ
    |    Документ.Заказ КАК Заказ
    |        ЛЕВОЕ СОЕДИНЕНИЕ Справочник.Контрагенты КАК Контрагенты
    |        ПО Заказ.Покупатель = Контрагенты.Ссылка
    |ГДЕ
    |    Заказ.Проведен = ИСТИНА
    |    И Заказ.СостояниеЗаказа = ЗНАЧЕНИЕ(Перечисление.СостоянияЗаказов.Открыт)
    |    И РАЗНОСТЬДАТ(НАЧАЛОПЕРИОДА(Заказ.Дата, ДЕНЬ), НАЧАЛОПЕРИОДА(&ДатаКонтроля, ДЕНЬ), ДЕНЬ) > 0";

    Запрос.УстановитьПараметр("ДатаКонтроля", ДатаКонтроля);

    Результат = Запрос.Выполнить();

    МассивЗаказов = Новый Массив;
    Выборка = Результат.Выбрать();

    Пока Выборка.Следующий() Цикл
        ОбъектJSON = Новый Структура;
        ОбъектJSON.Вставить("НомерЗаказа",      Выборка.НомерЗаказа);
        ОбъектJSON.Вставить("ДатаЗаказа",       Формат(Выборка.ДатаЗаказа, "ДФ=yyyy-MM-dd"));
        ОбъектJSON.Вставить("Покупатель",       Выборка.Покупатель);
        ОбъектJSON.Вставить("Сумма",            Выборка.Сумма);
        ОбъектJSON.Вставить("ЭлектроннаяПочта", Выборка.ЭлектроннаяПочта);
        ОбъектJSON.Вставить("СостояниеЗаказа",  Выборка.СостояниеЗаказа);
        ОбъектJSON.Вставить("ПросроченоДней",   Выборка.ПросроченоДней);
        МассивЗаказов.Добавить(ОбъектJSON);
    КонецЦикла;

    // Формирование имени файла с уникальным суффиксом
    ИмяФайла = КаталогВременныхФайлов() + "ПросроченныеЗаказы_" 
             + Формат(ТекущаяДатаСеанса(), "ДФ=yyyyMMdd_HHmmss") + ".json";

    ЗаписьJSON = Новый ЗаписьJSON;
    ЗаписьJSON.ОткрытьФайл(ИмяФайла, "UTF-8", ПереносСтрокJSON.Авто, Символы.Таб);
    ЗаписьJSON.ЗаписатьМассив(МассивЗаказов);
    ЗаписьJSON.Закрыть();

    Возврат ИмяФайла;

КонецФункции

Функция СформироватьОтчетПоОплатамПоОрганизациям() Экспорт
    // Создаем объект отчета
    ОтчетОбъект = Отчеты.ДокументыОплата.Создать();

    // Получаем основную схему компоновки данных
    СхемаКомпоновкиДанных = ОтчетОбъект.ПолучитьМакет("ОсновнаяСхемаКомпоновкиДанных");

    // Инициализируем компоновщик настроек и загружаем настройки варианта "Основной"
    КомпоновщикНастроек = Новый КомпоновщикНастроекКомпоновкиДанных;
    КомпоновщикНастроек.Инициализировать(Новый ИсточникДоступныхНастроекКомпоновкиДанных(СхемаКомпоновкиДанных));

    // Загружаем настройки варианта "Основной"
    Для Каждого Вариант Из СхемаКомпоновкиДанных.ВариантыНастроек Цикл
        Если Вариант.Имя = "Основной" Тогда
            КомпоновщикНастроек.ЗагрузитьНастройки(Вариант.Настройки);
            Прервать;
        КонецЕсли;
    КонецЦикла;

    Настройки = КомпоновщикНастроек.Настройки;

    // Очищаем существующую структуру и выбранные поля
    Настройки.Структура.Элементы.Очистить();
    Настройки.Выбор.Элементы.Очистить();

    // Создаем группировку по организации с иерархией
    ГруппировкаОрганизация = Настройки.Структура.Добавить(Тип("ГруппировкаКомпоновкиДанных"));
    ГруппировкаОрганизация.Использование = Истина;
    ГруппировкаОрганизация.Имя = "Организация";
    ГруппировкаОрганизация.Заголовок = "Организация";

    ПолеГруппировки = ГруппировкаОрганизация.ПоляГруппировки.Элементы.Добавить(Тип("ПолеГруппировкиКомпоновкиДанных"));
    ПолеГруппировки.Поле = Новый ПолеКомпоновкиДанных("Ссылка.Организация");
    ПолеГруппировки.ТипГруппировки = ТипГруппировкиКомпоновкиДанных.Иерархия;
    ПолеГруппировки.ТипДополнения = ТипДополненияПериодаКомпоновкиДанных.БезДополнения;

    // Добавляем детальные записи внутрь группировки
    ДетальныеЗаписи = ГруппировкаОрганизация.Выбор.Элементы.Добавить(Тип("ВыборКомпоновкиДанных"));
    ДетальныеЗаписи.Использование = Истина;

    // Добавляем выбранные поля
    МассивПолей = Новый Массив;
    МассивПолей.Добавить("Ссылка.Организация");
    МассивПолей.Добавить("Поставщик");
    МассивПолей.Добавить("Дата");
    МассивПолей.Добавить("Сумма");

    Для Каждого ИмяПоля Из МассивПолей Цикл
        ВыбранноеПоле = Настройки.Выбор.Элементы.Добавить(Тип("ВыбранноеПолеКомпоновкиДанных"));
        ВыбранноеПоле.Поле = Новый ПолеКомпоновкиДанных(ИмяПоля);
        ВыбранноеПоле.Использование = Истина;
    КонецЦикла;

    // Устанавливаем заголовок для поля "Ссылка.Организация"
    Для Каждого Элемент Из Настройки.Выбор.Элементы Цикл
        Если Элемент.Поле.ПутьКДанным = "Ссылка.Организация" Тогда
            Элемент.Заголовок = "Организация";
            Прервать;
        КонецЕсли;
    КонецЦикла;

    // Параметры вывода
    Настройки.ПараметрыВывода.ВыводитьПараметрыДанных = Ложь;
    Настройки.ПараметрыВывода.ВыводитьОтбор = Ложь;

    // Компоновка макета
    КомпоновщикМакета = Новый КомпоновщикМакетаКомпоновкиДанных;
    МакетКомпоновки = КомпоновщикМакета.Выполнить(СхемаКомпоновкиДанных, Настройки, , , Тип("ГенераторМакетаКомпоновкиДанныхДляКоллекцииЗначений"));

    // Процессор компоновки
    ПроцессорКомпоновкиДанных = Новый ПроцессорКомпоновкиДанных;
    ПроцессорКомпоновкиДанных.Инициализировать(МакетКомпоновки);

    // Процессор вывода в табличный документ
    ПроцессорВывода = Новый ПроцессорВыводаРезультатаКомпоновкиДанныхВТабличныйДокумент;
    ПроцессорВывода.УстановитьДокумент(Новый ТабличныйДокумент);
    ПроцессорВывода.Вывести(ПроцессорКомпоновкиДанных);

    Возврат ПроцессорВывода.Документ;
КонецФункции

