Функция СформироватьОтчетПоОплатамЗаПериод(ДатаНачала, ДатаОкончания)
    // Создаем объект отчета
    ОтчетОбъект = Отчеты.ДокументыОплата.Создать();

    // Получаем основную схему компоновки данных
    СхемаКД = ОтчетОбъект.ПолучитьМакет("ОсновнаяСхемаКомпоновкиДанных");

    // Загружаем настройки варианта "Основной"
    Настройки = Неопределено;
    Для Каждого Вариант Из СхемаКД.ВариантыНастроек Цикл
        Если Вариант.Имя = "Основной" Тогда
            Настройки = Вариант.Настройки;
            Прервать;
        КонецЕсли;
    КонецЦикла;
    Если Настройки = Неопределено Тогда
        Настройки = СхемаКД.НастройкиПоУмолчанию;
    КонецЕсли;

    // Очищаем и задаем нужные поля: Поставщик, Дата, Сумма
    ВыбранныеПоля = Настройки.Выбор.Элементы;
    ВыбранныеПоля.Очистить();

    Поле = ВыбранныеПоля.Добавить(Тип("ВыбранноеПолеКомпоновкиДанных"));
    Поле.Поле = Новый ПолеКомпоновкиДанных("Поставщик");

    Поле = ВыбранныеПоля.Добавить(Тип("ВыбранноеПолеКомпоновкиДанных"));
    Поле.Поле = Новый ПолеКомпоновкиДанных("Дата");

    Поле = ВыбранныеПоля.Добавить(Тип("ВыбранноеПолеКомпоновкиДанных"));
    Поле.Поле = Новый ПолеКомпоновкиДанных("Сумма");

    // Настройка отбора: Дата >= ДатаНачала И Дата <= ДатаОкончания
    Отбор = Настройки.Отбор;
    Отбор.Элементы.Очистить();

    ЭлементОтбора = Отбор.Элементы.Добавить(Тип("ЭлементОтбораКомпоновкиДанных"));
    ЭлементОтбора.ЛевоеЗначение = Новый ПолеКомпоновкиДанных("Дата");
    ЭлементОтбора.ВидСравнения = ВидСравненияКомпоновкиДанных.БольшеИлиРавно;
    ЭлементОтбора.ПравоеЗначение = ДатаНачала;

    ЭлементОтбора = Отбор.Элементы.Добавить(Тип("ЭлементОтбораКомпоновкиДанных"));
    ЭлементОтбора.ЛевоеЗначение = Новый ПолеКомпоновкиДанных("Дата");
    ЭлементОтбора.ВидСравнения = ВидСравненияКомпоновкиДанных.МеньшеИлиРавно;
    ЭлементОтбора.ПравоеЗначение = ДатаОкончания;

    // Параметры вывода: не выводить параметры данных и отбор
    Настройки.ПараметрыВывода.ВыводитьПараметрыДанных = Ложь;
    Настройки.ПараметрыВывода.ВыводитьОтбор = Ложь;

    // Формируем отчет и возвращаем табличный документ
    ТабличныйДокумент = Новый ТабличныйДокумент;
    ОтчетОбъект.СкомпоноватьРезультат(ТабличныйДокумент, Неопределено, Истина, Настройки);

    Возврат ТабличныйДокумент;
КонецФункции

Функция СформироватьТоп10ПродаваемыхТоваров(ДатаНач = Неопределено, ДатаКон = Неопределено) Экспорт
    // Обработка дат начала и окончания периода
    Если ДатаНач = Неопределено Тогда
        ДатаНач = НачалоДня(ТекущаяДата()) - 30 * 86400; // 30 дней назад от текущей даты
    Иначе
        ДатаНач = НачалоДня(ДатаНач);
    КонецЕсли;

    Если ДатаКон = Неопределено Тогда
        ДатаКон = КонецДня(ТекущаяДата());
    Иначе
        ДатаКон = КонецДня(ДатаКон);
    КонецЕсли;

    // Проверка корректности периода
    Если ДатаКон < ДатаНач Тогда
        ВызватьИсключение "Дата окончания периода не может быть меньше даты начала";
    КонецЕсли;

    // Построение запроса с получением первых 10 записей по количеству продаж
    Запрос = Новый Запрос;
    Запрос.Текст = 
    "ВЫБРАТЬ ПЕРВЫЕ 10
    |    ПродажиОбороты.Товар КАК Товар,
    |    СУММА(ПродажиОбороты.Количество) КАК КоличествоПродаж,
    |    СУММА(ПродажиОбороты.Сумма) КАК СуммаПродаж
    |ИЗ
    |    РегистрНакопления.Продажи.Обороты(&НачПериода, &КонПериода, ) КАК ПродажиОбороты
    |ГДЕ
    |    ПродажиОбороты.Товар <> ЗНАЧЕНИЕ(Справочник.Товары.ПустаяСсылка)
    |СГРУППИРОВАТЬ ПО
    |    ПродажиОбороты.Товар
    |УПОРЯДОЧИТЬ ПО
    |    КоличествоПродаж УБЫВ";

    Запрос.УстановитьПараметр("НачПериода", ДатаНач);
    Запрос.УстановитьПараметр("КонПериода", ДатаКон);

    // Выполнение запроса
    РезультатЗапроса = Запрос.Выполнить();

    // Формирование таблицы значений для результата
    ТЗ = Новый ТаблицаЗначений;
    ТЗ.Колонки.Добавить("Товар", Новый ОписаниеТипов("СправочникСсылка.Товары"));
    ТЗ.Колонки.Добавить("КоличествоПродаж", Новый ОписаниеТипов("Число", Новый КвалификаторыЧисла(10, 2)));
    ТЗ.Колонки.Добавить("СуммаПродаж", Новый ОписаниеТипов("Число", Новый КвалификаторыЧисла(10, 2)));

    // Заполнение результата (не более 10 строк уже гарантировано запросом)
    Выборка = РезультатЗапроса.Выбрать();
    Пока Выборка.Следующий() Цикл
        НоваяСтрока = ТЗ.Добавить();
        НоваяСтрока.Товар = Выборка.Товар;
        НоваяСтрока.КоличествоПродаж = Выборка.КоличествоПродаж;
        НоваяСтрока.СуммаПродаж = Выборка.СуммаПродаж;
    КонецЦикла;

    Возврат ТЗ;
КонецФункции

Функция СформироватьОтчетЖелаемыйУровеньПродаж(ДатаНачала, ДатаОкончания, УровеньПродаж) Экспорт

    // Получаем схему компоновки данных отчета "ДинамикаПродаж"
    Схема = Отчеты.ДинамикаПродаж.СхемаКомпоновкиДанных;

    // Создаем настройки на основе варианта "СуммаИКоличество"
    Настройки = Новый НастройкиКомпоновкиДанных;
    Настройки.Загрузить(Схема.ВариантыНастроек.СуммаИКоличество.Настройки);

    // Очищаем текущую структуру (диаграмму и прочее)
    Настройки.Структура.Очистить();

    // Добавляем группировку по полю "Период"
    Группировка = Настройки.Структура.Добавить(Тип("ГруппировкаКомпоновкиДанных"));
    Группировка.Использование = Истина;
    Группировка.Поле = Новый ПолеКомпоновкиДанных("Период");
    Группировка.ТипГруппировки = ТипГруппировкиКомпоновкиДанных.Элементы;
    Группировка.ТипДополнения = ТипДополненияПериодаКомпоновкиДанных.БезДополнения;

    // Устанавливаем параметры периода
    ЗначениеПериода = Новый СтандартныйПериод;
    ЗначениеПериода.ДатаНачала = ДатаНачала;
    ЗначениеПериода.ДатаОкончания = ДатаОкончания;
    Настройки.ПараметрыДанных.УстановитьЗначениеПараметра("Период", ЗначениеПериода);

    // Настройки вывода
    Настройки.ПараметрыВывода.ВыводитьПараметрыДанных = Ложь;
    Настройки.ПараметрыВывода.ВыводитьОтбор = Ложь;

    // Очищаем существующее условное оформление
    Настройки.УсловноеОформление.Элементы.Очистить();

    // Добавляем новый элемент условного оформления
    ЭлементУО = Настройки.УсловноеОформление.Элементы.Добавить();
    ЭлементУО.Использование = Истина;
    ЭлементУО.Оформление.УстановитьЗначениеПараметра("ЦветТекста", Новый Цвет(0, 150, 70));
    ЭлементУО.Отбор.Добавить(Новый ЭлементОтбораКомпоновкиДанных("СуммаОборот", ВидСравненияКомпоновкиДанных.БольшеИлиРавно, УровеньПродаж));
    ЭлементУО.ОформляемыеПоля.Добавить(Новый ПолеКомпоновкиДанных("Период"));
    ЭлементУО.ИспользоватьВЗаголовкеПолей = Ложь;

    // Компонуем макет и выводим в табличный документ
    КомпоновщикМакета = Новый КомпоновщикМакетаКомпоновкиДанных;
    МакетКомпоновки = КомпоновщикМакета.Выполнить(Схема, Настройки);

    ПроцессорКомпоновки = Новый ПроцессорКомпоновкиДанных;
    ПроцессорКомпоновки.Инициализировать(МакетКомпоновки);

    ТабДок = Новый ТабличныйДокумент;
    ПроцессорВывода = Новый ПроцессорВыводаРезультатаКомпоновкиДанныхВТабличныйДокумент;
    ПроцессорВывода.УстановитьДокумент(ТабДок);
    ПроцессорВывода.Вывести(ПроцессорКомпоновки);

    Возврат ТабДок;

КонецФункции

Функция СформироватьОтчетПродажиСуммированиеТолькоТоваров(ДатаНачала, ДатаОкончания)

    ТабличныйДокумент = Новый ТабличныйДокумент;

    Попытка
        // Получаем отчет
        ОтчетОбъект = Отчеты.ДинамикаПродаж;

        // Получаем макет основной схемы компоновки данных
        МакетСКД = ОтчетОбъект.ПолучитьМакет("ОсновнаяСхемаКомпоновкиДанных");
        Если МакетСКД = Неопределено Тогда
            ВызватьИсключение "Основная схема компоновки данных не найдена в отчете ДинамикаПродаж";
        КонецЕсли;

        Схема = Новый СхемаКомпоновкиДанных;
        Схема.Загрузить(МакетСКД);

        // Ищем вариант отчета
        ВариантОтчета = Неопределено;
        Для Каждого Вариант Из Схема.ВариантыНастроек Цикл
            Если Вариант.Имя = "ПродажиТоваровПоПокупателям" Тогда
                ВариантОтчета = Вариант;
                Прервать;
            КонецЕсли;
        КонецЦикла;

        Если ВариантОтчета = Неопределено Тогда
            ВызватьИсключение "Вариант отчета 'ПродажиТоваровПоПокупателям' не найден";
        КонецЕсли;

        // Создаем компоновщик настроек и загружаем настройки варианта
        КомпоновщикНастроек = Новый КомпоновщикНастроекКомпоновкиДанных;
        КомпоновщикНастроек.Инициализировать(Новый ИсточникДоступныхНастроекКомпоновкиДанных(Схема));
        КомпоновщикНастроек.ЗагрузитьНастройки(ВариантОтчета.Настройки);

        Настройки = КомпоновщикНастроек.Настройки;

        // Очищаем структуру отчета
        Настройки.Структура.Строки.Очистить();

        // Добавляем группировку "Покупатель"
        ГруппировкаПокупатель = Настройки.Структура.Строки.Добавить(Новый ГруппировкаКомпоновкиДанных);
        ГруппировкаПокупатель.ТипГруппировки = ТипГруппировкиКомпоновкиДанных.Элементы;
        ГруппировкаПокупатель.ИмяПоля = "Покупатель";
        ГруппировкаПокупатель.ТипДополнения = ТипДополненияЭлементаНастроекКомпоновкиДанных.БезДополнения;

        // Добавляем вложенную группировку "Товар"
        ГруппировкаТовар = ГруппировкаПокупатель.Строки.Добавить(Новый ГруппировкаКомпоновкиДанных);
        ГруппировкаТовар.ТипГруппировки = ТипГруппировкиКомпоновкиДанных.Элементы;
        ГруппировкаТовар.ИмяПоля = "Товар";
        ГруппировкаТовар.ТипДополнения = ТипДополненияЭлементаНастроекКомпоновкиДанных.БезДополнения;

        // Очищаем ранее установленные поля итога
        Настройки.ПоляИтога.Элементы.Очистить();

        // Первое поле итога: сумма только услуг по покупателю
        ПолеИтогаПокупатель = Настройки.ПоляИтога.Элементы.Добавить(Новый ВыбранноеПолеКомпоновкиДанных);
        ПолеИтогаПокупатель.Поле = Новый ПолеКомпоновкиДанных("СуммаОборот");
        ПолеИтогаПокупатель.Выражение = 
            "СУММА(ВычислитьВыражениеСГруппировкойМассив(""СУММА(СуммаОборот)"", ""Товар"", ""Товар.Вид = ЗНАЧЕНИЕ(Перечисление.ВидыТоваров.Услуга)""))";
        ПолеИтогаПокупатель.РасположениеПоля.Место = РасположениеПоляКомпоновкиДанных.Подвал;
        ПолеИтогаПокупатель.РасположениеПоля.ГруппировкаПоля = "Покупатель";

        // Первое поле итога: сумма только услуг по общему итогу
        ПолеИтогаОбщий = Настройки.ПоляИтога.Элементы.Добавить(Новый ВыбранноеПолеКомпоновкиДанных);
        ПолеИтогаОбщий.Поле = Новый ПолеКомпоновкиДанных("СуммаОборот");
        ПолеИтогаОбщий.Выражение = ПолеИтогаПокупатель.Выражение;
        ПолеИтогаОбщий.РасположениеПоля.Место = РасположениеПоляКомпоновкиДанных.Подвал;
        ПолеИтогаОбщий.РасположениеПоля.ГруппировкаПоля = "ОбщийИтог";

        // Второе поле итога: сумма по товару
        ПолеИтогаТовар = Настройки.ПоляИтога.Элементы.Добавить(Новый ВыбранноеПолеКомпоновкиДанных);
        ПолеИтогаТовар.Поле = Новый ПолеКомпоновкиДанных("СуммаОборот");
        ПолеИтогаТовар.Выражение = "СУММА(СуммаОборот)";
        ПолеИтогаТовар.РасположениеПоля.Место = РасположениеПоляКомпоновкиДанных.Подвал;
        ПолеИтогаТовар.РасположениеПоля.ГруппировкаПоля = "Товар";

        // Установка параметра "Период"
        ПараметрПериод = Настройки.ПараметрыДанных.Элементы.Найти("Период");
        Если ПараметрПериод = Неопределено Тогда
            ПараметрПериод = Настройки.ПараметрыДанных.Элементы.Добавить(Новый ПараметрДанныхКомпоновкиДанных);
            ПараметрПериод.Параметр = Новый ПараметрКомпоновкиДанных("Период");
        КонецЕсли;
        ПараметрПериод.Значение = Новый Структура("ДатаНачала, ДатаОкончания", ДатаНачала, ДатаОкончания);
        ПараметрПериод.Использование = Истина;

        // Настройка параметров вывода
        Настройки.ПараметрыВывода.ВыводитьПараметрыДанных = Ложь;
        Настройки.ПараметрыВывода.ВыводитьОтбор = Ложь;

        // Компоновка и вывод результата
        КомпоновщикМакета = Новый КомпоновщикМакетаКомпоновкиДанных;
        Макет = КомпоновщикМакета.Выполнить(Схема, Настройки, Новый ДанныеРасшифровкиКомпоновкиДанных);

        ПроцессорВывода = Новый ПроцессорВыводаРезультатаКомпоновкиДанныхВТабличныйДокумент;
        ПроцессорВывода.УстановитьДокумент(ТабличныйДокумент);
        ПроцессорВывода.Вывести(Макет);

    Исключение
        ТабличныйДокумент.Очистить();
        Сообщение = Новый СообщениеПользователю;
        Сообщение.Текст = "Ошибка формирования отчета: " + ОписаниеОшибки();
        Сообщение.Сообщить();
    КонецПопытки;

    Возврат ТабличныйДокумент;
КонецФункции

&НаСервере
Функция СформироватьОтчетПродажиТовараНаДень(ДатаНачала, ДатаОкончания)

    // Получаем объект отчета из метаданных
    Отчет = Отчеты.ДинамикаПродаж.Создать();

    // Извлекаем основную схему компоновки данных отчета
    СхемаКомпоновки = Отчет.ПолучитьМакет("ОсновнаяСхемаКомпоновкиДанных");

    // Инициализируем компоновщик настроек
    КомпоновщикНастроек = Новый КомпоновщикНастроекКомпоновкиДанных;
    КомпоновщикНастроек.Инициализировать(Новый ИсточникДоступныхНастроекКомпоновкиДанных(СхемаКомпоновки));

    // Загружаем настройки варианта отчета "СуммаИКоличество"
    ВариантНастройки = КомпоновщикНастроек.Настройки.ВариантыНастроек.Найти("СуммаИКоличество");
    Если ВариантНастройки = Неопределено Тогда
        ВызватьИсключение "Вариант отчета ""СуммаИКоличество"" не найден";
    КонецЕсли;
    КомпоновщикНастроек.ЗагрузитьНастройки(ВариантНастройки.Настройки);

    // Получаем корневую структуру настроек
    Настройки = КомпоновщикНастроек.Настройки;
    Структура = Настройки.Структура;

    // Вспомогательная функция для поиска группировки по имени в коллекции элементов
    Функция НайтиГруппировкуПоИмени(Имя, Коллекция)
        Для Каждого Элемент Из Коллекция Цикл
            Если ТипЗнч(Элемент) = Тип("ГруппировкаКомпоновкиДанных") 
               И Элемент.Имя = Имя Тогда
                Возврат Элемент;
            КонецЕсли;
        КонецЦикла;
        Возврат Неопределено;
    КонецФункции;

    // Ищем группировку "Период" на верхнем уровне
    ПериодГруппировка = НайтиГруппировкуПоИмени("Период", Структура);
    Если ПериодГруппировка = Неопределено Тогда
        ВызватьИсключение "Группировка ""Период"" не найдена в структуре отчета";
    КонецЕсли;

    // Устанавливаем для периода тип "Элементы" и дополнение "БезДополнения"
    ПериодГруппировка.ТипГруппировки = ТипГруппировкиКомпоновкиДанных.Элементы;
    Попытка
        ПериодГруппировка.Дополнение = ДополнениеПериодаКомпоновкиДанных.БезДополнения;
    Исключение
        // Если свойство "Дополнение" недоступно для данной группировки, игнорируем
    КонецПопытки;

    // Ищем группировку "Товар" – сначала внутри "Периода", затем на верхнем уровне
    ТоварГруппировка = НайтиГруппировкуПоИмени("Товар", ПериодГруппировка.Структура);
    Если ТоварГруппировка = Неопределено Тогда
        ТоварГруппировка = НайтиГруппировкуПоИмени("Товар", Структура);
    КонецЕсли;
    Если ТоварГруппировка = Неопределено Тогда
        ВызватьИсключение "Группировка ""Товар"" не найдена в структуре отчета";
    КонецЕсли;

    ТоварГруппировка.ТипГруппировки = ТипГруппировкиКомпоновкиДанных.Элементы;
    Попытка
        ТоварГруппировка.Дополнение = ДополнениеПериодаКомпоновкиДанных.БезДополнения;
    Исключение
        // Если свойство недоступно, пропускаем
    КонецПопытки;

    // Устанавливаем параметр периода
    ПараметрПериод = Настройки.ПараметрыДанных.НайтиЗначениеПараметра(
        Новый ПараметрКомпоновкиДанных("Период"));
    Если ПараметрПериод = Неопределено Тогда
        ВызватьИсключение "Параметр ""Период"" не найден в настройках отчета";
    КонецЕсли;

    ЗначениеПериода = Новый СтандартныйПериод;
    ЗначениеПериода.ДатаНачала = ДатаНачала;
    ЗначениеПериода.ДатаОкончания = ДатаОкончания;
    ПараметрПериод.Значение = ЗначениеПериода;
    ПараметрПериод.Использование = Истина;

    // Настройка вывода параметров данных и отбора
    Настройки.ПараметрыВывода.ВыводитьПараметрыДанных = ТипВыводаТекстаКомпоновкиДанных.НеВыводить;
    Настройки.ПараметрыВывода.ВыводитьОтбор = ТипВыводаТекстаКомпоновкиДанных.НеВыводить;

    // Компоновка макета и выполнение отчета
    КомпоновщикМакета = Новый КомпоновщикМакетаКомпоновкиДанных;
    МакетКомпоновки = КомпоновщикМакета.Выполнить(СхемаКомпоновки, Настройки,
        , , Тип("ГенераторМакетаКомпоновкиДанныхДляКоллекцииЗначений"));

    ПроцессорКомпоновки = Новый ПроцессорКомпоновкиДанных;
    ПроцессорКомпоновки.Инициализировать(МакетКомпоновки);

    // Формируем выходной табличный документ
    ТабличныйДокумент = Новый ТабличныйДокумент;
    ПроцессорВывода = Новый ПроцессорВыводаРезультатаКомпоновкиДанныхВТабличныйДокумент;
    ПроцессорВывода.УстановитьДокумент(ТабличныйДокумент);
    ПроцессорВывода.Вывести(ПроцессорКомпоновки);

    Возврат ТабличныйДокумент;

КонецФункции

// Функция должна выполняться на сервере (например, в серверном общем модуле)
Функция СформироватьОтчетВзаиморасчетыПодсветитьРасход(ДатаНачала, ДатаОкончания) Экспорт

    // Получаем схему компоновки данных отчета
    СхемаКомпоновкиДанных = Отчеты.ОтчетПоВзаиморасчетам.ПолучитьМакет("ОсновнаяСхемаКомпоновкиДанных");

    // Находим вариант отчета "Основной"
    Вариант = СхемаКомпоновкиДанных.ВариантыНастроек.Найти("Основной");
    Если Вариант = Неопределено Тогда
        ВызватьИсключение "Вариант отчета 'Основной' не найден";
    КонецЕсли;

    // Получаем настройки варианта
    Настройки = Вариант.Настройки;

    // Очищаем выбранные поля и добавляем нужные
    Настройки.Выбор.Элементы.Очистить();

    ПолеПриход = Настройки.Выбор.Элементы.Добавить(Тип("ВыбранноеПолеКомпоновкиДанных"));
    ПолеПриход.Поле = Новый ПолеКомпоновкиДанных("СуммаПриход");

    ПолеРасход = Настройки.Выбор.Элементы.Добавить(Тип("ВыбранноеПолеКомпоновкиДанных"));
    ПолеРасход.Поле = Новый ПолеКомпоновкиДанных("СуммаРасход");

    // Устанавливаем параметр периода
    ПараметрПериод = Настройки.ПараметрыДанных.Элементы.Найти("Период");
    Если ПараметрПериод = Неопределено Тогда
        // Если параметр отсутствует, добавляем его
        ПараметрПериод = Настройки.ПараметрыДанных.Элементы.Добавить(Тип("ПараметрДанныхКомпоновкиДанных"));
        ПараметрПериод.Параметр = Новый ПараметрКомпоновкиДанных("Период");
    КонецЕсли;

    // Значение периода передаем как структуру
    ПараметрПериод.Значение = Новый Структура("ДатаНачала, ДатаОкончания", ДатаНачала, ДатаОкончания);

    // Настройки вывода
    Настройки.ПараметрыВывода.ВыводитьПараметрыДанных = Ложь;
    Настройки.ПараметрыВывода.ВыводитьОтбор = Ложь;

    // Очищаем существующее условное оформление и создаем новое
    Настройки.УсловноеОформление.Элементы.Очистить();

    ЭлементОформления = Настройки.УсловноеОформление.Элементы.Добавить();

    // Устанавливаем цвет фона
    ЭлементОформления.Оформление.УстановитьЗначениеПараметра("ЦветФона", Новый Цвет(0, 150, 30));

    // Отбор: СуммаРасход > СуммаПриход
    Отбор = ЭлементОформления.Отбор.Элементы.Добавить(Тип("ЭлементОтбораКомпоновкиДанных"));
    Отбор.ЛевоеЗначение = Новый ПолеКомпоновкиДанных("СуммаРасход");
    Отбор.ВидСравнения = ВидСравненияКомпоновкиДанных.Больше;
    Отбор.ПравоеЗначение = Новый ПолеКомпоновкиДанных("СуммаПриход");

    // Запрещаем использование в заголовке полей ресурсов и общем итоге
    ЭлементОформления.ИспользоватьВЗаголовкеПолейРесурсов = Ложь;
    ЭлементОформления.ИспользоватьВОбщемИтоге = Ложь;

    // Указываем поля, к которым применяется оформление
    ПолеОформленияПриход = ЭлементОформления.Поля.Элементы.Добавить(Тип("ПолеКомпоновкиДанных"));
    ПолеОформленияПриход.Поле = Новый ПолеКомпоновкиДанных("СуммаПриход");

    ПолеОформленияРасход = ЭлементОформления.Поля.Элементы.Добавить(Тип("ПолеКомпоновкиДанных"));
    ПолеОформленияРасход.Поле = Новый ПолеКомпоновкиДанных("СуммаРасход");

    // Компонуем макет
    КомпоновщикМакета = Новый КомпоновщикМакетаКомпоновкиДанных;
    МакетКомпоновки = КомпоновщикМакета.Выполнить(СхемаКомпоновкиДанных, Настройки);

    // Выполняем компоновку данных и выводим в табличный документ
    ПроцессорКомпоновки = Новый ПроцессорКомпоновкиДанных;
    ПроцессорКомпоновки.Инициализировать(МакетКомпоновки);

    ТабличныйДокумент = Новый ТабличныйДокумент;
    ПроцессорВывода = Новый ПроцессорВыводаРезультатаКомпоновкиДанныхВТабличныйДокумент;
    ПроцессорВывода.УстановитьДокумент(ТабличныйДокумент);
    ПроцессорВывода.Вывести(ПроцессорКомпоновки);

    Возврат ТабличныйДокумент;

КонецФункции

Функция СформироватьОтчетВзаиморасчетыБезКопеек(ДатаНачала, ДатаОкончания)

    // Получаем схему компоновки данных отчета
    СхемаКомпоновкиДанных = Отчеты.ОтчетПоВзаиморасчетам.ПолучитьМакет("ОсновнаяСхемаКомпоновкиДанных");

    // Инициализируем компоновщик настроек и загружаем настройки варианта "Основной"
    ИсточникДоступныхНастроек = Новый ИсточникДоступныхНастроекКомпоновкиДанных(СхемаКомпоновкиДанных);
    КомпоновщикНастроек = Новый КомпоновщикНастроекКомпоновкиДанных;
    КомпоновщикНастроек.Инициализировать(ИсточникДоступныхНастроек);
    КомпоновщикНастроек.ЗагрузитьНастройки(СхемаКомпоновкиДанных.ВариантыНастроек.Найти("Основной").Настройки);

    Настройки = КомпоновщикНастроек.Настройки;

    // Устанавливаем параметр периода
    Период = Новый СтандартныйПериод;
    Период.ДатаНачала = ДатаНачала;
    Период.ДатаОкончания = ДатаОкончания;
    Настройки.ПараметрыДанных.УстановитьЗначениеПараметра("Период", Период);

    // Настраиваем выбранные поля: оставляем только СуммаПриход и СуммаРасход
    Настройки.Выбор.Элементы.Очистить();

    ПолеСуммаПриход = Новый ПолеКомпоновкиДанных("СуммаПриход");
    ЭлементВыбораПриход = Настройки.Выбор.Элементы.Добавить(Тип("ЭлементВыбораКомпоновкиДанныхПоле"));
    ЭлементВыбораПриход.Поле = ПолеСуммаПриход;

    ПолеСуммаРасход = Новый ПолеКомпоновкиДанных("СуммаРасход");
    ЭлементВыбораРасход = Настройки.Выбор.Элементы.Добавить(Тип("ЭлементВыбораКомпоновкиДанныхПоле"));
    ЭлементВыбораРасход.Поле = ПолеСуммаРасход;

    // Параметры вывода
    Настройки.ПараметрыВывода.ВыводитьПараметрыДанных = Ложь;
    Настройки.ПараметрыВывода.ВыводитьОтбор = Ложь;

    // Условное оформление: формат "ЧЦ=10" для полей СуммаПриход и СуммаРасход
    ЭлементОформления = Настройки.УсловноеОформление.Элементы.Добавить();
    ЭлементОформления.Использование = Истина;

    // Условие: всегда (пустое оформление применяется ко всем записям)
    // Поля, к которым применяется оформление
    МассивПолей = Новый Массив;
    МассивПолей.Добавить(ПолеСуммаПриход);
    МассивПолей.Добавить(ПолеСуммаРасход);
    ЭлементОформления.Поля.Добавить(МассивПолей);

    // Оформление: задаем формат
    ЗначениеОформления = ЭлементОформления.Оформление;
    ЗначениеОформления.УстановитьЗначениеПараметра("Формат", "ЧЦ=10");

    // Компоновка макета
    КомпоновщикМакета = Новый КомпоновщикМакетаКомпоновкиДанных;
    МакетКомпоновки = КомпоновщикМакета.Выполнить(СхемаКомпоновкиДанных, Настройки);

    // Вывод в табличный документ
    ПроцессорКомпоновки = Новый ПроцессорКомпоновкиДанных;
    ПроцессорКомпоновки.Инициализировать(МакетКомпоновки);

    ТабличныйДокумент = Новый ТабличныйДокумент;
    ПроцессорВывода = Новый ПроцессорВыводаРезультатаКомпоновкиДанныхВТабличныйДокумент;
    ПроцессорВывода.УстановитьДокумент(ТабличныйДокумент);
    ПроцессорВывода.Вывести(ПроцессорКомпоновки);

    Возврат ТабличныйДокумент;

КонецФункции

&НаСервере
Функция СформироватьОтчетВзаиморасчетыДобавитьКолонкуРазница(ДатаНачала, ДатаОкончания)
    // Получаем объект отчета
    ОтчетОбъект = Отчеты.ОтчетПоВзаиморасчетам.Создать();

    // Получаем схему компоновки данных
    СхемаКомпоновкиДанных = ОтчетОбъект.ПолучитьМакет("ОсновнаяСхемаКомпоновкиДанных");

    // Загружаем настройки варианта "Основной"
    Настройки = СхемаКомпоновкиДанных.ВариантыНастроек.Основной.Настройки;

    // 1. Добавляем вычисляемое поле "Разница"
    ВычисляемоеПоле = Настройки.ВычисляемыеПоля.Добавить();
    ВычисляемоеПоле.Заголовок = "Разница";
    ВычисляемоеПоле.ПутьКДанным = "Разница";
    ВычисляемоеПоле.Выражение = "СуммаПриход - СуммаРасход";
    ВычисляемоеПоле.Группировка = "Регистратор";
    ВычисляемоеПоле.ТипЗначения = Новый ОписаниеТипов("Число", Новый КвалификаторыЧисла(10, 2));

    // 2. Добавляем поле итога для "Разница"
    ПолеИтога = Настройки.ПоляИтога.Добавить();
    ПолеИтога.Поле = "Разница";
    ПолеИтога.Выражение = "Сумма(Разница)";

    // 3. Настраиваем параметр "Период"
    ПараметрПериод = Настройки.ПараметрыДанных.Найти("Период");
    Если ПараметрПериод = Неопределено Тогда
        ПараметрПериод = Настройки.ПараметрыДанных.Добавить();
        ПараметрПериод.Имя = "Период";
    КонецЕсли;
    ПараметрПериод.Значение = Новый СтандартныйПериод(ДатаНачала, ДатаОкончания);

    // 4. Устанавливаем выбранные поля
    Настройки.ВыбранныеПоля.Элементы.Очистить();

    ПолеСуммаПриход = Настройки.ВыбранныеПоля.Элементы.Добавить(Тип("ЭлементВыбранногоПоляКомпоновкиДанных"));
    ПолеСуммаПриход.Поле = Новый ПолеКомпоновкиДанных("СуммаПриход");

    ПолеСуммаРасход = Настройки.ВыбранныеПоля.Элементы.Добавить(Тип("ЭлементВыбранногоПоляКомпоновкиДанных"));
    ПолеСуммаРасход.Поле = Новый ПолеКомпоновкиДанных("СуммаРасход");

    ПолеРазница = Настройки.ВыбранныеПоля.Элементы.Добавить(Тип("ЭлементВыбранногоПоляКомпоновкиДанных"));
    ПолеРазница.Поле = Новый ПолеКомпоновкиДанных("Разница");

    // 5. Настройки вывода
    Настройки.НастройкиВывода.ВыводитьПараметрыДанных = Ложь;
    Настройки.НастройкиВывода.ВыводитьОтбор = Ложь;

    // 6. Компоновка макета
    КомпоновщикМакета = Новый КомпоновщикМакетаКомпоновкиДанных;
    МакетКомпоновки = КомпоновщикМакета.Выполнить(СхемаКомпоновкиДанных, Настройки);

    // 7. Выполнение компоновки и вывод в табличный документ
    ПроцессорКомпоновки = Новый ПроцессорКомпоновкиДанных;
    ПроцессорКомпоновки.Инициализировать(МакетКомпоновки);

    ТабДок = Новый ТабличныйДокумент;
    ПроцессорВывода = Новый ПроцессорВыводаРезультатаКомпоновкиДанныхВТабличныйДокумент;
    ПроцессорВывода.УстановитьДокумент(ТабДок);
    ПроцессорВывода.Вывести(ПроцессорКомпоновки);

    Возврат ТабДок;
КонецФункции

Функция СформироватьМаржинальностьПродаж(ДатаНач, ДатаКон) Экспорт

    Запрос = Новый Запрос;
    Запрос.Текст =
    "ВЫБРАТЬ
    |    РасходТовараТовары.Товар КАК Товар,
    |    СУММА(РасходТовараТовары.Количество) КАК КоличествоПродано,
    |    СУММА(РасходТовараТовары.Сумма) КАК СуммаПродажи,
    |    СУММА(РасходТовараТовары.Количество * ЕСТЬNULL(ПриходСредняя.СредняяЦена, 0)) КАК Себестоимость,
    |    СУММА(РасходТовараТовары.Сумма) - СУММА(РасходТовараТовары.Количество * ЕСТЬNULL(ПриходСредняя.СредняяЦена, 0)) КАК Маржа
    |ИЗ
    |    Документ.РасходТовара.Товары КАК РасходТовараТовары
    |        ЛЕВОЕ СОЕДИНЕНИЕ (ВЫБРАТЬ
    |            ПриходТовараТовары.Товар КАК Товар,
    |            ЕСТЬNULL(СУММА(ПриходТовараТовары.Сумма) / СУММА(ПриходТовараТовары.Количество), 0) КАК СредняяЦена
    |        ИЗ
    |            Документ.ПриходТовара.Товары КАК ПриходТовараТовары
    |        ГДЕ
    |            ПриходТовараТовары.Ссылка.Проведен
    |        СГРУППИРОВАТЬ ПО
    |            ПриходТовараТовары.Товар) КАК ПриходСредняя
    |        ПО РасходТовараТовары.Товар = ПриходСредняя.Товар
    |ГДЕ
    |    РасходТовараТовары.Ссылка.Проведен
    |    И РасходТовараТовары.Ссылка.Дата МЕЖДУ &ДатаНач И &ДатаКон
    |СГРУППИРОВАТЬ ПО
    |    РасходТовараТовары.Товар";

    Запрос.УстановитьПараметр("ДатаНач", ДатаНач);
    Запрос.УстановитьПараметр("ДатаКон", ДатаКон);

    РезультатЗапроса = Запрос.Выполнить();

    ТаблицаРезультат = Новый ТаблицаЗначений;
    ТаблицаРезультат.Колонки.Добавить("Товар", Новый ОписаниеТипов("СправочникСсылка.Товары"));
    ТаблицаРезультат.Колонки.Добавить("КоличествоПродано", Новый ОписаниеТипов("Число", Новый КвалификаторыЧисла(15, 2)));
    ТаблицаРезультат.Колонки.Добавить("СуммаПродажи", Новый ОписаниеТипов("Число", Новый КвалификаторыЧисла(15, 2)));
    ТаблицаРезультат.Колонки.Добавить("Себестоимость", Новый ОписаниеТипов("Число", Новый КвалификаторыЧисла(15, 2)));
    ТаблицаРезультат.Колонки.Добавить("Маржа", Новый ОписаниеТипов("Число", Новый КвалификаторыЧисла(15, 2)));

    Выборка = РезультатЗапроса.Выбрать();
    Пока Выборка.Следующий() Цикл
        Строка = ТаблицаРезультат.Добавить();
        Строка.Товар = Выборка.Товар;
        Строка.КоличествоПродано = Выборка.КоличествоПродано;
        Строка.СуммаПродажи = Выборка.СуммаПродажи;
        Строка.Себестоимость = Выборка.Себестоимость;
        Строка.Маржа = Выборка.Маржа;
    КонецЦикла;

    Возврат ТаблицаРезультат;

КонецФункции

Функция СформироватьОтчетОстаткиВыводРеквизитовТовара()

    // Получаем схему компоновки данных из отчета
    СхемаКомпоновкиДанных = Отчеты.ОстаткиТоваровНаСкладах.ПолучитьМакет("ОсновнаяСхемаКомпоновкиДанных");

    // Создаем компоновщик настроек и инициализируем его
    КомпоновщикНастроек = Новый КомпоновщикНастроекКомпоновкиДанных;
    КомпоновщикНастроек.Инициализировать(Новый ИсточникДоступныхНастроекКомпоновкиДанных(СхемаКомпоновкиДанных));
    Настройки = КомпоновщикНастроек.Настройки;

    // Формируем структуру отчета: группировка по товару
    ГруппировкаТовар = Настройки.Структура.Добавить(Тип("ГруппировкаКомпоновкиДанных"));
    ГруппировкаТовар.Имя = "Товар";
    ГруппировкаТовар.Поле = Новый ПолеКомпоновкиДанных("Товар");
    ГруппировкаТовар.ТипГруппировки = ТипГруппировкиКомпоновкиДанных.Элементы;
    ГруппировкаТовар.ТипДополнения = ТипДополненияПериодаКомпоновкиДанных.БезДополнения;

    // Выбранные поля
    // Поле Товар
    ПолеТовар = Настройки.Выборка.Добавить(Тип("ВыбранноеПолеКомпоновкиДанных"));
    ПолеТовар.Поле = Новый ПолеКомпоновкиДанных("Товар");

    // Группа колонок "Свойства"
    ГруппаСвойства = Настройки.Выборка.Добавить(Тип("ГруппаВыбранныхПолейКомпоновкиДанных"));
    ГруппаСвойства.Заголовок = "Свойства";
    ГруппаСвойства.Расположение = РасположениеПолейКомпоновкиДанных.ОтдельнаяКолонка;

    // Поле Артикул
    ПолеАртикул = ГруппаСвойства.Элементы.Добавить(Тип("ВыбранноеПолеКомпоновкиДанных"));
    ПолеАртикул.Поле = Новый ПолеКомпоновкиДанных("Товар.Артикул");
    ПолеАртикул.Заголовок = "Артикул";

    // Поле Изображение
    ПолеИзображение = ГруппаСвойства.Элементы.Добавить(Тип("ВыбранноеПолеКомпоновкиДанных"));
    ПолеИзображение.Поле = Новый ПолеКомпоновкиДанных("Товар.ФайлКартинки.ДанныеФайл");
    ПолеИзображение.Заголовок = "Изображение";

    // Поле КоличествоОстаток
    ПолеКоличество = Настройки.Выборка.Добавить(Тип("ВыбранноеПолеКомпоновкиДанных"));
    ПолеКоличество.Поле = Новый ПолеКомпоновкиДанных("КоличествоОстаток");

    // Параметры вывода
    Настройки.ПараметрыВывода.ВыводитьПараметрыДанных = Ложь;
    Настройки.ПараметрыВывода.ВыводитьОтбор = Ложь;

    // Компонуем макет и выводим результат
    КомпоновщикМакета = Новый КомпоновщикМакетаКомпоновкиДанных;
    МакетКомпоновки = КомпоновщикМакета.Выполнить(СхемаКомпоновкиДанных, Настройки, , , Тип("ГенераторМакетаКомпоновкиДанныхДляКоллекцииЗначений"));

    ПроцессорКомпоновки = Новый ПроцессорКомпоновкиДанных;
    ПроцессорКомпоновки.Инициализировать(МакетКомпоновки);

    ТабличныйДокумент = Новый ТабличныйДокумент;
    ПроцессорВывода = Новый ПроцессорВыводаРезультатаКомпоновкиДанныхВТабличныйДокумент;
    ПроцессорВывода.УстановитьДокумент(ТабличныйДокумент);
    ПроцессорВывода.Вывести(ПроцессорКомпоновки);

    Возврат ТабличныйДокумент;

КонецФункции

Функция СформироватьДублирующиесяЗаказы(ДатаНач = Неопределено, ДатаКон = Неопределено) Экспорт

    // Обработка параметров периода: если не заданы — текущий день
    Если ДатаНач = Неопределено Тогда
        ДатаНач = НачалоДня(ТекущаяДата());
    КонецЕсли;
    Если ДатаКон = Неопределено Тогда
        ДатаКон = КонецДня(ТекущаяДата());
    КонецЕсли;

    // Построение запроса
    Запрос = Новый Запрос;
    Запрос.Текст = 
    "ВЫБРАТЬ
    |    Заказ.Покупатель КАК Покупатель,
    |    НАЧАЛОПЕРИОДА(Заказ.Дата, ДЕНЬ) КАК ДатаЗаказа,
    |    КОЛИЧЕСТВО(Заказ.Ссылка) КАК КоличествоЗаказов
    |ИЗ
    |    Документ.Заказ КАК Заказ
    |ГДЕ
    |    Заказ.Проведен
    |    И Заказ.Дата МЕЖДУ &ДатаНач И &ДатаКон
    |СГРУППИРОВАТЬ ПО
    |    Заказ.Покупатель,
    |    НАЧАЛОПЕРИОДА(Заказ.Дата, ДЕНЬ)
    |ИМЕЮЩИЕ
    |    КОЛИЧЕСТВО(Заказ.Ссылка) > 1
    |УПОРЯДОЧИТЬ ПО
    |    Покупатель,
    |    ДатаЗаказа";

    // Передача параметров
    Запрос.УстановитьПараметр("ДатаНач", ДатаНач);
    Запрос.УстановитьПараметр("ДатаКон", ДатаКон);

    // Выполнение запроса
    РезультатЗапроса = Запрос.Выполнить();
    Выборка = РезультатЗапроса.Выбрать();

    // Формирование таблицы значений результата
    ТаблицаРезультата = Новый ТаблицаЗначений;
    ТаблицаРезультата.Колонки.Добавить("Покупатель", Новый ОписаниеТипов("СправочникСсылка.Контрагенты"));
    ТаблицаРезультата.Колонки.Добавить("ДатаЗаказа", Новый ОписаниеТипов("Дата"));
    ТаблицаРезультата.Колонки.Добавить("КоличествоЗаказов", Новый ОписаниеТипов("Число"));

    Пока Выборка.Следующий() Цикл
        НоваяСтрока = ТаблицаРезультата.Добавить();
        НоваяСтрока.Покупатель      = Выборка.Покупатель;
        НоваяСтрока.ДатаЗаказа      = Выборка.ДатаЗаказа;
        НоваяСтрока.КоличествоЗаказов = Выборка.КоличествоЗаказов;
    КонецЦикла;

    Возврат ТаблицаРезультата;

КонецФункции

&НаСервере
Функция СформироватьОтчетОстаткиИзменитьЗаголовокКолонкиОстаток()

    // Создание объекта отчета
    ОтчетОбъект = Отчеты.ОстаткиТоваровНаСкладах.Создать();

    // Инициализация компоновщика настроек
    КомпоновщикНастроек = Новый КомпоновщикНастроекКомпоновкиДанных;
    КомпоновщикНастроек.Инициализировать(Новый ИсточникДоступныхНастроекКомпоновкиДанных(ОтчетОбъект));

    // Загрузка настроек варианта "Основной"
    Вариант = ОтчетОбъект.Варианты.Найти("Основной");
    Если Вариант = Неопределено Тогда
        ВызватьИсключение "Вариант отчета 'Основной' не найден";
    КонецЕсли;
    КомпоновщикНастроек.ЗагрузитьНастройки(Вариант.Настройки);

    Настройки = КомпоновщикНастроек.Настройки;

    // Очистка существующего условного оформления
    Настройки.УсловноеОформление.Очистить();

    // --------------------------------
    // Условное оформление для заголовка полей ресурсов
    // --------------------------------
    ЭлементОформления = Настройки.УсловноеОформление.Добавить();
    ЭлементОформления.Использование = Истина;

    Область = ЭлементОформления.ОбластиИспользования.Добавить();
    Область.Использование = Истина;
    Область.ВидОбласти = ВидОбластиУсловногоОформленияКомпоновкиДанных.ЗаголовокПолейРесурсов;

    ОформляемоеПоле = ЭлементОформления.ОформляемыеПоля.Добавить();
    ОформляемоеПоле.Использование = Истина;
    ОформляемоеПоле.Поле = Новый ПолеКомпоновкиДанных("КоличествоОстаток");

    ЭлементОформления.Оформление.УстановитьЗначениеПараметра("Текст", "Остаток на складе");

    // --------------------------------
    // Условное оформление для заголовка полей ресурсов общего итога
    // --------------------------------
    ЭлементОформления2 = Настройки.УсловноеОформление.Добавить();
    ЭлементОформления2.Использование = Истина;

    Область2 = ЭлементОформления2.ОбластиИспользования.Добавить();
    Область2.Использование = Истина;
    Область2.ВидОбласти = ВидОбластиУсловногоОформленияКомпоновкиДанных.ЗаголовокПолейРесурсовОбщегоИтога;

    ОформляемоеПоле2 = ЭлементОформления2.ОформляемыеПоля.Добавить();
    ОформляемоеПоле2.Использование = Истина;
    ОформляемоеПоле2.Поле = Новый ПолеКомпоновкиДанных("КоличествоОстаток");

    ЭлементОформления2.Оформление.УстановитьЗначениеПараметра("Текст", "Количество");

    // --------------------------------
    // Настройки вывода
    // --------------------------------
    Настройки.ПараметрыВывода.ВыводитьПараметрыДанных = Ложь;
    Настройки.ПараметрыВывода.ВыводитьОтбор = Ложь;

    // --------------------------------
    // Компоновка макета и формирование табличного документа
    // --------------------------------
    КомпоновщикМакета = Новый КомпоновщикМакетаКомпоновкиДанных;
    МакетКомпоновки = КомпоновщикМакета.Выполнить(ОтчетОбъект.СхемаКомпоновкиДанных, Настройки);

    ПроцессорКомпоновки = Новый ПроцессорКомпоновкиДанных;
    ПроцессорКомпоновки.Инициализировать(МакетКомпоновки);

    ТабличныйДокумент = Новый ТабличныйДокумент;
    ПроцессорВывода = Новый ПроцессорВыводаРезультатаКомпоновкиДанныхВТабличныйДокумент;
    ПроцессорВывода.УстановитьДокумент(ТабличныйДокумент);
    ПроцессорВывода.Вывести(ПроцессорКомпоновки);

    Возврат ТабличныйДокумент;

КонецФункции

Функция НайтиНастройкуКомпоновщика(стрНастройки, КомпоновщикНастроек)

    // Проверка корректности входных параметров
    Если стрНастройки = Неопределено Или КомпоновщикНастроек = Неопределено Тогда
        Возврат Неопределено;
    КонецЕсли;

    ВидНастройки = стрНастройки.ВидНастройки;
    ИмяНастройки = стрНастройки.ИмяНастройки;

    // Если ключевые поля не заполнены, поиск невозможен
    Если Не ЗначениеЗаполнено(ВидНастройки) Или Не ЗначениеЗаполнено(ИмяНастройки) Тогда
        Возврат Неопределено;
    КонецЕсли;

    // Получаем коллекцию всех пользовательских настроек компоновщика
    Настройки = КомпоновщикНастроек.Настройки;

    // Перебираем элементы коллекции
    Для Каждого Элемент Из Настройки Цикл
        Если Элемент.Вид = ВидНастройки И Элемент.Имя = ИмяНастройки Тогда
            Возврат Элемент;
        КонецЕсли;
    КонецЦикла;

    // Настройка не найдена
    Возврат Неопределено;

КонецФункции

Функция СформироватьИсториюИзмененияЦен(ДатаНач = Неопределено, ДатаКон = Неопределено)

    // Установка значений по умолчанию: начало и конец текущего дня
    Если ДатаНач = Неопределено Тогда
        ДатаНач = НачалоДня(ТекущаяДатаСеанса());
    КонецЕсли;

    Если ДатаКон = Неопределено Тогда
        ДатаКон = КонецДня(ТекущаяДатаСеанса());
    КонецЕсли;

    // Формирование запроса к периодическому регистру сведений
    Запрос = Новый Запрос;
    Запрос.Текст = 
    "ВЫБРАТЬ
    |    ЦеныТоваров.Товар           КАК Товар,
    |    ЦеныТоваров.ВидЦен          КАК ВидЦен,
    |    ЦеныТоваров.Период          КАК ДатаИзменения,
    |    ЦеныТоваров.Цена            КАК Цена
    |ИЗ
    |    РегистрСведений.ЦеныТоваров КАК ЦеныТоваров
    |ГДЕ
    |    ЦеныТоваров.Период МЕЖДУ &ДатаНач И &ДатаКон
    |
    |УПОРЯДОЧИТЬ ПО
    |    Товар ВОЗР,
    |    ДатаИзменения ВОЗР";

    Запрос.УстановитьПараметр("ДатаНач", ДатаНач);
    Запрос.УстановитьПараметр("ДатаКон", ДатаКон);

    РезультатЗапроса = Запрос.Выполнить();

    // Создание таблицы значений для возврата
    ТаблицаРезультат = Новый ТаблицаЗначений;
    ТаблицаРезультат.Колонки.Добавить("Товар", 
        Новый ОписаниеТипов("СправочникСсылка.Товары"));
    ТаблицаРезультат.Колонки.Добавить("ВидЦен", 
        Новый ОписаниеТипов("СправочникСсылка.ВидыЦен"));
    ТаблицаРезультат.Колонки.Добавить("ДатаИзменения", 
        Новый ОписаниеТипов("Дата"));
    ТаблицаРезультат.Колонки.Добавить("Цена", 
        Новый ОписаниеТипов("Число", Новый КвалификаторыЧисла(10, 2)));

    // Перенос данных запроса в таблицу значений
    Выборка = РезультатЗапроса.Выбрать();
    Пока Выборка.Следующий() Цикл
        НоваяСтрока = ТаблицаРезультат.Добавить();
        НоваяСтрока.Товар = Выборка.Товар;
        НоваяСтрока.ВидЦен = Выборка.ВидЦен;
        НоваяСтрока.ДатаИзменения = Выборка.ДатаИзменения;
        НоваяСтрока.Цена = Выборка.Цена;
    КонецЦикла;

    Возврат ТаблицаРезультат;

КонецФункции

Функция ПолучитьСвойствоДоступногоПоля(СтруктураКД, Поле, Свойство)
    // Определяем коллекцию доступных полей в зависимости от типа первого параметра
    Если ТипЗнч(СтруктураКД) = Тип("КомпоновщикНастроекКомпоновкиДанных") Тогда
        ДоступныеПоля = СтруктураКД.Настройки.ДоступныеПоляВыбора;
    ИначеЕсли ТипЗнч(СтруктураКД) = Тип("ДоступныеПоляКомпоновкиДанных") Тогда
        ДоступныеПоля = СтруктураКД;
    Иначе
        // Неподдерживаемый тип – вернуть Неопределено
        Возврат Неопределено;
    КонецЕсли;

    // Приводим идентификатор поля к строке
    Если ТипЗнч(Поле) = Тип("ПолеКомпоновкиДанных") Тогда
        ИмяПоля = Поле.Поле; // свойство "Поле" содержит строковое имя поля
    ИначеЕсли ТипЗнч(Поле) = Тип("Строка") Тогда
        ИмяПоля = Поле;
    Иначе
        Возврат Неопределено;
    КонецЕсли;

    // Рекурсивный поиск элемента доступного поля
    НайденныйЭлемент = НайтиДоступноеПоле(ДоступныеПоля, ИмяПоля);

    Если НайденныйЭлемент = Неопределено Тогда
        Возврат Неопределено;
    КонецЕсли;

    // Извлечение значения свойства по имени
    Попытка
        ЗначениеСвойства = НайденныйЭлемент[Свойство];
        Возврат ЗначениеСвойства;
    Исключение
        Возврат Неопределено;
    КонецПопытки;
КонецФункции

// Вспомогательная рекурсивная функция поиска элемента в иерархии доступных полей
Функция НайтиДоступноеПоле(Коллекция, ИмяПоля)
    Для Каждого Элемент Из Коллекция Цикл
        // Проверяем, что у элемента есть поле (не группа без поля)
        Если Элемент.Поле <> Неопределено И Элемент.Поле.Поле = ИмяПоля Тогда
            Возврат Элемент;
        КонецЕсли;
        // Если это группа – рекурсивно обходим вложенные элементы
        Если Элемент.Элементы.Количество() > 0 Тогда
            Результат = НайтиДоступноеПоле(Элемент.Элементы, ИмяПоля);
            Если Результат <> Неопределено Тогда
                Возврат Результат;
            КонецЕсли;
        КонецЕсли;
    КонецЦикла;
    Возврат Неопределено;
КонецФункции

Функция СформироватьРекомендуемыйЗаказ(ДатаНач = Неопределено, ДатаКон = Неопределено) Экспорт

    // Установка периода анализа продаж
    Если ДатаНач = Неопределено Тогда
        ДатаНач = НачалоДня(ТекущаяДатаСеанса() - 30 * 86400); // 30 дней назад от текущей даты
    КонецЕсли;

    Если ДатаКон = Неопределено Тогда
        ДатаКон = КонецДня(ТекущаяДатаСеанса());
    КонецЕсли;

    ДатаОстатков = ТекущаяДатаСеанса(); // текущий момент для получения остатков

    Запрос = Новый Запрос;
    Запрос.Текст = 
    "ВЫБРАТЬ
    |    ПродажиОбороты.Товар КАК Товар,
    |    ПродажиОбороты.Продано КАК Продано,
    |    ЕСТЬNULL(Остатки.Остаток, 0) КАК Остаток,
    |    ПродажиОбороты.Продано - ЕСТЬNULL(Остатки.Остаток, 0) КАК РекомендуемыйЗаказ
    |ИЗ
    |    (ВЫБРАТЬ
    |        Продажи.Товар КАК Товар,
    |        СУММА(Продажи.Количество) КАК Продано
    |    ИЗ
    |        РегистрНакопления.Продажи.Обороты(&ДатаНач, &ДатаКон) КАК Продажи
    |    СГРУППИРОВАТЬ ПО
    |        Продажи.Товар) КАК ПродажиОбороты
    |        ЛЕВОЕ СОЕДИНЕНИЕ (ВЫБРАТЬ
    |            ТоварныеЗапасы.Товар КАК Товар,
    |            СУММА(ТоварныеЗапасы.Количество) КАК Остаток
    |        ИЗ
    |            РегистрНакопления.ТоварныеЗапасы.Остатки(&ДатаОстатков) КАК ТоварныеЗапасы
    |        СГРУППИРОВАТЬ ПО
    |            ТоварныеЗапасы.Товар) КАК Остатки
    |        ПО ПродажиОбороты.Товар = Остатки.Товар
    |ГДЕ
    |    ПродажиОбороты.Продано - ЕСТЬNULL(Остатки.Остаток, 0) > 0";

    Запрос.УстановитьПараметр("ДатаНач", ДатаНач);
    Запрос.УстановитьПараметр("ДатаКон", ДатаКон);
    Запрос.УстановитьПараметр("ДатаОстатков", ДатаОстатков);

    РезультатЗапроса = Запрос.Выполнить();

    // Формирование результирующей таблицы значений
    ТаблицаРезультат = Новый ТаблицаЗначений;
    ТаблицаРезультат.Колонки.Добавить("Товар", Новый ОписаниеТипов("СправочникСсылка.Товары"));
    ТаблицаРезультат.Колонки.Добавить("Продано", Новый ОписаниеТипов("Число", , , Новый КвалификаторыЧисла(10, 2)));
    ТаблицаРезультат.Колонки.Добавить("Остаток", Новый ОписаниеТипов("Число", , , Новый КвалификаторыЧисла(10, 2)));
    ТаблицаРезультат.Колонки.Добавить("РекомендуемыйЗаказ", Новый ОписаниеТипов("Число", , , Новый КвалификаторыЧисла(10, 2)));

    ВыборкаДетальныеЗаписи = РезультатЗапроса.Выбрать();
    Пока ВыборкаДетальныеЗаписи.Следующий() Цикл
        НоваяСтрока = ТаблицаРезультат.Добавить();
        НоваяСтрока.Товар = ВыборкаДетальныеЗаписи.Товар;
        НоваяСтрока.Продано = ВыборкаДетальныеЗаписи.Продано;
        НоваяСтрока.Остаток = ВыборкаДетальныеЗаписи.Остаток;
        НоваяСтрока.РекомендуемыйЗаказ = ВыборкаДетальныеЗаписи.РекомендуемыйЗаказ;
    КонецЦикла;

    Возврат ТаблицаРезультат;

КонецФункции

// Функция проверяет заполненность указанных реквизитов объекта (обычных и табличных частей).
// Параметры:
//   Объект - ДокументОбъект, СправочникОбъект - проверяемый объект.
//   МассивПроверяемыхРеквизитов - Массив из Строка - имена реквизитов в виде "Реквизит" или "ТЧ.Реквизит".
// Возвращаемое значение:
//   Булево - Истина, если все реквизиты заполнены, иначе Ложь.
Функция ПроверитьЗаполнениеРеквизитовОбъекта(Объект, МассивПроверяемыхРеквизитов)

    Для Каждого ИмяРеквизита Из МассивПроверяемыхРеквизитов Цикл
        ПозицияТочки = СтрНайти(ИмяРеквизита, ".");

        Если ПозицияТочки = 0 Тогда
            // Обычный реквизит объекта
            Если НЕ ЗначениеЗаполнено(Объект[ИмяРеквизита]) Тогда
                Возврат Ложь;
            КонецЕсли;
        Иначе
            // Реквизит табличной части, формат: "ИмяТЧ.ИмяРеквизита"
            ИмяТЧ = Лев(ИмяРеквизита, ПозицияТочки - 1);
            ИмяРеквизитаТЧ = Сред(ИмяРеквизита, ПозицияТочки + 1);

            ТабличнаяЧасть = Объект[ИмяТЧ];
            Если ТабличнаяЧасть.Количество() = 0 Тогда
                // Нет ни одной строки - считаем реквизит не заполненным
                Возврат Ложь;
            КонецЕсли;

            Для Каждого СтрокаТЧ Из ТабличнаяЧасть Цикл
                Если НЕ ЗначениеЗаполнено(СтрокаТЧ[ИмяРеквизитаТЧ]) Тогда
                    Возврат Ложь;
                КонецЕсли;
            КонецЦикла;
        КонецЕсли;
    КонецЦикла;

    Возврат Истина;

КонецФункции

Функция СформироватьПересортицу(ДатаНач = Неопределено, ДатаКон = Неопределено) Экспорт

    // Обработка параметров периода
    Если ДатаНач = Неопределено Тогда
        ДатаНач = ТекущаяДата() - 30 * 86400; // 30 дней назад
    КонецЕсли;
    Если ДатаКон = Неопределено Тогда
        ДатаКон = ТекущаяДата();
    КонецЕсли;

    НачПериода = НачалоДня(ДатаНач);
    КонПериода = КонецДня(ДатаКон);
    МоментОстатков = КонПериода; // остатки на конец периода

    Запрос = Новый Запрос;
    Запрос.Текст = 
    "ВЫБРАТЬ
    |    Продажи.Товар КАК Товар,
    |    Продажи.Продано КАК Продано,
    |    ЕСТЬNULL(Остатки.Остаток, 0) КАК Остаток,
    |    Продажи.Продано - ЕСТЬNULL(Остатки.Остаток, 0) КАК Пересортица
    |ИЗ
    |    (ВЫБРАТЬ
    |        ПродажиОбороты.Товар КАК Товар,
    |        СУММА(ПродажиОбороты.КоличествоОборот) КАК Продано
    |    ИЗ
    |        РегистрНакопления.Продажи.Обороты(&НачПериода, &КонПериода, ) КАК ПродажиОбороты
    |    СГРУППИРОВАТЬ ПО
    |        ПродажиОбороты.Товар) КАК Продажи
    |    ЛЕВОЕ СОЕДИНЕНИЕ (ВЫБРАТЬ
    |        ТоварныеЗапасыОстатки.Товар КАК Товар,
    |        СУММА(ТоварныеЗапасыОстатки.КоличествоОстаток) КАК Остаток
    |    ИЗ
    |        РегистрНакопления.ТоварныеЗапасы.Остатки(&МоментОстатков, ) КАК ТоварныеЗапасыОстатки
    |    СГРУППИРОВАТЬ ПО
    |        ТоварныеЗапасыОстатки.Товар) КАК Остатки
    |    ПО Продажи.Товар = Остатки.Товар
    |ГДЕ
    |    Продажи.Продано - ЕСТЬNULL(Остатки.Остаток, 0) > 0";

    Запрос.УстановитьПараметр("НачПериода", НачПериода);
    Запрос.УстановитьПараметр("КонПериода", КонПериода);
    Запрос.УстановитьПараметр("МоментОстатков", МоментОстатков);

    // Формирование таблицы значений результата
    ТЗ = Новый ТаблицаЗначений;
    ТЗ.Колонки.Добавить("Товар", Новый ОписаниеТипов("СправочникСсылка.Товары"));
    ТЗ.Колонки.Добавить("Продано", Новый ОписаниеТипов("Число", Новый КвалификаторыЧисла(10, 2)));
    ТЗ.Колонки.Добавить("Остаток", Новый ОписаниеТипов("Число", Новый КвалификаторыЧисла(10, 2)));
    ТЗ.Колонки.Добавить("Пересортица", Новый ОписаниеТипов("Число", Новый КвалификаторыЧисла(10, 2)));

    Выборка = Запрос.Выполнить().Выбрать();
    Пока Выборка.Следующий() Цикл
        Строка = ТЗ.Добавить();
        Строка.Товар = Выборка.Товар;
        Строка.Продано = Выборка.Продано;
        Строка.Остаток = Выборка.Остаток;
        Строка.Пересортица = Выборка.Пересортица;
    КонецЦикла;

    Возврат ТЗ;

КонецФункции

// Функция возвращает последний элемент структуры настроек компоновки данных.
// Параметры:
//   НастройкиКД - КомпоновщикНастроекКомпоновкиДанных, НастройкиКомпоновкиДанных - исходный объект, содержащий структуру.
//   ПолучитьСтроки - Булево - если Истина, то для таблиц возвращаются Строки (серии), иначе Колонки (точки).
// Возвращаемое значение:
//   ГруппировкаТаблицыКомпоновкиДанных, ГруппировкаКомпоновкиДанных, ГруппировкаДиаграммыКомпоновкиДанных - требуемый элемент.
//   Неопределено, если структура пуста или последний элемент не поддерживается.
Функция ПолучитьПоследнийЭлементСтруктуры(НастройкиКД, ПолучитьСтроки) Экспорт

    // Определяем коллекцию структуры в зависимости от типа входного параметра
    СтруктураЭлементов = Неопределено;
    Если ТипЗнч(НастройкиКД) = Тип("КомпоновщикНастроекКомпоновкиДанных") Тогда
        СтруктураЭлементов = НастройкиКД.Настройки.Структура;
    ИначеЕсли ТипЗнч(НастройкиКД) = Тип("НастройкиКомпоновкиДанных") Тогда
        СтруктураЭлементов = НастройкиКД.Структура;
    КонецЕсли;

    Если СтруктураЭлементов = Неопределено Или СтруктураЭлементов.Количество() = 0 Тогда
        Возврат Неопределено;
    КонецЕсли;

    ПоследнийЭлемент = СтруктураЭлементов[СтруктураЭлементов.Количество() - 1];

    ТипПоследнего = ТипЗнч(ПоследнийЭлемент);
    Если ТипПоследнего = Тип("ГруппировкаКомпоновкиДанных") Тогда
        Возврат ПоследнийЭлемент;

    ИначеЕсли ТипПоследнего = Тип("ТаблицаКомпоновкиДанных") Тогда
        Если ПолучитьСтроки Тогда
            Возврат ПоследнийЭлемент.Строки;
        Иначе
            Возврат ПоследнийЭлемент.Колонки;
        КонецЕсли;

    ИначеЕсли ТипПоследнего = Тип("ДиаграммаКомпоновкиДанных") Тогда
        Если ПолучитьСтроки Тогда
            Возврат ПоследнийЭлемент.Серии;
        Иначе
            Возврат ПоследнийЭлемент.Точки;
        КонецЕсли;

    Иначе
        Возврат Неопределено;
    КонецЕсли;

КонецФункции

Функция СформироватьАнализСезонностиПродаж(ДатаНач = Неопределено, ДатаКон = Неопределено)

    // Установка значений по умолчанию: начало и конец текущего года
    Если ДатаНач = Неопределено Тогда
        ДатаНач = НачалоГода(ТекущаяДата());
    КонецЕсли;

    Если ДатаКон = Неопределено Тогда
        ДатаКон = КонецГода(ТекущаяДата());
    КонецЕсли;

    // Формирование запроса к регистру накопления "Продажи" (обороты)
    Запрос = Новый Запрос;
    Запрос.Текст = 
    "ВЫБРАТЬ
    |    НАЧАЛОПЕРИОДА(Продажи.Период, МЕСЯЦ) КАК ПериодМесяца,
    |    СУММА(Продажи.Количество) КАК КоличествоПродано,
    |    СУММА(Продажи.Сумма) КАК СуммаПродаж
    |ИЗ
    |    РегистрНакопления.Продажи.Обороты КАК Продажи
    |ГДЕ
    |    Продажи.Период МЕЖДУ &ДатаНач И &ДатаКон
    |
    |СГРУППИРОВАТЬ ПО
    |    НАЧАЛОПЕРИОДА(Продажи.Период, МЕСЯЦ)
    |
    |УПОРЯДОЧИТЬ ПО
    |    ПериодМесяца";

    Запрос.УстановитьПараметр("ДатаНач", ДатаНач);
    Запрос.УстановитьПараметр("ДатаКон", ДатаКон);

    РезультатЗапроса = Запрос.Выполнить();
    Возврат РезультатЗапроса.Выгрузить();

КонецФункции

// Функция проверяет, содержится ли указанное поле в структуре настроек компоновки данных.
// Параметры:
//   СтруктураКД – коллекция элементов структуры (группировок, таблиц, диаграмм).
//   Поле        – Строка или ПолеКомпоновкиДанных – искомое поле.
//   ВключаяВложенныеПоля – Булево, по умолчанию Ложь – если Истина, учитываются вложенные поля.
// Возвращает: Булево – Истина, если поле найдено, иначе Ложь.
Функция НайтиПолеВСтуктуреКД(Знач СтруктураКД, Знач Поле, Знач ВключаяВложенныеПоля = Ложь) Экспорт

    // Преобразуем значение параметра Поле к строке для сравнения.
    Перем ИмяПоля;
    Если ТипЗнч(Поле) = Тип("Строка") Тогда
        ИмяПоля = Поле;
    ИначеЕсли ТипЗнч(Поле) = Тип("ПолеКомпоновкиДанных") Тогда
        ИмяПоля = Поле.Поле; // Путь к данным в виде строки
    Иначе
        Возврат Ложь; // Неподдерживаемый тип
    КонецЕсли;

    // Если структура не задана или пуста, вернуть Ложь
    Если СтруктураКД = Неопределено Или СтруктураКД.Количество() = 0 Тогда
        Возврат Ложь;
    КонецЕсли;

    // Рекурсивный обход элементов структуры
    Функция ПроверитьЭлементы(Коллекция, ИскомоеПоле, УчитыватьВложенные)
        Для Каждого Элемент Из Коллекция Цикл
            // Проверка полей группировки (характерно для Группировки)
            Если Элемент.Свойство("ПоляГруппировки") Тогда
                Для Каждого ПолеГруппировки Из Элемент.ПоляГруппировки Цикл
                    Если ПолеСовпадает(ПолеГруппировки, ИскомоеПоле, УчитыватьВложенные) Тогда
                        Возврат Истина;
                    КонецЕсли;
                КонецЦикла;
            КонецЕсли;

            // Проверка выбранных полей (для таблиц, диаграмм, группировок и пр.)
            Если Элемент.Свойство("ВыбранныеПоля") Тогда
                Для Каждого ВыбранноеПоле Из Элемент.ВыбранныеПоля Цикл
                    Если ТипЗнч(ВыбранноеПоле) = Тип("ВыбранноеПолеКомпоновкиДанных")
                       И ВыбранноеПоле.Свойство("Поле") Тогда
                        Если ПолеСовпадает(ВыбранноеПоле.Поле, ИскомоеПоле, УчитыватьВложенные) Тогда
                            Возврат Истина;
                        КонецЕсли;
                    КонецЕсли;
                КонецЦикла;
            КонецЕсли;

            // Если у элемента есть вложенная структура (рекурсия)
            Если Элемент.Свойство("Структура") Тогда
                Если ПроверитьЭлементы(Элемент.Структура, ИскомоеПоле, УчитыватьВложенные) Тогда
                    Возврат Истина;
                КонецЕсли;
            КонецЕсли;
        КонецЦикла;

        Возврат Ложь;
    КонецФункции // ПроверитьЭлементы

    // Вспомогательная функция сравнения полей с учётом вложенности
    Функция ПолеСовпадает(Значение, ИскомоеПоле, УчитыватьВложенные)
        Перем ТекущееПоле;

        Если ТипЗнч(Значение) = Тип("Строка") Тогда
            ТекущееПоле = Значение;
        ИначеЕсли ТипЗнч(Значение) = Тип("ПолеКомпоновкиДанных") Тогда
            ТекущееПоле = Значение.Поле;
        Иначе
            Возврат Ложь;
        КонецЕсли;

        Если УчитыватьВложенные Тогда
            // Полное совпадение или найденное поле является дочерним по отношению к искомому
            Возврат ТекущееПоле = ИскомоеПоле Или СтрНачинаетсяС(ТекущееПоле, ИскомоеПоле + ".");
        Иначе
            // Только точное совпадение
            Возврат ТекущееПоле = ИскомоеПоле;
        КонецЕсли;
    КонецФункции

    Возврат ПроверитьЭлементы(СтруктураКД, ИмяПоля, ВключаяВложенныеПоля);

КонецФункции

Функция СформироватьАнализПокупателейПоРегионам(ДатаНач = Неопределено, ДатаКон = Неопределено)
    // Если даты не заданы, используем текущий год
    Если ДатаНач = Неопределено Тогда
        ДатаНач = НачалоГода(ТекущаяДатаСеанса());
    КонецЕсли;
    Если ДатаКон = Неопределено Тогда
        ДатаКон = КонецГода(ТекущаяДатаСеанса());
    КонецЕсли;

    Запрос = Новый Запрос;
    Запрос.Текст = 
    "ВЫБРАТЬ
    |   ЕСТЬNULL(Контрагенты.Регион, ЗНАЧЕНИЕ(Справочник.Регионы.ПустаяСсылка)) КАК Регион,
    |   КОЛИЧЕСТВО(РАЗЛИЧНЫЕ ПродажиОбороты.Покупатель) КАК КоличествоПокупателей,
    |   СУММА(ПродажиОбороты.Количество) КАК КоличествоПродано,
    |   СУММА(ПродажиОбороты.Сумма) КАК СуммаПродаж
    |ИЗ
    |   РегистрНакопления.Продажи.Обороты(&ДатаНач, &ДатаКон) КАК ПродажиОбороты
    |       ЛЕВОЕ СОЕДИНЕНИЕ Справочник.Контрагенты КАК Контрагенты
    |       ПО ПродажиОбороты.Покупатель = Контрагенты.Ссылка
    |СГРУППИРОВАТЬ ПО
    |   ЕСТЬNULL(Контрагенты.Регион, ЗНАЧЕНИЕ(Справочник.Регионы.ПустаяСсылка))";

    Запрос.УстановитьПараметр("ДатаНач", ДатаНач);
    Запрос.УстановитьПараметр("ДатаКон", ДатаКон);

    РезультатЗапроса = Запрос.Выполнить();

    // Формирование результирующей таблицы значений
    ТаблицаРезультат = Новый ТаблицаЗначений;
    ТаблицаРезультат.Колонки.Добавить("Регион", Новый ОписаниеТипов("СправочникСсылка.Регионы"));
    ТаблицаРезультат.Колонки.Добавить("КоличествоПокупателей", Новый ОписаниеТипов("Число", Новый КвалификаторыЧисла(10, 0)));
    ТаблицаРезультат.Колонки.Добавить("КоличествоПродано", Новый ОписаниеТипов("Число", Новый КвалификаторыЧисла(10, 2)));
    ТаблицаРезультат.Колонки.Добавить("СуммаПродаж", Новый ОписаниеТипов("Число", Новый КвалификаторыЧисла(10, 2)));

    Выборка = РезультатЗапроса.Выбрать();
    Пока Выборка.Следующий() Цикл
        НоваяСтрока = ТаблицаРезультат.Добавить();
        НоваяСтрока.Регион                = Выборка.Регион;
        НоваяСтрока.КоличествоПокупателей = Выборка.КоличествоПокупателей;
        НоваяСтрока.КоличествоПродано     = Выборка.КоличествоПродано;
        НоваяСтрока.СуммаПродаж           = Выборка.СуммаПродаж;
    КонецЦикла;

    Возврат ТаблицаРезультат;
КонецФункции

Функция СформироватьКонтрольЗадержкиОплаты(ДатаНач = Неопределено, ДатаКон = Неопределено)

    // Установка значений по умолчанию
    Если ДатаНач = Неопределено Тогда
        ДатаНач = НачалоГода(ТекущаяДата());
    КонецЕсли;
    Если ДатаКон = Неопределено Тогда
        ДатаКон = КонецДня(ТекущаяДата());
    КонецЕсли;

    Запрос = Новый Запрос;
    Запрос.Текст = 
    "ВЫБРАТЬ
    |    ВзаиморасчетыОстатки.Контрагент КАК Покупатель,
    |    ВзаиморасчетыОстатки.СуммаОстаток КАК СуммаДолга
    |ИЗ
    |    РегистрНакопления.Взаиморасчеты.Остатки(&ДатаКон) КАК ВзаиморасчетыОстатки
    |ГДЕ
    |    ВзаиморасчетыОстатки.СуммаОстаток > 0";

    Запрос.УстановитьПараметр("ДатаКон", ДатаКон);

    РезультатЗапроса = Запрос.Выполнить();

    ТаблицаЗначений = РезультатЗапроса.Выгрузить();

    Возврат ТаблицаЗначений;

КонецФункции

Функция СформироватьИсториюДвиженияТовара(Товар, ДатаНач = Неопределено, ДатаКон = Неопределено)

    // Подготовка списка товаров
    Если ТипЗнч(Товар) = Тип("Массив") Тогда
        МассивТоваров = Товар;
    Иначе
        МассивТоваров = Новый Массив;
        МассивТоваров.Добавить(Товар);
    КонецЕсли;

    // Если список пуст, возвращаем пустую таблицу с нужной структурой
    Если МассивТоваров.Количество() = 0 Тогда
        ТЗ = Новый ТаблицаЗначений;
        ТЗ.Колонки.Добавить("Дата", Новый ОписаниеТипов("Дата"));
        ТЗ.Колонки.Добавить("ВидДвижения", Новый ОписаниеТипов("Строка"));
        ТЗ.Колонки.Добавить("Товар", Новый ОписаниеТипов("СправочникСсылка.Товары"));
        ТЗ.Колонки.Добавить("Количество", Новый ОписаниеТипов("Число", Новый КвалификаторыЧисла(10, 2)));
        ТЗ.Колонки.Добавить("Сумма", Новый ОписаниеТипов("Число", Новый КвалификаторыЧисла(10, 2)));
        Возврат ТЗ;
    КонецЕсли;

    // Определение периода
    Если ДатаНач = Неопределено Тогда
        ДатаНач = НачалоГода(ТекущаяДатаСеанса());
    КонецЕсли;
    Если ДатаКон = Неопределено Тогда
        ДатаКон = КонецДня(ТекущаяДатаСеанса());
    КонецЕсли;

    // Формирование запроса
    Запрос = Новый Запрос;
    Запрос.Текст = 
    "ВЫБРАТЬ
    |    ПриходТовараТовары.Ссылка.Дата КАК Дата,
    |    ""Приход"" КАК ВидДвижения,
    |    ПриходТовараТовары.Товар КАК Товар,
    |    ПриходТовараТовары.Количество КАК Количество,
    |    ПриходТовараТовары.Сумма КАК Сумма
    |ИЗ
    |    Документ.ПриходТовара.Товары КАК ПриходТовараТовары
    |ГДЕ
    |    ПриходТовараТовары.Ссылка.Проведен
    |    И ПриходТовараТовары.Товар В (&Товар)
    |    И ПриходТовараТовары.Ссылка.Дата МЕЖДУ &ДатаНач И &ДатаКон
    |
    |ОБЪЕДИНИТЬ ВСЕ
    |
    |ВЫБРАТЬ
    |    РасходТовараТовары.Ссылка.Дата,
    |    ""Расход"",
    |    РасходТовараТовары.Товар,
    |    РасходТовараТовары.Количество,
    |    РасходТовараТовары.Сумма
    |ИЗ
    |    Документ.РасходТовара.Товары КАК РасходТовараТовары
    |ГДЕ
    |    РасходТовараТовары.Ссылка.Проведен
    |    И РасходТовараТовары.Товар В (&Товар)
    |    И РасходТовараТовары.Ссылка.Дата МЕЖДУ &ДатаНач И &ДатаКон";

    Запрос.УстановитьПараметр("Товар", МассивТоваров);
    Запрос.УстановитьПараметр("ДатаНач", ДатаНач);
    Запрос.УстановитьПараметр("ДатаКон", ДатаКон);

    Результат = Запрос.Выполнить();

    ТЗ = Результат.Выгрузить();

    // Сортировка по дате
    ТЗ.Сортировать("Дата Возр");

    Возврат ТЗ;

КонецФункции

Функция СформироватьXYZАнализПродаж(ДатаНач = Неопределено, ДатаКон = Неопределено)

    // Установка значений по умолчанию
    Если ДатаНач = Неопределено Тогда
        ДатаНач = ДобавитьМесяц(ТекущаяДата(), -12);
    КонецЕсли;
    Если ДатаКон = Неопределено Тогда
        ДатаКон = КонецДня(ТекущаяДата());
    КонецЕсли;

    // Проверка корректности периода
    Если ДатаКон < ДатаНач Тогда
        ВызватьИсключение "Дата окончания периода не может быть меньше даты начала";
    КонецЕсли;

    // Подготовка запроса для получения месячных продаж
    Запрос = Новый Запрос;
    Запрос.Текст = 
    "ВЫБРАТЬ
    |    РасходТовараТовары.Товар КАК Товар,
    |    ГОД(РасходТовара.Дата) КАК Год,
    |    МЕСЯЦ(РасходТовара.Дата) КАК Месяц,
    |    СУММА(РасходТовараТовары.Количество) КАК Количество
    |ИЗ
    |    Документ.РасходТовара КАК РасходТовара
    |    ВНУТРЕННЕЕ СОЕДИНЕНИЕ Документ.РасходТовара.Товары КАК РасходТовараТовары
    |    ПО РасходТовара.Ссылка = РасходТовараТовары.Ссылка
    |ГДЕ
    |    РасходТовара.Проведен
    |    И РасходТовара.Дата МЕЖДУ &ДатаНач И &ДатаКон
    |
    |СГРУППИРОВАТЬ ПО
    |    РасходТовараТовары.Товар,
    |    ГОД(РасходТовара.Дата),
    |    МЕСЯЦ(РасходТовара.Дата)";

    Запрос.УстановитьПараметр("ДатаНач", ДатаНач);
    Запрос.УстановитьПараметр("ДатаКон", ДатаКон);
    РезультатЗапроса = Запрос.Выполнить();

    // Формирование полного списка месяцев в периоде
    МассивМесяцев = Новый Массив;
    ТекМесяц = НачалоМесяца(ДатаНач);
    КонецМесяцев = КонецМесяца(ДатаКон);
    Пока ТекМесяц <= КонецМесяцев Цикл
        МассивМесяцев.Добавить(Новый Структура("Год, Месяц", Год(ТекМесяц), Месяц(ТекМесяц)));
        ТекМесяц = ДобавитьМесяц(ТекМесяц, 1);
    КонецЦикла;
    КоличествоМесяцев = МассивМесяцев.Количество();

    // Построение индекса для быстрого поиска позиции месяца
    СоответствиеМесяцев = Новый Соответствие;
    Для Инд = 0 По КоличествоМесяцев - 1 Цикл
        Мес = МассивМесяцев[Инд];
        СоответствиеМесяцев.Вставить(Строка(Мес.Год) + "_" + Строка(Мес.Месяц), Инд);
    КонецЦикла;

    // Накопление данных по товарам (массивы продаж длиной КоличествоМесяцев)
    ДанныеТоваров = Новый Соответствие;
    Выборка = РезультатЗапроса.Выбрать();
    Пока Выборка.Следующий() Цикл
        Товар = Выборка.Товар;
        КлючМесяца = Строка(Выборка.Год) + "_" + Строка(Выборка.Месяц);
        ИндексМесяца = СоответствиеМесяцев[КлючМесяца];
        Если ИндексМесяца = Неопределено Тогда
            Продолжить;
        КонецЕсли;
        Если НЕ ДанныеТоваров.Свойство(Товар, МассивКоличеств) Тогда
            МассивКоличеств = Новый Массив(КоличествоМесяцев);
            Для i = 0 По КоличествоМесяцев - 1 Цикл
                МассивКоличеств[i] = 0;
            КонецЦикла;
            ДанныеТоваров.Вставить(Товар, МассивКоличеств);
        КонецЕсли;
        МассивКоличеств[ИндексМесяца] = МассивКоличеств[ИндексМесяца] + Выборка.Количество;
    КонецЦикла;

    // Формирование результирующей таблицы значений
    ТЗ = Новый ТаблицаЗначений;
    ТЗ.Колонки.Добавить("Товар", Новый ОписаниеТипов("СправочникСсылка.Товары"));
    ТЗ.Колонки.Добавить("СредниеПродажи", Новый ОписаниеТипов("Число"));
    ТЗ.Колонки.Добавить("ОтклонениеПродаж", Новый ОписаниеТипов("Число"));
    ТЗ.Колонки.Добавить("КоэффициентВариации", Новый ОписаниеТипов("Число"));
    ТЗ.Колонки.Добавить("XYZКатегория", Новый ОписаниеТипов("Строка"));

    // Расчёт показателей и категорий XYZ
    Для Каждого Пара Из ДанныеТоваров Цикл
        Товар = Пара.Ключ;
        МассивПродаж = Пара.Значение;

        // Среднее значение
        Сумма = 0;
        Для Каждого Кол Из МассивПродаж Цикл
            Сумма = Сумма + Кол;
        КонецЦикла;
        Среднее = Сумма / КоличествоМесяцев;

        // Стандартное отклонение (по генеральной совокупности)
        СуммаКвадратовОткл = 0;
        Для Каждого Кол Из МассивПродаж Цикл
            СуммаКвадратовОткл = СуммаКвадратовОткл + (Кол - Среднее) * (Кол - Среднее);
        КонецЦикла;
        Отклонение = Sqrt(СуммаКвадратовОткл / КоличествоМесяцев);

        // Коэффициент вариации и категория
        Если Среднее > 0 Тогда
            КоэфВариации = Отклонение / Среднее;
            Если КоэфВариации <= 0.10 Тогда
                Категория = "X";
            ИначеЕсли КоэфВариации <= 0.25 Тогда
                Категория = "Y";
            Иначе
                Категория = "Z";
            КонецЕсли;
        Иначе
            // При полном отсутствии продаж коэффициент не определён, условно 0, категория Z
            КоэфВариации = 0;
            Категория = "Z";
        КонецЕсли;

        // Добавление строки в таблицу
        НоваяСтрока = ТЗ.Добавить();
        НоваяСтрока.Товар = Товар;
        НоваяСтрока.СредниеПродажи = Среднее;
        НоваяСтрока.ОтклонениеПродаж = Отклонение;
        НоваяСтрока.КоэффициентВариации = КоэфВариации;
        НоваяСтрока.XYZКатегория = Категория;
    КонецЦикла;

    Возврат ТЗ;
КонецФункции

Функция ПолучитьЗначенияПолейДокумента(ДокументСсылка, Поля) Экспорт

    // Преобразуем входной параметр "Поля" в массив строк
    МассивПолей = Новый Массив;
    Если ТипЗнч(Поля) = Тип("Строка") Тогда
        МассивПолей = СтрРазделить(Поля, ",", Ложь);
        Для Инд = 0 По МассивПолей.Количество() - 1 Цикл
            МассивПолей[Инд] = СокрЛП(МассивПолей[Инд]);
        КонецЦикла;
    ИначеЕсли ТипЗнч(Поля) = Тип("Массив") Тогда
        Для Каждого Элемент Из Полей Цикл
            Если ТипЗнч(Элемент) = Тип("Строка") Тогда
                МассивПолей.Добавить(СокрЛП(Элемент));
            КонецЕсли;
        КонецЦикла;
    КонецЕсли;

    // Инициализация результата
    Результат = Новый Структура;
    Если МассивПолей.Количество() = 0 Тогда
        Возврат Результат;
    КонецЕсли;

    // Проверка, что передана ссылка на документ
    Если Не ЗначениеЗаполнено(ДокументСсылка) 
       Или ТипЗнч(ДокументСсылка) = Тип("Неопределено") Тогда
        Для Каждого Поле Из МассивПолей Цикл
            Результат.Вставить(Поле, Неопределено);
        КонецЦикла;
        Возврат Результат;
    КонецЕсли;

    Попытка
        ТипДокумента = ТипЗнч(ДокументСсылка);
        ОбъектМетаданных = Метаданные.Документы.Найти(ТипДокумента);
        Если ОбъектМетаданных = Неопределено Тогда
            Для Каждого Поле Из МассивПолей Цикл
                Результат.Вставить(Поле, Неопределено);
            КонецЦикла;
            Возврат Результат;
        КонецЕсли;

        ИмяТаблицы = "Документ." + ОбъектМетаданных.Имя;

        // Предварительная проверка существования полей через попытку компиляции запроса
        ВалидныеПоля = Новый Массив;
        Для Каждого Поле Из МассивПолей Цикл
            Если ПолеВалидноВЗапросе(ИмяТаблицы, Поле) Тогда
                ВалидныеПоля.Добавить(Поле);
            КонецЕсли;
        КонецЦикла;

        // Если нет ни одного валидного поля, возвращаем Неопределено для всех
        Если ВалидныеПоля.Количество() = 0 Тогда
            Для Каждого Поле Из МассивПолей Цикл
                Результат.Вставить(Поле, Неопределено);
            КонецЦикла;
            Возврат Результат;
        КонецЕсли;

        // Строим запрос с валидными полями
        Выражения = Новый Массив;
        СоответствиеАлиасов = Новый Соответствие;
        Индекс = 0;
        Для Каждого Поле Из ВалидныеПоля Цикл
            Алиас = "Поле" + Индекс;
            Выражения.Добавить("Документ." + Поле + " КАК " + Алиас);
            СоответствиеАлиасов.Вставить(Алиас, Поле);
            Индекс = Индекс + 1;
        КонецЦикла;

        Запрос = Новый Запрос;
        Запрос.Текст = 
        "ВЫБРАТЬ
        |" + СтрСоединить(Выражения, ",
        |") + "
        |ИЗ
        |    " + ИмяТаблицы + " КАК Документ
        |ГДЕ
        |    Документ.Ссылка = &Ссылка";

        Запрос.УстановитьПараметр("Ссылка", ДокументСсылка);

        РезультатЗапроса = Запрос.Выполнить();
        Если РезультатЗапроса.Пустой() Тогда
            Для Каждого Поле Из МассивПолей Цикл
                Результат.Вставить(Поле, Неопределено);
            КонецЦикла;
        Иначе
            Выборка = РезультатЗапроса.Выбрать();
            Выборка.Следующий();
            // Заполняем значения валидных полей
            Для Каждого Пара Из СоответствиеАлиасов Цикл
                Алиас = Пара.Ключ;
                ИсходноеПоле = Пара.Значение;
                Результат.Вставить(ИсходноеПоле, Выборка[Алиас]);
            КонецЦикла;
            // Для невалидных полей — Неопределено
            Для Каждого Поле Из МассивПолей Цикл
                Если Не Результат.Свойство(Поле) Тогда
                    Результат.Вставить(Поле, Неопределено);
                КонецЕсли;
            КонецЦикла;
        КонецЕсли;

    Исключение
        // В случае непредвиденной ошибки возвращаем Неопределено для всех запрошенных полей
        Для Каждого Поле Из МассивПолей Цикл
            Если Не Результат.Свойство(Поле) Тогда
                Результат.Вставить(Поле, Неопределено);
            КонецЕсли;
        КонецЦикла;
    КонецПопытки;

    Возврат Результат;

КонецФункции

// Проверя

Функция СформироватьДублиКонтрагентов() Экспорт

    Запрос = Новый Запрос;
    Запрос.Текст = 
    "ВЫБРАТЬ
    |   Контрагенты.Наименование КАК Наименование,
    |   Контрагенты.Телефон КАК Телефон,
    |   Контрагенты.ЭлектроннаяПочта КАК ЭлектроннаяПочта,
    |   КОЛИЧЕСТВО(Контрагенты.Ссылка) КАК Количество
    |ИЗ
    |   Справочник.Контрагенты КАК Контрагенты
    |ГДЕ
    |   Контрагенты.ЭтоГруппа = ЛОЖЬ
    |СГРУППИРОВАТЬ ПО
    |   Контрагенты.Наименование,
    |   Контрагенты.Телефон,
    |   Контрагенты.ЭлектроннаяПочта
    |ИМЕЮЩИЕ
    |   КОЛИЧЕСТВО(Контрагенты.Ссылка) > 1";

    РезультатЗапроса = Запрос.Выполнить();

    ТаблицаРезультат = Новый ТаблицаЗначений;
    ТаблицаРезультат.Колонки.Добавить("Наименование", Новый ОписаниеТипов("Строка"));
    ТаблицаРезультат.Колонки.Добавить("Телефон", Новый ОписаниеТипов("Строка"));
    ТаблицаРезультат.Колонки.Добавить("ЭлектроннаяПочта", Новый ОписаниеТипов("Строка"));
    ТаблицаРезультат.Колонки.Добавить("Количество", Новый ОписаниеТипов("Число"));

    Выборка = РезультатЗапроса.Выбрать();
    Пока Выборка.Следующий() Цикл
        Строка = ТаблицаРезультат.Добавить();
        Строка.Наименование = Выборка.Наименование;
        Строка.Телефон = Выборка.Телефон;
        Строка.ЭлектроннаяПочта = Выборка.ЭлектроннаяПочта;
        Строка.Количество = Выборка.Количество;
    КонецЦикла;

    Возврат ТаблицаРезультат;

КонецФункции

task:
Написать функцию СформироватьПродажиПоДнямНедели(ДатаНач, ДатаКон), которая формирует отчет о продажах предприятия с разбивкой по 
дням недели за выбранный период.
Задача предназначена для анализа покупательской активности и позволяет определить, в какие дни недели наблюдаются наибольшие продажи.

Результаты анализа могут использоваться для:
оптимизации графика работы персонала;
планирования акций и маркетинговых мероприятий;
анализа нагрузки на торговые точки;
выявления пиковых и слабых дней продаж;
повышения эффективности управления продажами.

Параметры функции:
ДатаНач — дата начала периода анализа;
ДатаКон — дата окончания периода анализа.

Если параметры периода не заданы, используются значения по умолчанию:
ДатаНач = начало дня 30 дней назад;
ДатаКон = конец текущего дня.

Перед выполнением расчета выполняется проверка параметров:
если ДатаКон < ДатаНач — генерируется исключение;
анализ выполняется только в пределах указанного периода.

Расчет выполняется на основании регистра накопления Продажи.
Используются следующие поля:
Период — дата продажи;
Количество — количество проданного товара;
Сумма — сумма продаж.

В процессе выполнения:
определяется день недели по дате продажи;
выполняется группировка по дням недели;
рассчитываются итоговые показатели по количеству и сумме продаж;
формируется итоговая таблица значений.

Результат функции представляет собой таблицу, содержащую:
день недели;
общее количество продаж;
общую сумму продаж.

output:
Функция СформироватьПродажиПоДнямНедели(Знач ДатаНач = Неопределено, Знач ДатаКон = Неопределено) Экспорт

    // Установка значений по умолчанию, если параметры не заданы
    Если ДатаНач = Неопределено Тогда
        ДатаНач = НачалоДня(ТекущаяДата() - 30);
    КонецЕсли;

    Если ДатаКон = Неопределено Тогда
        ДатаКон = КонецДня(ТекущаяДата());
    КонецЕсли;

    // Проверка корректности периода
    Если ДатаКон < ДатаНач Тогда
        ВызватьИсключение "Дата окончания периода не может быть меньше даты начала";
    КонецЕсли;

    Запрос = Новый Запрос;
    Запрос.Текст = 
    "ВЫБРАТЬ
    |   ДЕНЬНЕДЕЛИ(ПродажиОбороты.Период) КАК ДеньНедели,
    |   СУММА(ПродажиОбороты.Количество) КАК Количество,
    |   СУММА(ПродажиОбороты.Сумма) КАК Сумма
    |ИЗ
    |   РегистрНакопления.Продажи.Обороты(
    |       &ДатаНач,
    |       &ДатаКон,
    |       ,
    |   ) КАК ПродажиОбороты
    |СГРУППИРОВАТЬ ПО
    |   ДЕНЬНЕДЕЛИ(ПродажиОбороты.Период)
    |УПОРЯДОЧИТЬ ПО
    |   ДеньНедели";

    Запрос.УстановитьПараметр("ДатаНач", ДатаНач);
    Запрос.УстановитьПараметр("ДатаКон", ДатаКон);

    РезультатЗапроса = Запрос.Выполнить();

    // Таблица для возврата результата
    ТаблицаРезультат = Новый ТаблицаЗначений;
    ТаблицаРезультат.Колонки.Добавить("ДеньНедели", Новый ОписаниеТипов("Строка"));
    ТаблицаРезультат.Колонки.Добавить("Количество", Новый ОписаниеТипов("Число", Новый КвалификаторыЧисла(10, 2)));
    ТаблицаРезультат.Колонки.Добавить("Сумма",      Новый ОписаниеТипов("Число", Новый КвалификаторыЧисла(10, 2)));

    // Массив с названиями дней недели (1 – понедельник)
    ДниНедели = Новый Массив(7);
    ДниНедели[0] = "Понедельник";
    ДниНедели[1] = "Вторник";
    ДниНедели[2] = "Среда";
    ДниНедели[3] = "Четверг";
    ДниНедели[4] = "Пятница";
    ДниНедели[5] = "Суббота";
    ДниНедели[6] = "Воскресенье";

    // Заполнение итоговой таблицы
    Пока РезультатЗапроса.Следующий() Цикл
        Строка = ТаблицаРезультат.Добавить();
        НомерДня = РезультатЗапроса.ДеньНедели; // целое от 1 до 7
        Строка.ДеньНедели = ДниНедели[НомерДня - 1];
        Строка.Количество = РезультатЗапроса.Количество;
        Строка.Сумма = РезультатЗапроса.Сумма;
    КонецЦикла;

    Возврат ТаблицаРезультат;

КонецФункции

task:
Написать функцию СформироватьТоварыБезДвижения(ДатаНач, ДатаКон), которая формирует список товаров, по которым отсутствовали движения (продажи) 
за выбранный период.
Задача предназначена для анализа ассортимента и позволяет выявить товары, не участвующие в продажах.

Результаты анализа могут использоваться для:
выявления неликвидных и залежалых товаров;
принятия решений о скидках или акциях;
оптимизации ассортимента;
освобождения складских запасов;
повышения оборачиваемости товаров.

Параметры функции:
ДатаНач — дата начала периода анализа;
ДатаКон — дата окончания периода анализа.

Если параметры периода не заданы, используются значения по умолчанию:
ДатаНач = начало дня 30 дней назад;
ДатаКон = конец текущего дня.

Перед выполнением расчета выполняется проверка параметров:
если ДатаКон < ДатаНач — генерируется исключение;
анализ выполняется только в пределах указанного периода.

Расчет выполняется на основании следующих объектов конфигурации:
Справочник Товары — используется для получения полного списка товаров;
Регистр накопления Продажи — используется для определения наличия движений по товарам.

В процессе выполнения:
формируется список всех товаров без пометки удаления;
определяются товары, по которым были продажи за указанный период;
выполняется сравнение списков;
отбираются товары, по которым отсутствуют движения.

Результат функции представляет собой таблицу значений, содержащую:
товар;
наименование товара.

Полученный список позволяет оперативно выявить товары без движения и принять управленческие решения.

output:
Функция СформироватьТоварыБезДвижения(ДатаНач = Неопределено, ДатаКон = Неопределено)

    // Проверка и установка значений по умолчанию
    Если ДатаНач = Неопределено Тогда
        ДатаНач = НачалоДня(ТекущаяДата() - 30 * 86400);
    КонецЕсли;
    Если ДатаКон = Неопределено Тогда
        ДатаКон = КонецДня(ТекущаяДата());
    КонецЕсли;

    // Контроль корректности периода
    Если ДатаКон < ДатаНач Тогда
        ВызватьИсключение "Дата окончания периода не может быть меньше даты начала!";
    КонецЕсли;

    Запрос = Новый Запрос;
    Запрос.Текст = 
        "ВЫБРАТЬ
        |    Товары.Ссылка КАК Товар,
        |    Товары.Наименование КАК Наименование
        |ИЗ
        |    Справочник.Товары КАК Товары
        |    ЛЕВОЕ СОЕДИНЕНИЕ (ВЫБРАТЬ РАЗЛИЧНЫЕ
        |        ПродажиОбороты.Товар КАК Товар
        |    ИЗ
        |        РегистрНакопления.Продажи.Обороты(&ДатаНач, &ДатаКон) КАК ПродажиОбороты) КАК Продажи
        |    ПО (Товары.Ссылка = Продажи.Товар)
        |ГДЕ
        |    Продажи.Товар ЕСТЬ NULL
        |    И Товары.ПометкаУдаления = ЛОЖЬ";

    Запрос.УстановитьПараметр("ДатаНач", ДатаНач);
    Запрос.УстановитьПараметр("ДатаКон", ДатаКон);

    РезультатЗапроса = Запрос.Выполнить();

    Возврат РезультатЗапроса.Выгрузить();

КонецФункции

task:
Написать функцию НайтиПревышениеЛимитаПродаж(ДатаНач, ДатаКон, Лимит),
которая формирует список документов продаж предприятия, у которых сумма документа превышает установленный лимит за выбранный период.

Функция принимает три параметра:

ДатаНач — дата начала периода анализа;
ДатаКон — дата окончания периода анализа;
Лимит — максимальная допустимая сумма документа.

Если параметры периода не заданы, функция должна автоматически установить:

ДатаНач = начало дня 30 дней назад  
ДатаКон = конец текущего дня
Если параметр Лимит не задан — может использоваться значение по умолчанию


Перед выполнением расчета необходимо выполнить проверки:

если ДатаКон < ДатаНач — должно быть сгенерировано исключение;
если даты не заданы — используются значения по умолчанию;
анализ выполняется только в пределах указанного период 

Расчет выполняется на основании следующих объектов конфигурации:
Документ.РасходТовара

Функция должна возвращать объект типа ТаблицаЗначений, содержащий:

Ссылка — ссылка на документ;
Дата — дата документа;
Покупатель — контрагент;
Сумма — сумма документа

output:
Функция НайтиПревышениеЛимитаПродаж(ДатаНач = Неопределено, ДатаКон = Неопределено, Лимит = 0)

    // Если даты не заданы, используем значения по умолчанию
    Если ДатаНач = Неопределено Тогда
        ДатаНач = НачалоДня(ТекущаяДата() - 30 * 86400); // начало дня 30 дней назад
    КонецЕсли;

    Если ДатаКон = Неопределено Тогда
        ДатаКон = КонецДня(ТекущаяДата()); // конец текущего дня
    КонецЕсли;

    // Проверка корректности периода
    Если ДатаКон < ДатаНач Тогда
        ВызватьИсключение "Дата окончания периода не может быть меньше даты начала";
    КонецЕсли;

    // Создаем таблицу значений для результата
    Результат = Новый ТаблицаЗначений;
    Результат.Колонки.Добавить("Ссылка", Новый ОписаниеТипов("ДокументСсылка.РасходТовара"));
    Результат.Колонки.Добавить("Дата", Новый ОписаниеТипов("Дата"));
    Результат.Колонки.Добавить("Покупатель", Новый ОписаниеТипов("СправочникСсылка.Контрагенты"));
    Результат.Колонки.Добавить("Сумма", Новый ОписаниеТипов("Число", , 15, 2));

    // Запрос для получения данных
    Запрос = Новый Запрос;
    Запрос.Текст = 
    "ВЫБРАТЬ
    |    РасходТовара.Ссылка КАК Ссылка,
    |    РасходТовара.Дата КАК Дата,
    |    РасходТовара.Покупатель КАК Покупатель,
    |    СУММА(РасходТовараТовары.Сумма) КАК СуммаДокумента
    |ИЗ
    |    Документ.РасходТовара КАК РасходТовара
    |        ВНУТРЕННЕЕ СОЕДИНЕНИЕ Документ.РасходТовара.Товары КАК РасходТовараТовары
    |        ПО РасходТовара.Ссылка = РасходТовараТовары.Ссылка
    |ГДЕ
    |    РасходТовара.Дата МЕЖДУ &ДатаНач И &ДатаКон
    |
    |СГРУППИРОВАТЬ ПО
    |    РасходТовара.Ссылка,
    |    РасходТовара.Дата,
    |    РасходТовара.Покупатель
    |
    |ИМЕЮЩИЕ
    |    СУММА(РасходТовараТовары.Сумма) > &Лимит";

    Запрос.УстановитьПараметр("ДатаНач", ДатаНач);
    Запрос.УстановитьПараметр("ДатаКон", ДатаКон);
    Запрос.УстановитьПараметр("Лимит", Лимит);

    РезультатЗапроса = Запрос.Выполнить();

    Выборка = РезультатЗапроса.Выбрать();
    Пока Выборка.Следующий() Цикл
        НоваяСтрока = Результат.Добавить();
        НоваяСтрока.Ссылка = Выборка.Ссылка;
        НоваяСтрока.Дата = Выборка.Дата;
        НоваяСтрока.Покупатель = Выборка.Покупатель;
        НоваяСтрока.Сумма = Выборка.СуммаДокумента;
    КонецЦикла;

    Возврат Результат;

КонецФункции

Функция СформироватьОтчетОстаткиТоваровКонтроль(Период, КоличествоКонтроль)

    // Получаем схему компоновки данных отчета
    Схема = Отчеты.ОстаткиТоваровНаСкладах.СхемаКомпоновкиДанных;

    // Загружаем настройки варианта "Основной"
    ИсточникНастроек = Новый ИсточникДоступныхНастроекКомпоновкиДанных(Схема);
    КомпоновщикНастроек = Новый КомпоновщикНастроекКомпоновкиДанных;
    КомпоновщикНастроек.Инициализировать(ИсточникНастроек);
    Настройки = КомпоновщикНастроек.ЗагрузитьНастройки(Схема.Варианты["Основной"].Настройки);

    // Устанавливаем параметр Период
    ПараметрПериод = Настройки.ПараметрыДанных.Элементы.Найти("Период");
    Если ПараметрПериод <> Неопределено Тогда
        ПараметрПериод.Значение = Период;
        ПараметрПериод.Использование = Истина;
    КонецЕсли;

    // Перестраиваем структуру отчета
    Структура = Настройки.Структура;
    Структура.Очистить();

    // Корневая таблица
    Корень = Структура.Добавить(Тип("ГруппировкаКомпоновкиДанных"));
    Корень.Имя = "Таблица";
    Корень.РазмещениеИзмерений = РазмещениеИзмеренийКомпоновкиДанных.Таблица;

    // Группировка строк: Товар
    ГруппировкаТовар = Корень.Структура.Добавить(Тип("ГруппировкаКомпоновкиДанных"));
    ГруппировкаТовар.Имя = "Товар";
    ГруппировкаТовар.Расположение = РасположениеИзмеренийКомпоновкиДанных.Строки;
    ПолеТовар = ГруппировкаТовар.Выбор.Добавить(Тип("ВыбранноеПолеКомпоновкиДанных"));
    ПолеТовар.Поле = Новый ПолеКомпоновкиДанных("Товар");

    // Группировка колонок: Склад
    ГруппировкаСклад = Корень.Структура.Добавить(Тип("ГруппировкаКомпоновкиДанных"));
    ГруппировкаСклад.Имя = "Склад";
    ГруппировкаСклад.Расположение = РасположениеИзмеренийКомпоновкиДанных.Колонки;
    ПолеСклад = ГруппировкаСклад.Выбор.Добавить(Тип("ВыбранноеПолеКомпоновкиДанных"));
    ПолеСклад.Поле = Новый ПолеКомпоновкиДанных("Склад");

    // Выбранные поля
    Настройки.Выбор.Очистить();

    ВыбТовар = Настройки.Выбор.Добавить(Тип("ВыбранноеПолеКомпоновкиДанных"));
    ВыбТовар.Поле = Новый ПолеКомпоновкиДанных("Товар");

    ВыбСклад = Настройки.Выбор.Добавить(Тип("ВыбранноеПолеКомпоновкиДанных"));
    ВыбСклад.Поле = Новый ПолеКомпоновкиДанных("Склад");

    ВыбКол = Настройки.Выбор.Добавить(Тип("ВыбранноеПолеКомпоновкиДанных"));
    ВыбКол.Поле = Новый ПолеКомпоновкиДанных("КоличествоОстаток");

    // Отбор по количеству остатка
    Отбор = Настройки.Отбор;
    Отбор.Элементы.Очистить();
    ЭлементОтбора = Отбор.Добавить(Тип("ЭлементОтбораКомпоновкиДанных"));
    ЭлементОтбора.ЛевоеЗначение = Новый ПолеКомпоновкиДанных("КоличествоОстаток");
    ЭлементОтбора.ВидСравнения = ВидСравненияКомпоновкиДанных.МеньшеИлиРавно;
    ЭлементОтбора.ПравоеЗначение = КоличествоКонтроль;
    ЭлементОтбора.Использование = Истина;

    // Параметры вывода
    Настройки.ПараметрыВывода.ВыводитьПараметрыДанных = Ложь;
    Настройки.ПараметрыВывода.ВыводитьОтбор = Ложь;

    // Компоновка и вывод в табличный документ
    КомпоновщикМакета = Новый КомпоновщикМакетаКомпоновкиДанных;
    Макет = КомпоновщикМакета.Выполнить(Схема, Настройки);

    ПроцессорКомпоновки = Новый ПроцессорКомпоновкиДанных;
    ПроцессорКомпоновки.Инициализировать(Макет);

    ТабличныйДокумент = Новый ТабличныйДокумент;
    ПроцессорВывода = Новый ПроцессорВыводаРезультатаКомпоновкиДанныхВТабличныйДокумент;
    ПроцессорВывода.УстановитьДокумент(ТабличныйДокумент);
    ПроцессорВывода.Вывести(ПроцессорКомпоновки);

    Возврат ТабличныйДокумент;

КонецФункции

// Функция добавляет получателей в табличную часть "Получатели" для неотправленных исходящих писем.
// Параметры:
//   Получатели - Массив из СправочникСсылка.Контрагенты - контрагенты, чьи электронные почты будут добавлены.
//   Дата - Дата, письма с датой больше этой будут обработаны.
// Возвращаемое значение: Число - количество обработанных писем.
Функция ДобавитьПолучателейИсходящихПисем(Получатели, Дата) Экспорт

    // Проверка входных данных
    Если ТипЗнч(Получатели) <> Тип("Массив") ИЛИ Получатели.Количество() = 0 Тогда
        Возврат 0;
    КонецЕсли;

    // Получение электронных почт контрагентов
    МассивПочт = Новый Массив;
    ЗапросПочт = Новый Запрос;
    ЗапросПочт.Текст = 
    "ВЫБРАТЬ
    |	Контрагенты.ЭлектроннаяПочта КАК ЭлектроннаяПочта
    |ИЗ
    |	Справочник.Контрагенты КАК Контрагенты
    |ГДЕ
    |	Контрагенты.Ссылка В (&Получатели)";
    ЗапросПочт.УстановитьПараметр("Получатели", Получатели);
    ВыборкаПочт = ЗапросПочт.Выполнить().Выбрать();
    Пока ВыборкаПочт.Следующий() Цикл
        Если ЗначениеЗаполнено(ВыборкаПочт.ЭлектроннаяПочта) Тогда
            МассивПочт.Добавить(ВыборкаПочт.ЭлектроннаяПочта);
        КонецЕсли;
    КонецЦикла;

    Если МассивПочт.Количество() = 0 Тогда
        Возврат 0;
    КонецЕсли;

    // Отбор исходящих писем: дата > Дата, не помечены на удаление, состояние "Отправлено" = Ложь
    ЗапросПисем = Новый Запрос;
    ЗапросПисем.Текст = 
    "ВЫБРАТЬ
    |	ИсходящиеПисьма.Ссылка КАК Ссылка
    |ИЗ
    |	Справочник.ИсходящиеПисьма КАК ИсходящиеПисьма
    |		ВНУТРЕННЕЕ СОЕДИНЕНИЕ РегистрСведений.СостояниеИсходящихПисем КАК Состояние
    |		ПО ИсходящиеПисьма.Ссылка = Состояние.Письмо
    |ГДЕ
    |	ИсходящиеПисьма.Дата > &Дата
    |	И ИсходящиеПисьма.ПометкаУдаления = ЛОЖЬ
    |	И Состояние.Отправлено = ЛОЖЬ";
    ЗапросПисем.УстановитьПараметр("Дата", Дата);
    ВыборкаПисем = ЗапросПисем.Выполнить().Выбрать();

    // Обработка писем в транзакции
    КоличествоОбработано = 0;
    НачатьТранзакцию();
    Попытка
        Пока ВыборкаПисем.Следующий() Цикл
            ОбъектПисьмо = ВыборкаПисем.Ссылка.ПолучитьОбъект();
            // Очистка и заполнение табличной части "Получатели"
            ОбъектПисьмо.Получатели.Очистить();
            Для Каждого Почта Из МассивПочт Цикл
                НоваяСтрока = ОбъектПисьмо.Получатели.Добавить();
                НоваяСтрока.ЭлектроннаяПочта = Почта;
            КонецЦикла;
            ОбъектПисьмо.Записать();
            КоличествоОбработано = КоличествоОбработано + 1;
        КонецЦикла;
        ЗафиксироватьТранзакцию();
    Исключение
        ОтменитьТранзакцию();
        ВызватьИсключение;
    КонецПопытки;

    Возврат КоличествоОбработано;

КонецФункции
